LESSONS.push(
  {"id":"g9-phy-1-u1-1","grade":"g9","subject":"physics","term":1,"unit":1,"no":1,"title":"أهمية القياس","summary":"شرح متحرك لأهمية القياس الدقيق في الفيزياء والنظام الدولي للوحدات (SI) والبادئات، ثم أنشطة بثلاثة مستويات.","page":"lesson-importance-of-measurement.html","video":"","pdf":"","notes":["القياس الكامل يتكوّن من قيمة عددية ووحدة قياس.","وحدات النظام الدولي (SI) الأساسية: المتر (m) للطول، والكيلوجرام (kg) للكتلة، والثانية (s) للزمن.","البادئات: ١ كم = ١٠٠٠ م، ١ م = ١٠٠ سم = ١٠٠٠ مم.","لتجنّب الأخطاء: نفحص خطأ الصفر، ونجعل العين عموديةً على التدريج لتفادي خطأ اختلاف النظر.","تكرار القياس وحساب المتوسط يقللان الأخطاء العشوائية."],"exercises":["حوّل إلى المتر: ٤٫٥ كم ، ٣٥٠ سم ، ٨٠٠ مم.","اشرح كيف تتفادى خطأ الصفر وخطأ اختلاف النظر عند القياس بمسطرة."],"levels":{"easy":[{"type":"mcq","q":"ما وحدة الكتلة الأساسية في النظام الدولي (SI)؟","options":["الكيلوجرام (kg)","الجرام (g)","اللتر (L)","المتر (m)"],"answer":0,"why":"الكيلوجرام هو الوحدة الأساسية الدولية للكتلة."},{"type":"mcq","q":"كم ملليمترًا في ١ متر؟","options":["١٠٠ مم","١٠٠٠ مم","١٠ مم","١٠٠٠٠٠ مم"],"answer":1,"why":"١ م = ١٠٠٠ مم."},{"type":"mcq","q":"ما الجزءان اللذان يتكوّن منهما أي قياس فيزيائي صحيح؟","options":["وحدة فقط","عدد فقط","قيمة عددية ووحدة قياس","رسم فقط"],"answer":2,"why":"القيمة العددية بلا وحدة غير مفهومة فيزيائيًا."},{"type":"mcq","q":"ما وحدة الزمن في النظام الدولي (SI)؟","options":["الدقيقة","الساعة (h)","اليوم","الثانية (s)"],"answer":3,"why":"الثانية هي الوحدة الدولية الأساسية للزمن."}],"medium":[{"type":"mcq","q":"حوّل ٢٥٠ سم إلى متر:","options":["٢٫٥ م","٢٥ م","٠٫٢٥ م","٢٥٠٠٠ م"],"answer":0,"why":"نقسم ٢٥٠ ÷ ١٠٠ = ٢٫٥ م."},{"type":"tfr","q":"يمكن الاعتماد على حاسة اللمس وحدها لتحديد درجة حرارة الماء بدقة علمية.","answer":false,"reasons":["الحواس غير دقيقة وتتأثر بالحالة السابقة، لذا نحتاج أداة قياس كميزان الحرارة","الماء لا يُقاس","الحواس أدق من الأجهزة"],"reason":0},{"type":"essay","q":"اذكر طريقتين عمليتين لتقليل الأخطاء عند القياس في المختبر.","model":"١) وضع العين عموديةً على التدريج لتجنب خطأ اختلاف النظر. ٢) فحص الصفر وتكرار القياس وحساب المتوسط."},{"type":"tfr","q":"النظام الدولي للوحدات (SI) يسهّل تواصل العلماء وتبادل البيانات عالميًا.","answer":true,"reasons":["لأنه يلغي الأرقام","لأنه يوحّد الوحدات القياسية في كل دول العالم فيمنع أخطاء التحويل","لأنه خاص بدولة واحدة"],"reason":1},{"type":"mcq","q":"أخذ طالب ٣ قراءات لطول قلم: ١٤٫١ و ١٤٫٣ و ١٤٫٢ سم. ما المتوسط؟","options":["١٤٫١ سم","١٤٫٢ سم","٤٢٫٦ سم","١٤٫٣ سم"],"answer":1,"why":"(١٤٫١ + ١٤٫٣ + ١٤٫٢) ÷ ٣ = ١٤٫٢ سم."},{"type":"essay","q":"حوّل كلًّا مما يأتي إلى المتر: (١) ٠٫٦ كم، (٢) ٤٥ سم، (٣) ١٢٠٠ مم.","model":"(١) ٦٠٠ م. (٢) ٠٫٤٥ م. (٣) ١٫٢ م."},{"type":"tfr","q":"عند التحويل من وحدة صغيرة (ملليمتر) إلى وحدة كبيرة (متر) نضرب في ١٠٠٠.","answer":false,"reasons":["دائمًا نضرب في ١٠٠٠","نجمع ١٠٠٠","من صغير إلى كبير نقسم على ١٠٠٠، أما من كبير لصغير فنضرب"],"reason":2}],"hard":[{"type":"mcq","q":"إذا كانت بداية مسطرة مكسورة فبدأ الطالب القياس من ٢٫٠ سم وانتهى عند ١٥٫٤ سم، فما الطول الحقيقي؟","options":["١٥٫٤ سم","١٧٫٤ سم","١٣٫٤ سم","٢٫٠ سم"],"answer":2,"why":"نطرح قراءة البداية: ١٥٫٤ − ٢٫٠ = ١٣٫٤ سم."},{"type":"essay","q":"فسّر لماذا قد تختلف قراءة طالبين لمستوى الماء في مخبار مدرّج نفسه إذا لم يضعا عينيهما بمستوى السطح.","model":"بسبب خطأ اختلاف النظر (Parallax)؛ فالنظر من أعلى يعطي قراءة أصغر والنظر من أسفل يعطي قراءة أكبر، والصواب النظر أفقيًا بمستوى قاع التقعّر."},{"type":"tfr","q":"البادئة «ميكرو» (μ) تعني جزءًا من ألف (١٠⁻³).","answer":false,"reasons":["الميكرو تعني جزءًا من مليون (١٠⁻⁶)، أما جزء من ألف فهو المللي (m)","الميكرو تعني ١٠٠","الميكرو تعني مليون"],"reason":0},{"type":"mcq","q":"أيُّ القراءات الآتية تعادل ٠٫٠٠٥ متر؟","options":["٥٠ مم","٠٫٥ مم","٥ سم","٥ مم"],"answer":3,"why":"٠٫٠٠٥ × ١٠٠٠ = ٥ مم."},{"type":"essay","q":"اذكر مثالين من الحياة اليومية يوضحان خطورة غياب القياس الدقيق.","model":"١) تحضير جرعات الأدوية في الطب. ٢) قياس أبعاد الجسور والمباني في الهندسة."},{"type":"tfr","q":"إذا حصلتَ في تجربة على القراءات: ٥٫١ ، ٥٫٢ ، ٨٫٩ ، ٥٫١ سم، فمن الصواب استبعاد ٨٫٩ كقراءة شاذة وإعادة قياسها قبل حساب المتوسط.","answer":true,"reasons":["يجب إدخالها دائمًا","القراءة الشاذة ناتجة عن خطأ واضح وإدخالها يفسد المتوسط","لا توجد قراءات شاذة"],"reason":1},{"type":"mcq","q":"كم سنتيمترًا يساوي ٠٫٠٤ كيلومتر؟","options":["٤٠٠٠ سم","٤٠٠ سم","٤٠ سم","٤٠٠٠٠ سم"],"answer":0,"why":"٠٫٠٤ كم = ٤٠ م = ٤٠٠٠ سم."},{"type":"essay","q":"قارن بين خطأ الصفر وخطأ اختلاف النظر وكيفية معالجة كل منهما.","model":"خطأ الصفر: عدم بدء الجهاز من الصفر ويعالج بالتصفير أو طرح قراءة البداية. اختلاف النظر: قراءة التدريج بزاوية مائلة ويعالج بوضع العين عموديةً على التدريج."},{"type":"tfr","q":"تُعدّ السرعة والكثافة من الكميات المشتقة بينما الطول والكتلة والزمن كميات أساسية.","answer":true,"reasons":["الطول كمية مشتقة","السرعة كمية أساسية","الكميات المشتقة تُحسب من الكميات الأساسية كالمتر/الثانية والكيلوجرام/متر³"],"reason":2},{"type":"essay","q":"رتّب الأطوال الآتية تصاعديًا من الأصغر للأكبر: ٠٫٢ م ، ٢٥٠ مم ، ١٥ سم ، ٠٫٠٠٠١ كم.","model":"نحوّل للسم: ١٥ سم (١٥)، ٠٫٠٠٠١ كم (١٠ سم)، ٠٫٢ م (٢٠ سم)، ٢٥٠ مم (٢٥ سم). الترتيب: ٠٫٠٠٠١ كم < ١٥ سم < ٠٫٢ م < ٢٥٠ مم."}]}},
  {"id":"g9-phy-1-u1-2","grade":"g9","subject":"physics","term":1,"unit":1,"no":2,"title":"قياس الطول والحجم","summary":"شرح متحرك لقياس الأطوال الصغيرة (الورقة والسلك والميكرومتر) وقياس حجم المنتظم وغير المنتظم بالإزاحة، ثم أنشطة بثلاثة مستويات.","page":"lesson-measuring-length-and-volume.html","video":"","pdf":"","notes":["لقياس أطوال صغيرة جدًّا (سمك ورقة أو قطر سلك) نستخدم القياس المتعدد ونقسم على العدد، أو نستخدم الميكرومتر اللولبي (دقة ٠٫٠١ مم).","حجم متوازي المستطيلات = الطول × العرض × الارتفاع.","١ سم³ = ١ مل، و ١ لتر = ١٠٠٠ سم³، و ١ م³ = ١٠٠٠٠٠٠ سم³.","عند قراءة المخبار المدرّج نضعه على سطح أفقي ونقرأ عند قاع التقعّر.","حجم الجسم الصلب غير المنتظم = ح₂ − ح₁ (بطريقة الإزاحة، أو إناء الإزاحة للأجسام الكبيرة)."],"exercises":["لُفّ سلك ٣٠ لفةً متراصّةً حول قلم فشغل عرضًا قدره ٣٫٦ سم، احسب قطر السلك بالملليمتر.","اشرح كيف تقيس حجم قطعة فلين تطفو على سطح الماء."],"levels":{"easy":[{"type":"mcq","q":"ما الأداة الأنسب لقياس قطر سلك نحاسي رفيع جدًّا بدقة؟","options":["المخبار المدرّج","الميكرومتر اللولبي","الميزان","الشريط المتري"],"answer":1,"why":"الميكرومتر يقيس بدقة ٠٫٠١ مم."},{"type":"mcq","q":"مكعب طول ضلعه ٤ سم، ما حجمه؟","options":["٤ سم³","١٢ سم³","٦٤ سم³","١٦ سم³"],"answer":2,"why":"٤ × ٤ × ٤ = ٦٤ سم³."},{"type":"mcq","q":"كم ملليلترًا يعادل ٢٥ سم³؟","options":["٢٫٥ مل","٢٥٠٠ مل","٢٥٠ مل","٢٥ مل"],"answer":3,"why":"١ سم³ = ١ مل تمامًا."},{"type":"mcq","q":"في مخبار مدرّج به ٥٠ سم³ ماء، غمرنا مسمارًا فارتفع السطح إلى ٥٦ سم³؛ حجم المسمار:","options":["٦ سم³","٥٠ سم³","٥٦ سم³","١٠٦ سم³"],"answer":0,"why":"٥٦ − ٥٠ = ٦ سم³."}],"medium":[{"type":"mcq","q":"سمك ٢٠٠ ورقة في كتاب هو ١٫٨ سم؛ ما سمك الورقة الواحدة بالملليمتر؟","options":["٠٫٩ مم","٠٫٠٩ مم","٠٫٠٠٩ مم","٩ مم"],"answer":1,"why":"١٨ مم ÷ ٢٠٠ = ٠٫٠٩ مم."},{"type":"tfr","q":"نقرأ حجم الماء في المخبار المدرّج عند أعلى حافة التقعّر.","answer":false,"reasons":["نقرأ دائمًا عند قاع التقعّر والعين بمستوى أفقي","نقرأ من الأعلى دائمًا","لا يتكون تقعر للماء"],"reason":0},{"type":"essay","q":"اشرح خطوات قياس حجم حجر صغير غير منتظم باستخدام مخبار مدرّج وماء.","model":"١) نضع ماءً في المخبار ونسجّل ح₁. ٢) نغمر الحجر بلطف كاملًا دون تناثر الماء ونسجّل ح₂. ٣) حجم الحجر = ح₂ − ح₁."},{"type":"tfr","q":"تُستخدم طريقة قياس عدة لفات متراصّة من سلك لتقليل نسبة الخطأ في حساب قطره.","answer":true,"reasons":["لأن السلك لا يُقاس","بقسمة العرض الكلي على عدد اللفات يتوزع أي خطأ صغير على العدد كله فيقل جدًّا","لأنها تزيد الخطأ"],"reason":1},{"type":"mcq","q":"قراءة ميكرومتر: التدريج الرئيس ٥٫٠ مم والتدريج الدائري ٣٤؛ القراءة الكلية:","options":["٨٫٤ مم","٣٩ مم","٥٫٣٤ مم","٥٫٠٣٤ مم"],"answer":2,"why":"٥٫٠ + ٠٫٣٤ = ٥٫٣٤ مم."},{"type":"essay","q":"متوازي مستطيلات طوله ١٠ سم وعرضه ٤ سم وارتفاعه ٣ سم. احسب حجمه.","model":"الحجم = ١٠ × ٤ × ٣ = ١٢٠ سم³."},{"type":"tfr","q":"يمكن استخدام إزاحة الماء مباشرةً لقياس حجم مكعب من السكر.","answer":false,"reasons":["الماء يزيد حجم السكر","السكر لا يذوب في الماء","السكر يذوب في الماء فيقل حجمه، لذا يجب استخدام سائل لا يذيبه أو قياس أبعاده بالمسطرة"],"reason":2}],"hard":[{"type":"mcq","q":"في إناء إزاحة مملوء تمامًا بالماء حتى الفوهة، غمرنا حجرًا فتجمّع ٤٢ سم³ في مخبار فارغ؛ ما حجم الحجر؟","options":["لا يمكن معرفته","٢١ سم³","٨٤ سم³","٤٢ سم³"],"answer":3,"why":"حجم الماء المزاح يساوي تمامًا حجم الجسم المغمور."},{"type":"essay","q":"لُفّ سلك ٢٥ لفةً متراصّةً فشغل طولًا قدره ٣٫٠ سم. احسب قطر السلك بالملليمتر.","model":"٣٫٠ سم = ٣٠ مم ← القطر = ٣٠ ÷ ٢٥ = ١٫٢ مم."},{"type":"tfr","q":"١ متر مكعب (١ م³) يساوي ١٠٠ سم³.","answer":false,"reasons":["١ م = ١٠٠ سم ← ١ م³ = ١٠٠ × ١٠٠ × ١٠٠ = ١٠٠٠٠٠٠ سم³ (مليون سم³)","يساوي ١٠٠٠ سم³","يساوي ١٠ سم³"],"reason":0},{"type":"mcq","q":"قطعة فلين تطفو؛ حجم الماء + الثقل وحدهما ٦٠ سم³، وعند ربط الفلين بالثقل وغمرهما معًا أصبح الحجم ٧٤ سم³. ما حجم الفلين؟","options":["١٤ سم³","٦٠ سم³","٧٤ سم³","١٣٤ سم³"],"answer":0,"why":"٧٤ − ٦٠ = ١٤ سم³."},{"type":"essay","q":"اذكر خطأين عمليين قد يفسدان قياس حجم حجر بطريقة إزاحة الماء.","model":"١) إسقاط الحجر بقوة فيتناثر جزء من الماء خارج المخبار. ٢) عدم غمر الحجر بالكامل أو وجود فقاعات هواء ملتصقة به."},{"type":"tfr","q":"قبل استخدام الميكرومتر اللولبي يجب غلق فكّيه بلطف للتأكد من عدم وجود خطأ صفري.","answer":true,"reasons":["نغلقه بقوة شديدة","إن لم ينطبق الصفر عند الإغلاق نطرح أو نضيف قيمة الخطأ الصفري","لا يحتاج الميكرومتر لفحص الصفر"],"reason":1},{"type":"mcq","q":"قراءة ميكرومتر: التدريج الرئيس ٦٫٥ مم، والدائري ١٨. ما القراءة الصحيحة؟","options":["٦٫٨٣ مم","٦٫٦٨ مم","٢٤٫٥ مم","٦٫١٨ مم"],"answer":1,"why":"٦٫٥ + ٠٫١٨ = ٦٫٦٨ مم."},{"type":"essay","q":"صندوق أبعاده ٠٫٥ م × ٠٫٤ م × ٠٫٢ م. احسب حجمه بالمتر المكعب ثم بالسنتيمتر المكعب.","model":"بالمتر³: ٠٫٥ × ٠٫٤ × ٠٫٢ = ٠٫٠٤ م³. بالسم³: ٠٫٠٤ × ١٠٠٠٠٠٠ = ٤٠٠٠٠ سم³."},{"type":"tfr","q":"حجم ١ لتر من الماء يساوي ١٠٠٠ سم³.","answer":true,"reasons":["١ لتر = ١٠٠ سم³","١ لتر = ١٠ سم³","١ لتر = ١٠٠٠ مل = ١٠٠٠ سم³"],"reason":2},{"type":"essay","q":"لماذا نستخدم مخبارًا مدرّجًا ضيّقًا بدلًا من كأس واسع عند قياس حجم صغير مثل ١٥ سم³؟","model":"لأن تدريج المخبار الضيق أدقّ وتكون المسافة بين التدريجات أكبر فيقل الخطأ في القراءة."}]}},
  {"id":"g9-phy-1-u1-3","grade":"g9","subject":"physics","term":1,"unit":1,"no":3,"title":"قياس الزمن","summary":"شرح متحرك لأدوات قياس الزمن وزمن رد الفعل والبندول البسيط وحساب الزمن الدوري، ثم أنشطة بثلاثة مستويات.","page":"lesson-measuring-time.html","video":"","pdf":"","notes":["وحدة الزمن في النظام الدولي (SI) هي الثانية (s)؛ ١ دقيقة = ٦٠ ث، ١ ساعة = ٣٦٠٠ ث.","زمن ردّ الفعل البشري (~٠٫٢–٠٫٣ ث) يسبّب خطأً كبيرًا عند قياس أزمنة قصيرة جدًّا يدويًا.","لحساب الزمن الدوري (T) للبندول بدقة: نقيس زمن ٢٠ ذبذبة كاملة ثم نقسم على ٢٠.","يعتمد الزمن الدوري للبندول على طول الخيط فقط (كلما طال الخيط زاد الزمن الدوري) ولا يعتمد على كتلة الثقل.","البوابات الضوئية تُلغي خطأ رد الفعل البشري في القياسات السريعة جدًّا."],"exercises":["استغرق بندول ٣٢ ثانية لإتمام ٢٠ ذبذبة كاملة، احسب الزمن الدوري.","لماذا نضع علامة الإسناد عند منتصف مسار البندول بدلًا من أحد الطرفين؟"],"levels":{"easy":[{"type":"mcq","q":"ما وحدة قياس الزمن الدوري؟","options":["المتر/ث","المتر (m)","الثانية (s)","الكيلوجرام (kg)"],"answer":2,"why":"الزمن الدوري زمن ذبذبة واحدة فيُقاس بالثانية."},{"type":"mcq","q":"كم ثانيةً في نصف ساعة؟","options":["٣٠٠ ث","٦٠٠ ث","٣٦٠٠ ث","١٨٠٠ ث"],"answer":3,"why":"٣٠ دقيقة × ٦٠ = ١٨٠٠ ثانية."},{"type":"mcq","q":"أيُّ أداةٍ تُلغي خطأ ردّ الفعل البشري تمامًا عند قياس زمن سقوط كرة؟","options":["البوابات الضوئية","الساعة الرملية","المسطرة","ساعة الإيقاف اليدوية"],"answer":0,"why":"البوابات الضوئية تعمل إلكترونيًا بقطع الشعاع الضوئي."},{"type":"mcq","q":"إذا استغرق بندول ٢٠ ثانية لإتمام ١٠ ذبذبات، فما زمنه الدوري؟","options":["١٠ ث","٢ ث","٠٫٥ ث","٢٠٠ ث"],"answer":1,"why":"٢٠ ÷ ١٠ = ٢ ثانية."}],"medium":[{"type":"mcq","q":"إذا استبدلنا ثقل بندول كتلته ٥٠ جم بآخر كتلته ١٠٠ جم مع إبقاء طول الخيط ثابتًا، فإن الزمن الدوري:","options":["يقل للنصف","يصبح صفرًا","يبقى ثابتًا","يتضاعف"],"answer":2,"why":"الزمن الدوري للبندول لا يعتمد على كتلة الثقل."},{"type":"tfr","q":"نبدأ العدّ بالرقم «١» في اللحظة نفسها التي نضغط فيها زر بدء ساعة الإيقاف.","answer":false,"reasons":["نقول «صفر» عند بدء الساعة ثم «١» بعد إتمام أول ذبذبة كاملة حتى لا نخطئ في العدد","نبدأ من ١٠","نبدأ من الرقم ٢"],"reason":0},{"type":"essay","q":"اشرح خطوات قياس الزمن الدوري لبندول بسيط بدقة عالية في المختبر.","model":"نضع علامة عند منتصف المسار، نترك البندول يتأرجح، نبدأ الساعة عند مروره بالعلامة ونقول صفر، نعدّ ٢٠ ذبذبة كاملة ونوقف الساعة، نقسم الزمن على ٢٠، ونكرّر ٣ مرات لحساب المتوسط."},{"type":"tfr","q":"كلما زاد طول خيط البندول، زاد زمنه الدوري (أصبح يتأرجح أبطأ).","answer":true,"reasons":["كلما طال الخيط أسرع","هناك علاقة طردية بين طول الخيط والزمن الدوري للبندول","الطول لا يؤثر"],"reason":1},{"type":"mcq","q":"كم ثانيةً في القراءة 01:08.40 على ساعة الإيقاف؟","options":["١٠٨٫٤ ث","١٨٫٤ ث","٦٠٫٤ ث","٦٨٫٤ ث"],"answer":3,"why":"٦٠ + ٨٫٤ = ٦٨٫٤ ثانية."},{"type":"essay","q":"قارن بين استخدام ساعة الإيقاف اليدوية والبوابات الضوئية لقياس زمن سقوط جسم من ارتفاع ١ متر.","model":"البوابات الضوئية أدقّ بكثير لأن زمن السقوط قصير جدًّا (~٠٫٤٥ ث) فيشكّل زمن ردّ الفعل اليدوي (~٠٫٢ ث) نسبة خطأ ضخمة، بينما البوابات الضوئية إلكترونية بلا رد فعل."},{"type":"tfr","q":"تُعدّ حركة البندول من الطرف الأيمن إلى الطرف الأيسر فقط «ذبذبة كاملة».","answer":false,"reasons":["نعم هي ذبذبة كاملة","هي ذبذبتان","هذه نصف ذبذبة فقط؛ الذبذبة الكاملة تشمل الذهاب والإياب معًا"],"reason":2}],"hard":[{"type":"mcq","q":"في ٣ محاولات لقياس ٢٠ ذبذبة لبندول كانت الأزمنة: ٢٤٫٢ و ٢٤٫٠ و ٢٣٫٨ ث. ما متوسط الزمن الدوري؟","options":["١٫٢ ث","٢٫٤ ث","٢٤٫٠ ث","٠٫٨٣ ث"],"answer":0,"why":"المتوسط الكلي = ٢٤٫٠ ث ← الزمن الدوري = ٢٤٫٠ ÷ ٢٠ = ١٫٢ ث."},{"type":"essay","q":"لماذا يُفضَّل وضع علامة الإسناد عند «منتصف مسار البندول» وليس عند أحد طرفَي التأرجح؟","model":"لأن البندول يتحرك بأقصى سرعة عند المنتصف فيكون عبور النقطة حادًّا ومحددًا في لحظة دقيقة، بينما يتباطأ ويتوقف لحظيًا عند الطرفين فيصعب تحديد لحظة البداية بدقة."},{"type":"tfr","q":"إذا أردنا زيادة دقة ساعة حائط بندولية تؤخّر الوقت (بطيئة جدًّا)، فإننا نقصّر طول البندول قليلًا.","answer":true,"reasons":["تقصير الطول يقلّل الزمن الدوري فتسرع حركة البندول وتنضبط الساعة","نزيد كتلة الثقل","نطيل الخيط"],"reason":0},{"type":"mcq","q":"بندول زمنه الدوري ١٫٥ ثانية، كم ذبذبة كاملة يُتمّ في دقيقة واحدة؟","options":["٦٠ ذبذبة","٤٠ ذبذبة","٣٠ ذبذبة","٩٠ ذبذبة"],"answer":1,"why":"٦٠ ÷ ١٫٥ = ٤٠ ذبذبة."},{"type":"essay","q":"فسّر لماذا ينخفض الخطأ النسبي الناتج عن رد الفعل البشري عند قياس ٢٠ ذبذبة بدل ذبذبة واحدة.","model":"لأن خطأ رد الفعل (~٠٫٢ ث) يحدث فقط عند البداية والنهاية، وعند قسمة الزمن الكلي على ٢٠ ينقسم الخطأ على ٢٠ فيصبح ~٠٫٠١ ث فقط لكل ذبذبة."},{"type":"tfr","q":"الزمن الدوري هو مقلوب التردد (عدد الذبذبات في الثانية الواحدة).","answer":true,"reasons":["الزمن الدوري يساوي التردد","إذا كان الزمن الدوري ٠٫٥ ث، فالبندول يتم ذبذبتين في الثانية","لا علاقة بينهما"],"reason":1},{"type":"mcq","q":"تأرجح بندول من أقصى اليمين إلى أقصى اليسار في ٠٫٦ ثانية؛ ما زمنه الدوري الكامل؟","options":["٠٫٣ ث","٢٫٤ ث","١٫٢ ث","٠٫٦ ث"],"answer":2,"why":"من اليمين لليسار نصف ذبذبة ← الذبذبة الكاملة = ٠٫٦ × ٢ = ١٫٢ ث."},{"type":"essay","q":"اذكر متغيرين يجب تثبيتهما عند استقصاء أثر طول الخيط على الزمن الدوري للبندول.","model":"كتلة الثقل، وسعة الاهتزاز (زاوية الإفلات الصغيرة)، وطريقة العدّ ومكان علامة الإسناد."},{"type":"tfr","q":"بندولان متماثلان في الطول، أحدهما على الأرض والآخر على القمر (جاذبية أقل)، لهما الزمن الدوري نفسه.","answer":false,"reasons":["لا يتحرك على القمر","لهما الزمن نفسه دائمًا","الزمن الدوري يعتمد أيضًا على شدة الجاذبية، ففي القمر تكون الجاذبية أقل فيتأرجح أبطأ"],"reason":2},{"type":"essay","q":"تحرّكت كرة بين بوابتين ضوئيتين خلال ٠٫٠٨٥ ثانية؛ كم مللي ثانية يساوي ذلك؟","model":"٠٫٠٨٥ × ١٠٠٠ = ٨٥ مللي ثانية (ms)."}]}},
  {"id":"g9-phy-1-u2-1","grade":"g9","subject":"physics","term":1,"unit":2,"no":1,"title":"فهم السرعة","summary":"شرح متحرك لمفهوم السرعة والسرعة المتوسطة وقانون السرعة ومثلث الحسابات والتحويل بين km/h و m/s، ثم أنشطة بثلاثة مستويات.","page":"lesson-understanding-speed.html","video":"","pdf":"","notes":["السرعة (v) = المسافة (d) ÷ الزمن (t)، ووحدتها الدولية m/s.","المسافة d = v × t، والزمن t = d ÷ v.","السرعة المتوسطة = المسافة الكلية ÷ الزمن الكلي (شاملًا أوقات التوقف).","للتحويل من km/h إلى m/s نقسم على ٣٫٦، ومن m/s إلى km/h نضرب في ٣٫٦.","عدّاد السيارة يقيس السرعة اللحظية."],"exercises":["قطعت حافلة ٢٤٠ كم في ٣ ساعات، احسب سرعتها المتوسطة بوحدة كم/س ثم بوحدة م/ث.","كم دقيقةً تحتاج سيارة تسير بسرعة ١٠٠ كم/س لقطع مسافة ٥٠ كم؟"],"levels":{"easy":[{"type":"mcq","q":"ما وحدة السرعة في النظام الدولي (SI)؟","options":["كم/س","م·ث","ث/م","م/ث (m/s)"],"answer":3,"why":"المتر لكل ثانية هي الوحدة الدولية للسرعة."},{"type":"mcq","q":"قطعت دراجة ٦٠ مترًا في ٤ ثوانٍ؛ ما سرعتها؟","options":["١٥ م/ث","١٢ م/ث","٢٤٠ م/ث","٦٤ م/ث"],"answer":0,"why":"٦٠ ÷ ٤ = ١٥ م/ث."},{"type":"mcq","q":"جسم يسير بسرعة ٨ م/ث لمدة ٥ ثوانٍ، ما المسافة التي يقطعها؟","options":["١٫٦ م","٤٠ م","٣ م","١٣ م"],"answer":1,"why":"٨ × ٥ = ٤٠ م."},{"type":"mcq","q":"كم زمنًا يستغرق عدّاء لقطع ٢٠٠ م بسرعة ١٠ م/ث؟","options":["٢٠٠٠ ث","١٠ ث","٢٠ ث","٠٫٠٥ ث"],"answer":2,"why":"٢٠٠ ÷ ١٠ = ٢٠ ث."}],"medium":[{"type":"mcq","q":"حوّل سرعة ٣٦ كم/س إلى م/ث:","options":["٣٫٦ م/ث","١٢٩٫٦ م/ث","٣٦٠ م/ث","١٠ م/ث"],"answer":3,"why":"٣٦ ÷ ٣٫٦ = ١٠ م/ث."},{"type":"tfr","q":"عند حساب السرعة المتوسطة لرحلة تتخلّلها استراحة، نُهمل زمن الاستراحة من الزمن الكلي.","answer":false,"reasons":["الزمن الكلي يشمل زمن الحركة وزمن التوقف معًا","نعم نهمل الاستراحة دائمًا","السرعة لا تعتمد على الزمن"],"reason":0},{"type":"essay","q":"سارت سيارة ١٨٠ كم في ساعتين، ثم ٦٠ كم في ساعة واحدة. احسب سرعتها المتوسطة للرحلة كاملةً.","model":"المسافة الكلية = ٢٤٠ كم، الزمن الكلي = ٣ ساعات ← السرعة المتوسطة = ٢٤٠ ÷ ٣ = ٨٠ كم/س."},{"type":"tfr","q":"السرعة المتوسطة تساوي المسافة الكلية مقسومةً على الزمن الكلي.","answer":true,"reasons":["تساوي المسافة × الزمن","هذا هو التعريف القياسي للسرعة المتوسطة","تساوي الزمن ÷ المسافة"],"reason":1},{"type":"mcq","q":"حوّل سرعة ١٥ م/ث إلى كم/س:","options":["٥٤ كم/س","٤٫١٦ كم/س","١٥٠ كم/س","٣٦ كم/س"],"answer":0,"why":"١٥ × ٣٫٦ = ٥٤ كم/س."},{"type":"essay","q":"ما الفرق بين السرعة اللحظية والسرعة المتوسطة؟","model":"السرعة اللحظية هي سرعة الجسم في لحظة زمنية محددة (مثل قراءة عدّاد السيارة)، أما المتوسطة فهي المسافة الكلية ÷ الزمن الكلي."},{"type":"tfr","q":"سرعة ٢٠ م/ث أكبر من سرعة ٦٠ كم/س.","answer":true,"reasons":["٦٠ أكبر من ٢٠ دائمًا","هما متساويتان","٢٠ م/ث × ٣٫٦ = ٧٢ كم/س وهي أكبر من ٦٠ كم/س"],"reason":2}],"hard":[{"type":"mcq","q":"يصل صوت الرعد بعد ٥ ثوانٍ من البرق؛ إذا كانت سرعة الصوت ٣٤٠ م/ث، كم بُعد العاصفة؟","options":["٣٤٥ م","١٧٠٠ م (١٫٧ كم)","٦٨ م","٣٣٥ م"],"answer":1,"why":"d = ٣٤٠ × ٥ = ١٧٠٠ م."},{"type":"essay","q":"قطعت سيارة ٩٠ كم بسرعة ٩٠ كم/س، ثم توقفت ٣٠ دقيقة، ثم قطعت ٦٠ كم في ساعة. احسب سرعتها المتوسطة للرحلة كلها.","model":"المسافة الكلية = ١٥٠ كم. الزمن الكلي = ١ + ٠٫٥ + ١ = ٢٫٥ ساعة. السرعة المتوسطة = ١٥٠ ÷ ٢٫٥ = ٦٠ كم/س."},{"type":"tfr","q":"يمكن لجسم أن يسير بسرعة متوسطة ٦٠ كم/س دون أن يثبت عدّاد سرعته عند ٦٠ طوال الرحلة.","answer":true,"reasons":["قد تزيد سرعته وتنقص لكن النسبة الكلية (المسافة ÷ الزمن) تساوي ٦٠ كم/س","هذا مستحيل","يجب أن يبقى العداد عند ٦٠ دائمًا"],"reason":0},{"type":"mcq","q":"عربة طول بطاقتها ٠٫١٠ م عبرت بوابة ضوئية واحدة في ٠٫٠٥ ثانية؛ ما سرعتها؟","options":["٢٠ م/ث","٠٫٠٠٥ م/ث","٢ م/ث","٠٫٥ م/ث"],"answer":2,"why":"٠٫١٠ ÷ ٠٫٠٥ = ٢ م/ث."},{"type":"essay","q":"أثبت حسابيًا لماذا نقسم على ٣٫٦ عند التحويل من كم/س إلى م/ث.","model":"١ كم/س = ١٠٠٠ م ÷ ٣٦٠٠ ث = ١ ÷ ٣٫٦ م/ث، لذا نقسم أي سرعة بوحدة كم/س على ٣٫٦."},{"type":"tfr","q":"إذا قطعت سيارتان المسافة نفسها، فالسيارة التي تستغرق زمنًا أطول تكون سرعتها أكبر.","answer":false,"reasons":["لا علاقة بينهما","العلاقة عكسية بين السرعة والزمن عند ثبات المسافة؛ الزمن الأطول يعني سرعة أقل","الزمن الأطول يعني سرعة أكبر"],"reason":1},{"type":"mcq","q":"طائرة تطير بسرعة ٩٠٠ كم/س؛ كم مترًا تقطع في ثانية واحدة؟","options":["٩٠٠ م","٢٥ م","٣٢٤٠ م","٢٥٠ م"],"answer":3,"why":"٩٠٠ ÷ ٣٫٦ = ٢٥٠ م/ث."},{"type":"essay","q":"سافر أحمد من صحار إلى مسقط (٢١٦ كم) في ساعتين و٢٤ دقيقة. احسب سرعته المتوسطة بوحدة كم/س.","model":"٢٤ دقيقة = ٢٤ ÷ ٦٠ = ٠٫٤ ساعة ← الزمن = ٢٫٤ ساعة ← السرعة = ٢١٦ ÷ ٢٫٤ = ٩٠ كم/س."},{"type":"tfr","q":"في الفيزياء، «السرعة المتجهة» (Velocity) تتطلب تحديد المقدار والاتجاه معًا بخلاف السرعة القياسية.","answer":true,"reasons":["كلاهما بلا اتجاه","السرعة القياسية لها اتجاه","السرعة القياسية مقدار فقط، أما السرعة المتجهة فمقدار واتجاه"],"reason":2},{"type":"essay","q":"قارن بين استخدام بوابتين ضوئيتين وبين استخدام بوابة ضوئية واحدة مع بطاقة مثبتة على العربة لقياس السرعة.","model":"مع بوابتين نقسم المسافة بينهما على زمن العبور بينهما؛ ومع بوابة واحدة نقسم طول البطاقة على زمن قطعها للشعاع (وهي تقيس السرعة اللحظية تقريبًا عند البوابة)."}]}},
  {"id":"g9-phy-1-u2-2","grade":"g9","subject":"physics","term":1,"unit":2,"no":2,"title":"التمثيل البياني (المسافة/الزمن)","summary":"شرح متحرك لقراءة منحنى (المسافة–الزمن) واستنتاج السكون والسرعة الثابتة والتسارع وحساب السرعة من الميل، ثم أنشطة بثلاثة مستويات.","page":"lesson-distance-time-graphs.html","video":"","pdf":"","notes":["على منحنى (المسافة–الزمن): الزمن على المحور الأفقي والمسافة على المحور الرأسي.","الخط الأفقي يعني أن الجسم ساكن (السرعة = ٠).","الخط المستقيم المائل يعني سرعة ثابتة، وكلما زاد الانحدار زادت السرعة.","الخط المنحني للأعلى يعني تسارعًا، والمنحني المتسطّح يعني تباطؤًا.","ميل الخط المستقيم = (d₂ − d₁) ÷ (t₂ − t₁) = السرعة."],"exercises":["صف حركة جسم يمثّلها خط مستقيم مائل للأعلى ثم خط أفقي ثم خط مائل للأسفل على منحنى (المسافة–الزمن).","احسب سرعة جسم قطع المسافة من ٢٠ م عند الثانية ٢ إلى ٨٠ م عند الثانية ١٠."],"levels":{"easy":[{"type":"mcq","q":"على منحنى (المسافة–الزمن)، أيّ محورٍ يمثّل الزمن عادةً؟","options":["المحور الأفقي","القطر","المحور الرأسي","كلاهما"],"answer":0,"why":"الزمن متغير مستقل يوضع دائمًا على المحور الأفقي."},{"type":"mcq","q":"الخط المستقيم المائل للأعلى على منحنى (المسافة–الزمن) يدلّ على:","options":["تسارع غير منتظم","سرعة ثابتة","سكون","توقّف مفاجئ"],"answer":1,"why":"الميل الثابت يعني سرعة ثابتة."},{"type":"mcq","q":"يمر خط مستقيم من (٠، ٠) إلى (٤ ث، ٢٤ م)؛ ما سرعة الجسم؟","options":["٩٦ م/ث","٢٠ م/ث","٦ م/ث","٤ م/ث"],"answer":2,"why":"٢٤ ÷ ٤ = ٦ م/ث."},{"type":"mcq","q":"أيّ خطٍّ على منحنى (المسافة–الزمن) يمثّل جسمًا متوقفًا؟","options":["المنحنى الصاعد","الخط الهابط","الخط المائل بشدة","الخط الأفقي"],"answer":3,"why":"الخط الأفقي ميله صفر فالسرعة صفر."}],"medium":[{"type":"mcq","q":"إذا كان ميل الخط (أ) أكبر من ميل الخط (ب) على منحنى (المسافة–الزمن)، فإن:","options":["الجسم (أ) أسرع من (ب)","الجسم (ب) أسرع من (أ)","كلاهما ساكن","سرعتهما متساوية"],"answer":0,"why":"الميل يساوي السرعة، فالأكبر ميلًا هو الأسرع."},{"type":"tfr","q":"الخط الأفقي على منحنى (المسافة–الزمن) يعني أن الجسم يتحرك بسرعة ثابتة غير صفرية.","answer":false,"reasons":["بل يعني أن الجسم ساكن وسرعته صفر؛ السرعة الثابتة يمثلها خط أفقي في منحنى (السرعة–الزمن) فقط","يعني أنه يتسارع","نعم يتحرك بسرعة ثابتة"],"reason":0},{"type":"essay","q":"كيف تحسب سرعة جسم من خط مستقيم على منحنى (المسافة–الزمن)؟","model":"نختار نقطتين متباعدتين على الخط (t₁, d₁) و (t₂, d₂) ثم نحسب الميل: v = (d₂ − d₁) ÷ (t₂ − t₁)."},{"type":"tfr","q":"إذا تسطّح المنحنى تدريجيًا على رسم (المسافة–الزمن) فهذا يدلّ على تباطؤ الجسم.","answer":true,"reasons":["لأن المسافة تختفي","لأن تسطّح المنحنى يعني تناقص الميل، وبما أن الميل هو السرعة فالسرعة تتناقص","لأن السرعة تزداد"],"reason":1},{"type":"mcq","q":"تحرّك جسم من المسافة ١٥ م عند الزمن ٣ ث إلى المسافة ٤٥ م عند الزمن ٩ ث؛ ما سرعته؟","options":["٣ م/ث","٥ م/ث","١٠ م/ث","٧٫٥ م/ث"],"answer":1,"why":"(٤٥−١٥) ÷ (٩−٣) = ٣٠ ÷ ٦ = ٥ م/ث."},{"type":"essay","q":"ماذا يعني هبوط خط مستقيم من المسافة ١٠٠ م إلى المسافة ٠ م على منحنى (المسافة–الزمن)؟","model":"يعني أن الجسم يعود إلى نقطة البداية بسرعة ثابتة."},{"type":"tfr","q":"الخط المستقيم الذي يبدأ من نقطة الأصل (٠، ٠) يعني أن الجسم بدأ حركته من نقطة البداية عند الزمن صفر.","answer":true,"reasons":["يعني أنه توقف","يعني أنه بدأ بسرعة كبيرة","عند t=0 كانت المسافة d=0"],"reason":2}],"hard":[{"type":"mcq","q":"في رحلة مدتها ٢٠ ثانية: قطع جسم ٦٠ م في أول ١٠ ث، ثم توقف ٥ ث، ثم قطع ٤٠ م في آخر ٥ ث. ما السرعة المتوسطة للرحلة كلها؟","options":["٦ م/ث","٨ م/ث","٥ م/ث","١٠ م/ث"],"answer":2,"why":"المسافة الكلية ١٠٠ م ÷ الزمن الكلي ٢٠ ث = ٥ م/ث."},{"type":"essay","q":"لماذا يُنصح باختيار مثلث كبير (نقطتين متباعدتين) عند حساب الميل من الرسم البياني؟","model":"لأن اختيار نقطتين متباعدتين يقلّل نسبة الخطأ الناتجة عن قراءة الإحداثيات من شبكة الرسم البياني."},{"type":"tfr","q":"لا يمكن أن يظهر خط رأسي تمامًا على منحنى (المسافة–الزمن) لحركة جسم حقيقي.","answer":true,"reasons":["لأن الخط الرأسي يعني قطع مسافة في زمن صفر (سرعة لا نهائية)، وهذا مستحيل فيزيائيًا","الخط الرأسي يعني سكونًا","الخط الرأسي يعني سرعة بطيئة"],"reason":0},{"type":"mcq","q":"عدّاءان على نفس الرسم: العدّاء ١ انطلق عند t=0، والعدّاء ٢ انطلق عند t=4 وتقاطع خطاهما عند t=10؛ ماذا تعني نقطة التقاطع؟","options":["العدّاء ١ أسرع","توقف العدّاءان","الزمن صفر","العدّاء ٢ لحق بالعدّاء ١ والتقيا في الموضع نفسه"],"answer":3,"why":"نقطة التقاطع تعني المسافة نفسها في اللحظة نفسها."},{"type":"essay","q":"صف كيف يمكنك إيجاد السرعة اللحظية لجسم يتحرك بسرعة متغيّرة (خط منحنٍ) على منحنى (المسافة–الزمن) عند زمن محدد.","model":"نرسم خطًّا مماسًا للمنحنى عند تلك النقطة الزمنية، ثم نحسب ميل هذا المماس (التغير الرأسي ÷ التغير الأفقي)."},{"type":"tfr","q":"إذا بقي خط (المسافة–الزمن) أفقيًا عند d = ٥٠ م من t = ٤ إلى t = ٩ ث، فإن الجسم قطع ٥٠ مترًا خلال تلك الثواني الخمس.","answer":false,"reasons":["قطع ٢٥٠ مترًا","لم يقطع أي مسافة إضافية (المسافة المقطوعة ٠) لأنه كان متوقفًا على بُعد ٥٠ م من البداية","قطع ١٠ أمتار"],"reason":1},{"type":"mcq","q":"في المثال السابق (توقف عند ٥٠ م من t=4 إلى t=9)، كم مدة توقف الجسم؟","options":["٥ ثوانٍ","٩ ثوانٍ","٥٠ ثانية","٤ ثوانٍ"],"answer":0,"why":"٩ − ٤ = ٥ ثوانٍ."},{"type":"essay","q":"قارن بين شكل خط (المسافة–الزمن) لسيارة تنطلق من السكون وتتسارع، وسيارة تقترب من إشارة حمراء وتتباطأ.","model":"المنطلقة المتسارعة: خط منحنٍ يزداد ميله للأعلى. المتباطئة: خط منحنٍ يقلّ ميله ويتسطّح حتى يصبح أفقيًا عند التوقف."},{"type":"tfr","q":"إذا كان خط (المسافة–الزمن) لجسمين متوازيين (بنفس الميل)، فهذا يعني أن لهما السرعة نفسها.","answer":true,"reasons":["يعني أنهما متوقفان","يعني أن أحدهما أسرع","تساوي الميل يعني تساوي السرعة حتى لو انطلق أحدهما قبل الآخر"],"reason":2},{"type":"essay","q":"قطع طالب مسافة ٨٠ م في ٢٠ ثانية بسرعة ثابتة، ثم استراح ١٠ ثوانٍ، ثم عاد لنقطة البداية في ٢٠ ثانية. احسب سرعته في الذهاب وسرعته المتوسطة للرحلة كلها.","model":"سرعة الذهاب = ٨٠ ÷ ٢٠ = ٤ م/ث. المسافة الكلية = ٨٠ + ٨٠ = ١٦٠ م، والزمن الكلي = ٥٠ ث ← السرعة المتوسطة = ١٦٠ ÷ ٥٠ = ٣٫٢ م/ث."}]}},
  {"id":"g9-phy-1-u2-3","grade":"g9","subject":"physics","term":1,"unit":2,"no":3,"title":"فهم التسارع","summary":"شرح متحرك لمفهوم التسارع والتباطؤ وقراءة منحنيات (السرعة–الزمن)، ثم أنشطة بثلاثة مستويات.","page":"lesson-understanding-acceleration.html","video":"","pdf":"","notes":["التسارع: معدل تغيّر السرعة في وحدة الزمن، ووحدته الدولية m/s².","التسارع الموجب يعني زيادة السرعة، والتسارع السالب (التباطؤ) يعني تناقص السرعة.","على منحنى (السرعة–الزمن): الخط الأفقي فوق الصفر = سرعة ثابتة (التسارع = ٠)، وعلى الصفر = ساكن.","الخط المستقيم الصاعد = تسارع منتظم، والمستقيم الهابط = تباطؤ منتظم، والمنحني = تسارع غير منتظم.","يجب دائمًا قراءة عنوان المحور الرأسي للتمييز بين منحنى (المسافة–الزمن) ومنحنى (السرعة–الزمن)."],"exercises":["قارن بين دلالة «الخط الأفقي» على منحنى (المسافة–الزمن) وعلى منحنى (السرعة–الزمن).","صف حركة قطار يظهر منحناه (السرعة–الزمن) خطًّا صاعدًا ثم أفقيًا ثم هابطًا."],"levels":{"easy":[{"type":"mcq","q":"التسارع هو معدل تغيّر:","options":["المسافة بالنسبة للكتلة","السرعة بالنسبة للزمن","الكتلة بالنسبة للزمن","الحجم بالنسبة للطول"],"answer":1,"why":"التسارع يقيس تغيّر السرعة كل ثانية."},{"type":"mcq","q":"عندما يضغط السائق المكابح فتقل سرعة السيارة، نسمّي ذلك:","options":["سكونًا فوريًا","سرعة ثابتة","تباطؤًا (تسارعًا سالبًا)","تسارعًا موجبًا"],"answer":2,"why":"تناقص السرعة هو تباطؤ."},{"type":"mcq","q":"على منحنى (السرعة–الزمن)، الخط المستقيم الصاعد يدلّ على:","options":["تباطؤ","سرعة ثابتة","سكون","تسارع منتظم"],"answer":3,"why":"زيادة السرعة بانتظام مع الزمن."},{"type":"mcq","q":"ما تسارع سيارة تسير بسرعة ثابتة ٨٠ كم/س؟","options":["صفر","٨٠ م/ث²","−٨٠ م/ث²","١٠ م/ث²"],"answer":0,"why":"السرعة لا تتغيّر إذن التغيّر في السرعة = صفر."}],"medium":[{"type":"mcq","q":"على منحنى (السرعة–الزمن)، أين يظهر الجسم الساكن؟","options":["خط هابط","خط منطبق على محور الزمن (السرعة = ٠)","خط صاعد","خط أفقي عند ١٠ م/ث"],"answer":1,"why":"الجسم الساكن سرعته صفر طوال الوقت."},{"type":"tfr","q":"الخط المستقيم المائل للأعلى على منحنى (السرعة–الزمن) يدلّ على سرعة ثابتة.","answer":false,"reasons":["بل يدلّ على تسارع منتظم لأن السرعة تزداد باستمرار؛ السرعة الثابتة يمثلها خط أفقي","يدل على سكون","نعم سرعة ثابتة"],"reason":0},{"type":"essay","q":"فسّر معنى قولنا: «تسارع جسم يساوي ٤ م/ث²».","model":"يعني أن سرعة الجسم تزداد بمقدار ٤ م/ث في كل ثانية تمرّ عليه."},{"type":"tfr","q":"كلما كان الخط الصاعد على منحنى (السرعة–الزمن) أشد انحدارًا كان تسارع الجسم أكبر.","answer":true,"reasons":["لأن التسارع أقل","لأن ميل منحنى (السرعة–الزمن) يساوي التسارع","لأن السرعة ثابتة"],"reason":1},{"type":"mcq","q":"منحنى (السرعة–الزمن) الذي ينحني صعودًا ويزداد انحداره يدلّ على:","options":["تباطؤ ثابت","سكون","تسارع متزايد (غير منتظم)","تسارع ثابت"],"answer":2,"why":"تغيّر الميل يعني تغيّر التسارع."},{"type":"essay","q":"قارن بين منحنى (المسافة–الزمن) ومنحنى (السرعة–الزمن) لجسم يتحرك بسرعة ثابتة ١٠ م/ث.","model":"في (المسافة–الزمن): خط مستقيم مائل للأعلى ميله ١٠. وفي (السرعة–الزمن): خط أفقي ثابت عند ١٠ م/ث."},{"type":"tfr","q":"تسارع السقوط الحر للأجسام القريبة من سطح الأرض يساوي تقريبًا ١٠ م/ث² (٩٫٨ م/ث²).","answer":true,"reasons":["يساوي ١ م/ث²","يساوي صفرًا","تزداد سرعة الجسم الساقط حرًّا بنحو ١٠ م/ث في كل ثانية"],"reason":2}],"hard":[{"type":"mcq","q":"إذا سقطت كرة من السكون سقوطًا حرًّا بتسارع ١٠ م/ث²، فكم تصبح سرعتها بعد ٣ ثوانٍ؟","options":["٤٠ م/ث","١٠ م/ث","٣٫٣ م/ث","٣٠ م/ث"],"answer":3,"why":"تزداد ١٠ م/ث كل ثانية ← ١٠ × ٣ = ٣٠ م/ث."},{"type":"essay","q":"صف حركة جسم يمثّله على منحنى (السرعة–الزمن) خط منحنٍ صاعد لكن ميله يتناقص تدريجيًا حتى يصبح أفقيًا.","model":"تستمر سرعة الجسم في الزيادة لكن بمعدل أبطأ (تسارع متناقص)، وعندما يصبح الخط أفقيًا يصل لسرعة ثابتة (تسارع = صفر)."},{"type":"tfr","q":"إذا كان خط (السرعة–الزمن) هابطًا، فهل يعني ذلك أن الجسم يتحرك للخلف؟","answer":false,"reasons":["لا، ما دام الخط فوق محور الزمن فالسرعة موجبة والجسم ما زال يتحرك للأمام لكنه يتباطأ","يكون ساكنًا","نعم يعود للخلف فورًا"],"reason":0},{"type":"mcq","q":"أيُّ وصفٍ صحيح لسيارة تغيّرت سرعتها من ٢٥ م/ث إلى ٥ م/ث؟","options":["تسارعها سالب (تباطؤ)","تسارعها صفر","سرعتها ثابتة","تسارعها موجب"],"answer":0,"why":"تناقص السرعة يعطي تغيّرًا سالبًا (تباطؤًا)."},{"type":"essay","q":"ما الفرق بين «تباطؤ منتظم» و«تسارع متناقص»؟","model":"في التباطؤ المنتظم تنقص السرعة بمقدار ثابت كل ثانية (خط هابط). أما في التسارع المتناقص فالسرعة ما زالت تزيد لكن بمقدار أقل في كل ثانية (منحنى صاعد يتسطح)."},{"type":"tfr","q":"الخط الأفقي على منحنى (المسافة–الزمن) والخط المنطبق على محور الزمن في (السرعة–الزمن) يصفان الحالة نفسها (السكون).","answer":true,"reasons":["الأول سرعة ثابتة والثاني تسارع","كلاهما يعني أن السرعة تساوي صفرًا","لا علاقة بينهما"],"reason":1},{"type":"mcq","q":"أيّ جسمٍ له أكبر تسارع: جسم تزداد سرعته من ٠ إلى ٢٠ م/ث في ٤ ث، أم من ٠ إلى ٣٠ م/ث في ١٠ ث؟","options":["لا يمكن المقارنة","الأول (٥ م/ث² مقابل ٣ م/ث²)","الثاني","متساويان"],"answer":1,"why":"الأول ٢٠÷٤ = ٥ م/ث²، الثاني ٣٠÷١٠ = ٣ م/ث²."},{"type":"essay","q":"ارسم بالكلمات شكل منحنى (السرعة–الزمن) لسيارة سباق تنطلق من السكون بتسارع ثابت ثم تسير بسرعة ثابتة ثم تتباطأ بتسارع ثابت حتى التوقف.","model":"يبدأ من (٠، ٠) بخط مستقيم صاعد، ثم خط أفقي موازٍ لمحور الزمن، ثم خط مستقيم هابط يصل إلى محور الزمن (السرعة = ٠)."},{"type":"tfr","q":"الوحدة m/s² تعني تغيّر السرعة بوحدة m/s في كل ثانية.","answer":true,"reasons":["تعني متر × ثانية²","هي وحدة المسافة","(m/s) ÷ s = m/s²"],"reason":2},{"type":"essay","q":"لماذا لا يُعدّ تغيّر اتجاه حركة سيارة (كالدوران في دوّار بسرعة مقدارها ثابت) بلا تسارع في الفيزياء المتقدمة؟","model":"لأن السرعة المتجهة تعتمد على المقدار والاتجاه معًا، وتغيّر الاتجاه يعني تغيّر السرعة المتجهة وبالتالي وجود تسارع نحو المركز."}]}},
  {"id":"g9-phy-1-u2-4","grade":"g9","subject":"physics","term":1,"unit":2,"no":4,"title":"حساب السرعة والتسارع","summary":"شرح متحرك لحساب التسارع بالقانون a=(v−u)/t وحساب المسافة من المساحة تحت منحنى (السرعة–الزمن)، ثم أنشطة بثلاثة مستويات.","page":"lesson-calculating-speed-and-acceleration.html","video":"","pdf":"","notes":["قانون التسارع: a = (v − u) ÷ t حيث u السرعة الابتدائية و v النهائية و t الزمن.","ميل منحنى (السرعة–الزمن) يساوي التسارع.","المساحة المحصورة تحت منحنى (السرعة–الزمن) تساوي المسافة المقطوعة.","مساحة المستطيل = القاعدة × الارتفاع؛ ومساحة المثلث = ½ × القاعدة × الارتفاع.","الإشارة السالبة في التسارع تعني تباطؤًا (تناقص السرعة)."],"exercises":["انطلق قطار من السكون بتسارع ١٫٥ م/ث² لمدة ٢٠ ثانية، احسب سرعته النهائية والمسافة المقطوعة.","احسب المسافة المقطوعة لجسم تباطأ بانتظام من ١٨ م/ث إلى ٠ خلال ٦ ثوانٍ."],"levels":{"easy":[{"type":"mcq","q":"ما قانون حساب التسارع؟","options":["a = v × t","a = (v + u) × t","a = (v − u) ÷ t","a = d ÷ t"],"answer":2,"why":"التغيّر في السرعة مقسومًا على الزمن."},{"type":"mcq","q":"تغيّرت سرعة جسم من ٠ إلى ١٨ م/ث في ٣ ثوانٍ؛ ما تسارعه؟","options":["١٥ م/ث²","٣ م/ث²","٥٤ م/ث²","٦ م/ث²"],"answer":3,"why":"(١٨ − ٠) ÷ ٣ = ٦ م/ث²."},{"type":"mcq","q":"جسم سار بسرعة ثابتة ١٢ م/ث لمدة ٥ ثوانٍ؛ مساحة المستطيل تحت المنحنى (المسافة) =","options":["٦٠ م","٣٠ م","٢٫٤ م","١٧ م"],"answer":0,"why":"١٢ × ٥ = ٦٠ م."},{"type":"mcq","q":"ماذا تعني عبارة «انطلق الجسم من السكون» في المسائل؟","options":["v = ٠","u = ٠","a = ٠","t = ٠"],"answer":1,"why":"السرعة الابتدائية تساوي صفرًا."}],"medium":[{"type":"mcq","q":"سيارة سرعتها ١٠ م/ث تسارعت بمعدل ٣ م/ث² لمدة ٤ ثوانٍ؛ كم أصبحت سرعتها النهائية؟","options":["٤٠ م/ث","١٢ م/ث","٢٢ م/ث","٧ م/ث"],"answer":2,"why":"v = ١٠ + (٣ × ٤) = ٢٢ م/ث."},{"type":"tfr","q":"المساحة تحت منحنى (المسافة–الزمن) تساوي التسارع.","answer":false,"reasons":["المساحة تحت منحنى (السرعة–الزمن) هي التي تساوي المسافة، أما منحنى المسافة–الزمن فلا نستخدم مساحته","نعم تساوي التسارع","تساوي السرعة"],"reason":0},{"type":"essay","q":"تباطأت دراجة من ١٦ م/ث إلى ٤ م/ث خلال ٣ ثوانٍ. احسب تسارعها.","model":"a = (٤ − ١٦) ÷ ٣ = −١٢ ÷ ٣ = −٤ م/ث² (تباطؤ ٤ م/ث²)."},{"type":"tfr","q":"يمكن إيجاد المسافة المقطوعة أثناء التسارع المنتظم من السكون بحساب مساحة المثلث تحت منحنى (السرعة–الزمن).","answer":true,"reasons":["لأن الميل هو المسافة","لأن الخط المائل الصاعد من الصفر يشكّل مثلثًا مع محور الزمن مساحته ½ × t × v","لأنها مساحة مربع"],"reason":1},{"type":"mcq","q":"تباطأت سيارة من ٢٤ م/ث حتى التوقف خلال ٨ ثوانٍ. ما المسافة التي قطعتها أثناء التباطؤ؟","options":["٣ م","٤٨ م","١٩٢ م","٩٦ م"],"answer":3,"why":"مساحة مثلث = ½ × ٨ × ٢٤ = ٩٦ م."},{"type":"essay","q":"احسب الزمن اللازم لتزداد سرعة قارب من ٤ م/ث إلى ٢٢ م/ث إذا كان تسارعه ٣ م/ث².","model":"t = (v − u) ÷ a = (٢٢ − ٤) ÷ ٣ = ١٨ ÷ ٣ = ٦ ثوانٍ."},{"type":"tfr","q":"في قانون التسارع a = (v − u) ÷ t إذا كانت v < u يكون الناتج سالبًا.","answer":true,"reasons":["يكون صفرًا","يكون الناتج موجبًا","لأن السرعة النهائية أقل من الابتدائية، مما يعني تباطؤ الجسم"],"reason":2}],"hard":[{"type":"mcq","q":"تسارعت سيارة من ٠ إلى ٢٠ م/ث في ٥ ث، ثم سارت بـ ٢٠ م/ث لمدة ١٠ ث، ثم توقفت في ٥ ث. ما المسافة الكلية؟","options":["٣٠٠ م","٤٠٠ م","٢٥٠ م","٢٠٠ م"],"answer":0,"why":"مثلث١ (½×٥×٢٠=٥٠) + مستطيل (١٠×٢٠=٢٠٠) + مثلث٢ (½×٥×٢٠=٥٠) = ٣٠٠ م."},{"type":"essay","q":"في المسألة السابقة (المسافة الكلية ٣٠٠ م والزمن الكلي ٢٠ ث)، احسب السرعة المتوسطة للسيارة.","model":"السرعة المتوسطة = ٣٠٠ ÷ ٢٠ = ١٥ م/ث."},{"type":"tfr","q":"وحدة ناتج المساحة تحت منحنى (السرعة–الزمن) هي المتر لأن (م/ث) × ث = م.","answer":true,"reasons":["تختصر الثانية في المقام مع الثانية في البسط فيبقى المتر (m)","الناتج بوحدة م/ث²","الناتج بلا وحدة"],"reason":0},{"type":"mcq","q":"جسم زادت سرعته من ٨ م/ث إلى ٢٠ م/ث بانتظام خلال ٦ ثوانٍ؛ ما المسافة التي قطعها؟","options":["٤٨ م","٨٤ م","١٢٠ م","٣٦ م"],"answer":1,"why":"مساحة شبه منحرف = ½ × (٨ + ٢٠) × ٦ = ١٤ × ٦ = ٨٤ م."},{"type":"essay","q":"تسارعت طائرة على المدرج من السكون بتسارع ٢٫٥ م/ث² لمدة ٣٠ ثانية قبل الإقلاع. احسب سرعة الإقلاع وطول المدرج الذي قطعته.","model":"v = ٠ + ٢٫٥ × ٣٠ = ٧٥ م/ث. المسافة = ½ × ٣٠ × ٧٥ = ١١٢٥ مترًا."},{"type":"tfr","q":"إذا تضاعف زمن التوقف لسيارة تسير بالسرعة الابتدائية نفسها، فإن مسافة التوقف تتضاعف أيضًا.","answer":true,"reasons":["تقل للنصف","مسافة التوقف = ½ × v × t، فمضاعفة t تضاعف المسافة","تبقى ثابتة"],"reason":1},{"type":"mcq","q":"سيارة تتحرك بسرعة ٧٢ كم/س توقفت خلال ٤ ثوانٍ؛ ما تسارعها بوحدة م/ث²؟","options":["−١٨ م/ث²","−٢٠ م/ث²","−٥ م/ث²","+٥ م/ث²"],"answer":2,"why":"نحوّل ٧٢ كم/س = ٢٠ م/ث ← a = (٠ − ٢٠) ÷ ٤ = −٥ م/ث²."},{"type":"essay","q":"لماذا يجب تحويل السرعة من كم/س إلى م/ث قبل حساب التسارع بوحدة م/ث²؟","model":"لتتوافق الوحدات مع الزمن المقاس بالثانية، فلا يصح قسمة كم/س على ثانية مباشرة."},{"type":"tfr","q":"حساب السرعة المتوسطة لجسم يتسارع بانتظام من u إلى v يساوي (u + v) ÷ ٢.","answer":true,"reasons":["يساوي u × v","يساوي v − u","وهذا يطابق قانون مساحة شبه المنحرف: المسافة = [(u+v)÷٢] × t"],"reason":2},{"type":"essay","q":"قطار يسير بسرعة ٣٠ م/ث تباطأ بمعدل ٢ م/ث² حتى توقف. احسب زمن التوقف ومسافة التوقف.","model":"t = (٠ − ٣٠) ÷ (−٢) = ١٥ ثانية. المسافة = ½ × ١٥ × ٣٠ = ٢٢٥ مترًا."}]}},
  {"id":"g9-phy-1-u3-1","grade":"g9","subject":"physics","term":1,"unit":3,"no":1,"title":"الكتلة والوزن والجاذبية","summary":"شرح متحرك للفرق بين الكتلة والوزن وقانون الوزن W=mg واختلاف الوزن على القمر والمقارنة بالموازين، ثم أنشطة بثلاثة مستويات.","page":"lesson-mass-weight-and-gravity.html","video":"","pdf":"","notes":["الكتلة (m): مقدار ما يحتويه الجسم من مادة، وحدتها kg، ثابتة لا تتغير بالمكان، وتقيس القصور الذاتي.","الوزن (W): قوة جذب الجاذبية المؤثرة في الجسم، وحدته النيوتن (N)، ويتغيّر بتغيّر شدة مجال الجاذبية (g).","قانون الوزن: W = m × g (حيث m بالكيلوجرام، و g ≈ ١٠ N/kg على الأرض و ١٫٦ N/kg على القمر).","تُقاس الكتلة بالميزان ذي الكفتين، ويُقاس الوزن بالميزان الزنبركي (النيوتن متر).","الميزان ذو الكفتين يقارن كتلتين فيعمل بدقة على القمر كما على الأرض."],"exercises":["حقيبة كتلتها ٤٫٥ كجم، احسب وزنها على الأرض (g = ١٠) وعلى القمر (g = ١٫٦).","قارن في جدول بين الكتلة والوزن من حيث التعريف والوحدة والأداة وتأثرهما بالمكان."],"levels":{"easy":[{"type":"mcq","q":"ما وحدة قياس الوزن؟","options":["الجرام (g)","الكيلوجرام (kg)","الجول (J)","النيوتن (N)"],"answer":3,"why":"الوزن قوة يُقاس بالنيوتن."},{"type":"mcq","q":"جسم كتلته ٦ كجم على سطح الأرض (g = ١٠ N/kg)؛ كم وزنه؟","options":["٦٠ N","٠٫٦ N","١٦ N","٦ N"],"answer":0,"why":"٦ × ١٠ = ٦٠ نيوتن."},{"type":"mcq","q":"أيُّ كميةٍ تبقى ثابتةً إذا سافرتَ إلى كوكب المريخ؟","options":["الوزن","الكتلة","قوة الجذب","شدة الجاذبية"],"answer":1,"why":"الكتلة مقدار المادة فلا تتغير بتغيّر الكوكب."},{"type":"mcq","q":"ما أداة قياس الوزن مباشرةً؟","options":["الميكرومتر","المخبار المدرّج","الميزان الزنبركي","ساعة الإيقاف"],"answer":2,"why":"الميزان الزنبركي يقيس القوة بالنيوتن."}],"medium":[{"type":"mcq","q":"كرة كتلتها ٥٠٠ جم؛ كم وزنها على الأرض (g = ١٠ N/kg)؟","options":["٥٠ N","٠٫٥ N","٥٠٠٠ N","٥ N"],"answer":3,"why":"٥٠٠ جم = ٠٫٥ كجم ← ٠٫٥ × ١٠ = ٥ نيوتن."},{"type":"tfr","q":"تُقاس الكتلة بوحدة النيوتن والوزن بوحدة الكيلوجرام.","answer":false,"reasons":["العكس صحيح: الكتلة بالكيلوجرام والوزن بالنيوتن","كلاهما بالنيوتن","كلاهما بالكيلوجرام"],"reason":0},{"type":"essay","q":"عرّف كلًّا من الكتلة والوزن، واذكر وحدة قياس كل منهما.","model":"الكتلة: مقدار المادة في الجسم ووحدتها الكيلوجرام (kg). الوزن: قوة جذب الجاذبية للجسم ووحدته النيوتن (N)."},{"type":"tfr","q":"يعمل الميزان ذو الكفتين بدقة على سطح القمر لقياس الكتلة.","answer":true,"reasons":["لأنه يقيس بالنيوتن","لأن جاذبية القمر تؤثر بالنسبة نفسها على الكفتين فتتساويان عند تساوي الكتلتين","لأنه لا يعمل على القمر"],"reason":1},{"type":"mcq","q":"جسم وزنه ٤٥٠ نيوتن على الأرض (g = ١٠ N/kg)؛ ما كتلته؟","options":["٤٥ كجم","٤٥٠٠ كجم","٤٫٥ كجم","٤٤٠ كجم"],"answer":0,"why":"m = ٤٥٠ ÷ ١٠ = ٤٥ كجم."},{"type":"essay","q":"احسب وزن رائد فضاء كتلته ٧٥ كجم على سطح القمر (g = ١٫٦ N/kg).","model":"W = ٧٥ × ١٫٦ = ١٢٠ نيوتن."},{"type":"tfr","q":"كلما زادت كتلة الجسم، زادت مقاومته لتغيّر حالته الحركية (قصوره الذاتي).","answer":true,"reasons":["لا علاقة بين الكتلة والحركة","الكتلة الأكبر أسهل في الإيقاف","الكتلة مقياس للقصور الذاتي فالشاحنة أصعب في الإيقاف من الدراجة"],"reason":2}],"hard":[{"type":"mcq","q":"صخرة وزنها ٣٢ نيوتن على سطح القمر (g = ١٫٦ N/kg)؛ ما وزنها على سطح الأرض (g = ١٠ N/kg)؟","options":["٣٢٠ N","٢٠٠ N","٢٠ N","٥١٫٢ N"],"answer":1,"why":"كتلتها m = ٣٢ ÷ ١٫٦ = ٢٠ كجم ← وزنها على الأرض = ٢٠ × ١٠ = ٢٠٠ نيوتن."},{"type":"essay","q":"فسّر لماذا ينعدم وزن رائد الفضاء في محطة الفضاء لكنه ما زال يحتاج لقوة كبيرة لدفع صندوق كتلته ١٠٠ كجم.","model":"لأن الكتلة لا تتغيّر بانعدام الوزن، والكتلة مقياس للقصور الذاتي (مقاومة تغيير الحركة)، فدفع ١٠٠ كجم يحتاج قوة كبيرة لتسريعها."},{"type":"tfr","q":"وحدة شدة مجال الجاذبية (N/kg) تكافئ رياضيًا وحدة التسارع (m/s²).","answer":true,"reasons":["لأن القوة = الكتلة × التسارع، فقسمة القوة على الكتلة تعطي تسارع الجاذبية g","هما وحدتان مختلفتان تمامًا","g بلا وحدة"],"reason":0},{"type":"mcq","q":"على كوكب المشتري (g = ٢٥ N/kg)، ما وزن مسبار كتلته ٤٠ كجم؟","options":["٦٥ N","١٫٦ N","١٠٠٠ N","٤٠٠ N"],"answer":2,"why":"٤٠ × ٢٥ = ١٠٠٠ نيوتن."},{"type":"essay","q":"لماذا يعطي الميزان الزنبركي المصمّم للأرض قراءةً غير صحيحة للكتلة إذا أخذناه إلى القمر؟","model":"لأن الميزان الزنبركي يقيس قوة الوزن التي تعتمد على الجاذبية، فجاذبية القمر أقل بـ ٦ مرات فيستطيل الزنبرك أقل ويعطي قراءة أقل بـ ٦ مرات."},{"type":"tfr","q":"شدة مجال الجاذبية على قمة جبل شاهق أقلّ قليلًا جدًّا منها عند سطح البحر.","answer":true,"reasons":["تنعدم فوق الجبل","لأن الجاذبية تضعف قليلًا كلما ابتعدنا عن مركز الأرض","تزداد كلما ارتفعنا"],"reason":1},{"type":"mcq","q":"جسم كتلته ١٥٠ جم ووزنه على كوكب مجهول ٠٫٦ نيوتن؛ ما شدة مجال الجاذبية (g) على ذلك الكوكب؟","options":["٢٫٥ N/kg","٠٫٠٠٤ N/kg","٩٠ N/kg","٤ N/kg"],"answer":3,"why":"m = ٠٫١٥ كجم ← g = ٠٫٦ ÷ ٠٫١٥ = ٤ N/kg."},{"type":"essay","q":"قارن بين الميزان ذي الكفتين والميزان الزنبركي من حيث ما يقيسه كل منهما وهل يتأثر بتغيّر الكوكب.","model":"ذو الكفتين يقيس الكتلة بالمقارنة ولا يتأثر بتغيّر الكوكب؛ الزنبركي يقيس قوة الوزن بالاستطالة ويتأثر بتغيّر الجاذبية."},{"type":"tfr","q":"قوة الوزن كمية متجهة اتجاهها دائمًا نحو مركز الأرض.","answer":true,"reasons":["اتجاهه للأعلى","الوزن كمية قياسية بلا اتجاه","الوزن قوة جذب لها مقدار واتجاه نحو مركز الكوكب"],"reason":2},{"type":"essay","q":"إذا كانت كتلة سيارة ١٢٠٠ كجم، احسب وزنها على الأرض (استخدم g = ٩٫٨ N/kg).","model":"W = ١٢٠٠ × ٩٫٨ = ١١٧٦٠ نيوتن."}]}},
  {"id":"g9-phy-1-u4-1","grade":"g9","subject":"physics","term":1,"unit":4,"no":1,"title":"الكثافة","summary":"شرح متحرك لمفهوم الكثافة وقانونها ρ=m/V ووحداتها وقياس كثافة المنتظم وغير المنتظم والسوائل والطفو والغوص، ثم أنشطة بثلاثة مستويات.","page":"lesson-density.html","video":"","pdf":"","notes":["الكثافة (ρ) = الكتلة (m) ÷ الحجم (V)، ووحدتها g/cm³ أو kg/m³ (حيث ١ g/cm³ = ١٠٠٠ kg/m³).","الكتلة m = ρ × V، والحجم V = m ÷ ρ.","الكثافة خاصية مميّزة ثابتة للمادة النقية الواحدة ولا تتغير بتقطيعها.","يطفو الجسم إذا كانت كثافته أقل من كثافة السائل، ويغوص إذا كانت أكبر.","لقياس كثافة حجر: نقيس كتلته جافًا بالميزان ثم حجمه بالإزاحة في المخبار المدرّج."],"exercises":["حجر كتلته ٧٥ جم غُمر في مخبار به ٤٠ سم³ ماء فارتفع إلى ٦٥ سم³؛ احسب كثافته.","فسّر لماذا تطفو السفينة المصنوعة من الفولاذ رغم أن كثافة الفولاذ أكبر من كثافة الماء."],"levels":{"easy":[{"type":"mcq","q":"ما قانون حساب الكثافة؟","options":["الكثافة = الكتلة ÷ الحجم","الكثافة = الكتلة × الحجم","الكثافة = الحجم ÷ الكتلة","الكثافة = الوزن × الطول"],"answer":0,"why":"ρ = m ÷ V."},{"type":"mcq","q":"مكعب حجمه ٢٥ سم³ وكتلته ٢٠٠ جم؛ ما كثافته؟","options":["٢٢٥ جم/سم³","٨ جم/سم³","٠٫١٢٥ جم/سم³","٥٠٠٠ جم/سم³"],"answer":1,"why":"٢٠٠ ÷ ٢٥ = ٨ جم/سم³."},{"type":"mcq","q":"كم تساوي كثافة الماء النقي بوحدة جم/سم³؟","options":["١٠٠٠ جم/سم³","١٠ جم/سم³","١ جم/سم³","٠٫١ جم/سم³"],"answer":2,"why":"كثافة الماء ١ جم/سم³ (أي ١٠٠٠ كجم/م³)."},{"type":"mcq","q":"يطفو الزيت فوق الماء لأن كثافة الزيت:","options":["مساوية للماء","صفر","أكبر من كثافة الماء","أقل من كثافة الماء"],"answer":3,"why":"المادة الأقل كثافةً تطفو فوق الأكثر كثافةً."}],"medium":[{"type":"mcq","q":"قطعة حديد كثافتها ٧٫٨ جم/سم³ وحجمها ١٠ سم³؛ ما كتلتها؟","options":["٧٨ جم","٧٨٠ جم","١٧٫٨ جم","٠٫٧٨ جم"],"answer":0,"why":"m = ٧٫٨ × ١٠ = ٧٨ جم."},{"type":"tfr","q":"إذا تضاعف حجم قطعة من الألمنيوم النقي فإن كثافتها تتضاعف أيضًا.","answer":false,"reasons":["الكثافة تبقى ثابتة للمادة النقية الواحدة لأن الكتلة والحجم يتضاعفان معًا","نعم تتضاعف","تقل للنصف"],"reason":0},{"type":"essay","q":"اشرح خطوات قياس كثافة سائل (مثل زيت الطعام) في المختبر.","model":"١) نقيس كتلة مخبار فارغ (ك₁). ٢) نضع حجمًا معلومًا V من الزيت ونقيس كتلتهما معًا (ك₂). ٣) كتلة الزيت = ك₂ − ك₁. ٤) الكثافة = (ك₂ − ك₁) ÷ V."},{"type":"tfr","q":"في تجربة قياس كثافة حجر يجب قياس كتلته وهو جاف قبل غمره في الماء.","answer":true,"reasons":["لا يهم الترتيب","حتى لا يلتصق الماء بسطحه فيزيد قراءة الكتلة ويعطي كثافة غير دقيقة","الماء ينقص كتلته"],"reason":1},{"type":"mcq","q":"مخبار فارغ كتلته ٦٠ جم، وعند وضع ٥٠ سم³ من سائل أصبحت كتلته ١٠٠ جم؛ ما كثافة السائل؟","options":["٢ جم/سم³","٠٫٨ جم/سم³","٣٫٢ جم/سم³","١٫٢ جم/سم³"],"answer":1,"why":"كتلة السائل = ٤٠ جم ← ٤٠ ÷ ٥٠ = ٠٫٨ جم/سم³."},{"type":"essay","q":"احسب حجم قطعة رصاص كتلتها ٢٢٦ جم وكثافتها ١١٫٣ جم/سم³.","model":"V = m ÷ ρ = ٢٢٦ ÷ ١١٫٣ = ٢٠ سم³."},{"type":"tfr","q":"يطفو الثلج فوق الماء السائل لأن كثافة الثلج (٠٫٩٢ جم/سم³) أقل من كثافة الماء (١٫٠ جم/سم³).","answer":true,"reasons":["كثافتهما متساوية","الثلج أثقل كثافة من الماء","الماء يتمدد عند التجمد فتقل كثافته ويطفو الثلج"],"reason":2}],"hard":[{"type":"mcq","q":"متوازي مستطيلات أبعاده ٥ × ٤ × ٢ سم وكتلته ١٠٨ جم؛ ما كثافته؟","options":["١٫٣٥ جم/سم³","٥٫٤ جم/سم³","٢٫٧ جم/سم³","١٠٫٨ جم/سم³"],"answer":2,"why":"الحجم = ٤٠ سم³ ← الكثافة = ١٠٨ ÷ ٤٠ = ٢٫٧ جم/سم³."},{"type":"essay","q":"لماذا يسهل الطفو على الإنسان في ماء البحر المالح أكثر منه في ماء المسبح العذب؟","model":"لأن الأملاح الذائبة ترفع كثافة ماء البحر (نحو ١٫٠٣ جم/سم³) فتصبح أكبر من الماء العذب، مما يزيد قوة الطفو."},{"type":"tfr","q":"تاج ذهبي كتلته ٣٨٦ جم وحجمه ٢٥ سم³ يكون مصنوعًا من ذهب خالص (كثافة الذهب ١٩٫٣ جم/سم³).","answer":false,"reasons":["كثافة التاج = ٣٨٦ ÷ ٢٥ = ١٥٫٤٤ جم/سم³ ≠ ١٩٫٣، إذن التاج مخلوط بمعدن آخر أرخص!","الحجم لا يهم","نعم ذهب خالص"],"reason":0},{"type":"mcq","q":"حوّل كثافة ٢٥٠٠ كجم/م³ إلى وحدة جم/سم³:","options":["٢٥ جم/سم³","٠٫٢٥ جم/سم³","٢٥٠ جم/سم³","٢٫٥ جم/سم³"],"answer":3,"why":"نقسم على ١٠٠٠ ← ٢٫٥ جم/سم³."},{"type":"essay","q":"صُبّ في أنبوب زجاجي ثلاثة سوائل لا تمتزج: زئبق (١٣٫٦)، ماء (١٫٠)، زيت (٠٫٨) جم/سم³. رتّبها من الأسفل إلى الأعلى.","model":"من الأسفل للأعلى (من الأكبر كثافة للأقل): الزئبق في القاع، ثم الماء في الوسط، ثم الزيت في الأعلى."},{"type":"tfr","q":"تطفو السفينة الحديدية لأن تجويفها المملوء بالهواء يجعل متوسط كثافتها الكلي أقل من كثافة الماء.","answer":true,"reasons":["لأن الحديد أقل كثافة من الماء","متوسط الكثافة = الكتلة الكلية ÷ الحجم الكلي شاملاً الفراغ الهوائي، فيكون أقل من ١ جم/سم³","لأن السفينة بلا كتلة"],"reason":1},{"type":"mcq","q":"غرفة أبعادها ٥ م × ٤ م × ٣ م مملوءة بهواء كثافته ١٫٢ كجم/م³؛ ما كتلة الهواء داخل الغرفة؟","options":["٧٢ كجم","٥٠ كجم","٦٠ كجم","١٢ كجم"],"answer":0,"why":"الحجم = ٦٠ م³ ← الكتلة = ٦٠ × ١٫٢ = ٧٢ كجم."},{"type":"essay","q":"احسب كثافة حجر كتلته ٩٠ جم غُمر في مخبار به ٣٠ سم³ ماء فارتفع إلى ٦٠ سم³، ثم حوّل الناتج إلى كجم/م³.","model":"الحجم = ٦٠ − ٣٠ = ٣٠ سم³. الكثافة = ٩٠ ÷ ٣٠ = ٣ جم/سم³ = ٣٠٠٠ كجم/م³."},{"type":"tfr","q":"إذا ارتفعت درجة حرارة معظم المواد وتمددت، فإن كثافتها تقلّ قليلًا.","answer":true,"reasons":["تزداد كثافتها","تزداد كتلتها","تبقى الكتلة ثابتة ويزداد الحجم بالتمدد ← الكتلة ÷ الحجم تقلّ"],"reason":2},{"type":"essay","q":"كيف تتأكد عمليًا إن كان خاتم فضي مصنوعًا من الفضة النقية (١٠٫٥ جم/سم³) أم لا دون إتلافه؟","model":"نقيس كتلته بميزان دقيق وحجمه بالإزاحة، ثم نحسب كثافته (m ÷ V) ونقارنها بـ ١٠٫٥ جم/سم³."}]}},
  {"id":"g9-phy-1-u5-1","grade":"g9","subject":"physics","term":1,"unit":5,"no":1,"title":"حالات المادة","summary":"شرح متحرك لخصائص الحالات الثلاث للمادة (الصلبة والسائلة والغازية) وتحولات الحالة الفيزيائية، ثم أنشطة بثلاثة مستويات.","page":"lesson-states-of-matter.html","video":"","pdf":"","notes":["الصلب: شكل وحجم ثابتان، لا يتدفق ولا ينضغط. السائل: حجم ثابت وشكل متغيّر، يتدفق ولا ينضغط تقريبًا.","الغاز: شكل وحجم متغيّران، يملأ الإناء، وقابل للانضغاط بسهولة وكثافته منخفضة.","تحولات التسخين: الانصهار (صلب ← سائل)، الغليان والتبخر (سائل ← غاز).","تحولات التبريد: التكثّف (غاز ← سائل)، التجمّد (سائل ← صلب).","تثبت درجة حرارة المادة النقية أثناء الانصهار وأثناء الغليان."],"exercises":["قارن بين السائل والغاز من حيث الحجم والشكل وقابلية الانضغاط.","فسّر لماذا تبقى درجة حرارة خليط الماء والثلج ثابتة عند ٠°م أثناء التسخين حتى ينصهر الثلج كله."],"levels":{"easy":[{"type":"mcq","q":"أيُّ حالةٍ للمادة يكون شكلها وحجمها ثابتين؟","options":["البلازما","الصلبة","السائلة","الغازية"],"answer":1,"why":"المواد الصلبة تحافظ على شكلها وحجمها."},{"type":"mcq","q":"تحوّل المادة من الحالة الصلبة إلى السائلة يُسمّى:","options":["تجمّدًا","تكثّفًا","انصهارًا","غليانًا"],"answer":2,"why":"الانصهار هو تحول الصلب إلى سائل بالتسخين."},{"type":"mcq","q":"ما درجة غليان الماء النقي عند الضغط الجوي المعتاد؟","options":["٥٠°م","٣٧°م","٠°م","١٠٠°م"],"answer":3,"why":"يغلي الماء النقي عند ١٠٠°م."},{"type":"mcq","q":"أيُّ حالةٍ تملأ كامل حجم الوعاء الذي توضع فيه؟","options":["الغازية","الصلبة","الجليد","السائلة"],"answer":0,"why":"الغازات تنتشر لتملأ كامل الإناء."}],"medium":[{"type":"mcq","q":"ما الفرق بين التبخّر والغليان؟","options":["الغليان يحدث من السطح فقط","التبخّر يحدث من السطح عند أي حرارة، والغليان في كل السائل عند درجة محددة","التبخّر يحدث عند ١٠٠°م فقط","لا يوجد فرق"],"answer":1,"why":"التبخّر سطحي وتدريجي، والغليان شامل عند درجة الغليان."},{"type":"tfr","q":"تنضغط السوائل بسهولة مثل الغازات عند وضعها في محقنة مغلقة.","answer":false,"reasons":["السوائل غير قابلة للانضغاط تقريبًا لأن جسيماتها متقاربة جدًّا","الصلب فقط ينضغط","نعم تنضغط بسهولة"],"reason":0},{"type":"essay","q":"اذكر أربعة تحوّلات لحالة المادة مع تحديد ما إذا كان كل منها يحتاج تسخينًا أم تبريدًا.","model":"بالتسخين: الانصهار (صلب←سائل) والغليان (سائل←غاز). بالتبريد: التكثّف (غاز←سائل) والتجمّد (سائل←صلب)."},{"type":"tfr","q":"درجة انصهار المادة النقية تساوي درجة تجمّدها.","answer":true,"reasons":["تختلف بـ ١٠٠ درجة","الماء النقي ينصهر ويتجمد عند ٠°م","التجمد أعلى من الانصهار"],"reason":1},{"type":"mcq","q":"ظهور قطرات ماء على السطح الخارجي لكوب عصير بارد في يوم حار يُعدّ مثالًا على:","options":["الانصهار","التسامي","التكثّف","التجمّد"],"answer":2,"why":"تكاثف بخار الماء الموجود في الهواء على السطح البارد."},{"type":"essay","q":"لماذا لا تنضغط المواد الصلبة والسائلة بسهولة بينما تنضغط الغازات بسهولة؟","model":"لأن جسيمات الصلب والسائل متلاصقة تقريبًا دون فراغات كبيرة، بينما تفصل بين جسيمات الغاز مسافات شاسعة."},{"type":"tfr","q":"تحوّل الماء إلى بخار يُعدّ تغيّرًا كيميائيًا يُنتج مادةً جديدة.","answer":false,"reasons":["نعم ينتج مادة جديدة","لا يمكن عكسه","بل هو تغيّر فيزيائي عكوس، فالبخار لا يزال ماءً (H₂O)"],"reason":2}],"hard":[{"type":"mcq","q":"في منحنى تسخين مادة صلبة نقية، ظهرت فترتان أفقيّتان عند ٢٥°م وعند ١١٠°م؛ ماذا تعنيان؟","options":["درجة الغليان ٢٥°م","توقف التسخين","المادة غير نقية","درجة الانصهار ٢٥°م ودرجة الغليان ١١٠°م"],"answer":3,"why":"الثبات الأول للانصهار والثاني للغليان."},{"type":"essay","q":"اشرح سبب ثبات درجة الحرارة أثناء الانصهار رغم استمرار تزويد المادة بالحرارة.","model":"تُستهلك الطاقة الحرارية المضافة في التغلب على قوى التجاذب بين الجسيمات وفصلها جزئيًا بدل زيادة طاقتها الحركية، فتبقى الحرارة ثابتة."},{"type":"tfr","q":"وجود شوائب (كالملح) في الماء يرفع درجة غليانه فوق ١٠٠°م ويخفض درجة تجمّده تحت ٠°م.","answer":true,"reasons":["المواد غير النقية تنصهر وتغلي ضمن مدى حراري وتختلف درجاتها عن المادة النقية","الملح يخفض درجة الغليان","الشوائب لا تؤثر"],"reason":0},{"type":"mcq","q":"ما اسم تحوّل المادة مباشرةً من الصلب إلى الغاز دون المرور بالحالة السائلة (كاليود والجليد الجاف)؟","options":["التسامي","التجمّد","الانصهار","التكثّف"],"answer":0,"why":"التسامي انتقال مباشر من صلب إلى غاز."},{"type":"essay","q":"لماذا نرشّ الملح أحيانًا على الطرق الجليدية في الدول الباردة؟","model":"لأن الملح يخفض درجة تجمّد الماء إلى ما دون ٠°م، فيساعد على انصهار الجليد ومنع انزلاق السيارات."},{"type":"tfr","q":"تتساوى كتلة ١٠٠ جم من الثلج مع كتلة الماء الناتج عن انصهاره بالكامل في وعاء مغلق.","answer":true,"reasons":["تقل الكتلة للنصف","حفظ الكتلة: عدد الجسيمات لا يتغيّر عند تغيّر الحالة","تزداد الكتلة"],"reason":1},{"type":"mcq","q":"أيّ خاصيةٍ تُمكّننا من تمييز عينة ماء نقي عن ماء مخلوط بشوائب في المختبر؟","options":["قياس كتلته","قياس درجة غليانه (١٠٠°م بالضبط) وانصهاره (٠°م بالضبط)","النظر إلى لونه فقط","قياس حجمه"],"answer":1,"why":"المادة النقية لها درجة انصهار وغليان حادة ومحددة."},{"type":"essay","q":"قارن بين التبخّر والغليان في نقطتين على الأقل.","model":"١) التبخّر يحدث عند أي درجة حرارة، والغليان عند درجة الغليان فقط. ٢) التبخّر من السطح فقط، والغليان في جميع أنحاء السائل مع تكوّن فقاعات."},{"type":"tfr","q":"يسبّب التبخّر تبريد السائل المتبقّي لأن أسرع الجسيمات طاقةً هي التي تفلت من السطح.","answer":true,"reasons":["التبخّر يسخّن السائل","أبطأ الجسيمات هي التي تفلت","بمغادرة الجسيمات عالية الطاقة يقل متوسط الطاقة الحركية للباقي فتنخفض حرارته"],"reason":2},{"type":"essay","q":"مادة درجة انصهارها −٣٩°م ودرجة غليانها ٣٥٧°م (الزئبق)؛ ما حالتها الفيزيائية عند درجة حرارة الغرفة (٢٥°م)؟ علّل.","model":"سائلة؛ لأن ٢٥°م تقع بين درجة الانصهار (−٣٩°م) ودرجة الغليان (٣٥٧°م)."}]}},
  {"id":"g9-phy-1-u5-2","grade":"g9","subject":"physics","term":1,"unit":5,"no":2,"title":"نموذج الحركة الجُزيئية البسيطة للمادة","summary":"شرح متحرك لترتيب وحركة الجسيمات في الصلب والسائل والغاز والحركة البراونية كدليل تجريبي، ثم أنشطة بثلاثة مستويات.","page":"lesson-kinetic-particle-model.html","video":"","pdf":"","notes":["نموذج الحركة الجزيئية: تتكوّن المادة من جسيمات صغيرة جدًّا في حركة مستمرة.","الصلب: جسيمات متراصة منتظمة تهتز في مواضع ثابتة. السائل: متقاربة غير منتظمة تنزلق فوق بعضها.","الغاز: جسيمات متباعدة جدًّا تتحرك بسرعة عالية وعشوائية في جميع الاتجاهات.","درجة الحرارة مقياس لمتوسط الطاقة الحركية للجسيمات.","الحركة البراونية: حركة عشوائية متعرّجة لحبيبات الدخان (أو حبوب اللقاح) ناتجة عن تصادم جزيئات الهواء (أو الماء) السريعة بها."],"exercises":["صف ترتيب وحركة الجسيمات في كل من: الصلب، السائل، والغاز.","اشرح كيف تُعدّ الحركة البراونية دليلًا على وجود وحركة جزيئات الهواء."],"levels":{"easy":[{"type":"mcq","q":"كيف تتحرّك الجسيمات في المادة الصلبة؟","options":["تطير عشوائيًا","تنزلق بحرية","تهتزّ حول مواضع ثابتة","تتوقّف تمامًا"],"answer":2,"why":"تهتز الجسيمات في أماكنها الثابتة."},{"type":"mcq","q":"ما الذي نراه تحت المجهر في تجربة الحركة البراونية للدخان؟","options":["سكون تام","خطوط مستقيمة فقط","جزيئات الهواء مباشرةً","حبيبات الدخان تتحرك حركة عشوائية متعرّجة"],"answer":3,"why":"نرى حبيبات الدخان المضيئة ولا نرى جزيئات الهواء."},{"type":"mcq","q":"كيف تتغيّر سرعة جسيمات السائل عند تسخينه؟","options":["تزداد سرعتها","تقل سرعتها","تتوقف","لا تتغير"],"answer":0,"why":"التسخين يزيد الطاقة الحركية للجسيمات."},{"type":"mcq","q":"في أي حالة تنزلق الجسيمات المتقاربة فوق بعضها البعض؟","options":["الصلبة","السائلة","الجليد","الغازية"],"answer":1,"why":"هذا يفسّر تدفق السوائل."}],"medium":[{"type":"mcq","q":"لماذا تستطيع جزيئات الهواء الصغيرة جدًّا تحريك حبيبة دخان أكبر منها بكثير؟","options":["لأن الدخان غاز","بسبب الضوء","لأن جزيئات الهواء تتحرك بسرعة هائلة جدًّا وتصطدم بها بكثرة","لأن جزيئات الهواء أثقل من الدخان"],"answer":2,"why":"السرعة العالية جدًّا لجزيئات الهواء تعطيها زخمًا كافيًا لدفع حبيبة الدخان."},{"type":"tfr","q":"يمكن رؤية جزيئات الهواء نفسها بوضوح باستخدام المجهر الضوئي المدرسي.","answer":false,"reasons":["جزيئات الهواء أصغر بكثير من قدرة المجهر الضوئي؛ نحن نرى حبيبات الدخان فقط ونستدل منها على جزيئات الهواء","المجهر لا يرى الدخان","نعم نرى جزيئات الأكسجين بوضوح"],"reason":0},{"type":"essay","q":"فسّر الحركة البراونية لحبوب اللقاح المعلّقة في قطرة ماء تحت المجهر.","model":"تصطدم جزيئات الماء الصغيرة جدًّا والسريعة بحبوب اللقاح الكبيرة عشوائيًا وبقوة غير متساوية من الجهات المختلفة فتجعلها تتحرك حركة متعرجة."},{"type":"tfr","q":"درجة حرارة الجسم مرتبطة بمتوسط الطاقة الحركية لجسيماته.","answer":true,"reasons":["لا علاقة للحرارة بالحركة","كلما زاد متوسط الطاقة الحركية ارتفعت درجة الحرارة","الحرارة تقيس عدد الجسيمات فقط"],"reason":1},{"type":"mcq","q":"أيّ عبارة تصف جسيمات الغاز بدقة؟","options":["متقاربة وتنزلق","ساكنة في مكانها","متراصة ومنتظمة","متباعدة جدًّا وتتحرك بسرعة وعشوائية"],"answer":3,"why":"التباعد والحركة العشوائية السريعة سمة الغازات."},{"type":"essay","q":"كيف يفسّر نموذج الحركة الجزيئية قدرة الغاز على الانضغاط بسهولة مقارنةً بالسائل؟","model":"في الغاز توجد مسافات فارغة كبيرة جدًّا بين الجسيمات فيمكن تقريبها بالضغط، أما في السائل فالجسيمات متلاصقة تقريبًا."},{"type":"tfr","q":"عند تبريد مادة غازية تقل سرعة جسيماتها وتتقارب تدريجيًا.","answer":true,"reasons":["تزداد سرعتها بالتبريد","تتباعد أكثر","فقدان الطاقة الحرارية يخفض الطاقة الحركية للجسيمات"],"reason":2}],"hard":[{"type":"mcq","q":"لو سخّنّا الهواء داخل خلية الدخان في تجربة الحركة البراونية، ماذا نلاحظ على حركة حبيبات الدخان؟","options":["تصبح حركتها أسرع وأكثر عنفًا","تتباطأ بشدة","تتوقف عن الحركة","تتحرك في خط مستقيم"],"answer":0,"why":"تزداد سرعة جزيئات الهواء فتصبح تصادماتها بحبيبات الدخان أقوى وأسرع."},{"type":"essay","q":"اشرح لماذا يفسّر نموذج الحركة الجزيئية احتفاظ المكعب الصلب بشكله الثابت بينما يأخذ الماء شكل الكوب.","model":"في الصلب الجسيمات مرتّبة في مواضع ثابتة ولا تغادرها (تهتز فقط)، أما في السائل فتنزلق الجسيمات فوق بعضها بحرية فتأخذ شكل الإناء."},{"type":"tfr","q":"تتوقّف جسيمات قطعة ثلج عند −١٠°م عن الحركة تمامًا.","answer":false,"reasons":["لا تزال تهتزّ في مواضعها، ولا تقترب الحركة من أدنى حد لها إلا عند الصفر المطلق (−٢٧٣°م)","الثلج بلا جسيمات","نعم تتوقف عند الصفر المئوي"],"reason":0},{"type":"mcq","q":"ما أدنى درجة حرارة ممكنة نظريًا (الصفر المطلق) التي تصل عندها الطاقة الحركية للجسيمات لأدنى حد؟","options":["−٥٠°م","−٢٧٣°م (٠ كلفن)","−١٠٠°م","٠°م"],"answer":1,"why":"الصفر المطلق هو −٢٧٣٫١٥°م."},{"type":"essay","q":"لماذا يصف العلماء حركة حبيبات الدخان بأنها «عشوائية»؟","model":"لأن اتجاه وسرعة حركتها يتغيران باستمرار وبشكل غير متوقّع نتيجة التصادمات العشوائية غير المتوازنة من جزيئات الهواء."},{"type":"tfr","q":"انتشار رائحة العطر في غرفة ساكنة الهواء يُعدّ دليلًا إضافيًا على حركة جزيئات الغاز.","answer":true,"reasons":["جزيئات العطر ساكنة","تنتقل جزيئات العطر نتيجة حركتها العشوائية وتصادمها مع جزيئات الهواء","ينتقل العطر بالجاذبية فقط"],"reason":1},{"type":"mcq","q":"إذا كان متوسط الطاقة الحركية لجسيمات كوب شاي أكبر من كوب عصير، فهذا يعني أن:","options":["كتلة الشاي أكبر","كثافة الشاي أكبر","درجة حرارة الشاي أعلى من العصير","حجم الشاي أكبر"],"answer":2,"why":"درجة الحرارة مقياس مباشر لمتوسط الطاقة الحركية للجسيمات."},{"type":"essay","q":"صف تغيّر حركة وترتيب الجسيمات عندما ينصهر مكعب ثلج إلى ماء سائل ثم يغلي إلى بخار.","model":"في الثلج تهتز منتظمة متراصة ← عند الانصهار تتفكك الشبكة وتنزلق متقاربة في الماء ← عند الغليان تنفصل تمامًا وتتحرك بسرعة وعشوائية كغاز."},{"type":"tfr","q":"في تجربة الحركة البراونية، تُضاء خلية الدخان من الجانب لتظهر حبيبات الدخان كنقاط ضوئية لامعة على خلفية مظلمة.","answer":true,"reasons":["تُضاء لتسخين الدخان","لرؤية جزيئات الأكسجين","الإضاءة الجانبية تجعل حبيبات الدخان تعكس الضوء فتظهر واضحة جدًّا تحت المجهر"],"reason":2},{"type":"essay","q":"قارن بين جسيمات الصلب والسائل والغاز من حيث: الترتيب، والمسافات، ونوع الحركة.","model":"الصلب: منتظم، متراص، اهتزاز ثابت. السائل: غير منتظم، متقارب، انزلاق. الغاز: عشوائي، متباعد جدًّا، حركة سريعة في كل الاتجاهات."}]}},
  {"id":"g9-phy-1-u5-3","grade":"g9","subject":"physics","term":1,"unit":5,"no":3,"title":"القوى والنظرية الحركية الجُزيئية البسيطة للمادة","summary":"شرح متحرك لقوى التجاذب بين الجسيمات وتفسير الانصهار والغليان والتبخّر والتبريد بالتبخّر بالنظرية الحركية، ثم أنشطة بثلاثة مستويات.","page":"lesson-forces-and-kinetic-model.html","video":"","pdf":"","notes":["قوى التجاذب بين الجسيمات: قوية جدًّا في الصلب، متوسطة في السائل، وضعيفة جدًّا (مهملة) في الغاز.","الانصهار والغليان يحتاجان طاقة حرارية لإضعاف أو كسر قوى التجاذب بين الجسيمات.","التبخّر: إفلات الجزيئات الأسرع (الأعلى طاقةً حركية) من سطح السائل عند أي درجة حرارة.","التبريد بالتبخّر: رحيل الجزيئات الأسرع يخفض متوسط الطاقة الحركية للجزيئات المتبقية فتبرد (مثل العرق والجحلة والثلاجة).","يزداد معدل التبخّر بزيادة: درجة الحرارة، ومساحة السطح، وحركة الهواء (الرياح)."],"exercises":["اشرح بالنظرية الحركية لماذا يجفّ الماء المنسكب على الأرض أسرع من الكمية نفسها في كوب.","فسّر كيف يبرّد العرق جسم الإنسان في يوم حار."],"levels":{"easy":[{"type":"mcq","q":"في أي حالة تكون قوى التجاذب بين الجسيمات أقوى ما يمكن؟","options":["السائلة","الغازية","البخار","الصلبة"],"answer":3,"why":"قوى التجاذب القوية تحفظ شكل الصلب الثابت."},{"type":"mcq","q":"أيّ جزيئات السائل تستطيع الإفلات من السطح أثناء التبخّر؟","options":["الأسرع والأعلى طاقةً حركية","الأبطأ","الأثقل فقط","التي في قاع الكوب"],"answer":0,"why":"تحتاج طاقة كافية للتغلب على قوى التجاذب."},{"type":"mcq","q":"أيُّ ظرفٍ يجعل الملابس المبلّلة تجفّ أسرع؟","options":["يوم بارد ورطب وطي الملابس","يوم حار وعاصف مع فرد الملابس","غرفة مغلقة باردة","إناء ضيق"],"answer":1,"why":"الحرارة + الرياح + مساحة السطح الكبيرة."},{"type":"mcq","q":"ماذا يحدث لدرجة حرارة قطرة كحول على يدك أثناء تبخّرها؟","options":["ترتفع بشدة","تتجمد","تنخفض وتشعر يدك بالبرودة","لا تتغير"],"answer":2,"why":"التبخّر السريع للكحول يسحب الحرارة من الجلد."}],"medium":[{"type":"mcq","q":"كيف تساعد الرياح (تيار الهواء) في تسريع التبخّر؟","options":["تضغط السائل","تزيد قوى التجاذب","تخفض حرارة السائل أولًا","تزيح جزيئات البخار بعيدًا عن السطح فتمنع عودتها للسائل"],"answer":3,"why":"إبعاد البخار يمنع التكثف العكسي ويسرّع التبخّر."},{"type":"tfr","q":"تتحرك جميع جزيئات السائل عند درجة ٢٥°م بالسرعة نفسها تمامًا.","answer":false,"reasons":["تتوزع سرعات الجزيئات بين بطيئة ومتوسطة وسريعة جدًّا، والحرارة تمثّل المتوسط فقط","كلها ساكنة","نعم كلها بنفس السرعة"],"reason":0},{"type":"essay","q":"اذكر العوامل الثلاثة الرئيسة التي تزيد معدل تبخّر سائل.","model":"١) رفع درجة الحرارة. ٢) زيادة مساحة سطح السائل. ٣) زيادة حركة الهواء (الرياح) فوق السطح."},{"type":"tfr","q":"ارتفاع الرطوبة الشديد في الجو يقلّل من سرعة تبخّر العرق ويجعلنا نشعر بحرّ أكبر.","answer":true,"reasons":["الرطوبة تسرّع التبخّر","الهواء المشبع بالبخار يعيد الجزيئات للسطح فيبطئ التبخّر والتبريد","لا علاقة للرطوبة بالتبخّر"],"reason":1},{"type":"mcq","q":"تفسّر النظرية الحركية «الانصهار» بأنه:","options":["إضعاف قوى التجاذب الثابتة حتى تنزلق الجسيمات فوق بعضها","انضغاط الجسيمات","زيادة قوى التجاذب","توقف حركة الجسيمات"],"answer":0,"why":"الطاقة الحرارية تضعف الروابط الثابتة في الشبكة الصلبة."},{"type":"essay","q":"اشرح لماذا يبرد الشاي الساخن أسرع عندما ننفخ فوقه.","model":"النفخ يشكّل تيار هواء يزيح بخار الماء الساخن فوق السطح، فيزيد معدل التبخّر وتغادر الجزيئات الأعلى طاقة أسرع فيبرد الشاي."},{"type":"tfr","q":"في المواد الصلبة ذات درجات الانصهار العالية جدًّا كالحديد، تكون قوى التجاذب بين جسيماتها قوية جدًّا.","answer":true,"reasons":["لا توجد قوى بين ذرات الحديد","قواها ضعيفة جدًّا","تحتاج طاقة حرارية ضخمة لإضعاف هذه القوى وكسرها"],"reason":2}],"hard":[{"type":"mcq","q":"لماذا تستهلك عملية الغليان طاقةً حراريةً أكبر بكثير من عملية الانصهار للكتلة نفسها من الماء؟","options":["لأن البخار أثقل من الماء","لأن الغليان يفصل الجزيئات تمامًا ويكسر كل قوى التجاذب، بينما الانصهار يضعفها فقط","لأن الغليان يبرد الماء","لأن الثلج بلا قوى"],"answer":1,"why":"التغلب الكامل على قوى التجاذب يتطلب طاقة أكبر بكثير."},{"type":"essay","q":"فسّر بالنظرية الحركية لماذا يبرّد الكحول الطبي الجلد أسرع من الماء عند مسح اليد به.","model":"لأن قوى التجاذب بين جزيئات الكحول أضعف منها في الماء، فتفلت جزيئاته الأسرع وتتبحّر بسرعة أكبر بكثير فتمتص حرارة الجلد أسرع."},{"type":"tfr","q":"عند تغطية وعاء ماء ساخن بغطاء محكم يقلّ فقدانه للحرارة عبر التبخّر.","answer":true,"reasons":["الغطاء يحبس البخار فتتساوى سرعة التكثف مع التبخّر ويقل فقد الحرارة","الغطاء يزيد التبخّر","الغطاء يبرد الماء أسرع"],"reason":0},{"type":"mcq","q":"أين تحدث عملية التبخّر في الإناء؟","options":["في قاع الإناء فقط","في منتصف السائل فقط","عند السطح العلوي للسائل فقط","خارج الإناء"],"answer":2,"why":"الجزيئات السطحية فقط قادرة على الإفلات للهواء."},{"type":"essay","q":"كيف تعمل «الجحلة» العُمانية الفخارية على تبريد الماء صيفًا؟ اشرح بالنظرية الحركية.","model":"يتسرب قليل من الماء عبر مسام الفخار للسطح الخارجي، فتفلت الجزيئات الأسرع بالتبخر ساحبًة الطاقة الحرارية من الجرة والماء بداخلها فتنخفض حرارته."},{"type":"tfr","q":"يزداد معدل التبخّر بزيادة مساحة السطح لأن عدد الجزيئات الموجودة على السطح والقادرة على الإفلات يزداد.","answer":true,"reasons":["لأن الجزيئات تصبح أثقل","المزيد من الجزيئات السطحية يعني عددًا أكبر يفلت في الثانية الواحدة","لأن الحرارة ترتفع تلقائيًا"],"reason":1},{"type":"mcq","q":"أيُّ تغييرين يسرّعان تجفيف فوطة مبللة في وقت واحد؟","options":["طيّها ووضعها في كيس مغلق","زيادة رطوبة الغرفة","وضعها في مكان بارد مظلم","نشرها مفرودةً في الشمس مع وجود نسيم هواء"],"answer":3,"why":"مساحة سطح + حرارة + تيار هواء."},{"type":"essay","q":"قارن بين قوى التجاذب في غاز الأكسجين والماء السائل والحديد الصلب عند درجة حرارة الغرفة.","model":"الحديد الصلب: قوية جدًّا. الماء السائل: متوسطة. غاز الأكسجين: ضعيفة جدًّا (مهملة)."},{"type":"tfr","q":"لا يمكن أن يتبخّر الماء إلا بعد أن تصل درجة حرارته إلى ١٠٠°م.","answer":false,"reasons":["يتبخر فقط عند ٠°م","نعم لا يتبخر تحت ١٠٠°م","يتبخر الماء عند أي درجة حرارة (حتى ٢٠°م أو ٣٠°م)، أما ١٠٠°م فهي درجة الغليان"],"reason":2},{"type":"essay","q":"كيف تفسّر وجود قطرات ماء على المرآة في الحمام بعد الاستحمام بالماء الساخن؟","model":"يتبخّر الماء الساخن مكونًا بخارًا غنيًا بالطاقة، وعندما تصطدم جزيئاته بالمرآة الباردة تفقد طاقتها الحركية فتتقارب وتغلب قوى التجاذب فتتكثّف لقطرات سائل."}]}},
  {"id":"g9-phy-1-u5-4","grade":"g9","subject":"physics","term":1,"unit":5,"no":4,"title":"المواد الغازية ونموذج الحركة الجُزيئية البسيطة للمادة","summary":"شرح متحرك لتفسير ضغط الغاز وعلاقة الضغط بدرجة الحرارة وبالحجم (قانون بويل) بالنظرية الحركية، ثم أنشطة بثلاثة مستويات.","page":"lesson-gases-and-kinetic-model.html","video":"","pdf":"","notes":["ينشأ ضغط الغاز من تصادم جزيئاته السريعة باستمرار بجدران الوعاء الذي يحويه.","بثبات الحجم: رفع درجة الحرارة يزيد سرعة الجزيئات ← تصادمات أقوى وأكثر في الثانية ← يرتفع الضغط.","بثبات درجة الحرارة: تقليل الحجم يحصر الجزيئات في مساحة أضيق ← تصادمات أكثر في الثانية ← يرتفع الضغط.","قانون بويل (بثبات الحرارة والكتلة): P₁ × V₁ = P₂ × V₂ (علاقة عكسية بين الضغط والحجم).","التمثيل البياني لـ P مقابل V منحنٍ هابط، ولـ P مقابل 1/V خط مستقيم يمر بنقطة الأصل."],"exercises":["فسّر بالنظرية الحركية لماذا يزداد ضغط الهواء داخل أسطوانة صلبة عند تسخينها.","غاز حجمه ٥٠٠ سم³ تحت ضغط ١٢٠ كيلو باسكال؛ احسب حجمه إذا ارتفع الضغط إلى ٢٠٠ كيلو باسكال بثبات الحرارة."],"levels":{"easy":[{"type":"mcq","q":"ما مصدر ضغط الغاز المحبوس في أسطوانة؟","options":["تصادم جزيئات الغاز بجدران الأسطوانة","وزن الأسطوانة","برودة الغاز","قوة التجاذب بين الجزيئات"],"answer":0,"why":"تصادم الجزيئات المستمر يولد قوة ضغط على الجدران."},{"type":"mcq","q":"ما الصيغة الرياضية لقانون بويل؟","options":["P = d ÷ t","P₁ × V₁ = P₂ × V₂","P = m ÷ V","P₁ ÷ V₁ = P₂ ÷ V₂"],"answer":1,"why":"حاصل ضرب الضغط في الحجم ثابت عند ثبات الحرارة."},{"type":"mcq","q":"إذا سخّنا غازًا في وعاء معدني مغلق ثابت الحجم، فإن ضغطه:","options":["لا يتغيّر","يصبح صفرًا","يرتفع","ينخفض"],"answer":2,"why":"تزداد سرعة الجزيئات فتزداد قوة وتكرار التصادمات."},{"type":"mcq","q":"أيّ كميةٍ يجب أن تبقى ثابتةً لتطبيق قانون بويل؟","options":["الضغط فقط","الحجم فقط","لا شيء","درجة الحرارة وكتلة الغاز"],"answer":3,"why":"قانون بويل يشترط ثبات الحرارة والكتلة."}],"medium":[{"type":"mcq","q":"غاز حجمه ٣٠ سم³ وضغطه ٢٠٠ kPa، تغيّر حجمه إلى ٦٠ سم³ بثبات الحرارة؛ ما ضغطه الجديد؟","options":["١٠٠ kPa","٥٠ kPa","٢٠٠ kPa","٤٠٠ kPa"],"answer":0,"why":"٢٠٠ × ٣٠ ÷ ٦٠ = ١٠٠ kPa."},{"type":"tfr","q":"عند تقليل حجم الغاز بثبات درجة الحرارة، تزداد سرعة جزيئات الغاز.","answer":false,"reasons":["السرعة تعتمد على درجة الحرارة فتبقى ثابتة؛ الذي يزداد هو عدد التصادمات في الثانية لصغر المساحة","نعم تزداد السرعة","تقل السرعة"],"reason":0},{"type":"essay","q":"فسّر بالنظرية الحركية لماذا ينصح بعدم إلقاء عبوات العطور والمبيدات المضغوطة في النار.","model":"عند تسخين الغاز المحبوس تزداد سرعة جزيئاته بشدة فتصطدم بجدار العبوة بقوة وتكرار هائلين، فيرتفع الضغط جدًّا وقد تنفجر العبوة."},{"type":"tfr","q":"العلاقة بين ضغط الغاز وحجمه عند ثبات درجة الحرارة علاقة طردية.","answer":false,"reasons":["نعم طردية","بل علاقة عكسية: كلما قلّ الحجم زاد الضغط (P₁V₁ = P₂V₂)","لا علاقة بينهما"],"reason":1},{"type":"mcq","q":"غاز ضغطه ١٠٠ kPa وحجمه ٤٠٠ سم³؛ ما حجمه إذا أصبح ضغطه ٤٠٠ kPa بثبات الحرارة؟","options":["٤٠٠ سم³","١٠٠ سم³","٢٠٠ سم³","١٦٠٠ سم³"],"answer":1,"why":"١٠٠ × ٤٠٠ ÷ ٤٠٠ = ١٠٠ سم³."},{"type":"essay","q":"فسّر بالنظرية الحركية لماذا يرتفع ضغط الهواء داخل محقنة مغلقة عند دفع المكبس للداخل بثبات الحرارة.","model":"يقلّ الحجم فتقترب الجدران من بعضها وتصطدم الجزيئات بها عدد مرات أكبر في الثانية، مما يزيد القوة المؤثرة على وحدة المساحة فيرتفع الضغط."},{"type":"tfr","q":"عند رسم العلاقة بين الضغط (P) ومقلوب الحجم (1/V) لغاز بثبات الحرارة نحصل على خط مستقيم يمر بالأصل.","answer":true,"reasons":["نحصل على دائرة","نحصل على خط أفقي","لأن P تتناسب طرديًا مع 1/V (عكسيًا مع V)"],"reason":2}],"hard":[{"type":"mcq","q":"فقاعة هواء حجمها ٢ سم³ على عمق يكون فيه الضغط ٣٠٠ kPa؛ كم يصبح حجمها عند السطح (الضغط ١٠٠ kPa) بثبات الحرارة؟","options":["٠٫٦٧ سم³","٣ سم³","٦ سم³","٢٠٠ سم³"],"answer":2,"why":"٣٠٠ × ٢ ÷ ١٠٠ = ٦ سم³."},{"type":"essay","q":"قارن بين سبب زيادة الضغط عند «رفع الحرارة بثبات الحجم» وبين سببه عند «تقليل الحجم بثبات الحرارة».","model":"عند رفع الحرارة تزداد سرعة الجزيئات فتصطدم بقوة أكبر وعدد مرات أكثر. أما عند تقليل الحجم فتبقى السرعة ثابتة لكن تضيق المساحة فتزداد عدد التصادمات في الثانية فقط."},{"type":"tfr","q":"في تجربة التحقق من قانون بويل يجب ضغط الغاز ببطء حتى لا ترتفع درجة حرارته.","answer":true,"reasons":["الضغط السريع يسخّن الغاز ويخلّ بشرط ثبات درجة الحرارة في قانون بويل","الضغط السريع يبرّد الغاز","الحرارة لا تهم"],"reason":0},{"type":"mcq","q":"أسطوانة غاز حجمها ١٠ لتر بضغط ٥٠٠ kPa؛ كم بالونًا حجم كل منها ٢ لتر يمكن ملؤها بضغط ١٠٠ kPa (بثبات الحرارة)؟","options":["١٠ بالونات","٥٠ بالونًا","٥ بالونات","٢٥ بالونًا (أو ٢٠ بالونًا خارج الأسطوانة)"],"answer":3,"why":"الحجم الكلي عند ١٠٠ kPa هو ٥٠ لترًا ÷ ٢ = ٢٥ بالونًا إجماليًا (تبقى ١٠ لترات في الأسطوانة فيُملأ ٢٠ بالونًا)."},{"type":"essay","q":"لماذا يضعف ضغط الهواء في إطارات السيارة قليلًا في الصباح البارد مقارنةً بوقت الظهيرة الحار؟","model":"في البرد تقل الطاقة الحركية وسرعة جزيئات الهواء داخل الإطار فتقل قوة ومعدل تصادماتها بالجدار فينخفض الضغط."},{"type":"tfr","q":"إذا زاد عدد جزيئات الهواء بضخ هواء إضافي في إطار ثابت الحجم والحرارة، يزداد الضغط.","answer":true,"reasons":["يقل الضغط","زيادة عدد الجزيئات تزيد عدد التصادمات في الثانية على جدار الإطار","يبقى ثابتًا"],"reason":1},{"type":"mcq","q":"غاز ضغطه ٨٠ kPa وحجمه ١٥٠ سم³، تمدّد بثبات الحرارة ليصبح حجمه ٢٤٠ سم³؛ ما ضغطه الجديد؟","options":["٥٠ kPa","٤٠ kPa","١٢٨ kPa","٦٠ kPa"],"answer":0,"why":"٨٠ × ١٥٠ ÷ ٢٤٠ = ١٢٠٠٠ ÷ ٢٤٠ = ٥٠ kPa."},{"type":"essay","q":"اذكر فرقًا واحدًا بين ما يحدث لغاز عند تسخينه في «أسطوانة معدنية صلبة» وعند تسخينه في «بالون مطاطي مرن».","model":"في الأسطوانة الصلبة يبقى الحجم ثابتًا فيرتفع الضغط بشدة؛ أما في البالون المرن فيزداد الحجم (يتمدّد البالون) ليبقى الضغط قريبًا من الجوي."},{"type":"tfr","q":"وحدة الباسكال (Pa) في النظام الدولي تساوي نيوتن لكل متر مربع (N/m²).","answer":true,"reasons":["تساوي N × m²","تساوي kg/m³","الضغط = القوة ÷ المساحة = N/m² = Pa"],"reason":2},{"type":"essay","q":"برّر لماذا ينصح الغواصون بالزفير تدريجيًا أثناء الصعود السريع نحو سطح الماء.","model":"لأن الضغط يقلّ بالصعود فيتمدّد الهواء داخل الرئتين وفق قانون بويل، وإذا حبس الغواص أنفاسه قد يسبّب تمدد الهواء تلفًا في الرئتين."}]}},
  {"id":"g9-phy-1-u6-1","grade":"g9","subject":"physics","term":1,"unit":6,"no":1,"title":"التمدّد الحراري","summary":"شرح متحرك لظاهرة التمدد الحراري في الصلب والسائل والغاز وتفسيرها الجزيئي وتطبيقاتها ومشكلاتها، ثم أنشطة بثلاثة مستويات.","page":"lesson-thermal-expansion.html","video":"","pdf":"","notes":["التمدّد الحراري: زيادة حجم المادة بالتسخين ونقصانه (انكماشه) بالتبريد.","بالتسخين تزداد طاقة اهتزاز الجسيمات فتزداد المسافات بينها، بينما يبقى حجم الجسيمات وكتلتها ثابتين.","مقدار التمدد الحراري: الغازات > السوائل > المواد الصلبة.","حلول مشكلات التمدد: فواصل التمدد في الجسور والسكك الحديدية، إرخاء أسلاك الكهرباء، وحلقات التمدد في الأنابيب.","تطبيقات مفيدة: الشريط ثنائي الفلز في الثرموستات (ينحني بالتسخين نحو الفلز الأقل تمددًا)، موازين الحرارة، وفتح الأغطية المعدنية بالماء الساخن."],"exercises":["فسّر كيف يعمل الشريط ثنائي الفلز داخل مكواة الملابس الكهربائية كمنظم حرارة (ثرموستات).","لماذا يضع المهندسون فواصل تمدد في الجسور الفولاذية والخرسانية؟"],"levels":{"easy":[{"type":"mcq","q":"أيُّ حالةٍ للمادة هي الأقل تمدّدًا عند التسخين؟","options":["البخار","المواد الصلبة","الغازات","السوائل"],"answer":1,"why":"قوى التجاذب القوية في الصلب تحدّ من تمدّده."},{"type":"mcq","q":"ما الذي يزداد فعليًا عند تمدّد قضيب معدني بالتسخين؟","options":["حجم الذرات نفسها","كتلة القضيب","المسافات بين الجسيمات","عدد الذرات"],"answer":2,"why":"الكتلة وحجم الذرة ثابتان، والمسافات فقط تزداد."},{"type":"mcq","q":"في أي جهاز يُستخدم الشريط ثنائي الفلز لتنظيم درجة الحرارة تلقائيًا؟","options":["المخبار المدرج","المسطرة","العدسة","المكواة الكهربائية (الثرموستات)"],"answer":3,"why":"ينحني الشريط فيفصل الدائرة الكهربائية عند الحرارة المطلوبة."},{"type":"mcq","q":"لماذا نمرّر ماءً ساخنًا على غطاء معدني عالق لمرطبان زجاجي؟","options":["لأن المعدن يتمدّد أكثر من الزجاج فيتسع ويُفتح بسهولة","لأن الزجاج ينصهر","لأن المعدن ينكمش","لتجميد الغطاء"],"answer":0,"why":"الفلزات تتمدّد بمقدار أكبر من الزجاج."}],"medium":[{"type":"mcq","q":"رتّب حالات المادة تنازليًا من الأكثر تمدّدًا إلى الأقل تمدّدًا بالتسخين:","options":["صلب ← سوائل ← غازات","غازات ← سوائل ← صلب","سوائل ← صلب ← غازات","كلها متساوية"],"answer":1,"why":"الغازات أكثرها تمددًا ثم السوائل ثم الصلب."},{"type":"tfr","q":"عند تسخين قطعة حديد تزداد كتلتها لأنها تتمدّد.","answer":false,"reasons":["الكتلة تبقى ثابتة تمامًا لأن عدد الذرات لم يتغير، والذي يزداد هو الحجم فقط","تقل كتلتها","نعم تزداد كتلتها"],"reason":0},{"type":"essay","q":"اشرح لماذا ينكسر كوب زجاجي سميك أحيانًا عند صبّ ماء مغلي فيه فجأة.","model":"يتمدد السطح الداخلي للزجاج سريعًا بالحرارة بينما يبقى السطح الخارجي باردًا ولم يتمدد بعد، فيتولد إجهاد غير متساوٍ يؤدي لكسر الزجاج."},{"type":"tfr","q":"عند تسخين شريط ثنائي الفلز يتكوّن من نحاس وحديد، ينحني الشريط نحو جهة الحديد لأن النحاس يتمدّد أكثر.","answer":true,"reasons":["ينحني نحو النحاس","الفلز الأكثر تمددًا يصبح على القوس الخارجي الأطول، فينحني الشريط نحو الأقل تمددًا","لا ينحني"],"reason":1},{"type":"mcq","q":"ماذا يحدث لكثافة قضيب نحاسي عند تسخينه وتمدّده؟","options":["تزداد","تصبح صفرًا","تقلّ قليلًا (ثبات الكتلة وزيادة الحجم)","تتضاعف"],"answer":2,"why":"ρ = m ÷ V؛ زيادة V مع ثبات m تقلّل الكثافة."},{"type":"essay","q":"اذكر مشكلتين يسبّبهما التمدّد الحراري في الحياة العملية وكيف يعالجهما المهندسون.","model":"١) التواء قضبان السكك الحديدية والجسور ← تُترك فواصل تمدد. ٢) انقطاع أسلاك الكهرباء شتاءً ← تُترك مرتخية قليلًا عند تركيبها صيفًا."},{"type":"tfr","q":"في تجربة الكرة والحلقة المعدنية، لا تمرّ الكرة الساخنة عبر الحلقة لأن قطرها ازداد بالتمدّد.","answer":true,"reasons":["لأن الكرة انكمشت","لأن الحلقة انكمشت فقط","التسخين يمدد الكرة في جميع الأبعاد فيزداد قطرها"],"reason":2}],"hard":[{"type":"mcq","q":"لماذا يُفضّل استخدام زجاج «البيركس» (Pyrex) في أواني المختبر والفرن؟","options":["لأنه يتمدد أكثر من النحاس","لأنه لا يسخن أبدًا","لأنه معدن","لأن تمدّده الحراري ضئيل جدًّا فلا يتشقق بالتسخين المفاجئ"],"answer":3,"why":"معامل تمدد البيركس منخفض جدًّا فيتحمل تغير الحرارة."},{"type":"essay","q":"صف كيف يعمل منبّه الحريق المعتمد على الشريط ثنائي الفلز.","model":"عند نشوب حريق يسخن الشريط ثنائي الفلز فينحني باتجاه نقطة تلامس كهربائية، فيغلق الدائرة الكهربائية ويرنّ جرس الإنذار."},{"type":"tfr","q":"يجب أن يكون لمادة حشوة الأسنان معدل تمدّد حراري مقارب جدًّا لمعدل تمدد مينا الأسنان.","answer":true,"reasons":["حتى لا تتمدد الحشوة أكثر من السن عند شرب الساخن فتكسره، أو تنكمش أكثر عند البارد فتسقط","يجب أن تتمدد أكثر بكثير","لا علاقة لحشوة الأسنان بالتمدد"],"reason":0},{"type":"mcq","q":"إذا سخّنا لوحًا معدنيًا فيه ثقب دائري في منتصفه، ماذا يحدث لقطر الثقب؟","options":["يزداد قطر الثقب (يتمدد كالمادة المحيطة به)","يبقى ثابتًا تمامًا","يضيق الثقب","يختفي الثقب"],"answer":0,"why":"التمدد الحراري يشبه تكبير صورة فوتوغرافية؛ كل الأبعاد بما فيها الثقب تكبر."},{"type":"essay","q":"لماذا تنفجر أنابيب المياه أحيانًا في الدول شديدة البرودة عندما يتجمد الماء بداخلها؟","model":"لأن الماء شاذّ في سلوكه؛ يتمدد حجمه بنحو ٩٪ عند تجمده إلى جليد، فيولّد ضغطًا هائلًا يشقّ الأنبوب."},{"type":"tfr","q":"يتمدد الهواء داخل بالون بمقدار أكبر بكثير من تمدد حجم مماثل من الماء عند رفع حرارتهما بمقدار ١٠°م.","answer":true,"reasons":["يتمددان بنفس المقدار","الغازات تتمدد أكثر بكثير من السوائل لضعف قوى التجاذب بين جزيئاتها","الماء يتمدد أكثر من الهواء"],"reason":1},{"type":"mcq","q":"عند تثبيت إطار فولاذي على عجلة خشبية (أو برشام ساخن)، لماذا يُسخّن الفولاذ أولًا قبل التركيب؟","options":["لينصهر تمامًا","ليتمدد فيسهل تركيبه، ثم عند تبريده ينكمش ويشدّ بإحكام شديد","لتقليل كتلته","لمنع الصدأ"],"answer":1,"why":"الانكماش بالتبريد يولّد قوة تثبيت هائلة."},{"type":"essay","q":"اشرح لماذا ينصح بالابتعاد عن صبّ الماء البارد جدًّا على صينية زجاجية ساخنة خرجت للتو من الفرن.","model":"ينكمش السطح الخارجي فجأةً بينما يبقى الداخل ساخنًا متمددًا، فيحدث فرق إجهاد يسبّب تحطّم الزجاج."},{"type":"tfr","q":"في تجربة الكرة والحلقة، إذا سخّنا «الحلقة» فقط وبقيت الكرة باردة، فإن الكرة تمرّ بسهولة أكبر.","answer":true,"reasons":["لأن الفتحة تضيق بالتسخين","لأن الكرة تسخن وحدها","لأن تسخين الحلقة يوسّع قطر فتحتها الداخلية"],"reason":2},{"type":"essay","q":"قارن بين تمدّد المواد الصلبة والغازات من حيث السبب الجزيئي لاختلاف مقدار التمدد.","model":"في الصلب قوى التجاذب بين الجسيمات قوية جدًّا فتسمح بزيادة طفيفة فقط في المسافات، بينما في الغاز قوى التجاذب مهملة فتتباعد الجسيمات كثيرًا عند التسخين."}]}},
  {"id":"g9-phy-1-u7-1","grade":"g9","subject":"physics","term":1,"unit":7,"no":1,"title":"درجة الحرارة وموازين الحرارة","summary":"شرح متحرك للفرق بين درجة الحرارة والطاقة الحرارية وأنواع موازين الحرارة (السائل والمزدوجة الحرارية والرقمي) والنقاط الثابتة، ثم أنشطة بثلاثة مستويات.","page":"lesson-temperature-and-thermometers.html","video":"","pdf":"","notes":["درجة الحرارة تقيس متوسط الطاقة الحركية للجسيمات (°C أو K)، بينما الطاقة الحرارية تقيس مجموع طاقة كل الجسيمات (J).","تُعاير موازين السيليزيوس بنقطتين ثابتتين: ٠°م (انصهار الجليد النقي) و ١٠٠°م (بخار الماء النقي المغلي).","الزئبق (−٣٩°م إلى ٣٥٧°م) موصل جيد وسريع لكنه سام؛ الكحول (−١١٥°م إلى ٧٨°م) آمن وللبرد الشديد ولا يصلح للماء المغلي.","الميزان الطبي (٣٥–٤٢°م) يتميز بدقة عالية ووجود اختناق لمنع عودة السائل قبل القراءة.","المزدوجة الحرارية (سلكان من فلزين مختلفين) تولّد جهدًا كهربائيًا وتتميز بمدى واسع جدًّا واستجابة فورية."],"exercises":["في ميزان سائل: طول العمود عند ٠°م هو ٣ سم وعند ١٠٠°م هو ٢٣ سم. احسب درجة الحرارة عندما يكون طول العمود ١٥ سم.","قارن بين الميزان الزئبقي والمزدوجة الحرارية من حيث المدى وسرعة الاستجابة."],"levels":{"easy":[{"type":"mcq","q":"ما النقطة الثابتة السفلى في مقياس السيليزيوس؟","options":["١٠٠°م","٣٧°م","٠°م (درجة انصهار الجليد النقي)","−١٠٠°م"],"answer":2,"why":"تُحدد بوضع المستودع في جليد نقي منصهر."},{"type":"mcq","q":"أيّ سائلٍ يتجمّد عند −١١٥°م فيُستخدم لقياس درجات الحرارة المنخفضة جدًّا؟","options":["الزئبق","الزيت","الماء","الكحول"],"answer":3,"why":"الكحول لا يتجمد إلا عند −١١٥°م."},{"type":"mcq","q":"كم كلفن تساوي درجة حرارة ٢٧°م؟","options":["٣٠٠ كلفن","٣٧٣ كلفن","٢٤٦ كلفن","٢٧ كلفن"],"answer":0,"why":"٢٧ + ٢٧٣ = ٣٠٠ K."},{"type":"mcq","q":"ما الخاصية الفيزيائية التي تعتمد عليها المزدوجة الحرارية؟","options":["تغيّر اللون","تغيّر الجهد الكهربائي بين وصلتَي فلزين مختلفين","انصهار الجليد","تمدّد الكحول"],"answer":1,"why":"فرق الحرارة بين الوصلتين يولّد جهدًا كهربائيًا."}],"medium":[{"type":"mcq","q":"لماذا لا يُستخدم ميزان الكحول لقياس درجة غليان الماء (١٠٠°م)؟","options":["لأن الكحول يتجمد","لأن الكحول سام","لأن الكحول يغلي عند ٧٨°م قبل الوصول إلى ١٠٠°م","لأنه شفاف"],"answer":2,"why":"درجة غليان الكحول ٧٨°م أقل من ١٠٠°م."},{"type":"tfr","q":"درجة الحرارة والطاقة الحرارية هما نفس الكمية الفيزيائية تمامًا.","answer":false,"reasons":["درجة الحرارة تقيس متوسط الطاقة الحركية للجسيم الواحد (°C)، أما الطاقة الحرارية فمجموع طاقات الجسيمات كلها (J)","نعم هما متطابقتان","الطاقة الحرارية تُقاس بـ °C"],"reason":0},{"type":"essay","q":"اشرح كيف تضع علامتَي ٠°م و ١٠٠°م على ميزان حرارة زجاجي غير مدرّج.","model":"نضع المستودع في جليد نقي منصهر ونعلّم مستوى السائل بـ ٠°م، ثم نضعه في بخار ماء نقي يغلي عند الضغط الجوي المعتاد ونعلّم ١٠٠°م، ثم نقسم المسافة إلى ١٠٠ قسم متساوٍ."},{"type":"tfr","q":"تستجيب المزدوجة الحرارية للتغيّرات السريعة جدًّا في درجة الحرارة لأن كتلتها الحرارية عند الوصلة صغيرة جدًّا.","answer":true,"reasons":["لا تقيس الحرارة العالية","تسخن الوصلة المعدنية الصغيرة وتبرد في أجزاء من الثانية فتقيس التغيرات السريعة بدقة","تستجيب ببطء شديد"],"reason":1},{"type":"mcq","q":"ميزان سائل طول عموده عند ٠°م هو ٤ سم وعند ١٠٠°م هو ٢٤ سم؛ كم درجة الحرارة عند طول ١٤ سم؟","options":["٦٠°م","٢٥°م","٤٠°م","٥٠°م"],"answer":3,"why":"[(١٤−٤) ÷ (٢٤−٤)] × ١٠٠ = (١٠ ÷ ٢٠) × ١٠٠ = ٥٠°م."},{"type":"essay","q":"اذكر ميزتين للمزدوجة الحرارية مقارنةً بميزان الحرارة الزئبقي.","model":"١) مدى قياس واسع جدًّا (حتى ١٥٠٠°م). ٢) استجابة سريعة جدًّا للتغيرات، ويمكن ربطها بحاسوب لقراءة البيانات عن بُعد."},{"type":"tfr","q":"في معايرة النقطة العليا (١٠٠°م) نضع مستودع الميزان في «بخار الماء المغلي» وليس في الماء نفسه.","answer":true,"reasons":["لأن الماء لا يغلي","لأن البخار أبرد من الماء","لأن الشوائب ترفع درجة غليان الماء نفسه فوق ١٠٠°م، بينما يبقى البخار المتصاعد نقيًا عند ١٠٠°م"],"reason":2}],"hard":[{"type":"mcq","q":"طول عمود الزئبق في ميزان عند ٠°م هو ١٫٥ سم وعند ١٠٠°م هو ٢١٫٥ سم؛ ما طول العمود عند درجة ٣٥°م؟","options":["٨٫٥ سم","١٠٫٥ سم","٩٫٥ سم","٧٫٠ سم"],"answer":0,"why":"٢٠ سم لكل ١٠٠ درجة = ٠٫٢ سم/درجة ← ٣٥×٠٫٢ = ٧ سم ← ١٫٥ + ٧ = ٨٫٥ سم."},{"type":"essay","q":"لماذا لا يُستخدم الماء كسائل داخل موازين الحرارة الزجاجية؟ (اذكر سببين).","model":"١) يتجمد عند ٠°م ويتمدد عند التجمّد فيكسر الزجاج. ٢) تمدّده غير منتظم بين ٠°م و ٤°م، كما أنه يلتصق بالزجاج وشفاف."},{"type":"tfr","q":"يمكن لميزان حراري رقمي متصل بمزدوجة حرارية تسجيل درجة حرارة لهب أو محرك نفاث عن بُعد بأمان.","answer":true,"reasons":["لأن الإشارة الكهربائية تنتقل عبر أسلاك طويلة إلى شاشة القراءة أو الحاسوب","الزئبق أفضل للمحرك","لا يمكن قياس حرارة المحرك"],"reason":0},{"type":"mcq","q":"أيُّ جسمين له طاقة حرارية أكبر: إناء به ١٠٠ جم ماء عند ٨٠°م أم حوض به ١٠ كجم ماء عند ٥٠°م؟","options":["لا توجد طاقة في الحوض","الحوض (لأن كتلته أكبر بـ ١٠٠ مرة)","متساويان","الإناء"],"answer":1,"why":"الطاقة الحرارية تعتمد على الكتلة ودرجة الحرارة معًا."},{"type":"essay","q":"قارن بين الزئبق والكحول كسائلين في موازين الحرارة من حيث: درجة التجمّد، درجة الغليان، والسمّية.","model":"الزئبق: يتجمد عند −٣٩°م ويغلي عند ٣٥٧°م وسام. الكحول: يتجمد عند −١١٥°م ويغلي عند ٧٨°م وآمن غير سام."},{"type":"tfr","q":"إذا وُضع جسم ساخن (٨٠°م) في تلامس مع جسم بارد (٢٠°م) تنتقل الطاقة الحرارية من الساخن إلى البارد حتى تتساوى درجتا حرارتهما.","answer":true,"reasons":["لا تنتقل الحرارة","تنتقل الحرارة تلقائيًا من الأعلى درجة حرارة للأقل حتى الاتزان الحراري","تنتقل من البارد للساخن"],"reason":1},{"type":"mcq","q":"كم درجة سيليزيوس تعادل ٣١٠ كلفن (درجة حرارة جسم الإنسان)؟","options":["٥٨٣°م","١٠٠°م","٣٧°م","٠°م"],"answer":2,"why":"٣١٠ − ٢٧٣ = ٣٧°م."},{"type":"essay","q":"اشرح لماذا يضاف صبغ أحمر أو أزرق إلى الكحول في موازين الحرارة الكحولية.","model":"لأن الكحول النقي سائل شفاف عديم اللون يصعب رؤيته داخل الأنبوب الشعري الرفيع، فتلوينه يسهّل قراءة التدريج."},{"type":"tfr","q":"في المزدوجة الحرارية، إذا كانت الوصلتان عند درجة الحرارة نفسها تمامًا، فإن قراءة الفولتميتر تكون صفرًا.","answer":true,"reasons":["تكون القراءة عظمى","ينصهر السلك","الجهد الكهربائي ينشأ فقط بسبب وجود فرق في درجة الحرارة بين الوصلتين"],"reason":2},{"type":"essay","q":"اذكر ثلاثة أسباب تجعل الميزان الطبي مختلفًا عن الميزان المخبري العادي.","model":"١) مداه ضيق (٣٥–٤٢°م) مقابل (−١٠ إلى ١١٠°م). ٢) دقته أعلى (٠٫١°م). ٣) يحتوي على اختناق لمنع رجوع السائل قبل القراءة."}]}},
  {"id":"g9-phy-1-u7-2","grade":"g9","subject":"physics","term":1,"unit":7,"no":2,"title":"تصميم ميزان حرارة","summary":"شرح متحرك لخصائص تصميم ميزان الحرارة: الحساسية والمدى والخطّية وسرعة الاستجابة وكيف يغيّرها التصميم، ثم أنشطة بثلاثة مستويات.","page":"lesson-designing-a-thermometer.html","video":"","pdf":"","notes":["الحساسية: طول تمدد عمود السائل لكل تغير قدره ١°م؛ تزيد بتضييق الأنبوب الشعري أو تكبير المستودع أو استخدام سائل أكثر تمددًا.","المدى: الفرق بين أدنى وأعلى درجة يقيسها الميزان؛ يزيد بإطالة الأنبوب أو توسيعه أو تصغير المستودع.","الخطّية: تمدّد السائل بانتظام متساوٍ لكل درجة حرارة مما يعطي تدريجات متساوية المسافة.","سرعة الاستجابة: سرعة وصول الميزان للقراءة الصحيحة؛ تزيد بترقيق زجاج المستودع وتصغير المستودع واستخدام سائل موصل كالزئبق.","مع ثبات طول الأنبوب، زيادة الحساسية تؤدي إلى تقليل المدى."],"exercises":["اقترح طريقتين لزيادة حساسية ميزان حرارة كحولي، وطريقة واحدة لزيادة مداه دون تقليل حساسيته.","لماذا يكون جدار زجاج مستودع الميزان رقيقًا جدًّا بينما يكون زجاج الساق سميكًا؟"],"levels":{"easy":[{"type":"mcq","q":"ما المقصود بـ «مدى» ميزان الحرارة؟","options":["طول المستودع","لون السائل","سمك الزجاج","أدنى إلى أعلى درجة حرارة يستطيع قياسها"],"answer":3,"why":"المدى يحدد نطاق القياس المتاح."},{"type":"mcq","q":"لجعل ميزان حرارة أكثر حساسيةً نستخدم أنبوبًا شعريًا:","options":["أضيق قطرًا","أوسع قطرًا","أقصر","أسمك جدارًا"],"answer":0,"why":"نفس حجم التمدد يرتفع مسافة أطول في الأنبوب الأضيق."},{"type":"mcq","q":"لجعل ميزان الحرارة أسرع استجابةً، يجب أن يكون زجاج المستودع:","options":["معتمًا","رقيقًا جدًّا","بلاستيكيًا سميكًا","سميكًا جدًّا"],"answer":1,"why":"الجدار الرقيق ينقل الحرارة للسائل أسرع."},{"type":"mcq","q":"ما الخاصية التي تعني تساوي المسافات بين التدريجات على طول الميزان؟","options":["الكثافة","الاختناق","الخطّية","المدى"],"answer":2,"why":"التمدد الخطي المنتظم يعطي تدريجات متساوية."}],"medium":[{"type":"mcq","q":"كيف نزيد «مدى» ميزان حرارة دون أن نخسر من «حساسيته»؟","options":["بتوسيع الأنبوب","بتصغير المستودع","بترقيق الزجاج","بإطالة الأنبوب الشعري"],"answer":3,"why":"إطالة الأنبوب تتيح ارتفاع السائل لدرجات أعلى مع بقاء الحساسية نفسها."},{"type":"tfr","q":"زيادة حجم المستودع تجعل الميزان أسرع استجابةً لتغيّر درجة الحرارة.","answer":false,"reasons":["المستودع الأكبر يحتوي على سائل أكثر فيستغرق وقتًا أطول ليسخن كله (أبطأ استجابة)، لكنه يزيد الحساسية","لا يؤثر على الاستجابة","نعم يصبح أسرع استجابة"],"reason":0},{"type":"essay","q":"عرّف كلًّا من «الحساسية» و«الخطّية» في تصميم موازين الحرارة.","model":"الحساسية: مقدار حركة السائل لكل ١°م. الخطّية: تمدّد السائل بمقادير متساوية لكل زيادة متساوية في درجة الحرارة."},{"type":"tfr","q":"الكحول يعطي حساسية أعلى من الزئبق في ميزانين متماثلين لأن الكحول يتمدّد أكثر من الزئبق.","answer":true,"reasons":["الزئبق يتمدد أكثر من الكحول","معامل تمدد الكحول أكبر من الزئبق فيتحرك مسافة أطول لكل درجة","تمددهما متساوٍ"],"reason":1},{"type":"mcq","q":"أيّ ميزانين أكثر حساسية: ميزان يتمدد سائله ٣ مم لكل ١°م، أم ميزان يتمدد ١ مم لكل ١°م؟","options":["الأول (٣ مم/°م)","لا يمكن المعرفة","متساويان","الثاني (١ مم/°م)"],"answer":0,"why":"كلما زادت المسافة لكل درجة زادت الحساسية وسهلت قراءة أجزاء الدرجة."},{"type":"essay","q":"لماذا يُصنع زجاج مستودع الميزان رقيقًا، بينما يُصنع زجاج ساق الميزان سميكًا؟","model":"المستودع رقيق لسرعة انتقال الحرارة واستجابة الميزان، أما الساق فسميكة لحماية الأنبوب الشعري من الكسر ولعملها كعدسة مكبّرة تسهل رؤية خيط السائل."},{"type":"tfr","q":"استخدام أنبوب شعري أوسع يزيد مدى الميزان لكنه يقلّل حساسيته.","answer":true,"reasons":["يقلل المدى","يزيد الحساسية والمدى معًا","في الأنبوب الأوسع يرتفع السائل مسافة أقل لكل درجة فتقل الحساسية ويزداد المدى"],"reason":2}],"hard":[{"type":"mcq","q":"صمّم طالب ميزانًا بحساسية عالية جدًّا لكنه لاحظ أن السائل يفيض ويصل لأعلى الأنبوب عند ٦٠°م فقط؛ ما السبب؟","options":["الزجاج رقيق","المدى أصبح ضيقًا بسبب الأنبوب الضيق جدًّا أو القصير","الاستجابة سريعة","السائل خطّي"],"answer":1,"why":"المقايضة بين الحساسية والمدى عند قصر الأنبوب."},{"type":"essay","q":"قارن بين أثر «تضييق الأنبوب الشعري» و«تكبير المستودع» على كل من: الحساسية، والمدى، وسرعة الاستجابة.","model":"كلاهما يزيد الحساسية ويقلّل المدى (بثبات الطول). لكن تضييق الأنبوب لا يبطئ الاستجابة، بينما تكبير المستودع يبطئ الاستجابة لزيادة كمية السائل."},{"type":"tfr","q":"إذا كان الميزان غير خطّي، فلا يمكن قراءة درجة الحرارة بدقة بتقسيم المسافة بين ٠°م و ١٠٠°م إلى ١٠٠ قسم متساوٍ.","answer":true,"reasons":["لأن التمدد غير المنتظم يعني أن كل سم لا يمثّل عدد الدرجات نفسه في كل جزء من التدريج","يمكن تقسيمه بالتساوي دائمًا","الخطية غير مهمة"],"reason":0},{"type":"mcq","q":"ما أفضل مجموعة مواصفات لتصميم ميزان طبي دقيق وسريع؟","options":["بلا تدريج","سائل ماء + أنبوب قصير","أنبوب ضيق جدًّا + مدى ٣٥–٤٢°م + مستودع رقيق الجدار + اختناق","أنبوب واسع + مدى ٠–٥٠٠°م + زجاج سميك"],"answer":2,"why":"يجمع بين الحساسية العالية وسرعة الاستجابة وسهولة القراءة."},{"type":"essay","q":"لماذا يكون ميزان الزئبق أسرع استجابةً من ميزان الكحول المتماثل معه في الأبعاد؟","model":"لأن الزئبق فلز سائل موصل ممتاز للحرارة فتصل الحرارة إلى جميع أجزائه بسرعة أكبر من الكحول."},{"type":"tfr","q":"السعة الحرارية الصغيرة لمستودع الميزان تضمن أنه لا يمتص حرارةً كبيرةً تغيّر درجة حرارة السائل الصغير الذي نقيسه.","answer":true,"reasons":["المستودع الضخم أفضل للعينات الصغيرة","لو كان المستودع ضخمًا لامتص جزءًا ملحوظًا من حرارة العينة الصغيرة وغيّر قراءتها","لا علاقة له بالعينة"],"reason":1},{"type":"mcq","q":"إذا استبدلنا سائل ميزان بآخر يتمدد نصف مقدار الأول فقط (مع بقاء الأنبوب والمستودع كما هما)، فإن:","options":["المدى يقل للنصف","لا يتغير شيء","الحساسية تتضاعف","الحساسية تقل للنصف والمدى يتضاعف"],"answer":3,"why":"نصف التمدد لكل درجة يعني نصف الحساسية وضعف المدى."},{"type":"essay","q":"اقترح مواصفات ميزان حرارة مناسب لقياس حرارة غرفة المختبر بدقة ٠٫٥°م ضمن المدى ١٠°م إلى ٤٠°م.","model":"أنبوب شعري ضيق نسبيًا لحساسية عالية، بطول يكفي للمدى ١٠–٤٠°م، وجدار مستودع رقيق لاستجابة سريعة، وسائل كحول ملوّن خطّي وآمن."},{"type":"tfr","q":"بعض موازين الحرارة الزجاجية تكون مقطعيًا مثلثة الشكل (منشورية) لتكبير صورة خيط السائل الرفيع.","answer":true,"reasons":["لتقليل الحساسية","لتقليل المدى","يعمل الزجاج السميك المقوّس كعدسة مكبّرة تسهل قراءة الأنبوب الشعري الدقيق"],"reason":2},{"type":"essay","q":"لماذا يجب رجّ الميزان الطبي الزئبقي قبل استخدامه لقياس حرارة مريض جديد؟","model":"لأن وجود الاختناق يمنع عودة الزئبق تلقائيًا للمستودع بعد الاستخدام السابق، فالرجّ يعيده تحت ٣٥°م ليبدأ قياسًا صحيحًا."}]}},
  {"id":"g9-phy-1-u8-1","grade":"g9","subject":"physics","term":1,"unit":8,"no":1,"title":"التغيّرات في الطاقة","summary":"شرح متحرك لمفهوم الطاقة وصورها ومخازنها وطرق انتقالها وتحوّلها بين الأشكال المختلفة، ثم أنشطة بثلاثة مستويات.","page":"lesson-energy-changes.html","video":"","pdf":"","notes":["الطاقة هي القدرة على بذل شغل أو إحداث تغيير، وتُقاس بوحدة الجول (J).","أبرز مخازن الطاقة: الحركية، والوضع الجاذبية، والكيميائية، والمرونية (الإجهاد)، والحرارية، والنووية.","طرق انتقال الطاقة الأربع: ميكانيكيًا (بقوة)، كهربائيًا (بتيار)، بالتسخين، وبالإشعاع (ضوء/صوت).","في أي جهاز، تتحول الطاقة الداخلة إلى طاقة مفيدة (تحقق الغرض) وطاقة مهدرة (غالبًا حرارة)."],"exercises":["اكتب سلسلة تحوّلات الطاقة في: (أ) مكواة كهربائية، (ب) مروحة سقف، (ج) سهم ينطلق من قوس مشدود.","حدّد الطاقة المفيدة والطاقة المهدرة في محرك السيارة.","حوّل 3.5 kJ إلى وحدة الجول (J)."],"levels":{"easy":[{"type":"mcq","q":"وحدة قياس الطاقة في النظام الدولي (SI) هي:","options":["الجول (J)","الواط (W)","النيوتن (N)","الباسكال (Pa)"],"answer":0,"why":"تُقاس الطاقة بجميع صورها بوحدة الجول (J)."},{"type":"mcq","q":"الطاقة التي يمتلكها الجسم بسبب ارتفاعه عن سطح الأرض تُسمّى:","options":["الطاقة المرونية","طاقة الوضع الجاذبية","طاقة الحركة","الطاقة النووية"],"answer":1,"why":"الارتفاع عن الأرض يكسب الجسم طاقة وضع جاذبية."},{"type":"mcq","q":"يختزن النابض المضغوط أو الشريط المطاطي المشدود طاقة:","options":["كيميائية","ضوئية","وضع مرونية","نووية"],"answer":2,"why":"تغيّر شكل الجسم المرن يختزن طاقة وضع مرونية (إجهاد)."},{"type":"mcq","q":"تنتقل الطاقة من الشمس إلى الأرض عبر الفضاء بطريقة:","options":["التيار الكهربائي","الحمل","التوصيل","الإشعاع"],"answer":3,"why":"الموجات الكهرومغناطيسية تنقل الطاقة الشمسية عبر الفراغ بالإشعاع."}],"medium":[{"type":"mcq","q":"عند تشغيل مصباح يدوي يعمل ببطارية، فإن تسلسل تحوّل الطاقة هو:","options":["كيميائية ← كهربائية ← ضوئية وحرارية","نووية ← ضوئية ← كيميائية","حركية ← كهربائية ← ضوئية","مرونية ← حرارية ← ضوئية"],"answer":0,"why":"تتحول الطاقة الكيميائية في البطارية إلى كهربائية ثم ضوئية مفيدة وحرارية مهدرة."},{"type":"mcq","q":"تُعادل قيمة 2.4 kJ بوحدة الجول:","options":["0.0024 J","2400 J","240 J","24 J"],"answer":1,"why":"الكيلوجول = ١٠٠٠ جول، إذن 2.4 × 1000 = 2400 J."},{"type":"mcq","q":"أي الجمل التالية يصف «طاقة الحركة» بدقة؟","options":["طاقة يمتلكها الجسم الساكن على ارتفاع معين","طاقة تنتج عن ضغط النوابض فقط","طاقة يمتلكها الجسم بسبب حركته وتعتمد على كتلته وسرعته","طاقة مخزنة في الروابط الكيميائية فقط"],"answer":2,"why":"طاقة الحركة مرتبطة بحركة الجسم وتزداد بزيادة الكتلة والسرعة."},{"type":"tfr","q":"يزداد مقدار طاقة الوضع الجاذبية للجسم كلما ارتفع عن سطح الأرض.","answer":true,"reasons":["لأننا نبذل شغلًا ضد الجاذبية لرفعه فيختزن طاقة وضع أكبر","لأن الجاذبية تنعدم فوق سطح الأرض","لأن كتلته تزداد مع الارتفاع"],"reason":0},{"type":"tfr","q":"تُعد الطاقة الحرارية الناتجة في محرك السيارة طاقةً مفيدةً.","answer":false,"reasons":["لأن الحرارة تتحول كلها إلى بنزين","لأن الغرض من المحرك هو تحريك السيارة، فتُعد الحرارة طاقةً مهدرةً","لأن المحرك لا ينتج حرارة أبدًا"],"reason":1},{"type":"essay","q":"اذكر أربعًا من طرق انتقال الطاقة مع مثال واحد لكل طريقة.","model":"١) ميكانيكيًا: دفع عربة. ٢) كهربائيًا: تيار يسري في مصباح. ٣) بالتسخين: غلي الماء على موقد. ٤) بالإشعاع: ضوء الشمس أو موجات الصوت."},{"type":"essay","q":"تتبّع تحوّلات الطاقة في كرة تُقذف رأسيًا إلى أعلى حتى تعود إلى يدك.","model":"كيميائية في العضلات ← حركية عند الانطلاق ← تتحول تدريجيًا إلى وضع جاذبية حتى تتوقف لحظيًا في أعلى نقطة ← تعود إلى حركية أثناء السقوط."}],"hard":[{"type":"mcq","q":"في البندول البسيط المتأرجح، يكون للجسم أكبر طاقة حركة عند:","options":["نقطة التوقف اللحظي","أعلى نقطة على اليسار","أعلى نقطة على اليمين","أدنى نقطة في مساره (المنتصف)"],"answer":3,"why":"في أدنى نقطة تكون طاقة الوضع أقل ما يمكن وسرعة الكرة أكبر ما يمكن."},{"type":"mcq","q":"عندما تضغط على فرامل السيارة لتتوقف، تتحوّل طاقة الحركة أساسًا إلى:","options":["طاقة حرارية في المكابح والإطارات","طاقة وضع جاذبية","طاقة كيميائية في الوقود","طاقة نووية"],"answer":0,"why":"الاحتكاك في المكابح يحوّل طاقة حركة السيارة إلى طاقة حرارية."},{"type":"mcq","q":"أي الأجهزة التالية يحوّل الطاقة الكهربائية أساسًا إلى طاقة حركية مفيدة؟","options":["السخان الكهربائي","المروحة الكهربائية","الخلية الشمسية","المصباح الكهربائي"],"answer":1,"why":"المحرك الكهربائي في المروحة يحوّل الكهرباء إلى حركة دورانية."},{"type":"mcq","q":"سيارة كتلتها 1000 kg تتحرك بسرعة ثابتة، وشاحنة كتلتها 4000 kg تتحرك بنفس السرعة. أيهما تمتلك طاقة حركة أكبر؟","options":["السيارة","تمتلكان نفس طاقة الحركة","الشاحنة (أربعة أضعاف)","كلاهما صفر"],"answer":2,"why":"عند تساوي السرعة تتناسب طاقة الحركة طرديًا مع الكتلة."},{"type":"tfr","q":"يمكن للطاقة أن تنتقل ميكانيكيًا دون أن تؤثر أي قوة في الجسم.","answer":false,"reasons":["لأن الانتقال الميكانيكي يحدث عبر الأسلاك فقط","لأن القوة تمنع انتقال الطاقة","لأن الانتقال الميكانيكي يتطلب قوةً تحرّك الجسم مسافةً في اتجاهها"],"reason":2},{"type":"tfr","q":"تختزن المياه خلف سدّ عالٍ طاقة وضع جاذبية يمكن استغلالها لتوليد الكهرباء.","answer":true,"reasons":["لأن ارتفاع الماء يمنحه طاقة وضع تتحول إلى حركة تدير التوربينات والمولدات","لأن الماء خلف السد يكون ساخنًا جدًّا","لأن الماء يختزن طاقة مرونية"],"reason":0},{"type":"tfr","q":"في الخلية الشمسية تتحوّل الطاقة الضوئية مباشرة إلى طاقة كهربائية.","answer":true,"reasons":["لأن الشمس تنتج تيارًا عبر الأسلاك","لأن الألواح الكهروضوئية تحوّل إشعاع الشمس مباشرةً إلى تيار كهربائي","لأن الخلية تحرق الوقود لتوليد الكهرباء"],"reason":1},{"type":"essay","q":"قارن بين «مخازن الطاقة» و«طرق انتقال الطاقة» مع ذكر مثالين لكل منهما.","model":"مخازن الطاقة هي الأشكال التي تُحفظ بها الطاقة داخل الجسم أو النظام (مثل الكيميائية والوضع والحركية). أما طرق الانتقال فهي المسارات التي تنتقل بها الطاقة من مخزن لآخر (مثل الانتقال الميكانيكي والكهربائي والتسخين والإشعاع)."},{"type":"essay","q":"فسّر لماذا يسخن هاتفك المحمول بعد استخدامه لفترة طويلة.","model":"لأن جزءًا من الطاقة الكهربائية الداخلة من البطارية يتحول إلى طاقة حرارية مهدرة بسبب مقاومة الدوائر الإلكترونية، بينما الطاقة المفيدة هي الضوء والصوت ومعالجة البيانات."},{"type":"essay","q":"اشرح تحوّلات الطاقة في لعبة القفز بالحبل المطاطي (Bungee Jumping) من لحظة القفز حتى أدنى نقطة.","model":"قبل القفز: طاقة وضع جاذبية عالية ← أثناء السقوط: تتحول إلى طاقة حركة ← عند شد الحبل المطاطي: تتحول طاقة الحركة والوضع إلى طاقة وضع مرونية في الحبل حتى يتوقف القافز لحظيًا في أدنى نقطة."}]}},
  {"id":"g9-phy-1-u8-2","grade":"g9","subject":"physics","term":1,"unit":8,"no":2,"title":"تطبيقات على تغيّرات الطاقة","summary":"شرح متحرك لتطبيقات تحوّل الطاقة في محطات توليد الكهرباء ومصادر الطاقة المتجددة وغير المتجددة، ثم أنشطة بثلاثة مستويات.","page":"lesson-energy-change-applications.html","video":"","pdf":"","notes":["معظم محطات الكهرباء تحوّل مصدر الطاقة إلى حركة تدير توربينًا متّصلًا بمولّد كهربائي.","الخلايا الشمسية (الكهروضوئية) تحوّل الطاقة الضوئية مباشرة إلى كهرباء دون توربين.","المصادر المتجددة: الشمس، الرياح، المياه (السدود)، الأمواج، المدّ والجزر، الحرارية الأرضية، الوقود الحيوي.","المصادر غير المتجددة: الفحم، النفط، الغاز الطبيعي، والوقود النووي (اليورانيوم).","المصادر الثلاثة التي لا يكون أصلها الشمس: النووية، الحرارية الأرضية، والمدّ والجزر."],"exercises":["اكتب سلسلة تحوّلات الطاقة في محطة كهرباء تعمل بالغاز الطبيعي.","اذكر ميزة واحدة وعيبًا واحدًا لكل من: طاقة الرياح والطاقة النووية.","علّل: تُعد الطاقة الكهرومائية ناتجة بشكل غير مباشر عن الشمس."],"levels":{"easy":[{"type":"mcq","q":"الجهاز الذي يحوّل الطاقة الحركية الدورانية في محطة التوليد إلى طاقة كهربائية هو:","options":["المصباح","السخّان الشمسي","البطارية الكيميائية","المولّد الكهربائي"],"answer":3,"why":"المولّد الكهربائي يحوّل حركة التوربين إلى كهرباء."},{"type":"mcq","q":"أي من المصادر الآتية يُصنّف مصدرًا متجددًا للطاقة؟","options":["طاقة الرياح","النفط","الفحم الحجري","اليورانيوم"],"answer":0,"why":"الرياح تتجدد طبيعيًا باستمرار ولا تنفد."},{"type":"mcq","q":"تُحوّل الخلايا الشمسية الطاقة الضوئية مباشرة إلى طاقة:","options":["صوتية","كهربائية","مرونية","نووية"],"answer":1,"why":"الخلايا الكهروضوئية تنتج تيارًا كهربائيًا مباشرًا من الضوء."},{"type":"mcq","q":"ينشأ المدّ والجزر في البحار أساسًا بسبب جاذبية:","options":["الوقود الأحفوري","باطن الأرض","القمر (والشمس)","الرياح فقط"],"answer":2,"why":"جاذبية القمر هي السبب الرئيس لحركة المدّ والجزر."}],"medium":[{"type":"mcq","q":"في محطة توليد كهرباء تعمل بالفحم، ما الترتيب الصحيح لتحوّلات الطاقة؟","options":["نووية ← حركية ← حرارية ← كهربائية","وضع ← حركية ← كيميائية ← كهربائية","حرارية ← كيميائية ← ضوئية ← كهربائية","كيميائية ← حرارية ← حركية ← كهربائية"],"answer":3,"why":"حرق الفحم يحرر حرارة تغلي الماء فينتج بخار يحرّك التوربين والمولد."},{"type":"mcq","q":"أي مجموعة من المصادر التالية لا يعود أصلها إلى الشمس؟","options":["النووية، الحرارية الأرضية، المدّ والجزر","الأمواج، الغاز الطبيعي، الخشب","السدود، النفط، الخلايا الشمسية","الرياح، الوقود الحيوي، الفحم"],"answer":0,"why":"هذه المصادر الثلاثة فقط لا تعتمد على طاقة الشمس."},{"type":"mcq","q":"من أبرز عيوب الطاقة الشمسية والرياح في توليد الكهرباء أنها:","options":["تنتج نفايات إشعاعية خطيرة","متقطّعة وتعتمد على الطقس ووقت اليوم","تُنتج كميات ضخمة من ثاني أكسيد الكربون","تنفد خلال سنوات قليلة"],"answer":1,"why":"شدة الشمس والرياح تتغير بتغير الطقس والليل والنهار."},{"type":"tfr","q":"لا تُنتج محطات الطاقة النووية غاز ثاني أكسيد الكربون أثناء التشغيل، لكنها تُعد غير متجددة.","answer":true,"reasons":["لأن اليورانيوم يتجدد يوميًا","لأنها تحرق الفحم الحجري","لأنها تعتمد على خام اليورانيوم المحدود في الأرض دون احتراق كربوني"],"reason":2},{"type":"tfr","q":"تحتاج الخلايا الشمسية إلى بخار ماء وتوربين لإنتاج الكهرباء.","answer":false,"reasons":["لأنها تحوّل ضوء الشمس مباشرة إلى كهرباء عبر أشباه الموصلات دون توربين","لأنها تحرق الوقود الحيوي","لأنها تعمل بالرياح"],"reason":0},{"type":"essay","q":"قارن بين محطة الوقود الأحفوري ومحطة طاقة الرياح من حيث التجدّد والأثر البيئي والاستمرارية.","model":"الوقود الأحفوري غير متجدد ويلوّث الهواء بغاز CO₂ لكنه يعطي إنتاجًا مستمرًا وموثوقًا. أما الرياح فمتجددة ونظيفة بلا انبعاثات، لكنها متقطّعة تعتمد على سرعة الهواء."},{"type":"essay","q":"فسّر لماذا يُعد الوقود الأحفوري (النفط والغاز) طاقة شمسية مخزّنة قديمًا.","model":"لأنه تكوّن من بقايا نباتات وكائنات بحرية قديمة حصلت على طاقتها من الشمس عبر البناء الضوئي قبل ملايين السنين."}],"hard":[{"type":"mcq","q":"لماذا تُعد الطاقة الحرارية الأرضية أكثر موثوقيةً من الطاقة الشمسية؟","options":["لأنها تتوفر بكثرة في كل مكان على سطح الأرض","لأنها غير متجددة","لأن حرارة باطن الأرض متوفرة باستمرار ليلًا ونهارًا بغض النظر عن الطقس","لأنها لا تحتاج إلى توربينات"],"answer":2,"why":"حرارة باطن الأرض لا تتوقف في الليل أو في الأيام الغائمة."},{"type":"mcq","q":"في المحطة الكهرومائية، أي تحوّل طاقة يحدث فور فتح بوابات السد ليندفع الماء للأسفل؟","options":["طاقة حرارية ← طاقة نووية","طاقة كهربائية ← طاقة وضع","طاقة حركة ← طاقة كيميائية","طاقة وضع جاذبية ← طاقة حركة"],"answer":3,"why":"هبوط الماء يحوّل طاقة وضعه الجاذبية إلى طاقة حركة سريعة."},{"type":"mcq","q":"من الآثار البيئية لبناء السدود الكهرومائية الكبيرة:","options":["غمر مساحات واسعة من الأراضي وتغيير مواطن الكائنات الحية","استنزاف غاز الأكسجين الجوي","تراكم نفايات نووية مشعة","انبعاث كميات هائلة من الدخان والرماد"],"answer":0,"why":"تخزين المياه خلف السد يغمر الأودية والقرى والمواطن الطبيعية."},{"type":"mcq","q":"ما التحوّل الذي يحدث في السخّان الشمسي المثبّت على سطح المنزل؟","options":["طاقة وضع ← طاقة حرارية","طاقة إشعاعية (ضوئية وحرارية) ← طاقة حرارية في الماء","طاقة ضوئية ← طاقة كهربائية ← طاقة حركية","طاقة كيميائية ← طاقة حرارية"],"answer":1,"why":"يمتص السخان الشمسي إشعاع الشمس مباشرة لتسخين الماء دون كهرباء."},{"type":"tfr","q":"يمكن اعتبار الوقود الحيوي «محايدًا كربونيًا» تقريبًا عند إعادة زراعة النباتات.","answer":true,"reasons":["لأن الوقود الحيوي لا يحتوي على كربون","لأن النباتات الجديدة تمتص كمية CO₂ مقاربة لما ينبعث عند حرق الوقود الحيوي","لأن حرق الخشب لا يُنتج ثاني أكسيد الكربون أبدًا"],"reason":1},{"type":"tfr","q":"تعتمد طاقة الرياح على الشمس بصورة غير مباشرة.","answer":true,"reasons":["لأن ضوء الشمس يدفع شفرات التوربين مباشرة","لأن الرياح تنشأ من جاذبية القمر","لأن تسخين الشمس غير المتساوي لسطح الأرض يسبّب فروق ضغط تحرّك الهواء فتنشأ الرياح"],"reason":2},{"type":"tfr","q":"يُعد اليورانيوم مصدرًا متجددًا لأنه ينتج كمية طاقة كبيرة جدًّا من كتلة صغيرة.","answer":false,"reasons":["لأن كميته في القشرة الأرضية محدودة ولا يتجدد طبيعيًا، لذا هو غير متجدد","لأنه لا يُنتج طاقة كافية","لأنه يُصنع من النباتات"],"reason":0},{"type":"essay","q":"اقترح خطةً متكاملةً لتوليد الكهرباء في سلطنة عُمان تجمع بين مصدرين متجددين مع تبرير اختيارك.","model":"الجمع بين محطات الطاقة الشمسية (لاستغلال السطوع الشمسي القوي نهارًا في معظم المحافظات) ومحطات طاقة الرياح (مثل ظفار للاستفادة من الرياح الموسمية ليلًا ونهارًا) مع بطاريات تخزين لضمان استقرار الشبكة."},{"type":"essay","q":"اذكر ثلاث مزايا وثلاثة تحديات للطاقة النووية في توليد الكهرباء.","model":"المزايا: إنتاج كمية طاقة هائلة من وقود قليل، لا تنبعث منها غازات دفيئة (CO₂)، موثوقة ومستمرة. التحديات: نفايات مشعة خطيرة طويلة الأمد، تكلفة بناء وتفكيك عالية جدًّا، مخاطر التسرب الإشعاعي."},{"type":"essay","q":"فسّر لماذا لا تستطيع معظم الدول الاعتماد على الألواح الشمسية وحدها لتشغيل شبكتها الكهربائية طوال ٢٤ ساعة.","model":"لأن إنتاج الألواح الشمسية يتوقف ليلًا ويضعف في الأيام الغائمة، لذا يلزم وجود أنظمة تخزين طاقة ضخمة أو مصادر مساندة مستمرة لتغطية الطلب طوال اليوم."}]}},
  {"id":"g9-phy-1-u8-3","grade":"g9","subject":"physics","term":1,"unit":8,"no":3,"title":"حفظ الطاقة","summary":"شرح متحرك لمبدأ حفظ الطاقة ومخططات سانكي وحساب الكفاءة المئوية للأجهزة، ثم أنشطة بثلاثة مستويات.","page":"lesson-conservation-of-energy.html","video":"","pdf":"","notes":["مبدأ حفظ الطاقة: الطاقة لا تفنى ولا تُستحدث من العدم، ولكن تتحوّل من صورة إلى أخرى.","الطاقة الكلية الداخلة = الطاقة المفيدة + الطاقة المهدرة (المتشتّتة).","في مخطط سانكي: يمثّل عرض السهم مقدار الطاقة بمقياس رسم، ويتفرع السهم الداخل إلى سهم مفيد (مستقيم) ومهدر (منحنٍ).","الكفاءة = (الطاقة المفيدة ÷ الطاقة الكلية الداخلة) × 100%، وليس لها وحدة ولا تتجاوز 100%.","نرفع كفاءة الآلات بالتزييت لتقليل الاحتكاك، والعزل الحراري، والتصميم الانسيابي."],"exercises":["محرك سيارة يستهلك 1000 J من طاقة الوقود، ويحوّل 250 J منها إلى حركة. احسب الطاقة المهدرة وكفاءة المحرك.","مصباح LED كفاءته 80%، إذا كانت الطاقة الداخلة 50 J، فما مقدار الطاقة الضوئية المفيدة؟","اشرح كيف يقلل التزييت من الطاقة المهدرة في تروس الدراجة الهوائية."],"levels":{"easy":[{"type":"mcq","q":"ينصّ مبدأ حفظ الطاقة على أن الطاقة:","options":["تزداد تلقائيًا مع الزمن","تُستحدث داخل المحركات الكهربائية","لا تفنى ولا تُستحدث ولكن تتحوّل من صورة لأخرى","تختفي تمامًا عند توقف الجسم"],"answer":2,"why":"الطاقة الكلية محفوظة دائمًا وتتغير صورها فقط."},{"type":"mcq","q":"في مخطط سانكي، السهم المتجه للأسفل يمثّل عادةً:","options":["الكتلة","الطاقة الداخلة","الطاقة المفيدة","الطاقة المهدرة"],"answer":3,"why":"تُظهر مخططات سانكي الطاقة المهدرة بسهم ينحني للأسفل."},{"type":"mcq","q":"مصباح تدخله 100 J وينتج 15 J ضوءًا مفيدًا؛ كفاءته تساوي:","options":["15%","1.5%","115%","85%"],"answer":0,"why":"(15 ÷ 100) × 100% = 15%."},{"type":"mcq","q":"وحدة قياس الكفاءة هي:","options":["الجول (J)","ليس لها وحدة (نسبة مئوية)","النيوتن (N)","الواط (W)"],"answer":1,"why":"الكفاءة نسبة بين كميتين متماثلتين لذا هي بلا وحدة."}],"medium":[{"type":"mcq","q":"محرّك كهربائي تدخله 600 J، وتبلغ الطاقة المهدرة فيه 180 J. كم تبلغ الطاقة المفيدة وكفاءته؟","options":["780 J وكفاءته 130%","180 J وكفاءته 30%","420 J وكفاءته 70%","420 J وكفاءته 30%"],"answer":2,"why":"المفيدة = 600 − 180 = 420 J، والكفاءة = (420 ÷ 600) × 100% = 70%."},{"type":"mcq","q":"آلة كفاءتها 60% وتستهلك 500 J. ما مقدار الطاقة المفيدة الناتجة؟","options":["200 J","30 J","833 J","300 J"],"answer":3,"why":"المفيدة = 0.60 × 500 = 300 J."},{"type":"mcq","q":"لتقليل الطاقة المهدرة في محرك ميكانيكي نلجأ إلى:","options":["تزييت الأجزاء المتحركة لتقليل الاحتكاك","إزالة الزيت من المحرك","زيادة وزن الأجزاء المتحركة","زيادة خشونة التروس"],"answer":0,"why":"التزييت يقلل الاحتكاك فيقلل تحوّل الحركة إلى حرارة مهدرة."},{"type":"tfr","q":"عندما يتوقف بندول متأرجح بعد عدة دقائق، فإن طاقته تكون قد فنيت.","answer":false,"reasons":["لأن الجاذبية اختفت","لأن طاقته لم تفنَ بل تشتّتت كحرارة في الهواء ونقطة التعليق بسبب المقاومة والاحتكاك","لأن كتلته تلاشت"],"reason":1},{"type":"tfr","q":"مجموع عَرض الأسهم الخارجة في مخطط سانكي يجب أن يساوي عَرض السهم الداخل.","answer":true,"reasons":["لأن كل الأسهم لها نفس اللون","لأن المهدرة تساوي صفرًا دائمًا","تحقيقًا لمبدأ حفظ الطاقة حيث الداخلة = المفيدة + المهدرة"],"reason":2},{"type":"essay","q":"سخّان كهربائي تدخله 2500 J، فينقل 2000 J إلى الماء. احسب: (أ) الطاقة المهدرة، (ب) كفاءة السخان.","model":"أ) الطاقة المهدرة = 2500 − 2000 = 500 J. ب) الكفاءة = (2000 ÷ 2500) × 100% = 80%."},{"type":"essay","q":"لماذا يُنصح باستبدال مصابيح الفتيلة التقليدية بمصابيح LED في المنازل؟","model":"لأن كفاءة مصابيح LED أعلى بكثير (تحوّل نسبة أكبر من الكهرباء إلى ضوء وأقل إلى حرارة مهدرة)، مما يوفّر استهلاك الكهرباء والمال."}],"hard":[{"type":"mcq","q":"جهاز كفاءته 40% أنتج طاقةً مفيدةً مقدارها 120 J. ما مقدار الطاقة الكلية الداخلة؟","options":["200 J","300 J","160 J","48 J"],"answer":1,"why":"الداخلة = المفيدة ÷ الكفاءة = 120 ÷ 0.40 = 300 J."},{"type":"mcq","q":"في مخطط سانكي، عَرض السهم الداخل 10 cm ويمثّل 500 J. إذا كان عَرض سهم الطاقة المفيدة 3 cm، فكم مقدار الطاقة المهدرة؟","options":["500 J","300 J","350 J","150 J"],"answer":2,"why":"كل 1 cm يمثل 50 J. المفيدة = 3 × 50 = 150 J، إذن المهدرة = 500 − 150 = 350 J."},{"type":"mcq","q":"مخترع يدّعي أنه صنع محرّكًا كفاءته 110%. كيف نردّ عليه فيزيائيًا؟","options":["ممكن إذا استخدمنا زيتًا ممتازًا","ممكن في الفضاء فقط","ممكن إذا زادت درجة الحرارة","مستحيل لأنه يناقض مبدأ حفظ الطاقة"],"answer":3,"why":"لا يمكن إنتاج طاقة مفيدة أكبر من الطاقة الداخلة لأن الطاقة لا تُستحدث من العدم."},{"type":"mcq","q":"تبلغ قدرة مصباح 20 W وكفاءته 75%. ما القدرة الضوئية المفيدة التي يشعّها؟","options":["15 W","5 W","25 W","150 W"],"answer":0,"why":"القدرة المفيدة = 0.75 × 20 = 15 W."},{"type":"tfr","q":"يمكن أن تكون كفاءة السخان الكهربائي الموضوع داخل غرفة لتدفئتها قريبة جدًّا من 100%.","answer":true,"reasons":["لأن الحرارة هنا هي الطاقة المفيدة المطلوبة نفسها وليست طاقة مهدرة","لأن السخان يستحدث طاقة جديدة","لأن السخان لا يستهلك كهرباء"],"reason":0},{"type":"tfr","q":"إذا زادت الطاقة المهدرة لجهاز مع ثبات الطاقة الداخلة، فإن كفاءته تزداد.","answer":false,"reasons":["لأن الكفاءة لا تعتمد على المفيدة","لأن زيادة المهدرة تعني نقصان المفيدة فتقل الكفاءة","لأن الطاقة الداخلة تزداد تلقائيًا"],"reason":1},{"type":"tfr","q":"التصميم الانسيابي للسيارات الحديثة يرفع كفاءتها في استهلاك الوقود.","answer":true,"reasons":["لأنه يزيد الاحتكاك مع الطريق","لأنه يزيد كتلة السيارة","لأنه يقلل مقاومة الهواء فيقلل الطاقة المهدرة للتغلب عليها"],"reason":2},{"type":"essay","q":"قارن بين محرك بنزين كفاءته 25% ومحرك كهربائي كفاءته 85% إذا أُمدّ كل منهما بـ 4000 J.","model":"محرك البنزين يعطي 1000 J مفيدة ويهدر 3000 J كحرارة وصوت. أما المحرك الكهربائي فيعطي 3400 J مفيدة ويهدر 600 J فقط؛ لذا المحرك الكهربائي أكثر كفاءة بكثير."},{"type":"essay","q":"صف خطوات رسم مخطط سانكي لمحطة كهرباء تدخلها 1000 J، وتنتج 350 J كهرباء و 650 J حرارة مهدرة بمقياس 1 cm لكل 100 J.","model":"نرسم سهمًا داخلًا من اليسار عرضه 10 cm. يتفرع منه سهم مستقيم لليمين عرضه 3.5 cm (كهرباء مفيدة 350 J)، وسهم ينحني للأسفل عرضه 6.5 cm (حرارة مهدرة 650 J)."},{"type":"essay","q":"محطة توليد كهرباء كفاءتها 40% تنتج 800 MJ كهرباء. احسب الطاقة الكلية الداخلة من الوقود والطاقة الحرارية المهدرة.","model":"الداخلة = 800 ÷ 0.40 = 2000 MJ. الطاقة المهدرة = 2000 − 800 = 1200 MJ."}]}},
  {"id":"g9-phy-1-u8-4","grade":"g9","subject":"physics","term":1,"unit":8,"no":4,"title":"حسابات الطاقة","summary":"شرح متحرك لقانوني طاقة الوضع الجاذبية (ΔEp = mgΔh) وطاقة الحركة (Ek = ½mv²) وتبادل الطاقة أثناء السقوط، ثم أنشطة بثلاثة مستويات.","page":"lesson-energy-calculations.html","video":"","pdf":"","notes":["طاقة الوضع الجاذبية: ΔEp = m × g × Δh (حيث m بـ kg، g ≈ 10 N/kg، Δh بـ m).","طاقة الحركة: Ek = ½ × m × v² (حيث v بـ m/s).","مضاعفة السرعة تضاعف طاقة الحركة ٤ أضعاف لأنها تتناسب مع v².","لحساب السرعة من طاقة الحركة: v = √(2 × Ek ÷ m).","في السقوط الحر (بإهمال مقاومة الهواء): طاقة الوضع المفقودة = طاقة الحركة المكتسبة (mgh = ½mv²)."],"exercises":["احسب طاقة الوضع الجاذبية لصندوق كتلته 8 kg رُفع مسافة 2.5 m (g = 10 N/kg).","سيارة كتلتها 1000 kg تسير بسرعة 20 m/s. احسب طاقة حركتها بالكيلوجول (kJ).","حجر كتلته 0.5 kg سقط من ارتفاع 5 m. احسب طاقة وضعه في الأعلى وسرعته قبل ملامسة الأرض مباشرة (g = 10 N/kg)."],"levels":{"easy":[{"type":"mcq","q":"قانون حساب طاقة الوضع الجاذبية هو:","options":["ΔEp = m ÷ h","ΔEp = m g Δh","ΔEp = ½ m v²","ΔEp = F ÷ t"],"answer":1,"why":"طاقة الوضع الجاذبية تساوي حاصل ضرب الكتلة في شدة الجاذبية في الارتفاع."},{"type":"mcq","q":"قانون حساب طاقة الحركة هو:","options":["Ek = ½ m v","Ek = m v","Ek = ½ m v²","Ek = m g h"],"answer":2,"why":"طاقة الحركة تساوي نصف الكتلة في مربّع السرعة."},{"type":"mcq","q":"جسم كتلته 2 kg يرتفع 5 m عن الأرض (g = 10 N/kg). طاقة وضعه تساوي:","options":["25 J","50 J","10 J","100 J"],"answer":3,"why":"ΔEp = 2 × 10 × 5 = 100 J."},{"type":"mcq","q":"كرة كتلتها 2 kg تتحرك بسرعة 4 m/s. طاقة حركتها تساوي:","options":["16 J","8 J","32 J","4 J"],"answer":0,"why":"Ek = 0.5 × 2 × 4² = 1 × 16 = 16 J."}],"medium":[{"type":"mcq","q":"رُفع جسم وزنه 50 N مسافة رأسية 3 m. ما مقدار طاقة الوضع التي اكتسبها؟","options":["53 J","150 J","1500 J","16.7 J"],"answer":1,"why":"الوزن W = m g = 50 N، إذن ΔEp = W × h = 50 × 3 = 150 J."},{"type":"mcq","q":"جسم كتلته 500 g يتحرّك بسرعة 6 m/s. طاقة حركته تساوي:","options":["3 J","9000 J","9 J","18 J"],"answer":2,"why":"نحوّل الكتلة: 500 g = 0.5 kg. إذن Ek = 0.5 × 0.5 × 36 = 9 J."},{"type":"mcq","q":"إذا تضاعفت سرعة جسم 3 مرات مع ثبات كتلته، فإن طاقة حركته تصبح:","options":["ثابتة","3 أضعاف قيمتها","6 أضعاف قيمتها","9 أضعاف قيمتها"],"answer":3,"why":"طاقة الحركة تتناسب مع v²، وبما أن 3² = 9 فإنها تزداد 9 أضعاف."},{"type":"tfr","q":"لا تعتمد سرعة جسم يسقط سقوطًا حرًّا من ارتفاع معين (بإهمال مقاومة الهواء) على كتلته.","answer":true,"reasons":["لأن الكتلة m تُختصر من طرفي المعادلة mgh = ½mv² فتبقى v = √(2gh)","لأن الأجسام الساقطة ليس لها كتلة","لأن الجاذبية لا تؤثر في الكتلة"],"reason":0},{"type":"tfr","q":"طاقة الوضع لجسم كتلته 4 kg على ارتفاع 2 m أكبر من طاقة وضع جسم كتلته 2 kg على ارتفاع 5 m.","answer":false,"reasons":["لأن الارتفاع لا يؤثر في طاقة الوضع","لأن الأول = 4×10×2 = 80 J والثاني = 2×10×5 = 100 J، فالثاني أكبر","لأنهما متساويان"],"reason":1},{"type":"essay","q":"احسب ارتفاع رفٍّ وُضع عليه كتاب كتلته 1.5 kg فأصبحت طاقة وضعه الجاذبية 30 J (حيث g = 10 N/kg).","model":"Δh = ΔEp ÷ (m × g) = 30 ÷ (1.5 × 10) = 30 ÷ 15 = 2 m."},{"type":"essay","q":"سيارة كتلتها 1200 kg تتحرك بسرعة 10 m/s. احسب طاقة حركتها، ثم احسب طاقة حركتها إذا زادت سرعتها إلى 20 m/s.","model":"عند 10 m/s: Ek = 0.5 × 1200 × 100 = 60,000 J (60 kJ). عند 20 m/s: Ek = 0.5 × 1200 × 400 = 240,000 J (240 kJ) — أي أربعة أضعاف."}],"hard":[{"type":"mcq","q":"جسم كتلته 4 kg وطاقة حركته 200 J. كم تبلغ سرعته؟","options":["10 m/s","50 m/s","100 m/s","25 m/s"],"answer":0,"why":"v = √(2 × 200 ÷ 4) = √100 = 10 m/s."},{"type":"mcq","q":"سقطت تفاحة كتلتها 0.2 kg من شجرة ارتفاعها 5 m (g = 10 N/kg). بإهمال مقاومة الهواء، طاقة حركتها لحظة ملامسة الأرض هي:","options":["1 J","10 J","5 J","100 J"],"answer":1,"why":"Ek في الأسفل = ΔEp في الأعلى = 0.2 × 10 × 5 = 10 J."},{"type":"mcq","q":"قُذفت كرة رأسيًا للأعلى بسرعة 10 m/s (g = 10 N/kg). ما أقصى ارتفاع تصل إليه بإهمال مقاومة الهواء؟","options":["1 m","10 m","5 m","20 m"],"answer":2,"why":"½ v² = g h ← h = v² ÷ (2g) = 100 ÷ 20 = 5 m."},{"type":"mcq","q":"إذا كانت طاقة الوضع لكرة في أعلى منحدر 100 J، ووصلت للأسفل بطاقة حركة 85 J، فأين ذهبت الـ 15 J المتبقية؟","options":["تحوّلت إلى كتلة إضافية","تحوّلت إلى طاقة نووية","اختفت من الكون","تحوّلت إلى حرارة بالاحتكاك ومقاومة الهواء"],"answer":3,"why":"الفرق 15 J تشتّت كحرارة بسبب الاحتكاك ومقاومة الهواء."},{"type":"tfr","q":"تتطلب مضاعفة سرعة سيارة مسافةَ كبحٍ أطول بكثير لأن طاقة حركتها تتضاعف أربع مرات.","answer":true,"reasons":["لأن الاحتكاك ينعدم عند السرعة العالية","لأن وزن السيارة يتضاعف 4 مرات","لأن المكابح تحتاج لبذل شغل أكبر بأربع مرات لتبديد طاقة الحركة المتضاعفة"],"reason":2},{"type":"tfr","q":"إذا زادت كتلة جسم متحرّك إلى الضعف مع ثبات سرعته، تتضاعف طاقة حركته أربع مرات.","answer":false,"reasons":["لأن طاقة الحركة تتناسب طرديًا مع الكتلة m (وليس m²)، فتتضاعف مرتين فقط","لأنها تبقى ثابتة","لأنها تقل للنصف"],"reason":0},{"type":"tfr","q":"يمكن لجسمين مختلفين في الكتلة أن يمتلكا نفس طاقة الحركة إذا تحرّك الأخفّ بسرعة أكبر.","answer":true,"reasons":["لأن السرعة لا تؤثر في طاقة الحركة","لأن زيادة v² للجسم الأخف تعوّض صغر كتلته في المعادلة ½mv²","لأن طاقة الحركة لا تعتمد على الكتلة"],"reason":1},{"type":"essay","q":"عربة ملاهي كتلتها 500 kg تبدأ من السكون على ارتفاع 20 m (g = 10 N/kg). احسب طاقة وضعها في الأعلى وسرعتها في الأسفل بافتراض انعدام الاحتكاك.","model":"ΔEp = 500 × 10 × 20 = 100,000 J (100 kJ). في الأسفل Ek = 100,000 J، إذن v = √(2 × 10 × 20) = √400 = 20 m/s."},{"type":"essay","q":"إذا وصلت عربة الملاهي السابقة إلى الأسفل بسرعة فعلية 18 m/s فقط، احسب مقدار الطاقة المفقودة بالاحتكاك.","model":"Ek الفعلية = 0.5 × 500 × 18² = 250 × 324 = 81,000 J. الطاقة المهدرة بالاحتكاك = 100,000 − 81,000 = 19,000 J (19 kJ)."},{"type":"essay","q":"اشتقّ علاقة السرعة v لجسم يسقط من السكون من ارتفاع h باستخدام مبدأ حفظ الطاقة.","model":"بإهمال مقاومة الهواء: ΔEp المفقودة = Ek المكتسبة ← m g h = ½ m v². بقسمة الطرفين على m: g h = ½ v² ← v² = 2 g h ← v = √(2 g h)."}]}},
  {"id":"g9-phy-1-u8-5","grade":"g9","subject":"physics","term":1,"unit":8,"no":5,"title":"القدرة","summary":"شرح متحرك لمفهوم القدرة وعلاقتها بالطاقة والزمن ووحدة الواط (W) ومقارنة قدرة الأجهزة اليومية، ثم أنشطة بثلاثة مستويات.","page":"lesson-power.html","video":"","pdf":"","notes":["القدرة (P) هي معدل نقل الطاقة أو معدل بذل الشغل بالنسبة للزمن: P = ΔE / t = W / t.","وحدة القدرة هي الواط (W)، ويساوي 1 جول في الثانية (1 W = 1 J/s).","مضاعفات الواط: 1 kW = 1000 W، و 1 MW = 1,000,000 W.","عند ثبات الشغل، كلما قلّ الزمن زادت القدرة (تناسب عكسي مع الزمن)."],"exercises":["اشرح المقصود بقولنا إن قدرة مكواة كهربائية هي 1500 W.","قارن بين الطاقة والقدرة من حيث التعريف والرمز ووحدة القياس.","رفعت رافعتان نفس الكتلة لنفس الارتفاع؛ استغرقت الأولى 10 s والثانية 30 s. قارن بين شغليهما وقدرتيهما."],"levels":{"easy":[{"type":"mcq","q":"تُعرَّف القدرة بأنها:","options":["معدل نقل الطاقة أو بذل الشغل في الثانية","مقدار القوة المؤثرة في الجسم","المسافة المقطوعة في الثانية","كتلة الجسم المتحرك"],"answer":0,"why":"القدرة هي الطاقة المنقولة مقسومةً على الزمن."},{"type":"mcq","q":"تُكافئ وحدة الواط (W):","options":["نيوتن / ثانية (N/s)","جول / ثانية (J/s)","كيلوجرام / ثانية","جول × ثانية (J·s)"],"answer":1,"why":"P = E/t لذا 1 W = 1 J/s."},{"type":"mcq","q":"قيمة 3 kW بوحدة الواط تساوي:","options":["30 W","0.003 W","3000 W","300 W"],"answer":2,"why":"1 kW = 1000 W، إذن 3 × 1000 = 3000 W."},{"type":"mcq","q":"أي الأجهزة المنزلية الآتية له أكبر قدرة عادةً؟","options":["شاحن الهاتف","ساعة الحائط","مصباح LED","غلاية الماء الكهربائية"],"answer":3,"why":"الغلاية الكهربائية تحتاج قدرة عالية (نحو 2000 W) لتسخين الماء بسرعة."}],"medium":[{"type":"mcq","q":"صعد أحمد وسالم (لهما نفس الوزن) الطابق نفسه؛ وصل أحمد في 10 s وسالم في 20 s. أي العبارات صحيحة؟","options":["بذلا نفس الشغل، لكن قدرة أحمد ضعف قدرة سالم","قدرة سالم ضعف قدرة أحمد","لهما نفس القدرة","بذل أحمد ضعف شغل سالم"],"answer":0,"why":"نفس الوزن والارتفاع يعني نفس الشغل، وبما أن زمن أحمد النصف فقدرته الضعف."},{"type":"mcq","q":"قيمة 0.5 MW بوحدة الكيلوواط (kW) تساوي:","options":["5000 kW","500 kW","5 kW","50 kW"],"answer":1,"why":"1 MW = 1000 kW، إذن 0.5 × 1000 = 500 kW."},{"type":"mcq","q":"عند ثبات الطاقة المنقولة، العلاقة بين القدرة والزمن هي علاقة:","options":["ثابتة لا تتغير","طردية","عكسية","لا توجد علاقة"],"answer":2,"why":"من P = E/t، كلما قلّ الزمن t زادت القدرة P."},{"type":"tfr","q":"الجهاز ذو القدرة الأعلى يحوّل كمية أكبر من الطاقة في الثانية الواحدة.","answer":true,"reasons":["لأن الجهاز ذو القدرة الأعلى يعمل زمنًا أطول دائمًا","لأن القدرة لا ترتبط بالطاقة","لأن القدرة تقيس عدد الجولات المحوّلة في كل ثانية"],"reason":2},{"type":"tfr","q":"يمكن أن يبذل شخصان نفس مقدار الشغل وتكون قدرتاهما مختلفتين.","answer":true,"reasons":["إذا أنجز أحدهما الشغل في زمن مختلف عن الآخر","لأن الزمن لا يؤثر في القدرة","لأن الشغل يُقاس بالواط"],"reason":0},{"type":"essay","q":"ما الفرق بين «الطاقة» و«القدرة»؟ وضّح بمثال من حياتك اليومية.","model":"الطاقة هي الكمية الكلية للشغل وتُقاس بالجول (مثل كمية الطاقة اللازمة لغلي لتر ماء)، أما القدرة فهي سرعة نقل هذه الطاقة وتُقاس بالواط (غلاية 2000 W تغلي الماء أسرع من غلاية 1000 W رغم استهلاك نفس الطاقة تقريبًا)."},{"type":"essay","q":"لماذا يكتب المصنّعون قيمة القدرة بالواط (W) على جميع الأجهزة الكهربائية؟","model":"لتوضيح معدل استهلاك الجهاز للطاقة الكهربائية في الثانية، مما يساعد المستهلك على تقدير سرعة أدائه وتكلفة تشغيله واختيار القاطع الكهربائي المناسب."}],"hard":[{"type":"mcq","q":"سيارتان متماثلتان في الكتلة تتسارعان من السكون إلى 100 km/h. السيارة (أ) وصلت في 6 s والسيارة (ب) في 12 s. إذن:","options":["القدرتان متساويتان","الطاقة الحركية النهائية لـ (أ) ضعف (ب)","قدرة محرك (ب) ضعف (أ)","قدرة محرك (أ) ضعف قدرة محرك (ب)"],"answer":3,"why":"اكتسبتا نفس طاقة الحركة، وبما أن (أ) استغرقت نصف الزمن فقدرتها الضعف."},{"type":"mcq","q":"مضخة ماء قدرتها 1.2 kW. هذا يعني أنها تنقل في كل ثانية طاقة مقدارها:","options":["1200 J","12,000 J","120 J","1.2 J"],"answer":0,"why":"1.2 kW = 1200 W = 1200 J/s."},{"type":"mcq","q":"أي الوحدات الآتية لا تُستخدم لقياس القدرة؟","options":["واط (W)","جول × ثانية (J·s)","كيلوواط (kW)","جول / ثانية (J/s)"],"answer":1,"why":"القدرة = جول ÷ ثانية وليس جول × ثانية."},{"type":"mcq","q":"مصباح (س) قدرته 100 W يعمل لمدة 10 s، ومصباح (ص) قدرته 20 W يعمل لمدة 50 s. أيهما استهلك طاقةً أكبر؟","options":["المصباح (ص)","لا يمكن التحديد","استهلكا نفس مقدار الطاقة (1000 J)","المصباح (س)"],"answer":2,"why":"E = P × t: للأول 100 × 10 = 1000 J، وللثاني 20 × 50 = 1000 J."},{"type":"tfr","q":"الجهاز ذو القدرة الأعلى يستهلك دائمًا طاقةً كليةً أكبر بغضّ النظر عن مدة تشغيله.","answer":false,"reasons":["لأن القدرة والطاقة نفس الشيء","لأن الطاقة الكلية تعتمد على القدرة والزمن معًا (E = P × t)، فجهاز قوي يعمل لثوانٍ قد يستهلك طاقة أقل من جهاز ضعيف يعمل لساعات","لأن الزمن لا يدخل في حساب الطاقة"],"reason":1},{"type":"tfr","q":"القدرة تساوي حاصل ضرب القوة في السرعة (P = F × v) لجسم يتحرك بسرعة ثابتة.","answer":true,"reasons":["لأن السرعة تُقاس بالواط","لأن القوة تساوي الزمن","لأن P = W/t = (F × d)/t = F × (d/t) = F × v"],"reason":2},{"type":"tfr","q":"تبلغ قدرة محطة توليد كهرباء 200 MW، وهذا يعادل 200,000 W.","answer":false,"reasons":["لأن 1 MW = 1,000,000 W، إذن 200 MW = 200,000,000 W","لأن الميجاواط أصغر من الواط","لأن 1 MW = 100 W"],"reason":0},{"type":"essay","q":"فسّر لماذا يستطيع مصعد كهربائي حمل 8 أشخاص في 10 ثوانٍ بينما يحتاج صعودهم الدرج سيرًا إلى دقيقة كاملة.","model":"لأن محرك المصعد يمتلك قدرة عالية جدًّا تمكّنه من نقل نفس مقدار طاقة الوضع الجاذبية (mgh) في زمن قصير جدًّا مقارنةً بقدرة عضلات الإنسان."},{"type":"essay","q":"اشرح كيف يمكن لآلة ذات قدرة منخفضة أن تنجز شغلًا كليًا أكبر من آلة ذات قدرة مرتفعة.","model":"عن طريق تشغيل الآلة ذات القدرة المنخفضة لفترة زمنية أطول بكثير، لأن الشغل الكلي W = P × t."},{"type":"essay","q":"أثبت من تعريفي الشغل والقدرة أن وحدة الواط تكافئ (kg·m²/s³).","model":"القدرة P = W/t = (F × d)/t. ووحدة القوة النيوتن = kg·m/s²، وبالضرب في المتر m تصبح الجول = kg·m²/s²، وبالقسمة على الثانية s تصبح الواط = kg·m²/s³."}]}},
  {"id":"g9-phy-1-u8-6","grade":"g9","subject":"physics","term":1,"unit":8,"no":6,"title":"حساب القدرة","summary":"شرح متحرك لتطبيق مثلث القدرة (P = ΔE/t) وحساب القدرة والطاقة والزمن وقدرة رفع الأجسام (mgh/t) بأمثلة محلولة، ثم أنشطة بثلاثة مستويات.","page":"lesson-calculating-power.html","video":"","pdf":"","notes":["مثلث القدرة: P = ΔE / t، ΔE = P × t، t = ΔE / P.","قدرة رفع جسم ضد الجاذبية: P = (m × g × h) / t = (W × h) / t.","لقياس قدرة طالب يصعد درجًا: نضرب كتلته في g في (عدد الدرجات × ارتفاع الدرجة) ثم نقسم على زمن الصعود.","تحويلات ضرورية: 1 min = 60 s، 1 h = 3600 s، 1 kW = 1000 W، 1 kJ = 1000 J."],"exercises":["سخان قدرته 1.5 kW يعمل لمدة 5 دقائق. احسب الطاقة المستهلكة بالكيلوجول.","رافعة ترفع صندوقًا كتلته 120 kg إلى ارتفاع 10 m خلال 24 s (g = 10 N/kg). احسب قدرة الرافعة.","مصباح قدرته 60 W استهلك 18,000 J. احسب مدة تشغيله بالدقائق."],"levels":{"easy":[{"type":"mcq","q":"جهاز ينقل 800 J في 4 s؛ قدرته تساوي:","options":["804 W","3200 W","400 W","200 W"],"answer":3,"why":"P = 800 ÷ 4 = 200 W."},{"type":"mcq","q":"مروحة قدرتها 60 W تعمل لمدة 10 s؛ الطاقة المستهلكة تساوي:","options":["600 J","6000 J","70 J","6 J"],"answer":0,"why":"ΔE = P × t = 60 × 10 = 600 J."},{"type":"mcq","q":"لحساب الزمن من الطاقة والقدرة نستخدم القانون:","options":["t = P ÷ ΔE","t = ΔE ÷ P","t = ΔE − P","t = P × ΔE"],"answer":1,"why":"من مثلث القدرة: t = ΔE ÷ P."},{"type":"mcq","q":"عند تحويل 3 دقائق إلى ثوانٍ نحصل على:","options":["30 s","300 s","180 s","120 s"],"answer":2,"why":"3 × 60 = 180 s."}],"medium":[{"type":"mcq","q":"غلاية قدرتها 2 kW تعمل لمدة دقيقة واحدة. الطاقة المنقولة هي:","options":["1200 J","2 kJ","12 kJ","120 kJ"],"answer":3,"why":"P = 2000 W و t = 60 s ← ΔE = 2000 × 60 = 120,000 J = 120 kJ."},{"type":"mcq","q":"رفع طالب حقيبة كتلتها 6 kg مسافة 2 m خلال 3 s (g = 10 N/kg). قدرته تساوي:","options":["40 W","360 W","20 W","120 W"],"answer":0,"why":"W = 6 × 10 × 2 = 120 J، إذن P = 120 ÷ 3 = 40 W."},{"type":"mcq","q":"مكواة قدرتها 1200 W استهلكت 72,000 J. ما زمن تشغيلها؟","options":["6 s","60 s (دقيقة واحدة)","120 s","600 s"],"answer":1,"why":"t = 72,000 ÷ 1200 = 60 s."},{"type":"tfr","q":"إذا زاد زمن رفع نفس الجسم لنفس الارتفاع إلى الضعف، فإن القدرة تقلّ إلى النصف.","answer":true,"reasons":["لأن الكتلة تقل للنصف","لأن P = W/t فتتناسب القدرة عكسيًا مع الزمن عند ثبات الشغل","لأن الشغل يقل للنصف"],"reason":1},{"type":"tfr","q":"مصباح قدرته 10 W يعمل لمدة ساعة كاملة يستهلك 360 J فقط.","answer":false,"reasons":["لأن المصباح لا يستهلك طاقة","لأن الساعة = 60 s فقط","لأن الساعة = 3600 s، إذن الطاقة = 10 × 3600 = 36,000 J (36 kJ)"],"reason":2},{"type":"essay","q":"صعد طالب كتلته 60 kg درجًا ارتفاعه الكلي 5 m في زمن 12 s (g = 10 N/kg). احسب قدرته.","model":"W = m g h = 60 × 10 × 5 = 3000 J. القدرة P = 3000 ÷ 12 = 250 W."},{"type":"essay","q":"احسب الطاقة التي يستهلكها مكيّف قدرته 2.5 kW عند تشغيله لمدة 20 دقيقة (بالكيلوجول).","model":"P = 2500 W، الزمن t = 20 × 60 = 1200 s. الطاقة = 2500 × 1200 = 3,000,000 J = 3000 kJ (3 MJ)."}],"hard":[{"type":"mcq","q":"مصعد كتلته مع الركاب 800 kg يرتفع 15 m خلال 20 s (g = 10 N/kg). ما القدرة المفيدة لمحرك المصعد؟","options":["60 kW","12 kW","6 kW","600 W"],"answer":2,"why":"W = 800 × 10 × 15 = 120,000 J. P = 120,000 ÷ 20 = 6000 W = 6 kW."},{"type":"mcq","q":"إذا كانت القدرة الكهربائية الداخلة للمصعد السابق 8 kW، فكم تبلغ كفاءته؟","options":["133%","80%","60%","75%"],"answer":3,"why":"الكفاءة = (6 ÷ 8) × 100% = 75%."},{"type":"mcq","q":"تتسارع سيارة كتلتها 1000 kg من السكون إلى سرعة 20 m/s خلال 8 s. ما متوسط القدرة المفيدة لمحركها؟","options":["25 kW","50 kW","200 kW","2.5 kW"],"answer":0,"why":"Ek = 0.5 × 1000 × 400 = 200,000 J. P = 200,000 ÷ 8 = 25,000 W = 25 kW."},{"type":"mcq","q":"مضخة ماء ترفع 300 kg من الماء إلى خزان ارتفاعه 10 m كل دقيقة (g = 10 N/kg). قدرتها المفيدة هي:","options":["50 W","500 W","3000 W","30,000 W"],"answer":1,"why":"W = 300 × 10 × 10 = 30,000 J، الزمن 60 s ← P = 30,000 ÷ 60 = 500 W."},{"type":"tfr","q":"يمكن حساب قدرة جسم يتحرّك بسرعة ثابتة ضد قوة مقاومة F بالقانون P = F × v.","answer":true,"reasons":["لأن الشغل W = F × d، وبقسمته على الزمن t يصبح P = F × (d/t) = F × v","لأن القوة تُقاس بالجول","لأن السرعة تساوي الطاقة"],"reason":0},{"type":"tfr","q":"تحتاج رافعة قدرتها 2 kW إلى 15 ثانية لرفع كتلة 600 kg إلى ارتفاع 5 m (g = 10 N/kg).","answer":true,"reasons":["لأن الزمن = 150 s","لأن الشغل = 600 × 10 × 5 = 30,000 J، والزمن t = 30,000 ÷ 2000 = 15 s","لأن الشغل = 3000 J"],"reason":1},{"type":"tfr","q":"إذا أردنا قياس قدرة طالب يصعد الدرج تجريبيًا، نحتاج فقط إلى ساعة إيقاف وميزان حرارة.","answer":false,"reasons":["نحتاج ميزان حرارة فقط","لا نحتاج لقياس الارتفاع","نحتاج ميزانًا لقياس الكتلة، وشريطًا متريًا لقياس ارتفاع الدرج، وساعة إيقاف لقياس الزمن"],"reason":2},{"type":"essay","q":"صمّم تجربةً عمليةً لقياس قدرتك عند صعود درج المدرسة، موضحًا الأدوات والقياسات والحسابات.","model":"الأدوات: ميزان لقياس كتلتي m (kg)، مسطرة/شريط متري لقياس ارتفاع درجة واحدة وضربه في عدد الدرجات لإيجاد h (m)، وساعة إيقاف لقياس زمن الصعود t (s). ثم أحسب P = (m × 10 × h) ÷ t بوحدة الواط."},{"type":"essay","q":"سيارة تسير بسرعة ثابتة 25 m/s ضد قوة مقاومة هواء واحتكاك مقدارها 800 N. احسب قدرة المحرك المفيدة بالكيلوواط.","model":"P = F × v = 800 × 25 = 20,000 W = 20 kW."},{"type":"essay","q":"رافعة قدرتها الداخلة 5 kW وكفاءتها 60% ترفع حمولةً وزنها 6000 N إلى ارتفاع 12 m. احسب الزمن اللازم لرفع الحمولة.","model":"القدرة المفيدة = 0.60 × 5000 = 3000 W. الشغل المطلوب = 6000 × 12 = 72,000 J. الزمن t = 72,000 ÷ 3000 = 24 s."}]}},
  {"id":"g9-phy-1-u9-1","grade":"g9","subject":"physics","term":1,"unit":9,"no":1,"title":"التوصيل","summary":"شرح متحرك لآلية التوصيل الحراري في المواد الصلبة والفرق بين الموصلات والعوازل ودور الإلكترونات الحرة، ثم أنشطة بثلاثة مستويات.","page":"lesson-conduction.html","video":"","pdf":"","notes":["التوصيل الحراري: انتقال الطاقة الحرارية عبر المادة الصلبة من الطرف الساخن للبارد دون انتقال الجزيئات من مواقعها.","آلية التوصيل: اهتزاز الذرات وتصادمها (في جميع الصلب) + حركة الإلكترونات الحرة السريعة (في الفلزات فقط).","الموصلات الجيدة: الفلزات مثل النحاس والألمنيوم والحديد.","العوازل الحرارية: الخشب، البلاستيك، الزجاج، الصوف، الماء، والهواء الساكن.","لا يحدث التوصيل الحراري في الفراغ لعدم وجود جسيمات."],"exercises":["فسّر بالاعتماد على الجسيمات لماذا يوصل النحاس الحرارة أسرع بكثير من الزجاج.","علّل: تشعر بأن مقبض الباب المعدني أبرد من الباب الخشبي رغم أنهما في نفس درجة حرارة الغرفة.","اشرح كيف تعمل الملابس الصوفية على تدفئة الجسم في الشتاء."],"levels":{"easy":[{"type":"mcq","q":"أفضل المواد الآتية توصيلًا للحرارة هو:","options":["الخشب","الهواء","النحاس","البلاستيك"],"answer":2,"why":"النحاس فلز غني بالإلكترونات الحرة وهو من أفضل الموصلات."},{"type":"mcq","q":"المادة التي تُستخدم لصنع مقابض أواني الطبخ هي:","options":["الألمنيوم","النحاس","الحديد","البلاستيك أو الخشب (عازل)"],"answer":3,"why":"نستخدم العوازل للمقابض لمنع انتقال الحرارة لليد."},{"type":"mcq","q":"تنتقل الحرارة بالتوصيل في اللافلزات الصلبة عن طريق:","options":["اهتزاز الذرات وتصادمها مع المجاورة","الإلكترونات الحرة فقط","الموجات الكهرومغناطيسية","تيارات الحمل"],"answer":0,"why":"اللافلزات لا تحتوي إلكترونات حرة فتعتمد على اهتزاز الذرات فقط."},{"type":"mcq","q":"يُعد الهواء الساكن المحبوس بين ألياف الصوف:","options":["فلزًا سائلًا","عازلًا حراريًا ممتازًا","موصلًا حراريًا قويًا","مصدرًا للحرارة"],"answer":1,"why":"تباعد جزيئات الهواء يجعله عازلًا ممتازًا عند منعه من الحركة."}],"medium":[{"type":"mcq","q":"لماذا توصل الفلزات الحرارة أسرع بكثير من اللافلزات؟","options":["لأن الفلزات خفيفة الوزن","لأن ذرات الفلزات لا تهتز","لوجود إلكترونات حرة تنقل الطاقة بسرعة عبر الفلز","لأن المسافات بين ذرات الفلزات ضخمة"],"answer":2,"why":"حركة الإلكترونات الحرة السريعة وتصادمها بالذرات يسرّع التوصيل جدًّا."},{"type":"mcq","q":"في تجربة مقارنة توصيل قضبان متماثلة من النحاس والحديد والألمنيوم، الشرط الضروري لعدالة التجربة هو:","options":["أن نضع شمعًا أكثر على الحديد","أن يكون النحاس أقصر من الحديد","أن نستخدم لهبًا مختلفًا لكل قضيب","أن تكون القضبان بنفس الطول والسمك وتُسخَّن بنفس اللهب"],"answer":3,"why":"تثبيت المتغيرات (الطول والسمك ومصدر الحرارة) يجعل المقارنة عادلة."},{"type":"mcq","q":"عندما تلمس قطعة معدن وقطعة خشب في نفس الغرفة (20°C)، تبدو قطعة المعدن أبرد لأن:","options":["المعدن يسحب الحرارة من يدك أسرع من الخشب","درجة حرارة المعدن أقل من 20°C","المعدن عازل حراري","الخشب يُنتج حرارة ذاتية"],"answer":0,"why":"المعدن موصل جيد فينقل حرارة يدك الدافئة (37°C) بعيدًا بسرعة."},{"type":"tfr","q":"الماء موصل جيّد للحرارة بالتوصيل.","answer":false,"reasons":["لأن تجربة تسخين أعلى أنبوب الماء وبه ثلج في القاع تثبت أنه موصل رديء بالتوصيل","لأن الماء مادة صلبة","لأن الماء يحتوي إلكترونات حرة"],"reason":0},{"type":"tfr","q":"لا يمكن أن تنتقل الحرارة من الشمس إلى الأرض بالتوصيل.","answer":true,"reasons":["لأن الأرض عازل","لأن الفضاء فراغ لا يحتوي على جسيمات تنقل الاهتزاز أو تتصادم","لأن الشمس باردة"],"reason":1},{"type":"essay","q":"صف باختصار تجربةً عمليةً لإثبات أن الماء موصل رديء للحرارة.","model":"نضع قطعة ثلج مربوطة بثقل (شبك معدني) في قاع أنبوب اختبار مملوء بالماء، ثم نسخّن الجزء العلوي من الأنبوب بلهب بنزن. نلاحظ غليان الماء في الأعلى بينما يبقى الثلج في القاع دون أن ينصهر."},{"type":"essay","q":"لماذا تُصنع قواعد أواني الطبخ الفاخرة أحيانًا من النحاس أو الألمنيوم وتُصنع مقابضها من البلاستيك؟","model":"القاعدة من فلز موصل جيد لتنقل الحرارة بسرعة وانتظام من الموقد إلى الطعام، والمقبض من بلاستيك عازل لحماية اليد من الحرارة."}],"hard":[{"type":"mcq","q":"في النوافذ ذات الزجاج المزدوج، يتم حبس طبقة رقيقة من الهواء (أو الأرجون) بين لوحي الزجاج بهدف:","options":["زيادة توصيل الحرارة للداخل","تقليل انتقال الحرارة بالتوصيل لكون الهواء عازلًا","منع دخول الضوء","زيادة وزن النافذة"],"answer":1,"why":"الهواء المحبوس عازل ممتاز يقلل التوصيل الحراري عبر النافذة."},{"type":"mcq","q":"أي الترتيبات الآتية يُرتّب المواد من الأفضل توصيلًا إلى الأضعف توصيلًا؟","options":["هواء ← زجاج ← حديد ← نحاس","حديد ← نحاس ← هواء ← زجاج","نحاس ← حديد ← زجاج ← هواء","زجاج ← نحاس ← حديد ← هواء"],"answer":2,"why":"النحاس أفضل من الحديد، وكلاهما فلزات أفضل من الزجاج الصلب، والهواء أضعفها."},{"type":"mcq","q":"لماذا تُعد الغازات أضعف المواد توصيلًا للحرارة؟","options":["لأنها أثقل من الفلزات","لأنها تحتوي إلكترونات حرة","لأن جزيئاتها ساكنة لا تتحرك","لأن المسافات بين جزيئاتها كبيرة جدًّا فتقل التصادمات المباشرة"],"answer":3,"why":"تباعد الجزيئات يجعل نقل الطاقة بالتصادم نادرًا وبطيئًا."},{"type":"mcq","q":"تنفش الطيور ريشها في الأيام الباردة بهدف:","options":["حبس طبقة أكبر من الهواء الساكن العازل حول أجسامها","التخلّص من الإلكترونات الحرة","تقليل حجمها","زيادة فقدان الحرارة بالتوصيل"],"answer":0,"why":"الهواء الساكن المحبوس بين الريش يقلل فقدان حرارة جسم الطائر."},{"type":"tfr","q":"في الصيف الحار بعُمان، يبدو مقبض السيارة المعدني أسخن بكثير من مقعد القماش رغم تساوي حرارتهما.","answer":true,"reasons":["لأن القماش أبرد دائمًا بـ 20 درجة","لأن المعدن عازل","لأن المعدن موصل جيد فينقل الحرارة من المقبض الساخن إلى يدك بسرعة كبيرة"],"reason":2},{"type":"tfr","q":"إزالة الهواء تمامًا (التفريغ) بين جدارَي الترمس تمنع انتقال الحرارة بالتوصيل.","answer":true,"reasons":["لأن التوصيل يتطلب وجود جسيمات مادية، والفراغ خالٍ من الجسيمات","لأن الفراغ يوصل الحرارة بسرعة","لأن الزجاج فلز"],"reason":0},{"type":"tfr","q":"تعتمد سرعة التوصيل الحراري في الفلزات على اهتزاز الذرات وحده دون أي دور للإلكترونات.","answer":false,"reasons":["لأن الفلزات بلا إلكترونات","بل للإلكترونات الحرة الدور الأكبر والأسرع في التوصيل الحراري داخل الفلزات","لأن ذرات الفلز لا تهتز"],"reason":1},{"type":"essay","q":"قارن بين آلية التوصيل الحراري في قضيب من الألمنيوم وقضيب من الزجاج.","model":"في الزجاج (لافلز): ينتقل التوصيل ببطء عبر اهتزاز الذرات وتصادمها مع جيرانها فقط. في الألمنيوم (فلز): بالإضافة لاهتزاز الذرات، تكتسب الإلكترونات الحرة طاقة وتتحرك بسرعة كبيرة عبر الفلز لتصطدم بالذرات البعيدة فتنقل الحرارة بسرعة فائقة."},{"type":"essay","q":"لماذا يُستخدم الفوم (البوليسترين الممدد) والصوف الصخري في عزل جدران وأسطح المباني الحديثة؟","model":"لأن بنيتهما المسامية تحبس ملايين الفقاعات الدقيقة من الهواء الساكن، مما يقلل التوصيل الحراري ويمنع تسرب حرارة الصيف للداخل ويوفر طاقة التكييف."},{"type":"essay","q":"فسّر لماذا يضع الطباخون أحيانًا قفازًا سميكًا من القماش عند إمساك صينية ساخنة من الفرن.","model":"لأن القماش السميك مادة عازلة تحبس الهواء داخل أليافها، فتبطئ جدًّا انتقال الحرارة بالتوصيل من الصينية المعدنية الساخنة إلى اليد."}]}},
  {"id":"g9-phy-1-u9-2","grade":"g9","subject":"physics","term":1,"unit":9,"no":2,"title":"الحمل الحراري","summary":"شرح متحرك لتيارات الحمل الحراري في السوائل والغازات وعلاقتها بالكثافة، وتطبيقاتها في المكيّف والمدفأة ونسيم البحر والبر، ثم أنشطة بثلاثة مستويات.","page":"lesson-convection.html","video":"","pdf":"","notes":["الحمل الحراري: انتقال الطاقة الحرارية في الموائع (السوائل والغازات) عبر حركة المائع نفسه نتيجة اختلاف الكثافة.","آليته: يسخن المائع ← يتمدد (يزداد حجمه) ← تقل كثافته ← يصعد للأعلى، ويهبط المائع البارد الأكثر كثافة ليحل محله.","لا يحدث الحمل الحراري في المواد الصلبة (لأن جزيئاتها ثابتة المواقع) ولا في الفراغ.","أجهزة التسخين (الغلاية، المدفأة) توضع في الأسفل، وأجهزة التبريد (المكيّف، الفريزر) توضع في الأعلى.","نسيم البحر (نهارًا: من البحر لليابسة) ونسيم البر (ليلًا: من اليابسة للبحر) ينشآن بتيارات الحمل."],"exercises":["فسّر لماذا يُثبّت مكيّف الهواء في أعلى جدار الغرفة.","اشرح بالخطوات كيف ينشأ «نسيم البر» خلال الليل على المناطق الساحلية.","علّل: لا تنتقل الحرارة بالحمل الحراري داخل قضيب من الحديد."],"levels":{"easy":[{"type":"mcq","q":"يحدث انتقال الحرارة بالحمل الحراري في:","options":["الفلزات الصلبة فقط","السوائل والغازات فقط","الفراغ فقط","المواد الصلبة فقط"],"answer":1,"why":"تحتاج تيارات الحمل لمائع يستطيع التدفق والحركة."},{"type":"mcq","q":"عند تسخين الهواء في أسفل الغرفة فإنه:","options":["تزداد كتلته ويبقى في الأسفل","يتحوّل إلى مادة صلبة","يتمدد وتقل كثافته فيصعد للأعلى","ينكمش وتزداد كثافته ويهبط"],"answer":2,"why":"التمدد الحراري يقلل الكثافة فيصعد الهواء الدافئ."},{"type":"mcq","q":"تُوضع المدفأة الكهربائية عادةً على أرضية الغرفة (في الأسفل) لكي:","options":["يبقى الهواء الساخن عند الأرض فقط","تمنع التوصيل","تقل كثافة الأرضية","يصعد الهواء الساخن ويهبط البارد فتدفأ الغرفة كلها"],"answer":3,"why":"تيار الحمل الصاعد يوزع الدفء في أنحاء الغرفة."},{"type":"mcq","q":"في ظاهرة نسيم البحر نهارًا، يتحرّك الهواء البارد من:","options":["البحر نحو اليابسة","الأعلى نحو الفضاء","اليابسة نحو البحر","الفضاء نحو البحر"],"answer":0,"why":"يسخن هواء اليابسة ويصعد فيحل محله هواء البحر البارد."}],"medium":[{"type":"mcq","q":"لماذا تُستخدم بلورة برمنجنات البوتاسيوم البنفسجية في تجربة الحمل الحراري بالماء؟","options":["لمنع الماء من التمدد","لتلوين الماء وجعل حركة تيار الحمل مرئيةً بالعين","لتجميد الماء في القاع","لتسخين الماء دون لهب"],"answer":1,"why":"الماء شفاف، واللون البنفسجي يوضح مسار صعود وهبوط تيارات الحمل."},{"type":"mcq","q":"إذا وُضع عنصر التسخين في «أعلى» خزان ماء فقط، فما الذي سيحدث للماء في القاع؟","options":["ستهبط تيارات الحمل الساخنة للقاع","سيغلي أسرع من الماء في الأعلى","سيبقى باردًا تقريبًا لعدم نشوء تيار حمل ولأن الماء موصل رديء","سيتجمد الماء"],"answer":2,"why":"الماء الساخن أقل كثافة فيبقى في الأعلى ولا يهبط للقاع."},{"type":"mcq","q":"سبب هبوب نسيم البر ليلًا هو أن:","options":["الجاذبية تنعكس ليلًا","كثافة الهواء الساخن أكبر من البارد","اليابسة تسخن ليلًا أكثر من البحر","البحر يبقى أدفأ من اليابسة فيصعد هواؤه ويندفع هواء اليابسة نحوه"],"answer":3,"why":"تفقد اليابسة حرارتها ليلًا أسرع من البحر فيبقى هواء البحر أدفأ وأقل كثافة."},{"type":"tfr","q":"يزداد حجم جزيء الهواء نفسه عند تسخينه فيقل وزنه ويصعد للأعلى.","answer":false,"reasons":["لأن الهواء البارد يصعد للأعلى","لأن الهواء ينكمش بالتسخين","لأن الجزيء نفسه لا يكبر، بل تتباعد الجزيئات عن بعضها فيزداد حجم المائع وتقل كثافته"],"reason":2},{"type":"tfr","q":"يُوضع مجمّد الثلاجة (الفريزر) في الجزء العلوي منها لتبريد الثلاجة بكفاءة عبر تيارات الحمل.","answer":true,"reasons":["لأن الهواء الملامس للفريزر يبرد وتزداد كثافته فيهبط لتبريد الرفوف السفلية ويصعد الدافئ مكانه","لأن الهواء البارد يصعد للأعلى","لأن الفريزر يعمل بالتوصيل فقط"],"reason":0},{"type":"essay","q":"اشرح ماذا يحدث في تجربة صندوق الدخان ذي المدخنتين عند إشعال شمعة أسفل إحدى المدخنتين.","model":"يسخن الهواء فوق الشمعة فيتمدد وتقل كثافته ويصعد خارجًا من المدخنة الأولى، فينسحب الهواء البارد ومعه الدخان للأسفل عبر المدخنة الثانية ليحل محله، مشكلًا تيار حمل حراري واضح."},{"type":"essay","q":"لماذا لا تنتقل الحرارة من الشمس إلى الأرض بالحمل الحراري؟","model":"لأن الفضاء بين الشمس والأرض فراغ لا يحتوي على أي سائل أو غاز لتتشكّل فيه تيارات حمل."}],"hard":[{"type":"mcq","q":"تُبنى مداخن المصانع عاليةً جدًّا لأن:","options":["الغازات الساخنة الأقل كثافةً تصعد بقوة للأعلى فتسحب هواءً نقيًا للاحتراق وتُبعد الدخان","المداخن تمنع التمدد","الهواء البارد يصعد لأعلى المدخنة","الحمل الحراري يحدث في الطوب الصلب"],"answer":0,"why":"تيار الحمل الصاعد في المدخنة يطرد الدخان عاليًا ويجلب الأكسجين للموقد."},{"type":"mcq","q":"تستفيد الطيور الجارحة والطائرات الشراعية من تيارات هواء صاعدة دافئة تُسمّى:","options":["الضغط الجوي الساكن","التيارات الحرارية (Thermals)","التوصيل الإلكتروني","الإشعاع تحت الأحمر"],"answer":1,"why":"تسخين الشمس لليابسة يولد تيارات حمل صاعدة ترفع الطيور والطائرات الشراعية."},{"type":"mcq","q":"أثناء اشتعال حريق داخل غرفة مغلقة، لماذا يُنصح بالزحف قريبًا من الأرضية للخروج؟","options":["لأن الأرضية موصل ممتاز","لأن الأكسجين يختفي قرب الأرض","لأن الدخان والغازات الساخنة السامة أقل كثافةً فتصعد وتتركز قرب السقف","لأن الهواء الساخن يهبط للأرض"],"answer":2,"why":"الهواء الأبرد والأقل دخانًا يكون أكثر كثافةً فيبقى قريبًا من الأرضية."},{"type":"mcq","q":"كيف يقلّل حبس الهواء في طبقة رقيقة جدًّا داخل الزجاج المزدوج أو الصوف من «الحمل الحراري»؟","options":["بتحويل الهواء إلى فراغ","بجعل الهواء مادة صلبة","بزيادة كثافة الهواء","بمنع الهواء من الدوران وتشكيل تيارات حمل حرة"],"answer":3,"why":"حبس الهواء في فراغات ضيقة يوقف حركته الدورانية فيقلل الحمل والتوصيل معًا."},{"type":"tfr","q":"لا يمكن حدوث تيارات حمل حراري في محطة فضائية يسودها انعدام الوزن الظاهري.","answer":true,"reasons":["لأن المحطة لا تحتوي هواءً","لأن صعود الأقل كثافة وهبوط الأكثر كثافة يعتمد على وجود الجاذبية (الطفو)","لأن الهواء لا يتمدد في الفضاء"],"reason":1},{"type":"tfr","q":"تنتقل الحرارة عبر سلك نحاسي ساخن بالتوصيل والحمل الحراري معًا داخل السلك.","answer":false,"reasons":["لأن النحاس لا يوصل الحرارة","لأن النحاس مائع","لأن النحاس مادة صلبة فلا يحدث فيه حمل حراري، بل توصيل فقط"],"reason":2},{"type":"tfr","q":"في سخان الماء الشمسي، يتدفق الماء الساخن من اللوح إلى «أعلى» الخزان تلقائيًا دون مضخة أحيانًا.","answer":true,"reasons":["بفضل تيار الحمل الحراري الطبيعي حيث يصعد الماء الساخن الأقل كثافةً للأعلى ويهبط البارد للوح","لأن الماء الساخن أثقل","بسبب التوصيل في الماء"],"reason":0},{"type":"essay","q":"قارن بين التوصيل الحراري والحمل الحراري من حيث: (١) الوسط الذي يحدثان فيه، (٢) حركة المادة نفسها.","model":"التوصيل يحدث أساسًا في المواد الصلبة ولا تتحرك الجزيئات من مواقعها بل تهتز وتنقل الطاقة (مع الإلكترونات الحرة في الفلزات). أما الحمل فيحدث في الموائع (السوائل والغازات) وتتحرك فيه كتل المائع نفسها صعودًا وهبوطًا لاختلاف الكثافة."},{"type":"essay","q":"تخيّل أن غلاية ماء وُضع عنصر تسخينها في منتصف ارتفاعها بدلًا من قاعها. توقّع درجة حرارة الماء فوق العنصر وأسفله بعد دقيقتين.","model":"سيسخن الماء «فوق» العنصر بسرعة بفضل تيارات الحمل الصاعدة، بينما يبقى الماء «أسفل» العنصر باردًا تقريبًا لأن الماء الساخن لا يهبط والماء موصل رديء."},{"type":"essay","q":"اشرح كيف تساهم تيارات الحمل الحراري في حركة الرياح وتغيّر الطقس على كوكب الأرض.","model":"تسخّن الشمس المناطق الاستوائية أكثر من القطبين، فيتمدد الهواء الدافئ وتقل كثافته ويصعد للأعلى، فيندفع الهواء الأبرد الأكثر كثافةً من المناطق المجاورة ليحل محله، مما يولّد الرياح العالمية والمحلية."}]}},
  {"id":"g9-phy-1-u9-3","grade":"g9","subject":"physics","term":1,"unit":9,"no":3,"title":"الإشعاع","summary":"شرح متحرك للإشعاع الحراري (الأشعة تحت الحمراء) وقدرته على عبور الفراغ وتأثير لون وملمس السطح في الامتصاص والانبعاث، ثم أنشطة بثلاثة مستويات.","page":"lesson-radiation.html","video":"","pdf":"","notes":["الإشعاع الحراري: انتقال الطاقة الحرارية عبر موجات كهرومغناطيسية (أشعة تحت حمراء) دون الحاجة لوسط مادي.","يعبر الإشعاع الفراغ بسرعة الضوء، وتصدره جميع الأجسام وتزداد شدته بارتفاع درجة الحرارة.","السطح الأسود المعتم: أفضل ماصّ وأفضل باعث للإشعاع (وعاكس رديء).","السطح الأبيض أو الفضي اللامع: أفضل عاكس للإشعاع (وماصّ وباعث رديء).","مكعب ليسلي أداة مخبرية لمقارنة قدرة الأسطح المختلفة على إشعاع الحرارة."],"exercises":["علّل: يرتدي الناس في سلطنة عُمان ملابس بيضاء فاتحة في فصل الصيف.","فسّر لماذا يُلفّ الطعام الساخن أو عدّاءو الماراثون ببطانيات/رقائق فضية لامعة.","صف كيف نستخدم مكعب ليسلي لإثبات أن السطح الأسود المعتم يشع حرارة أكثر من الفضي اللامع."],"levels":{"easy":[{"type":"mcq","q":"نوع الموجات المسؤولة عن الإشعاع الحراري هو:","options":["الأشعة تحت الحمراء","موجات الصوت","الإلكترونات الحرة","تيارات الحمل"],"answer":0,"why":"الإشعاع الحراري ينتقل على هيئة موجات كهرومغناطيسية تحت حمراء."},{"type":"mcq","q":"الطريقة التي تنقل الحرارة عبر الفراغ هي:","options":["التوصيل فقط","الإشعاع فقط","الحمل فقط","التوصيل والحمل"],"answer":1,"why":"التوصيل والحمل يحتاجان لوسط مادي، أما الإشعاع فيعبر الفراغ."},{"type":"mcq","q":"أفضل سطح لـ«عكس» الإشعاع الحراري هو:","options":["السطح الأسود المعتم","السطح البني الخشن","السطح الفضي أو الأبيض اللامع","السطح الرمادي المعتم"],"answer":2,"why":"الأسطح اللامعة الفاتحة تعكس معظم الإشعاع الساقط عليها."},{"type":"mcq","q":"تُطلى خزانات المياه والوقود في المناطق الحارة باللون الأبيض أو الفضي اللامع لكي:","options":["تزيد التوصيل الحراري","تزيد كثافة الماء","تمتص أكبر قدر من الحرارة","تعكس إشعاع الشمس فلا تسخن كثيرًا"],"answer":3,"why":"الأبيض والفضي اللامع يقللان امتصاص حرارة الشمس."}],"medium":[{"type":"mcq","q":"أي العبارات الآتية صحيحة عن السطح الأسود المعتم؟","options":["هو أفضل ماصّ وأفضل باعث للإشعاع الحراري","لا يشعّ أي حرارة أبدًا","هو أفضل عاكس للإشعاع","هو أفضل ماصّ لكنه أضعف باعث"],"answer":0,"why":"الماصّ الجيد للإشعاع هو دائمًا باعث جيد أيضًا."},{"type":"mcq","q":"في تجربة «مكعب ليسلي» المملوء بالماء المغلي، يُسجّل كاشف الأشعة تحت الحمراء أعلى قراءة أمام الوجه:","options":["الفضي اللامع","الأسود المعتم","الأبيض اللامع","المصقول اللامع"],"answer":1,"why":"الوجه الأسود المعتم يبث أكبر كمية من الأشعة تحت الحمراء."},{"type":"mcq","q":"متى تبقى درجة حرارة كوكب الأرض ثابتةً تقريبًا؟","options":["عندما تختفي الشمس","عندما تتوقف الأرض عن الإشعاع","عندما يتساوى معدل امتصاص إشعاع الشمس مع معدل إشعاع الأرض للفضاء","عندما يزداد التوصيل عبر الفضاء"],"answer":2,"why":"ثبات الحرارة يعني تساوي معدل الطاقة الممتصة مع الطاقة المشعّة."},{"type":"tfr","q":"لا يُصدر جسم الإنسان أي إشعاع حراري لأن درجة حرارته 37°C فقط.","answer":false,"reasons":["لأن الإشعاع يصدر من الشمس فقط","لأن جميع الأجسام فوق الصفر المطلق تشعّ أشعةً تحت حمراء، وتلتقطها الكاميرات الحرارية","لأن الإنسان لا يفقد حرارة أبدًا"],"reason":1},{"type":"tfr","q":"يبرد إبريق الشاي الفضي اللامع أبطأ من إبريق أسود معتم متماثل له.","answer":true,"reasons":["لأن الأسود عازل حراري","لأن الفضي يمتص حرارة من الغرفة","لأن السطح الفضي اللامع باعث رديء للإشعاع الحراري فيفقد حرارته ببطء أكبر"],"reason":2},{"type":"essay","q":"علّل: تُطلى أنابيب التبريد الموجودة خلف الثلاجة باللون الأسود المعتم.","model":"لأن الأسود المعتم أفضل باعث للإشعاع الحراري، فيساعد على التخلّص السريع من الحرارة المسحوبة من داخل الثلاجة إلى هواء الغرفة."},{"type":"essay","q":"كيف تجعل تجربة مقارنة امتصاص علبتين (سوداء وفضية) لإشعاع مصباح تجربةً عادلةً؟","model":"باستخدام علبتين متماثلتين في الحجم والمادة، وملئهما بنفس كتلة الماء وبنفس درجة الحرارة الابتدائية، ووضعهما على نفس المسافة من المصباح لنفس المدة الزمنية."}],"hard":[{"type":"mcq","q":"يرتدي رجال الإطفاء بدلات ذات سطح فضي لامع عند الاقتراب من الحرائق الشديدة لأنها:","options":["تمتص الحرارة بسرعة","تسمح بدخول تيارات الحمل","تزيد التوصيل الحراري لأجسامهم","تعكس معظم الأشعة تحت الحمراء القادمة من اللهب"],"answer":3,"why":"السطح الفضي اللامع يعكس الإشعاع الحراري الشديد فيحمي رجل الإطفاء."},{"type":"mcq","q":"إذا زادت درجة حرارة الأرض بسبب تراكم الغازات الدفيئة، فذلك يعني أن:","options":["معدل الطاقة الممتصة أصبح أكبر من معدل الطاقة المشعّة للفضاء","الأرض أصبحت سطحًا فضيًا لامعًا","الشمس توقفت عن الإشعاع","التوصيل في الفضاء زاد"],"answer":0,"why":"حبس جزء من الأشعة تحت الحمراء يقلل الانبعاث للفضاء فترتفع الحرارة."},{"type":"mcq","q":"لماذا يُبطَّن السطح الداخلي للترمس (قارورة حفظ الحرارة) بطبقة فضية لامعة؟","options":["لزيادة التوصيل الحراري","لتقليل فقدان أو اكتساب الحرارة بالإشعاع عبر عكسها","لزيادة امتصاص الحرارة","لتوليد تيارات حمل"],"answer":1,"why":"السطح الفضي اللامع عاكس ممتاز وباعث رديء فيمنع تسرب الحرارة بالإشعاع."},{"type":"mcq","q":"في ليالي الصحراء الصافية، تنخفض درجة الحرارة بسرعة كبيرة مقارنةً بالليالي الغائمة لأن:","options":["الهواء يصبح موصلًا ممتازًا","الرمال تتحوّل إلى فضة لامعة","السماء الصافية تسمح للأرض بإشعاع حرارتها للفضاء دون غيوم تعكسها","الغيوم تمتص ضوء الشمس ليلًا"],"answer":2,"why":"الغيوم تعكس جزءًا من الأشعة تحت الحمراء للأرض، وغيابها يسرّع التبريد بالإشعاع."},{"type":"tfr","q":"للمقارنة العادلة في مكعب ليسلي، يجب وضع كاشف الإشعاع على مسافة مختلفة لكل وجه.","answer":false,"reasons":["يجب وضعه على المسافة نفسها تمامًا أمام كل وجه حتى تكون المقارنة عادلة","المسافة لا تؤثر في شدة الإشعاع","يجب أن يلامس الكاشف الوجه"],"reason":0},{"type":"tfr","q":"يمكن انتقال الحرارة بالإشعاع عبر بعض المواد الشفافة مثل الهواء والزجاج، بالإضافة إلى الفراغ.","answer":true,"reasons":["لأن الهواء صلب","لأن الإشعاع الحراري موجات كهرومغناطيسية تعبر الفراغ والأوساط الشفافة لها","لأن الإشعاع يحتاج هواءً فقط"],"reason":1},{"type":"tfr","q":"إذا أردت أن يبرد محرك دراجة نارية بسرعة أكبر، فمن الأفضل طلاء زعانف التبريد باللون الأسود المعتم.","answer":true,"reasons":["لأن الأسود يمنع الإشعاع","لأن الأسود يعكس الحرارة للداخل","لأن الأسود المعتم أفضل باعث للإشعاع الحراري فيسرّع فقدان حرارة المحرك"],"reason":2},{"type":"essay","q":"قارن بين طرق انتقال الحرارة الثلاث (التوصيل، الحمل، الإشعاع) من حيث الحاجة لوسط مادي، وأمثلة كل منها.","model":"التوصيل يحتاج وسطًا ماديًا (غالبًا صلبًا مثل تسخين ملعقة معدنية). الحمل يحتاج مائعًا سائلًا أو غازًا (مثل تسخين ماء في قدر ونسيم البحر). الإشعاع لا يحتاج وسطًا ماديًا ويعبر الفراغ (مثل وصول حرارة الشمس للأرض)."},{"type":"essay","q":"لماذا تُستخدم بطانية فضية لامعة خفيفة لتغطية المصابين بانخفاض حرارة الجسم أو العدّائين بعد السباق؟","model":"لأن السطح الفضي اللامع يعكس الأشعة تحت الحمراء الصادرة من جسم الشخص مرةً أخرى إليه ويقلل انبعاثها للخارج، كما يمنع تيارات الهواء (الحمل) من تبريد جسمه."},{"type":"essay","q":"اشرح لماذا يسخن داخل سيارة مغلقة متوقفة تحت شمس عُمان بشدة (تأثير البيت الزجاجي المصغّر).","model":"يدخل إشعاع الشمس ذو الطول الموجي القصير عبر الزجاج فتمتصه المقاعد السوداء وتسخن، ثم تُشع المقاعد أشعةً تحت حمراء طويلة الموجة يصعب خروجها عبر الزجاج، فتحتبس الحرارة وترتفع درجة الحرارة داخل السيارة بشدة."}]}},
  {"id":"g9-phy-1-u10-1","grade":"g9","subject":"physics","term":1,"unit":10,"no":1,"title":"بعض التطبيقات والآثار المترتّبة على نقل الطاقة الحرارية","summary":"شرح متحرك لتطبيقات التحكم بنقل الحرارة في الترمس (القارورة المفرّغة) وعزل المنازل وأواني الطبخ والبيوت المحمية، ثم أنشطة بثلاثة مستويات.","page":"lesson-thermal-transfer-applications.html","video":"","pdf":"","notes":["الترمس (القارورة المفرّغة): الفراغ يمنع التوصيل والحمل، والطلاء الفضي اللامع يقلل الإشعاع، والسدادة العازلة تمنع الحمل والتبخر وتقلل التوصيل.","عزل المباني: الجدران المزدوجة بالفوم والصوف الصخري والزجاج المزدوج تحبس الهواء الساكن لتقليل التوصيل والحمل، والطلاء الأبيض يعكس الإشعاع.","تسريع التبادل الحراري: استخدام الفلزات الموصلة، وزيادة مساحة السطح (الزعانف)، واللون الأسود المعتم (كما في مشعاع السيارة ومشتت الحاسوب).","البيوت المحمية تحبس الحرارة عبر السماح بدخول إشعاع الشمس ومنع هروب الهواء الدافئ بالحمل وحبس الأشعة تحت الحمراء."],"exercises":["اشرح وظيفة كل جزء في الترمس: (أ) الفراغ، (ب) الطلاء الفضي اللامع، (ج) السدادة البلاستيكية.","اقترح ثلاث طرق عملية لتقليل تسرب حرارة الصيف إلى داخل منزل في سلطنة عُمان.","كيف يساعد تصميم مشعاع السيارة (الرادياتير) على تبريد المحرك بسرعة؟"],"levels":{"easy":[{"type":"mcq","q":"الجزء الذي يمنع انتقال الحرارة بالتوصيل والحمل معًا في الترمس هو:","options":["اللون الأسود","الطلاء الفضي اللامع","المقبض الخارجي","طبقة الفراغ بين الجدارين"],"answer":3,"why":"الفراغ لا يحتوي جسيمات فيمنع التوصيل والحمل تمامًا."},{"type":"mcq","q":"الجزء الذي يقلل فقدان الحرارة بـ«الإشعاع» في الترمس هو:","options":["السطح الفضي اللامع","الماء بداخل الترمس","الفراغ","السدادة الفلينية"],"answer":0,"why":"السطح الفضي اللامع يعكس الأشعة تحت الحمراء للداخل."},{"type":"mcq","q":"لماذا تُصنع السدادة العلوية للترمس من البلاستيك أو الفلين؟","options":["لأنها موصل ممتاز","لأنها عازلة تقلل التوصيل وتمنع تيارات الحمل والتبخر","لأنها ثقيلة جدًّا","لأنها تسمح بخروج البخار"],"answer":1,"why":"السدادة تغلق الفوهة فتوقف الحمل والتبخر، وتقلل التوصيل لكونها عازلة."},{"type":"mcq","q":"في البيوت المحمية الزراعية، يمنع السقف والجدران الزجاجية فقدان الحرارة أساسًا عن طريق:","options":["تحويل الزجاج إلى فراغ","منع دخول ضوء الشمس","منع هروب الهواء الدافئ بتيارات الحمل","زيادة التوصيل"],"answer":2,"why":"إغلاق البيت المحمي يمنع اختلاط الهواء الدافئ بالخارج فيحفظ الدفء."}],"medium":[{"type":"mcq","q":"يمكن للترمس أن يحفظ مشروبًا مثلّجًا باردًا لساعات طويلة لأنه:","options":["يُنتج برودة داخلية بالكهرباء","يزيد امتصاص الأشعة تحت الحمراء","يسمح بمرور الهواء البارد","يمنع دخول الحرارة من الخارج بالتوصيل والحمل والإشعاع"],"answer":3,"why":"منع انتقال الحرارة يعمل في الاتجاهين: يمنع خروجها من الساخن ودخولها للبارد."},{"type":"mcq","q":"أي تصميمٍ لمشتّت حراري (Heat Sink) داخل الحاسوب يبرّد المعالج بأفضل كفاءة؟","options":["مصنوع من الألمنيوم وبه زعانف كثيرة ومطلي بالأسود المعتم","مصنوع من الخشب ومغلف بالصوف","مصنوع من البلاستيك وأملس وأبيض","مصنوع من الزجاج ومفرّغ من الهواء"],"answer":0,"why":"الألمنيوم موصل ممتاز، والزعانف تزيد مساحة السطح، والأسود المعتم يسرّع الإشعاع."},{"type":"mcq","q":"لماذا يُنصح بإغلاق الستائر الفاتحة على النوافذ في ظهيرة الصيف الحار؟","options":["لزيادة امتصاص الحرارة","لعكس إشعاع الشمس وتقليل الحمل الحراري قرب الزجاج الساخن","لزيادة التوصيل","لتوليد طاقة كهربائية"],"answer":1,"why":"الستائر الفاتحة تعكس الإشعاع وتحبس طبقة هواء عازلة قرب النافذة."},{"type":"tfr","q":"رغم وجود الفراغ في الترمس، يفقد الشاي الساخن حرارته ببطء شديد عبر ساعات طويلة.","answer":true,"reasons":["لأن بعض الحرارة يتسرّب تدريجيًا بالتوصيل عبر السدادة وعنق الزجاج وبقدر ضئيل بالإشعاع","لأن الفراغ يختفي بعد ساعة","لأن الحرارة تفنى تلقائيًا"],"reason":0},{"type":"tfr","q":"طلاء سقف المنزل باللون الأسود الداكن يقلّل من استهلاك المكيّف في الصيف.","answer":false,"reasons":["لأن الأسود يعكس كل أشعة الشمس","بل يزيد امتصاص حرارة الشمس فيرفع حرارة المنزل ويزيد استهلاك المكيّف؛ الأفضل اللون الأبيض","لأن اللون لا يؤثر في الإشعاع"],"reason":1},{"type":"essay","q":"اربط كل ميزة في عزل المنازل الحديثة بطريقة انتقال الحرارة التي تقلّلها: (١) حشو الجدران بالفوم، (٢) طلاء السطح بالأبيض، (٣) إغلاق شقوق الأبواب.","model":"١) الفوم يقلّل التوصيل والحمل (يحبس الهواء الساكن). ٢) الطلاء الأبيض يقلّل الإشعاع (يعكس أشعة الشمس). ٣) إغلاق الشقوق يمنع الحمل الحراري (تيارات الهواء الساخن الداخلة)."},{"type":"essay","q":"فسّر لماذا يسخن مشروب ساخن أو يبرد بسرعة أكبر بكثير إذا تركت غطاء الترمس مفتوحًا.","model":"لأن فتح الغطاء يسمح بصعود الهواء الساخن والبخار (تيارات الحمل الحراري والتبخر) فتفقد القهوة حرارتها بسرعة كبيرة."}],"hard":[{"type":"mcq","q":"عند وضع ورقة فضية لامعة خلف مدفأة الجدار في منزل ببلد بارد، فإن الهدف هو:","options":["منع الحمل الحراري في الغرفة","زيادة التوصيل عبر الجدار للخارج","عكس الإشعاع الحراري المتجه نحو الجدار وإعادته إلى داخل الغرفة","امتصاص الحرارة داخل الجدار"],"answer":2,"why":"الرقاقة اللامعة تقلل ضياع الحرارة بالإشعاع نحو الجدار الخارجي."},{"type":"mcq","q":"في الصحراء، لماذا تنام بعض الحيوانات داخل جحور عميقة تحت الرمال خلال النهار الحار؟","options":["لأن الإشعاع يخترق الأرض","لأن الرمل موصل ممتاز للبرودة","لأن تيارات الحمل تهبط تحت الرمل","لأن الرمل عازل حراري رديء التوصيل فيبقى الجحر في الأسفل باردًا ومعتدلًا"],"answer":3,"why":"الرمل المحبوس بينه هواء موصل رديء، فلا تصل حرارة السطح الشديدة إلى عمق الجحر."},{"type":"mcq","q":"ما الأثر البيئي المباشر لزيادة غاز ثاني أكسيد الكربون في الغلاف الجوي على توازن الإشعاع الأرضي؟","options":["امتصاص وإعادة إشعاع الأشعة تحت الحمراء نحو الأرض مما يرفع متوسط حرارتها","زيادة التوصيل الحراري بين الأرض والفضاء","منع وصول ضوء الشمس تمامًا للأرض","تجميد المحيطات"],"answer":0,"why":"الغازات الدفيئة تحبس جزءًا من الأشعة تحت الحمراء الصادرة من الأرض فتسبب الاحترار العالمي."},{"type":"mcq","q":"أيهما يبرّد محرك سيارة أسرع: مشعاع (رادياتير) أبيض لامع أملس أم مشعاع أسود معتم ذو زعانف ومروحة؟","options":["الأبيض لأنه يعكس الحرارة للخارج","الأسود المعتم ذو الزعانف والمروحة","كلاهما بنفس السرعة","الأبيض اللامع الأملس"],"answer":1,"why":"المروحة تسرّع الحمل، والزعانف تزيد مساحة السطح، والأسود المعتم يسرّع الإشعاع."},{"type":"tfr","q":"تسهم تيارات الحمل الحراري في المحيطات (التيارات البحرية) في توزيع الحرارة حول الكوكب.","answer":true,"reasons":["لأن المحيطات لا تتأثر بالشمس","لأن الماء موصل ممتاز بالتوصيل","لأن المياه الدافئة الاستوائية تتحرك نحو المناطق الأبرد والمياه الباردة تتحرك نحو الاستواء"],"reason":2},{"type":"tfr","q":"دعامات الفلين أو البلاستيك التي تثبّت القارورة الزجاجية داخل الغلاف الخارجي للترمس هدفها زيادة التوصيل.","answer":false,"reasons":["هدفها تثبيت القارورة مع تقليل التوصيل الحراري للغلاف الخارجي إلى أدنى حد","هدفها منع الإشعاع","هدفها السماح بدخول الهواء"],"reason":0},{"type":"tfr","q":"تعتمد البيوت التراثية العمانية ذات الجدران الطينية السميكة على ضعف توصيل الطين لإبقاء الداخل باردًا نهارًا.","answer":true,"reasons":["لأن الطين يولد تيارات تبريد كهربائية","لأن الجدران السميكة العازلة تبطئ جدًّا انتقال حرارة النهار الشديدة إلى داخل الغرفة","لأن الطين فلز موصل"],"reason":1},{"type":"essay","q":"قارن بين تصميم «الترمس» وتصميم «مشعاع السيارة» من حيث الهدف وطريقة التعامل مع التوصيل والحمل والإشعاع.","model":"هدف الترمس «منع» انتقال الحرارة: يستخدم الفراغ (لا توصيل ولا حمل) والفضي اللامع (لا إشعاع) وسدادة عازلة. أما مشعاع السيارة فهدفه «تسريع» فقدان الحرارة: يستخدم فلزًا موصلًا (توصيل) ومروحة وهواء متحركًا (حمل) ولونًا أسود معتمًا وزعانف واسعة (إشعاع وحمل)."},{"type":"essay","q":"اشرح كيف تتحقّق ظاهرة «الاحتباس الحراري» الطبيعية ولماذا يؤدي تزايدها عن الحد الطبيعي إلى تغيّر المناخ.","model":"يمر إشعاع الشمس للغلاف الجوي ويدفئ الأرض، فتُشع الأرض أشعة تحت حمراء يمتص جزءًا منها غازات الدفيئة (مثل CO₂ وبخار الماء) فتحفظ دفء الأرض. لكن حرق الوقود الأحفوري يزيد هذه الغازات بشدة، فيحتبس مزيد من الحرارة مما يرفع حرارة الكوكب ويذيب الجليد ويغير أنماط الطقس."},{"type":"essay","q":"صمّم صندوقًا محمولًا لحفظ الأدوية باردةً أثناء نقلها في يوم حار بعُمان، موضحًا المواد المختارة والسبب الفيزيائي لكل مادة.","model":"جدران سميكة من الفوم العازل (تحبس الهواء الساكن لتقليل التوصيل والحمل)، وغلاف خارجي أبيض أو فضي لامع (يعكس إشعاع الشمس)، وغطاء محكم الإغلاق مع بطانة مطاطية (يمنع دخول الهواء الساخن بالحمل الحراري)، مع أكياس ثلج في الأعلى (ليهبط الهواء البارد ويبرد الأدوية بالحمل)."}]}},
  {"id":"g9-phy-2-u11-1","grade":"g9","subject":"physics","term":2,"unit":11,"no":1,"title":"الطاقة التي نستخدمها","summary":"شرح متحرك بـ SVG لدرس الطاقة التي نستخدمها (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-energy-we-use.html","video":"","pdf":"","notes":["مصادر الطاقة تنقسم لمتجددة (شمس، رياح، ماء، حرارية أرضية، حيوي) وغير متجددة (وقود أحفوري، نووي).","معظم المحطات تدير توربينًا متّصلًا بمولّد، بينما الخلايا الشمسية تحوّل الضوء مباشرةً لكهرباء.","لا يوجد مصدر مثالي وحده؛ لذا تعتمد الدول مزيج طاقة يوازن بين النظافة والموثوقية والتكلفة.","سلطنة عُمان رائدة في مشاريع الطاقة الشمسية والرياح والهيدروجين الأخضر."],"exercises":["قارن بين المصادر المتجددة وغير المتجددة مع مثالين لكل منهما.","اشرح سلسلة تحوّل الطاقة في محطة كهرباء تعمل بالغاز الطبيعي.","اذكر ميزتين وعيبين للطاقة الشمسية في سلطنة عُمان."],"levels":{"easy":[{"type":"mcq","q":"أي المصادر الآتية يُعد مصدرًا «غير متجدد» للطاقة؟","options":["الطاقة الحرارية الأرضية","طاقة الرياح","الطاقة الشمسية","الغاز الطبيعي واليورانيوم"],"answer":3,"why":"الغاز الطبيعي وقود أحفوري واليورانيوم خام محدود كلاهما غير متجدد."},{"type":"mcq","q":"ما المصدر الذي يحوّل الضوء مباشرةً إلى كهرباء دون توربين؟","options":["الخلايا الشمسية الكهروضوئية","محطة الفحم","محطة الرياح","المحطة النووية"],"answer":0,"why":"الخلايا الشمسية تنتج تيارًا كهربائيًا مباشرةً من الضوء."},{"type":"mcq","q":"ما الميزة الكبرى لطاقة المدّ والجزر مقارنةً بطاقة الرياح؟","options":["لا تحتاج ماءً","مواعيدها متوقّعة بدقة يوميًا","غير متجددة","تنتج CO₂"],"answer":1,"why":"حركة المد والجزر مرتبطة بحركة القمر المنتظمة فيسهل التنبؤ بها."},{"type":"mcq","q":"ما العيب البيئي الأبرز لمحطات الطاقة النووية؟","options":["اعتمادها على الرياح","انبعاث كميات ضخمة من CO₂","النفايات المشعة الخطيرة التي تحتاج تخزينًا آمنًا لآلاف السنين","عدم قدرتها على العمل ليلًا"],"answer":2,"why":"النووي لا يطلق CO₂ لكنه يخلّف نفايات مشعة خطيرة."}],"medium":[{"type":"mcq","q":"ما وظيفة المولّد الكهربائي في محطة الطاقة؟","options":["امتصاص CO₂","حرق الوقود","تخزين الماء","تحويل الطاقة الحركية الدورانية إلى طاقة كهربائية"],"answer":3,"why":"التوربين يدير المولد فينتج الكهرباء."},{"type":"mcq","q":"أي مصدر متجدد يعمل باستمرار ليلًا ونهارًا دون التأثر بالطقس؟","options":["الطاقة الحرارية الأرضية","الخلايا الشمسية","طاقة الرياح","الأمواج"],"answer":0,"why":"حرارة باطن الأرض مستمرة دائمًا في المناطق الجيولوجية المناسبة."},{"type":"mcq","q":"لماذا تُعد الطاقة الشمسية والرياح مكمّلتين لبعضهما؟","options":["لأنهما غير متجددتين","لأن الشمس متوفرة نهارًا بينما قد تهب الرياح ليلًا ونهارًا","لأنهما تنتجان دخانًا","لأنهما لا تحتاجان مساحة"],"answer":1,"why":"الجمع بينهما يقلل أثر التقطع."},{"type":"tfr","q":"تُعد الطاقة النووية مصدرًا متجددًا لأنها لا تُطلق غاز CO₂.","answer":false,"reasons":["هي غير متجددة لأن خام اليورانيوم محدود في الأرض وينفد","نعم متجددة","لأنها تعمل بالرياح"],"reason":0},{"type":"tfr","q":"تحتاج معظم محطات توليد الكهرباء إلى توربين ومولّد كهربائي.","answer":true,"reasons":["لا توجد محطة تستخدم توربينًا","لتتحول حركة التوربين الدورانية إلى طاقة كهربائية، باستثناء الخلايا الشمسية","الخلايا الشمسية تستخدم توربينًا"],"reason":1},{"type":"essay","q":"قارن بين المصادر المتجددة وغير المتجددة مع مثالين لكل منهما.","model":"المتجددة تتجدد طبيعيًا ولا تنفد وأقل تلوثًا (الشمس، الرياح). غير المتجددة محدودة وتنفد (النفط، الغاز، اليورانيوم)."},{"type":"essay","q":"اشرح سلسلة تحوّل الطاقة في محطة كهرباء تعمل بالغاز الطبيعي.","model":"طاقة كيميائية في الغاز ← حرارية تغلي الماء ← حركية في البخار والتوربين ← كهربائية في المولّد."}],"hard":[{"type":"mcq","q":"في المحطة الكهرومائية (السدود)، ما تحوّل الطاقة الأساسي؟","options":["كيميائية ← حرارية","نووية ← ضوئية","وضع جاذبية ← حركية ← كهربائية","مرونية ← صوتية"],"answer":2,"why":"الماء المرتفع يختزن طاقة وضع تتحول لحركة تدير التوربين."},{"type":"mcq","q":"من عيوب التوسّع الكبير في زراعة محاصيل الوقود الحيوي:","options":["توقف المطر","انعدام الأكسجين","إنتاج نفايات نووية","منافسة الأراضي الزراعية المخصّصة للغذاء"],"answer":3,"why":"تخصيص أراضٍ للوقود قد يقلل المساحة المتاحة للغذاء."},{"type":"mcq","q":"لماذا يُعد الغاز الطبيعي أنظف نسبيًا من الفحم الحجري؟","options":["لأنه يطلق كمية أقل من CO₂ والملوثات لكل وحدة طاقة","لأنه متجدد","لأنه لا يحترق","لأنه لا يحتوي كربون"],"answer":0,"why":"الغاز أقل انبعاثًا للكربون والكبريت من الفحم لكنه يظل غير متجدد."},{"type":"mcq","q":"يُسمّى الاعتماد على عدة مصادر طاقة مختلفة لضمان استمرار الكهرباء:","options":["الاحتكار","مزيج الطاقة المستدام","التوصيل الحراري","التسارع"],"answer":1,"why":"التنويع يضمن أمن الطاقة وتقليل التلوث."},{"type":"tfr","q":"محطة ظفار لطاقة الرياح ومحطة عبري للطاقة الشمسية مثالان على الطاقة المتجددة في عُمان.","answer":true,"reasons":["غير متجددتين","تعملان بالفحم","فهما تستغلان الرياح والشمس لتوليد كهرباء نظيفة ومستدامة"],"reason":2},{"type":"tfr","q":"تعمل الخلايا الشمسية بكامل طاقتها في منتصف الليل دون بطاريات.","answer":false,"reasons":["الخلايا الشمسية تحتاج لضوء الشمس، وتلزم بطاريات تخزين لتشغيل الأجهزة ليلًا","تعمل بالظلام","تعمل بالرياح"],"reason":0},{"type":"tfr","q":"بناء السدود الكهرومائية الكبيرة قد يغمر مساحات زراعية ويغيّر مواطن الكائنات الحية.","answer":true,"reasons":["لا أثر لها مطلقًا","فرغم أنها متجددة ونظيفة إلا أن لها أثرًا بيئيًا محليًا عند البناء","تنتج نفايات مشعة"],"reason":1},{"type":"essay","q":"اذكر ميزتين وعيبين للطاقة الشمسية في سلطنة عُمان.","model":"المزايا: متجددة ونظيفة وسطوع الشمس قوي في عُمان. العيوب: لا تعمل ليلًا وتحتاج مساحة وأنظمة تخزين وتنظيف من الغبار."},{"type":"essay","q":"علّل: لماذا تتجه الدول إلى «مزيج طاقة» بدل الاعتماد على مصدر واحد فقط؟","model":"لأن المصادر النظيفة كالشمس والرياح متقطّعة، فالتنويع مع التخزين يضمن استقرار الشبكة ٢٤ ساعة مع تقليل التلوث."},{"type":"essay","q":"ما الفرق بين المحطة النووية ومحطة الوقود الأحفوري من حيث الأثر البيئي؟","model":"الوقود الأحفوري يطلق CO₂ و SO₂ (احتباس حراري ومطر حمضي)، بينما النووي لا يطلق غازات دفيئة لكنه ينتج نفايات إشعاعية خطيرة طويلة الأمد."}]}},
  {"id":"g9-phy-2-u11-2","grade":"g9","subject":"physics","term":2,"unit":11,"no":2,"title":"الشمس كمصدر للطاقة","summary":"شرح متحرك بـ SVG لدرس الشمس كمصدر للطاقة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-sun-as-energy-source.html","video":"","pdf":"","notes":["تنتج الشمس طاقتها بالاندماج النووي (دمج أنوية الهيدروجين إلى هيليوم).","الشمس أصل معظم طاقات الأرض: الشمسية، الرياح، الأمواج، السدود، الوقود الحيوي، والوقود الأحفوري.","المصادر الثلاثة المستثناة (ليست من الشمس): النووية، الحرارية الأرضية، والمدّ والجزر.","السخانات الشمسية تحول الإشعاع لحرارة، والخلايا الشمسية تحول الضوء مباشرةً لكهرباء."],"exercises":["اشرح كيف تنتج الشمس طاقتها وكيف تصل هذه الطاقة إلى الأرض.","اذكر المصادر الثلاثة للطاقة التي لا يكون أصلها الشمس وبيّن مصدر كل منها.","تتبّع سلسلة انتقال الطاقة من الشمس حتى حركة سفينة شراعية أو توربين رياح."],"levels":{"easy":[{"type":"mcq","q":"ما التفاعل الذي يُنتج الطاقة الهائلة في قلب الشمس؟","options":["الاندماج النووي (دمج أنوية الهيدروجين لتكوين الهيليوم)","احتراق الفحم","الانشطار النووي لليورانيوم","الاحتكاك"],"answer":0,"why":"تندمج أنوية الهيدروجين في الشمس لتكوين الهيليوم مطلقةً طاقة هائلة."},{"type":"mcq","q":"أي مصدر من المصادر الآتية «لا» يعود أصله إلى الشمس؟","options":["طاقة الرياح","الطاقة الحرارية الأرضية","الوقود الأحفوري","الطاقة الكهرومائية"],"answer":1,"why":"المصادر الثلاثة غير الشمسية هي: النووية، الحرارية الأرضية، والمد والجزر."},{"type":"mcq","q":"كيف يعود أصل «الطاقة الكهرومائية» في السدود إلى الشمس؟","options":["الشمس تجمد الماء","الشمس تدير التوربين مباشرة","تسخّن الشمس ماء البحر فيتبخر ويكوّن سحبًا وأمطارًا تملأ السدود المرتفعة","لا علاقة للشمس بالسدود"],"answer":2,"why":"دورة الماء في الطبيعة تعمل بطاقة الشمس."},{"type":"mcq","q":"كيف يعود أصل «الوقود الأحفوري» إلى الشمس؟","options":["نتج عن البراكين","سقط من الشمس مباشرة","نتج عن القمر","تكوّن من نباتات وكائنات قديمة خزّنت طاقة الشمس عبر البناء الضوئي قبل ملايين السنين"],"answer":3,"why":"الطاقة الكيميائية في النفط والفحم أصلها ضوء الشمس قديمًا."}],"medium":[{"type":"mcq","q":"ما الفرق الأساسي بين الاندماج النووي والانشطار النووي؟","options":["الاندماج يدمج أنوية خفيفة (H)، بينما الانشطار يقسّم نواة ثقيلة (يورانيوم)","كلاهما نفس الشيء","الاندماج يحدث في المفاعلات التجارية اليوم فقط","الانشطار يحدث في الشمس"],"answer":0,"why":"الشمس تعمل بالاندماج النووي، والمحطات الحالية بالانشطار."},{"type":"mcq","q":"أي عنصر ينتج عن اندماج أنوية الهيدروجين داخل الشمس؟","options":["الحديد","الهيليوم (He)","النحاس","اليورانيوم"],"answer":1,"why":"تندمج أنوية الهيدروجين لتكوّن الهيليوم."},{"type":"mcq","q":"لماذا يقل إنتاج الألواح الشمسية إذا تراكم عليها الغبار؟","options":["لأن الغبار يزيد الجهد","لأن الغبار يبرد السلك","لأن الغبار يحجب جزءًا من ضوء الشمس عن الخلايا الكهروضوئية","لا يتأثر الإنتاج"],"answer":2,"why":"نظافة سطح اللوح ضرورية لامتصاص أقصى ضوء."},{"type":"tfr","q":"تُعد الطاقة النووية والحرارية الأرضية والمدّ والجزر المصادر الثلاثة التي لا ترجع للشمس.","answer":true,"reasons":["كل الطاقات ترجع للشمس بلا استثناء","فالنووية من اليورانيوم والأرضية من باطن الأرض والمد والجزر من جاذبية القمر","الرياح ليست من الشمس"],"reason":1},{"type":"tfr","q":"تُنتج الشمس طاقتها عبر احتراق غاز الأكسجين والفحم في باطنها.","answer":false,"reasons":["بالتوصيل الحراري","نعم بالاحتراق العادي","تُنتج طاقتها بالاندماج النووي للهيدروجين إلى هيليوم، وليس احتراقًا كيميائيًا"],"reason":2},{"type":"essay","q":"اشرح كيف تنتج الشمس طاقتها وكيف تصل هذه الطاقة إلى الأرض.","model":"تندمج أنوية الهيدروجين في قلب الشمس لتكوين الهيليوم (اندماج نووي) مطلقةً طاقة هائلة تصل للأرض عبر الفراغ بالإشعاع."},{"type":"essay","q":"اذكر المصادر الثلاثة للطاقة التي لا يكون أصلها الشمس وبيّن مصدر كل منها.","model":"١) النووية (أنوية اليورانيوم). ٢) الحرارية الأرضية (حرارة باطن الأرض). ٣) المدّ والجزر (جاذبية القمر)."}],"hard":[{"type":"mcq","q":"ينشأ المدّ والجزر أساسًا بسبب:","options":["الوقود الحيوي","رياح الصيف","حرارة باطن الأرض","جاذبية القمر (والشمس بدرجة أقل)"],"answer":3,"why":"جاذبية القمر تحرّك مياه البحار صعودًا وهبوطًا."},{"type":"mcq","q":"تنتقل الطاقة من الشمس إلى الأرض عبر الفضاء بـ:","options":["الإشعاع الكهرومغناطيسي","التوصيل","الحمل الحراري","التيار الكهربائي"],"answer":0,"why":"الإشعاع هو الطريقة الوحيدة التي تعبر الفراغ."},{"type":"mcq","q":"أي مجموعة من المصادر التالية كلها أصلها الشمس؟","options":["النووية، الأرضية، المد والجزر","الرياح، الأمواج، الوقود الحيوي، الفحم","الرياح، النووية، الفحم","السدود، المد والجزر، النفط"],"answer":1,"why":"الرياح والأمواج والوقود الحيوي والأحفوري كلها ترجع للشمس."},{"type":"mcq","q":"لماذا يصعب حتى الآن تشغيل محطات اندماج نووي تجارية على الأرض؟","options":["لأنها لا تنتج طاقة","لعدم وجود هيدروجين على الأرض","لأنها تحتاج درجات حرارة وضغطًا هائلين جدًّا يشبهان قلب الشمس لدمج الأنوية","لأنها تنتج دخانًا أسود"],"answer":2,"why":"السيطرة على البلازما شديدة الحرارة تحدٍّ هندسي كبير."},{"type":"tfr","q":"تعتمد طاقة الرياح على تسخين الشمس غير المتساوي لسطح الأرض.","answer":true,"reasons":["فيسخن الهواء في مناطق ويصعد ويندفع الهواء البارد مكانه فتنشأ الرياح","تنشأ الرياح من القمر","لا علاقة للشمس بالرياح"],"reason":0},{"type":"tfr","q":"السخان الشمسي يحوّل إشعاع الشمس إلى كهرباء أولًا ثم يسخّن الماء.","answer":false,"reasons":["نعم يحوله لكهرباء","السخان الشمسي يمتص الإشعاع مباشرةً في أنابيب سوداء لتسخين الماء دون كهرباء","يعمل بالبطاريات"],"reason":1},{"type":"tfr","q":"زيادة مساحة الألواح الشمسية تضاعف الطاقة الكهربائية المنتجة عند نفس شدة السطوع.","answer":true,"reasons":["المساحة الأكبر تقلل الكهرباء","المساحة لا تؤثر","لأن المساحة الأكبر تلتقط كمية أكبر من الإشعاع الشمسي في الثانية"],"reason":2},{"type":"essay","q":"تتبّع سلسلة انتقال الطاقة من الشمس حتى حركة سفينة شراعية أو توربين رياح.","model":"اندماج نووي في الشمس ← إشعاع يسخن الغلاف الجوي ← تيارات حمل تولّد الرياح (حركية) ← تدفع الشراع أو تدير التوربين."},{"type":"essay","q":"قارن بين «الخلية الشمسية» و«السخان الشمسي» من حيث تحوّل الطاقة.","model":"الخلية الشمسية تحوّل الضوء مباشرةً إلى طاقة كهربائية؛ أما السخان الشمسي فيحوّل الإشعاع مباشرةً إلى طاقة حرارية لتسخين الماء."},{"type":"essay","q":"لماذا يُعد الاندماج النووي حلم العلماء لطاقة المستقبل على الأرض؟","model":"لأنه يستخدم الهيدروجين المتوفر بكثرة في الماء، وينتج طاقة هائلة جدًّا دون غازات دفيئة أو نفايات مشعة طويلة الأمد كالانشطار."}]}},
  {"id":"g9-phy-2-u11-3","grade":"g9","subject":"physics","term":2,"unit":11,"no":3,"title":"الكفاءة","summary":"شرح متحرك بـ SVG لدرس الكفاءة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-efficiency-phy.html","video":"","pdf":"","notes":["الكفاءة = (الطاقة المفيدة ÷ الداخلة) × 100% = (القدرة المفيدة ÷ الداخلة) × 100%.","الكفاءة بلا وحدة ولا تتجاوز 100% أبدًا.","نرفع الكفاءة بالتزييت والعزل الحراري والتصميم الانسيابي وأجهزة LED.","في مخطط سانكي يتناسب عَرض كل سهم طرديًا مع مقدار الطاقة."],"exercises":["محطة كهرباء تدخلها 2500 MJ من الغاز وتنتج 1000 MJ كهرباء. احسب الطاقة المهدرة والكفاءة.","اذكر ثلاث طرق عملية لرفع كفاءة الأجهزة والسيارات والمباني.","مضخة ماء قدرتها الداخلة 1500 W وكفاءتها 60%. احسب القدرة المفيدة والمهدرة."],"levels":{"easy":[{"type":"mcq","q":"آلة تدخلها 500 J وتنتج 350 J مفيدة؛ كفاءتها تساوي:","options":["30%","70%","142%","50%"],"answer":1,"why":"(350 ÷ 500) × 100% = 70%."},{"type":"mcq","q":"مصباح LED قدرته الداخلة 10 W وكفاءته 80%؛ ما قدرته الضوئية المفيدة؟","options":["12.5 W","2 W","8 W","80 W"],"answer":2,"why":"0.80 × 10 = 8 W."},{"type":"mcq","q":"وحدة قياس الكفاءة هي:","options":["النيوتن","الجول","الواط","بلا وحدة (نسبة مئوية أو كسر عشري)"],"answer":3,"why":"الكفاءة نسبة بين كميتين متماثلتين لذا هي بلا وحدة."},{"type":"mcq","q":"لماذا لا تتجاوز كفاءة أي آلة 100%؟","options":["وفق مبدأ حفظ الطاقة لا يمكن أن تزيد الطاقة المفيدة عن الداخلة","لأن الجول صغير","لأن الآلات بلا احتكاك","لأن القدرة صفر"],"answer":0,"why":"الطاقة لا تُستحدث من العدم."}],"medium":[{"type":"mcq","q":"محرك كفاءته 25% أنتج 100 J حركة مفيدة؛ ما الطاقة الداخلة من الوقود؟","options":["25 J","400 J","125 J","250 J"],"answer":1,"why":"الداخلة = 100 ÷ 0.25 = 400 J."},{"type":"mcq","q":"ما الطريقة الأفضل لتقليل الطاقة المهدرة بالاحتكاك في التروس؟","options":["زيادة الوزن","زيادة الخشونة","التزييت والتشحيم","إيقاف التبريد"],"answer":2,"why":"الزيت يقلل الاحتكاك والحرارة المهدرة."},{"type":"mcq","q":"في مخطط سانكي، عَرض السهم الداخل 8 cm وعرض سهم المفيدة 2 cm؛ الكفاءة تساوي:","options":["20%","75%","40%","25%"],"answer":3,"why":"(2 ÷ 8) × 100% = 25%."},{"type":"tfr","q":"يمكن حساب الكفاءة بقسمة القدرة المفيدة على القدرة الداخلة × 100%.","answer":true,"reasons":["تُضرب في الزمن","تُحسب بالطاقة فقط","لأن القدرة هي الطاقة في الثانية فيعطي نفس النسبة تمامًا"],"reason":2},{"type":"tfr","q":"مصباح الفتيلة القديم أعلى كفاءةً من مصباح LED الحديث.","answer":false,"reasons":["مصباح الفتيلة يهدر نحو 90% كحرارة بينما LED يحول معظم الكهرباء لضوء","كلاهما 100%","LED يهدر حرارة أكثر"],"reason":0},{"type":"essay","q":"محطة كهرباء تدخلها 2500 MJ من الغاز وتنتج 1000 MJ كهرباء. احسب الطاقة المهدرة والكفاءة.","model":"المهدرة = 2500 − 1000 = 1500 MJ. الكفاءة = (1000 ÷ 2500) × 100% = 40%."},{"type":"essay","q":"اذكر ثلاث طرق عملية لرفع كفاءة الأجهزة والسيارات والمباني.","model":"١) التزييت لتقليل الاحتكاك. ٢) العزل الحراري للمباني. ٣) التصميم الانسيابي واستخدام مصابيح LED."}],"hard":[{"type":"mcq","q":"جهاز تدخله 1000 J ويهدر 350 J؛ كم كفاءته؟","options":["65%","35%","135%","75%"],"answer":0,"why":"المفيدة = 650 J ← الكفاءة = 65%."},{"type":"mcq","q":"بطاقة كفاءة الطاقة على المكيّفات تساعد المستهلك على:","options":["زيادة الفاتورة","اختيار جهاز يستهلك كهرباء أقل لنفس التبريد","معرفة لون الجهاز","معرفة وزن الجهاز"],"answer":1,"why":"توضح البطاقة مدى كفاءة الجهاز في استهلاك الكهرباء."},{"type":"mcq","q":"إذا تضاعفت الطاقة المهدرة لجهاز مع ثبات الطاقة الداخلة فإن كفاءته:","options":["تبقى ثابتة","تزداد","تقلّ","تصبح 100%"],"answer":2,"why":"زيادة المهدرة تقلل المفيدة فتقل الكفاءة."},{"type":"mcq","q":"غلاية قدرتها 2000 W وكفاءتها 90%؛ ما القدرة الحرارية المهدرة؟","options":["90 W","1800 W","100 W","200 W"],"answer":3,"why":"المفيدة 1800 W إذن المهدرة = 2000 − 1800 = 200 W."},{"type":"tfr","q":"مجموع الطاقة المفيدة والمهدرة يساوي دائمًا الطاقة الداخلة.","answer":true,"reasons":["المفيدة أكبر من الداخلة","تحقيقًا لمبدأ حفظ الطاقة","المهدرة تختفي"],"reason":1},{"type":"tfr","q":"يمكن لسخان كهربائي يدفّئ غرفة أن تقترب كفاءته من 100%.","answer":true,"reasons":["لأنه لا يستهلك كهرباء","لأنه يستحدث طاقة","لأن الحرارة هنا هي الطاقة المفيدة المطلوبة نفسها"],"reason":2},{"type":"tfr","q":"ادّعاء مخترع صناعة محرك كفاءته 115% ممكن باستخدام مغناطيس قوي.","answer":false,"reasons":["مستحيل لأنه يناقض مبدأ حفظ الطاقة","ممكن بالتزييت","ممكن بالكهرباء"],"reason":0},{"type":"essay","q":"مضخة ماء قدرتها الداخلة 1500 W وكفاءتها 60%. احسب القدرة المفيدة والمهدرة.","model":"المفيدة = 0.60 × 1500 = 900 W. المهدرة = 1500 − 900 = 600 W."},{"type":"essay","q":"اشرح كيف نقرأ الكفاءة من مخطط سانكي.","model":"نقسم عَرض سهم الطاقة المفيدة على عَرض سهم الطاقة الداخلة ونضرب في 100%."},{"type":"essay","q":"لماذا يؤدي شراء مكيّف أعلى كفاءةً إلى توفير المال رغم أن سعره الأولي قد يكون أعلى قليلًا؟","model":"لأنه يستهلك كهرباء أقل يوميًا طوال سنوات تشغيله فيوفر في الفواتير أضعاف فرق السعر."}]}},
  {"id":"g9-phy-2-u12-1","grade":"g9","subject":"physics","term":2,"unit":12,"no":1,"title":"انعكاس الضوء","summary":"شرح متحرك بـ SVG لدرس انعكاس الضوء (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-reflection-of-light.html","video":"","pdf":"","notes":["قانون الانعكاس: زاوية السقوط (i) = زاوية الانعكاس (r) مقاستين من العمود المقام.","الانعكاس المنتظم يحدث على الأسطح الملساء ويكوّن صورة؛ وغير المنتظم على الأسطح الخشنة.","صفات الصورة في المرآة المستوية: تقديرية، معتدلة، مساوية، معكوسة جانبيًا، وبنفس البُعد.","البيروسكوب يستخدم مرآتين مائلتين بزاوية 45°."],"exercises":["اذكر الصفات الخمس للصورة المتكوّنة في المرآة المستوية.","سقط شعاع ضوئي بزاوية 35° مع سطح المرآة. احسب: (أ) زاوية السقوط، (ب) زاوية الانعكاس، (ج) الزاوية بين الشعاع الساقط والمنعكس.","قارن بين الانعكاس المنتظم والانعكاس غير المنتظم من حيث نوع السطح وتكوين الصورة."],"levels":{"easy":[{"type":"mcq","q":"ما الزاوية التي نُقيس منها زاوية السقوط وزاوية الانعكاس؟","options":["الأفق","سطح المرآة","العمود المقام على السطح العاكس","اتجاه الجاذبية"],"answer":2,"why":"تُقاس الزاويتان دائمًا بالنسبة للعمود المقام."},{"type":"mcq","q":"إذا كانت زاوية السقوط 35°، فكم تساوي زاوية الانعكاس؟","options":["90°","55°","70°","35°"],"answer":3,"why":"وفق قانون الانعكاس: i = r = 35°."},{"type":"mcq","q":"وقف شخص على بُعد 1.5 m أمام مرآة مستوية. كم المسافة بينه وبين صورته؟","options":["3 m","1.5 m","0.75 m","4.5 m"],"answer":0,"why":"بُعد الصورة خلف المرآة 1.5 m، إذن المسافة بينهما 1.5 + 1.5 = 3 m."},{"type":"mcq","q":"لماذا تُكتب كلمة «إسعاف» معكوسةً على مقدّمة سيارة الإسعاف؟","options":["للزينة فقط","لأن المرآة المستوية تعكس الصورة جانبيًا فيقرأها السائق أمامها صحيحةً","لأن المرآة تقلبها رأسيًا","لتكبير الكلمة"],"answer":1,"why":"الانعكاس الجانبي يقلب اليمين يسارًا فيعيد الكلمة المعكوسة صحيحةً."}],"medium":[{"type":"mcq","q":"إذا صنع شعاع ساقط زاوية 25° مع سطح المرآة، فكم تساوي زاوية الانعكاس؟","options":["50°","25°","65°","90°"],"answer":2,"why":"i = 90° − 25° = 65°، إذن r = 65°."},{"type":"mcq","q":"إذا سقط شعاع ضوئي عموديًا على مرآة مستوية (i = 0°)، فإنه:","options":["يختفي","ينعكس بزاوية 90°","ينفذ عبر المرآة","يرتدّ على نفسه (r = 0°)"],"answer":3,"why":"عندما i = 0° تكون r = 0° فيرتد الشعاع على نفسه."},{"type":"mcq","q":"الانعكاس على سطح ورقة بيضاء خشنة يُعد:","options":["انعكاسًا غير منتظم (مشتّتًا)","انعكاسًا منتظمًا","انكسارًا","تداخلًا"],"answer":0,"why":"الأسطح الخشنة تشتت الأشعة في اتجاهات متعددة."},{"type":"tfr","q":"الصورة المتكوّنة في المرآة المستوية تكون دائمًا مساويةً للجسم في الحجم ومعتدلةً.","answer":true,"reasons":["وهي أيضًا تقديرية ومعكوسة جانبيًا وبُعدها يساوي بُعد الجسم","تكون مصغّرة ومقلوبة","تكون مكبّرة"],"reason":0},{"type":"tfr","q":"تُقاس زاوية السقوط بين الشعاع الساقط وسطح المرآة.","answer":false,"reasons":["نعم مع سطح المرآة","بل تُقاس بين الشعاع الساقط والعمود المقام على السطح","مع الشعاع المنعكس"],"reason":1},{"type":"essay","q":"اذكر الصفات الخمس للصورة المتكوّنة في المرآة المستوية.","model":"١) تقديرية. ٢) معتدلة. ٣) مساوية للجسم. ٤) معكوسة جانبيًا. ٥) بُعدها خلف المرآة يساوي بُعد الجسم أمامها."},{"type":"essay","q":"سقط شعاع ضوئي بزاوية 35° مع سطح المرآة. احسب: (أ) زاوية السقوط، (ب) زاوية الانعكاس، (ج) الزاوية بين الشعاع الساقط والمنعكس.","model":"أ) i = 90 − 35 = 55°. ب) r = 55°. ج) 55 + 55 = 110°."}],"hard":[{"type":"mcq","q":"تُسمّى الصورة في المرآة المستوية «تقديرية» لأنها:","options":["أكبر من الجسم","تتكوّن من تلاقي امتدادات الأشعة المنعكسة ولا يمكن استقبالها على حائل","مقلوبة رأسيًا","حقيقية أمام المرآة"],"answer":1,"why":"لا تتلاقى الأشعة الفعلية خلف المرآة بل امتداداتها فقط."},{"type":"mcq","q":"ما زاوية ميل كل مرآة في البيروسكوب البسيط؟","options":["0°","90°","45°","180°"],"answer":2,"why":"زاوية 45° تعكس الضوء بزاوية قائمة 90°."},{"type":"mcq","q":"إذا اقترب جسم مسافة 0.5 m نحو مرآة مستوية، فإن المسافة بين الجسم وصورته تقلّ بمقدار:","options":["2.0 m","0.5 m","0.25 m","1.0 m"],"answer":3,"why":"يقترب الجسم 0.5 m وتقترب الصورة 0.5 m فالمجموع 1.0 m."},{"type":"mcq","q":"الزاوية الكلية بين الشعاع الساقط والشعاع المنعكس إذا كانت i = 40° هي:","options":["80°","40°","50°","90°"],"answer":0,"why":"i + r = 40° + 40° = 80°."},{"type":"tfr","q":"ينطبق قانون الانعكاس (i = r) على الانعكاس غير المنتظم أيضًا عند كل نقطة دقيقة على السطح.","answer":true,"reasons":["يختفي القانون","لا ينطبق إلا على المرآة","لكن اختلاف ميل السطح الخشن من نقطة لأخرى يشتت الأشعة المنعكسة"],"reason":2},{"type":"tfr","q":"يمكن استقبال الصورة المتكوّنة في المرآة المستوية على شاشة ورقية خلف المرآة.","answer":false,"reasons":["لأنها صورة تقديرية لا تصل الأشعة الحقيقية خلف المرآة","نعم صورة حقيقية","يمكن استقبالها دائمًا"],"reason":0},{"type":"tfr","q":"إذا نظرت لساعة حائط تشير إلى 3:00 في مرآة مستوية فستبدو كأنها تشير إلى 9:00.","answer":true,"reasons":["تبقى 3:00","بسبب خاصية الانعكاس الجانبي في المرآة المستوية","تصبح 6:00"],"reason":1},{"type":"essay","q":"قارن بين الانعكاس المنتظم والانعكاس غير المنتظم من حيث نوع السطح وتكوين الصورة.","model":"المنتظم: سطح أملس مصقول (مرآة)، تنعكس الأشعة متوازية وتتكون صورة واضحة. غير المنتظم: سطح خشن (ورق/جدار)، تتشتت الأشعة ولا تتكون صورة."},{"type":"essay","q":"اشرح فكرة عمل البيروسكوب مع تحديد زاوية المرآتين.","model":"يحتوي أنبوبًا به مرآتان مستويتان متوازيتان مائلتان بزاوية 45°؛ تعكس العليا الضوء بزاوية 90° للأسفل نحو السفلى فتعكسه 90° نحو عين الراصد."},{"type":"essay","q":"كيف تثبت عمليًا قانون الانعكاس باستخدام مرآة مستوية وصندوق ضوئي ومنقلة؟","model":"نرسم خط المرآة والعمود المقام على ورقة، نوجّه شعاعًا بزاوية سقوط i معلومة، نحدد مسار الشعاع المنعكس ونقيس r بالمنقلة فنكرّر لعدة زوايا فنجد دائمًا i = r."}]}},
  {"id":"g9-phy-2-u13-1","grade":"g9","subject":"physics","term":2,"unit":13,"no":1,"title":"انكسار الضوء","summary":"شرح متحرك بـ SVG لدرس انكسار الضوء (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-refraction-of-light.html","video":"","pdf":"","notes":["انكسار الضوء: انحراف الضوء عند انتقاله مائلًا بين وسطين شفّافين بسبب تغيّر سرعته.","من أقل لأكبر كثافة ضوئية: يقترب من العمود؛ ومن أكبر لأقل: يبتعد عن العمود.","قانون سنل ومعامل الانكسار: n = sin i / sin r = c / v (بلا وحدة).","من ظواهر الانكسار: العمق الظاهري أقل من الحقيقي، وتشتت الضوء في المنشور."],"exercises":["فسّر لماذا يبدو القلم المغمور جزئيًا في كوب ماء كأنه مكسور.","سقط شعاع من الهواء على سائل بزاوية 45° فانكسر بزاوية 30°. احسب معامل انكسار السائل (sin45=0.707, sin30=0.5).","قارن بين مسار الشعاع عند الانتقال من الهواء للزجاج ومن الزجاج للهواء."],"levels":{"easy":[{"type":"mcq","q":"ما السبب الفيزيائي المباشر لحدوث انكسار الضوء بين وسطين شفافين؟","options":["توقف الضوء","تغيّر لون الضوء","امتصاص الضوء","تغيّر سرعة الضوء عند انتقاله بين الوسطين"],"answer":3,"why":"اختلاف سرعة الضوء بين الأوساط هو سبب انحرافه."},{"type":"mcq","q":"عند انتقال شعاع ضوئي مائل من الهواء إلى الزجاج فإنه:","options":["تقل سرعته وينكسر مقتربًا من العمود المقام","تزداد سرعته ويبتعد عن العمود","يرتد للخلف","لا تتغير سرعته"],"answer":0,"why":"الزجاج أكبر كثافة ضوئية فيبطئ الضوء ويقترب من العمود."},{"type":"mcq","q":"قانون سنل لحساب معامل الانكسار (n) عند السقوط من الهواء هو:","options":["n = i + r","n = sin i ÷ sin r","n = sin r ÷ sin i","n = i × r"],"answer":1,"why":"نسبة جيب زاوية السقوط إلى جيب زاوية الانكسار."},{"type":"mcq","q":"لماذا تبدو بركة الماء الصافي أقل عمقًا من عمقها الحقيقي؟","options":["بسبب الانعكاس فقط","لأن الماء يكبر الأجسام فقط","بسبب انكسار الأشعة الخارجة من الماء للهواء مبتعدةً عن العمود","بسبب التبخر"],"answer":2,"why":"تتلاقى امتدادات الأشعة المنكسرة عند عمق ظاهري أقرب للسطح."}],"medium":[{"type":"mcq","q":"سقط شعاع عموديًا على سطح ماء (i = 0°). ماذا يحدث له؟","options":["يتوقف","ينكسر بزاوية 45°","ينعكس تمامًا","تقل سرعته لكنه ينفذ مستقيمًا دون انحراف (r = 0°)"],"answer":3,"why":"السقوط العمودي يغير السرعة دون تغيير الاتجاه."},{"type":"mcq","q":"وحدة قياس معامل الانكسار (n) هي:","options":["ليس له وحدة","الدرجة (°)","m/s","المتر"],"answer":0,"why":"نسبة بين كميتين متماثلتين لذا هو بلا وحدة."},{"type":"mcq","q":"إذا كانت سرعة الضوء في الفراغ 3×10⁸ m/s وفي الزجاج 2×10⁸ m/s، فمعامل انكسار الزجاج هو:","options":["0.67","1.5","6.0","1.0"],"answer":1,"why":"n = 3×10⁸ ÷ 2×10⁸ = 1.5."},{"type":"tfr","q":"تقلّ سرعة الضوء عند انتقاله من الهواء إلى الماء أو الزجاج.","answer":true,"reasons":["تزداد سرعته في الزجاج","لأن الماء والزجاج أكبر كثافةً ضوئيةً من الهواء","تبقى ثابتة"],"reason":1},{"type":"tfr","q":"ينكسر الشعاع الساقط عموديًا (i = 0°) بزاوية انكسار 90°.","answer":false,"reasons":["يرتد دائمًا","ينكسر بزاوية 45°","ينفذ على استقامته دون انحراف (r = 0°) مع تغير سرعته فقط"],"reason":2},{"type":"essay","q":"فسّر لماذا يبدو القلم المغمور جزئيًا في كوب ماء كأنه مكسور.","model":"لأن الأشعة الضوئية القادمة من الجزء المغمور تنكسر مبتعدةً عن العمود المقام عند خروجها من الماء للهواء، فتراها العين على امتداداتها في موضع أقرب للسطح."},{"type":"essay","q":"سقط شعاع من الهواء على سائل بزاوية 45° فانكسر بزاوية 30°. احسب معامل انكسار السائل (sin45=0.707, sin30=0.5).","model":"n = sin 45° ÷ sin 30° = 0.707 ÷ 0.5 ≈ 1.41."}],"hard":[{"type":"mcq","q":"عند خروج شعاع ضوئي من الماء إلى الهواء مائلًا، فإنه ينكسر:","options":["لا ينكسر","مقتربًا من العمود","مبتعدًا عن العمود المقام (r > i)","بزاوية 0°"],"answer":2,"why":"تزداد سرعته في الهواء فيبتعد عن العمود."},{"type":"mcq","q":"أي ألوان الطيف يكون «الأكثر انكسارًا» عند مرور الضوء الأبيض عبر منشور زجاجي؟","options":["الأصفر","الأحمر","البرتقالي","البنفسجي"],"answer":3,"why":"البنفسجي أبطأ قليلًا في الزجاج فينحرف بزاوية أكبر من الأحمر."},{"type":"mcq","q":"عند مرور شعاع عبر لوح زجاجي متوازي الوجهين، يكون الشعاع الخارج:","options":["موازيًا للشعاع الساقط الأصلي ومزاحًا جانبيًا","عموديًا على الساقط","منطبقًا دون إزاحة","مختفيًا"],"answer":0,"why":"الانكسار الثاني يعادل الانكسار الأول فيخرج موازيًا."},{"type":"mcq","q":"إذا كان معامل انكسار الماس 2.4 وللماء 1.33، فأيهما يكون فيه الضوء أبطأ؟","options":["الماء","الماس (لأن معامل انكساره أكبر)","متساويان","لا يمر الضوء في الماس"],"answer":1,"why":"كلما زاد n قلت سرعة الضوء في الوسط (v = c/n)."},{"type":"tfr","q":"معامل الانكسار لأي مادة شفافة يكون دائمًا أكبر من أو يساوي 1.","answer":true,"reasons":["لأن سرعة الضوء في الفراغ c هي القصوى، وبما أن v ≤ c فإن n = c/v ≥ 1","قد يكون 0.5","دائمًا أقل من 1"],"reason":0},{"type":"tfr","q":"العمق الحقيقي للسمكة في الماء أكبر من العمق الظاهري الذي يراه الصياد من الهواء.","answer":true,"reasons":["العمق الظاهري أكبر","لذا على الصياد التصويب أعمق قليلًا من الموضع الظاهري للسمكة","متساويان"],"reason":1},{"type":"tfr","q":"يبقى تردّد الضوء ثابتًا عند انتقاله بين وسطين بينما تتغير سرعته وطوله الموجي.","answer":true,"reasons":["لا يتغير شيء","يتغير التردد فقط","التردد يعتمد على المصدر فقط، وتغير السرعة يغير الطول الموجي"],"reason":2},{"type":"essay","q":"قارن بين مسار الشعاع عند الانتقال من الهواء للزجاج ومن الزجاج للهواء.","model":"من الهواء للزجاج: تقل السرعة ويقترب من العمود (r < i). من الزجاج للهواء: تزداد السرعة ويبتعد عن العمود (r > i)."},{"type":"essay","q":"احسب سرعة الضوء في الماء إذا كان معامل انكساره 1.33 وسرعة الضوء في الفراغ 3×10⁸ m/s.","model":"v = c ÷ n = (3×10⁸) ÷ 1.33 ≈ 2.26 × 10⁸ m/s."},{"type":"essay","q":"اشرح سبب تفريق المنشور الزجاجي للضوء الأبيض إلى ألوان الطيف السبعة.","model":"الضوء الأبيض مزيج من سبعة ألوان تختلف قليلًا في سرعتها ومعامل انكسارها داخل الزجاج، فينكسر البنفسجي أكثر من الأحمر وتتفرق الألوان."}]}},
  {"id":"g9-phy-2-u13-2","grade":"g9","subject":"physics","term":2,"unit":13,"no":2,"title":"الانعكاس الداخلي الكلّي","summary":"شرح متحرك بـ SVG لدرس الانعكاس الداخلي الكلّي (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-total-internal-reflection.html","video":"","pdf":"","notes":["الزاوية الحرجة (c): زاوية السقوط في الوسط الأكبر كثافة التي تقابلها زاوية انكسار 90°.","شرطا الانعكاس الداخلي الكلي: من أكبر لأقل كثافة، و i > c.","العلاقة: sin c = 1 / n (كلما زاد n صغرت c).","تطبيقاته: الألياف البصرية للإنترنت، المناظير الطبية، والمناشير العاكسة."],"exercises":["اذكر شرطي حدوث الانعكاس الداخلي الكلي، وعرّف الزاوية الحرجة.","احسب الزاوية الحرجة للماء إذا كان معامل انكساره n = 1.33 (sin 48.8° ≈ 0.752).","اشرح كيف تنقل الألياف البصرية إشارات الإنترنت فائق السرعة عبر مسافات طويلة."],"levels":{"easy":[{"type":"mcq","q":"ما الزاوية الحرجة (c)؟","options":["زاوية السقوط في الوسط الأكبر كثافةً التي تقابلها زاوية انكسار 90°","زاوية انعكاس تساوي 0°","زاوية السقوط في الهواء دائمًا","زاوية تساوي 180°"],"answer":0,"why":"عند i = c يخرج الشعاع مماسًا للسطح (r = 90°)."},{"type":"mcq","q":"ما شرطا حدوث الانعكاس الداخلي الكلي؟","options":["من أقل لأكبر كثافة و i < c","انتقال الضوء من وسط أكبر لأقل كثافة، وأن تكون i > c","أن تكون i = 0°","استخدام مرآة سوداء"],"answer":1,"why":"لا بد من تحقق الشرطين معًا."},{"type":"mcq","q":"العلاقة الرياضية بين معامل الانكسار (n) والزاوية الحرجة (c) هي:","options":["c = 1 ÷ n","n = sin c","sin c = 1 ÷ n","n = 1 + sin c"],"answer":2,"why":"n = 1 / sin c."},{"type":"mcq","q":"التطبيق التقني الأهم للانعكاس الداخلي الكلي في الاتصالات والطب هو:","options":["السخان الشمسي","المصباح التقليدي","المغناطيس","الألياف البصرية والمنظار الطبي"],"answer":3,"why":"الألياف البصرية تنقل البيانات والصورة بالانعكاس الداخلي الكلي."}],"medium":[{"type":"mcq","q":"إذا كانت الزاوية الحرجة للماء 49° وسقط شعاع من الماء للهواء بزاوية 55°، فإنه:","options":["ينعكس انعكاسًا داخليًا كليًا بزاوية 55°","ينكسر للهواء","ينفذ عموديًا","يختفي"],"answer":0,"why":"لأن 55° > 49° ومن ماء لهواء يحدث انعكاس داخلي كلي."},{"type":"mcq","q":"إذا كانت الزاوية الحرجة لمادة شفافة 30° (sin 30° = 0.5)، فمعامل انكسارها n يساوي:","options":["0.5","2.0","1.5","3.0"],"answer":1,"why":"n = 1 ÷ 0.5 = 2.0."},{"type":"mcq","q":"لماذا يُفضّل المنشور العاكس (45°) على المرآة المستوية في المناظير الدقيقة؟","options":["لأنه يعكس 50% فقط","لأنه أرخص دائمًا","لأنه يعكس 100% من الضوء دون فقد أو صور ظلية مزدوجة","لأنه يكسر الضوء للخارج"],"answer":2,"why":"الانعكاس الداخلي الكلي كامل لا يفقد شدة الضوء."},{"type":"tfr","q":"يحدث الانعكاس الداخلي الكلي عندما تكون زاوية السقوط أكبر من الزاوية الحرجة في الوسط الأكبر كثافة.","answer":true,"reasons":["في الهواء فقط","عندما تكون أصغر من c","فتنعكس 100% من الأشعة داخل الوسط دون خروج"],"reason":2},{"type":"tfr","q":"كلما زاد معامل انكسار المادة (n)، زادت زاويتها الحرجة (c).","answer":false,"reasons":["بل «تقل» الزاوية الحرجة لأن sin c = 1/n (علاقة عكسية)","نعم تزداد","لا علاقة بينهما"],"reason":0},{"type":"essay","q":"اذكر شرطي حدوث الانعكاس الداخلي الكلي، وعرّف الزاوية الحرجة.","model":"الشرطان: (١) انتقال الضوء من وسط أكبر كثافة لأقل كثافة، (٢) i > c. والزاوية الحرجة هي زاوية السقوط التي تقابلها زاوية انكسار 90°."},{"type":"essay","q":"احسب الزاوية الحرجة للماء إذا كان معامل انكساره n = 1.33 (sin 48.8° ≈ 0.752).","model":"sin c = 1 ÷ 1.33 ≈ 0.752 ← إذن c ≈ 48.8°."}],"hard":[{"type":"mcq","q":"لماذا يتميّز الماس ببريق استثنائي مقارنةً بالزجاج؟","options":["لأنه معتم","لأنه يشع كهرباء","لأن زاويته الحرجة 80°","لأن معامل انكساره كبير جدًّا فزاويته الحرجة صغيرة جدًّا (24°) فيكثر الانعكاس الداخلي الكلي"],"answer":3,"why":"صغر الزاوية الحرجة يحبس الضوء داخله وينعكس مرارًا."},{"type":"mcq","q":"هل يمكن حدوث انعكاس داخلي كلي عند انتقال الضوء من «الهواء إلى الماء»؟","options":["لا أبدًا، لأنه ينتقل من أقل كثافة إلى أكبر كثافة","نعم دائمًا","نعم عند 45°","نعم عند 0°"],"answer":0,"why":"الشرط الأول ينص على الانتقال من الأكبر كثافة إلى الأقل كثافة."},{"type":"mcq","q":"من مزايا كابلات الألياف البصرية مقارنةً بالأسلاك النحاسية في الإنترنت:","options":["وزنها أثقل بكثير","سرعة نقل هائلة، فقدان ضئيل للإشارة، وأمان أعلى ضد التشويش","نقل أبطأ","تصدأ بالماء"],"answer":1,"why":"الضوء ينقل بيانات ضخمة لمسافات طويلة بسرعة فائقة."},{"type":"mcq","q":"عندما يرتد الشعاع داخل الزجاج بانعكاس داخلي كلي، فإنه يخضع لـ:","options":["يخرج بزاوية 0°","قانون الانكسار فقط","قانون الانعكاس (زاوية السقوط = زاوية الانعكاس)","يتحول إلى صوت"],"answer":2,"why":"ينطبق قانون الانعكاس بدقة داخل السطح العاكس."},{"type":"tfr","q":"يعمل المنظار الطبي (Endoscope) باستخدام حزم من الألياف البصرية لنقل الضوء والصورة من داخل الجسم.","answer":true,"reasons":["يستخدم أسلاك نحاس فقط","حزمة تضيء الداخل وحزمة تنقل الصورة بالانعكاس الداخلي الكلي","يستخدم أشعة إكس"],"reason":1},{"type":"tfr","q":"إذا سقط شعاع من الزجاج (c=42°) نحو الهواء بزاوية 40° فسيحدث له انعكاس داخلي كلي.","answer":false,"reasons":["ينفذ عموديًا","نعم ينعكس كليًا","لأن 40° أقل من 42° فسينكسر خارجًا للهواء مبتعدًا عن العمود"],"reason":2},{"type":"tfr","q":"المسافات الطويلة في الألياف البصرية لا تمنع انحناء الكابل ما دامت زاوية السقوط داخل الليف تبقى أكبر من الزاوية الحرجة.","answer":true,"reasons":["فيستمر الضوء بالانعكاس الكلي المتتابع على جدران الليف","ينكسر الضوء عند أول انحناء بسيط","الألياف لا تنحني"],"reason":0},{"type":"essay","q":"اشرح كيف تنقل الألياف البصرية إشارات الإنترنت فائق السرعة عبر مسافات طويلة.","model":"تُحوَّل البيانات إلى نبضات ضوئية تسير داخل قلب زجاجي نقي وتصطدم بجداره بزاوية أكبر من الزاوية الحرجة فتنعكس كليًا مرارًا دون فقدان يذكر."},{"type":"essay","q":"قارن بين مسار شعاع سقط من الزجاج (c=42°) نحو الهواء بزاوية 30° ثم 42° ثم 55°.","model":"عند 30°: ينكسر للهواء مبتعدًا عن العمود. عند 42°: يخرج مماسًا للسطح (r=90°). عند 55°: ينعكس داخليًا كليًا بزاوية 55°."},{"type":"essay","q":"اذكر ثلاثة تطبيقات عملية للانعكاس الداخلي الكلي في حياتنا الحديثة.","model":"١) كابلات الإنترنت بالألياف البصرية. ٢) المناظير الطبية (Endoscope). ٣) المناشير العاكسة في المناظير والبيروسكوب."}]}},
  {"id":"g9-phy-2-u14-1","grade":"g9","subject":"physics","term":2,"unit":14,"no":1,"title":"العدسات","summary":"شرح متحرك بـ SVG لدرس العدسات (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-thin-converging-lenses.html","video":"","pdf":"","notes":["العدسة المحدّبة (اللامّة) تجمع الأشعة المتوازية في البؤرة F، والمسافة إليها هي البعد البؤري f.","الأشعة الثلاثة: موازٍ ← F، بالمركز ← مستقيم، بـ F ← موازٍ.","الجسم أبعد من F ← صورة حقيقية مقلوبة؛ أقرب من F ← تقديرية معتدلة مكبّرة (عدسة مكبّرة).","طول النظر يُصحّح بعدسة محدّبة، وقصر النظر بعدسة مقعّرة."],"exercises":["اذكر الأشعة القياسية الثلاثة المستخدمة في رسم مسار الأشعة خلال العدسة المحدّبة الرقيقة.","قارن بين الصورة المتكوّنة عندما يكون الجسم أبعد من 2F وعندما يكون أقرب من F.","قارن بين طول النظر وقصر النظر من حيث موضع تكوّن الصورة والعدسة المصحّحة."],"levels":{"easy":[{"type":"mcq","q":"ما النقطة التي تتجمّع فيها الأشعة المتوازية بعد مرورها بالعدسة المحدّبة؟","options":["المركز البصري","البؤرة الرئيسة (F)","حافة العدسة","الشاشة البعيدة"],"answer":1,"why":"تجمع العدسة المحدّبة الأشعة المتوازية في البؤرة F."},{"type":"mcq","q":"الشعاع الذي يمر بالمركز البصري للعدسة الرقيقة:","options":["ينكسر بزاوية 90°","ينعكس للخلف","ينفذ على استقامته دون انحراف","يختفي"],"answer":2,"why":"الشعاع المار بالمركز البصري لا ينحرف."},{"type":"mcq","q":"أين نضع الجسم أمام عدسة محدّبة لتعمل كـ«عدسة مكبّرة» (تقديرية، معتدلة، مكبّرة)؟","options":["في اللانهاية","أبعد من 2F","عند 2F تمامًا","أقرب من البؤرة (على بُعد أقل من f)"],"answer":3,"why":"الوضع الوحيد الذي يعطي صورة تقديرية معتدلة مكبّرة هو أقل من f."},{"type":"mcq","q":"ما نوع العدسة المستخدمة لتصحيح «طول النظر»؟","options":["عدسة محدّبة (لامّة)","عدسة مقعّرة (مفرّقة)","مرآة مستوية","زجاج معتم"],"answer":0,"why":"تجمع العدسة المحدّبة الأشعة لتقع على الشبكية بدل خلفها."}],"medium":[{"type":"mcq","q":"وُضع جسم على بُعد 2F أمام عدسة محدّبة. صفات الصورة هي:","options":["تقديرية ومكبرة","حقيقية، مقلوبة، ومساوية للجسم","حقيقية ومصغرة","لا تتكون صورة"],"answer":1,"why":"عند 2F تكون الصورة عند 2F مساوية ومقلوبة وحقيقية."},{"type":"mcq","q":"أي جهاز يستخدم عدسة محدّبة وجسمًا أبعد من 2F لتكوين صورة حقيقية مصغّرة؟","options":["جهاز العرض","العدسة المكبّرة","الكاميرا (والعين البشرية)","المرآة المستوية"],"answer":2,"why":"الكاميرا تكوّن صورة حقيقية مصغرة على المستشعر."},{"type":"mcq","q":"أي جهاز يضع الشريحة بين F و 2F لتكوين صورة حقيقية مقلوبة مكبّرة على الحائط؟","options":["النظارة الشمسية","العدسة المكبّرة","مرآة السيارة","جهاز العرض (البروجكتر)"],"answer":3,"why":"العارض يكبّر الصورة على شاشة حقيقية."},{"type":"tfr","q":"تكون جميع الصور الحقيقية المتكوّنة بالعدسة المحدّبة مقلوبةً.","answer":true,"reasons":["بينما تكون الصورة التقديرية معتدلةً دائمًا","الصورة الحقيقية معتدلة دائمًا","العدسة لا تكون صورًا حقيقية"],"reason":0},{"type":"tfr","q":"الشعاع الساقط موازيًا للمحور الرئيس ينكسر مارًّا بالبؤرة F.","answer":true,"reasons":["يمر بالمركز البصري","وهذه القاعدة الأولى في رسم مخطط الأشعة للعدسة اللامّة","يرتد للخلف"],"reason":1},{"type":"essay","q":"اذكر الأشعة القياسية الثلاثة المستخدمة في رسم مسار الأشعة خلال العدسة المحدّبة الرقيقة.","model":"١) الموازي للمحور ينكسر بالبؤرة F. ٢) المار بالمركز البصري ينفذ مستقيمًا. ٣) المار بالبؤرة ينكسر موازيًا للمحور."},{"type":"essay","q":"قارن بين الصورة المتكوّنة عندما يكون الجسم أبعد من 2F وعندما يكون أقرب من F.","model":"أبعد من 2F: حقيقية، مقلوبة، مصغّرة (تُستقبل على شاشة). أقرب من F: تقديرية، معتدلة، مكبّرة (لا تُستقبل على شاشة — عدسة مكبّرة)."}],"hard":[{"type":"mcq","q":"عدسة محدّبة بعدها البؤري 8 cm. إذا وُضع جسم على بُعد 5 cm منها فالصورة تكون:","options":["تقديرية، معتدلة، مكبّرة","حقيقية، مقلوبة، مصغرة","حقيقية ومساوية","حقيقية ومكبرة"],"answer":0,"why":"لأن 5 cm < 8 cm (أقرب من البؤرة)."},{"type":"mcq","q":"الفرق الأساسي بين الصورة الحقيقية والتقديرية هو أن الحقيقية:","options":["معتدلة دائمًا","تُستقبل على شاشة وتتكوّن من تلاقي الأشعة الفعلية","لا تُستقبل على شاشة","تتكون من امتدادات الأشعة"],"answer":1,"why":"الصورة الحقيقية ناتجة عن تلاقي الأشعة نفسها."},{"type":"mcq","q":"ما نوع العدسة المستخدمة لتصحيح «قصر النظر»؟","options":["منشور زجاجي","عدسة محدّبة (لامّة)","عدسة مقعّرة (مفرّقة)","لوح خشبي"],"answer":2,"why":"العدسة المقعرة تفرّق الأشعة قليلًا لتتجمع على الشبكية بدل أمامها."},{"type":"mcq","q":"عدسة محدّبة أكثر سمكًا وتحدّبًا يكون بُعدها البؤري:","options":["صفرًا","أطول بكثير","لانهائيًا","أقصر (أقوى تجميعًا للضوء)"],"answer":3,"why":"زيادة التحدّب تقرّب البؤرة وتزيد قدرة العدسة."},{"type":"tfr","q":"تُستخدم العدسة المحدّبة لتصحيح قصر النظر.","answer":false,"reasons":["تصحّح كليهما","نعم لقصر النظر","العدسة المحدّبة تصحّح طول النظر، أما قصر النظر فتصحّحه العدسة المقعّرة"],"reason":2},{"type":"tfr","q":"عند وضع جسم عند البؤرة F تمامًا لا تتكوّن صورة واضحة لأن الأشعة تخرج متوازيةً.","answer":true,"reasons":["وتُستغل هذه الحالة في كشافات الإضاءة لإنتاج حزمة ضوء متوازية","تتكوّن صورة مصغّرة","تتكوّن صورة عند المركز"],"reason":0},{"type":"tfr","q":"تغطية النصف السفلي لعدسة محدّبة بقطعة ورق سوداء يُخفي نصف الصورة على الشاشة.","answer":false,"reasons":["يختفي نصف الصورة","تبقى الصورة كاملةً لكن تقلّ شدة إضاءتها (سطوعها) لأن باقي العدسة يمرر أشعة من كل الجسم","تختفي الصورة تمامًا"],"reason":1},{"type":"essay","q":"قارن بين طول النظر وقصر النظر من حيث موضع تكوّن الصورة والعدسة المصحّحة.","model":"طول النظر: تتكوّن خلف الشبكية ويُصحّح بعدسة محدّبة. قصر النظر: تتكوّن أمام الشبكية ويُصحّح بعدسة مقعّرة."},{"type":"essay","q":"عدسة محدّبة بعدها البؤري 12 cm. حدّد صفات الصورة لجسم يبعد: (أ) 30 cm، (ب) 24 cm، (ج) 8 cm.","model":"أ) >2F: حقيقية مقلوبة مصغّرة. ب) =2F: حقيقية مقلوبة مساوية. ج) <F: تقديرية معتدلة مكبّرة."},{"type":"essay","q":"كيف تقيس البعد البؤري (f) لعدسة محدّبة في مختبر المدرسة باستخدام نافذة بعيدة وشاشة ورقية؟","model":"نحرّك الشاشة خلف العدسة حتى تتكوّن أوضح صورة مصغّرة ومقلوبة للنافذة البعيدة، ثم نقيس المسافة بين العدسة والشاشة بالمسطرة فتكون هي البعد البؤري f."}]}},
  {"id":"g9-phy-2-u15-1","grade":"g9","subject":"physics","term":2,"unit":15,"no":1,"title":"التيّار الكهربائيّ في الدوائر الكهربائيّة","summary":"شرح متحرك بـ SVG لدرس التيّار الكهربائيّ في الدوائر الكهربائيّة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-electric-current-circuits.html","video":"","pdf":"","notes":["التيار الكهربائي I = Q / t، ووحدته الأمبير (1 A = 1 C/s).","في الفلزات ينتج التيار عن حركة الإلكترونات الحرة (من − إلى +)، بينما التيار الاصطلاحي من + إلى −.","يُوصل الأميتر دائمًا على التوالي، والتيار متساوٍ في جميع نقاط دائرة التوالي.","البطاريات تعطي تيارًا مستمرًا (DC)، ومقابس المنزل تيارًا مترددًا (AC)."],"exercises":["عرّف التيار الكهربائي واكتب قانونه ووحدات قياس كمياته الثلاث.","يمر تيار شدته 0.5 A في مصباح لمدة 4 دقائق. احسب الشحنة الكهربائية المارة.","قارن بين التيار المستمر (DC) والتيار المتردد (AC) مع مثال لمصدر كل منهما."],"levels":{"easy":[{"type":"mcq","q":"ما وحدة قياس شدة التيار الكهربائي في النظام الدولي؟","options":["الأوم (Ω)","الفولت (V)","الأمبير (A)","الكولوم (C)"],"answer":2,"why":"يُقاس التيار الكهربائي بوحدة الأمبير (A)."},{"type":"mcq","q":"كيف يُوصَّل جهاز الأميتر في الدائرة الكهربائية لقياس التيار؟","options":["بين الأرضي والسقف","على التوازي","خارج الدائرة","على التوالي"],"answer":3,"why":"الأميتر يُوصل على التوالي ليمر عبره كامل التيار."},{"type":"mcq","q":"مرّت شحنة كهربائية 60 C عبر سلك خلال 15 s. شدة التيار تساوي:","options":["4 A","900 A","45 A","0.25 A"],"answer":0,"why":"I = Q ÷ t = 60 ÷ 15 = 4 A."},{"type":"mcq","q":"ما اتجاه «تدفق الإلكترونات» الفعلي خارج البطارية؟","options":["من الموجب إلى السالب","من القطب السالب (−) إلى القطب الموجب (+)","في كلا الاتجاهين معًا","لا تتحرك الإلكترونات"],"answer":1,"why":"الإلكترونات سالبة فتتنافر مع السالب وتنجذب للموجب."}],"medium":[{"type":"mcq","q":"تيار شدته 3 A يسري لمدة دقيقة واحدة (60 s). ما الشحنة المارة؟","options":["20 C","3 C","180 C","63 C"],"answer":2,"why":"Q = 3 × 60 = 180 C."},{"type":"mcq","q":"ما وحدة قياس الشحنة الكهربائية (Q)؟","options":["الواط (W)","الأمبير (A)","الجول (J)","الكولوم (C)"],"answer":3,"why":"تقاس الشحنة بالكولوم (C)."},{"type":"mcq","q":"ما نوع التيار الذي تنتجه البطاريات الجافة؟","options":["تيار مستمر (DC) يسري في اتجاه واحد","تيار متردد (AC)","تيار حراري","لا تنتج تيارًا"],"answer":0,"why":"البطاريات مصدر للتيار المستمر DC."},{"type":"tfr","q":"التيار الاصطلاحي يسري من القطب الموجب إلى السالب، وهو عكس اتجاه حركة الإلكترونات.","answer":true,"reasons":["في نفس الاتجاه","اصطلح العلماء على اتجاهه قبل اكتشاف الإلكترون السالب","كلاهما من السالب للموجب"],"reason":1},{"type":"tfr","q":"يُستهلك التيار الكهربائي تدريجيًا أثناء مروره في المصباح فيقل بعد المصباح.","answer":false,"reasons":["يختفي بعد المصباح","نعم يقل للنصف","التيار (الشحنات) محفوظ ولا يُستهلك؛ الذي يتحول ويُستهلك هو الطاقة الكهربائية"],"reason":2},{"type":"essay","q":"عرّف التيار الكهربائي واكتب قانونه ووحدات قياس كمياته الثلاث.","model":"معدل تدفق الشحنة الكهربائية في الثانية: I = Q ÷ t، حيث I بالأمبير (A)، و Q بالكولوم (C)، و t بالثانية (s)."},{"type":"essay","q":"يمر تيار شدته 0.5 A في مصباح لمدة 4 دقائق. احسب الشحنة الكهربائية المارة.","model":"t = 4 × 60 = 240 s. Q = 0.5 × 240 = 120 C."}],"hard":[{"type":"mcq","q":"لماذا تُغلّف أسلاك النحاس الكهربائية بطبقة من البلاستيك؟","options":["لزيادة التيار","لأن البلاستيك عازل كهربائي يحمي الإنسان من الصعق ويمنع التماس الأسلاك","لتسخين السلك","لجعل السلك أثقل"],"answer":1,"why":"العزل البلاستيكي ضروري للسلامة الكهربائية."},{"type":"mcq","q":"في دائرة توالي بها مصباحان وأميتر قبل الأول يقرأ 0.5 A؛ كم يقرأ أميتر آخر بعد المصباح الثاني؟","options":["1.0 A","0.25 A","0.5 A (نفس القراءة)","0 A"],"answer":2,"why":"التيار لا يُستهلك ويبقى ثابتًا في كل نقاط دائرة التوالي."},{"type":"mcq","q":"كم ثانيةً تلزم لمرور شحنة 120 C في سلك تياره 4 A؟","options":["0.03 s","480 s","124 s","30 s"],"answer":3,"why":"t = Q ÷ I = 120 ÷ 4 = 30 s."},{"type":"mcq","q":"ما نوع التيار الموجود في مقابس الكهرباء المنزلية؟","options":["تيار متردد (AC)","تيار مستمر (DC)","تيار ساكن","تيار مغناطيسي"],"answer":0,"why":"كهرباء الشبكة المنزلية تيار متردد AC."},{"type":"tfr","q":"الأمبير الواحد (1 A) يكافئ مرور شحنة 1 كولوم كل ثانية (1 C/s).","answer":true,"reasons":["من القانون I = Q / t","يكافئ 1 جول/ثانية","يكافئ 1 فولت/ثانية"],"reason":0},{"type":"tfr","q":"يجب توصيل الأميتر على التوازي مع المصباح.","answer":false,"reasons":["نعم على التوازي","يُوصل الأميتر دائمًا على التوالي، أما الفولتميتر فعلى التوازي","لا فرق بينهما"],"reason":1},{"type":"tfr","q":"في الفلزات الصلبة، تتحرك الإلكترونات الحرة لتنقل التيار الكهربائي.","answer":true,"reasons":["لا توجد إلكترونات حرة","تتحرك البروتونات","أما الذرات الموجبة فتهتز في مواقعها الثابتة فقط"],"reason":2},{"type":"essay","q":"قارن بين التيار المستمر (DC) والتيار المتردد (AC) مع مثال لمصدر كل منهما.","model":"DC يسري في اتجاه واحد ثابت (البطارية). AC يعكس اتجاهه دوريًا (مقبس الكهرباء المنزلي)."},{"type":"essay","q":"ما الفرق بين «التيار الاصطلاحي» و«تدفق الإلكترونات»؟","model":"التيار الاصطلاحي يُرسم من (+) إلى (−) خارج البطارية، أما الإلكترونات السالبة فتتحرك فعليًا من (−) إلى (+)."},{"type":"essay","q":"لماذا تكون قراءة الأميتر متساوية قبل وبعد المصباح في دائرة التوالي؟","model":"لأن الشحنات الكهربائية محفوظة لا تفنى في المصباح، وإنما تنقل طاقتها إلى المصباح لتتحول إلى ضوء وحرارة."}]}},
  {"id":"g9-phy-2-u15-2","grade":"g9","subject":"physics","term":2,"unit":15,"no":2,"title":"فرق الجهد والقوّة الدافعة الكهربائيّة","summary":"شرح متحرك بـ SVG لدرس فرق الجهد والقوّة الدافعة الكهربائيّة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-voltage-and-emf.html","video":"","pdf":"","notes":["القوة الدافعة (e.m.f) للمصدر وفرق الجهد (p.d) للمكوّن كلاهما يُقاس بالفولت (1 V = 1 J/C).","القانون: V = E / Q، ومنه E = Q × V.","يُوصل الفولتميتر دائمًا على التوازي، والأميتر على التوالي.","عند توصيل الخلايا على التوالي تُجمع فولتيتها، ومجموع فروق الجهد في التوالي يساوي e.m.f."],"exercises":["قارن بين الأميتر والفولتميتر من حيث الكمية المقاسة والوحدة وطريقة التوصيل في الدائرة.","نقلت بطارية 9 V طاقةً مقدارها 180 J. احسب الشحنة الكهربائية Q المارة في الدائرة.","عرّف القوة الدافعة الكهربائية (e.m.f) وفرق الجهد (p.d) موضحًا الفرق بينهما."],"levels":{"easy":[{"type":"mcq","q":"ما وحدة قياس فرق الجهد والقوة الدافعة الكهربائية؟","options":["الكولوم (C)","الأمبير (A)","الأوم (Ω)","الفولت (V)"],"answer":3,"why":"تُقاس كل من e.m.f و p.d بوحدة الفولت (V)."},{"type":"mcq","q":"كيف يُوصَّل جهاز الفولتميتر لقياس فرق الجهد عبر مصباح؟","options":["على التوازي بين طرفي المصباح","على التوالي في السلك","خارج الدائرة","بدل البطارية"],"answer":0,"why":"الفولتميتر يُوصل دائمًا على التوازي."},{"type":"mcq","q":"تكافئ وحدة الفولت الواحد (1 V):","options":["1 كولوم / ثانية","1 جول / كولوم (1 J/C)","1 جول × ثانية","1 نيوتن / متر"],"answer":1,"why":"من القانون V = E / Q."},{"type":"mcq","q":"مرّت شحنة 4 C عبر مصباح فرق جهده 6 V. ما الطاقة المحوّلة فيه؟","options":["10 J","1.5 J","24 J","2 J"],"answer":2,"why":"E = Q × V = 4 × 6 = 24 J."}],"medium":[{"type":"mcq","q":"وُصلت 4 بطاريات متماثلة (1.5 V لكل منها) على التوالي في نفس الاتجاه. القوة الدافعة الكلية هي:","options":["12 V","1.5 V","3 V","6 V"],"answer":3,"why":"4 × 1.5 = 6 V."},{"type":"mcq","q":"في دائرة توالٍ ببطارية 9 V ومصباحين: فرق الجهد على الأول 4 V. كم فرق الجهد على الثاني؟","options":["5 V","9 V","13 V","4 V"],"answer":0,"why":"9 − 4 = 5 V."},{"type":"mcq","q":"ما الفرق بين القوة الدافعة (e.m.f) وفرق الجهد (p.d)؟","options":["e.m.f بالأمبير و p.d بالفولت","e.m.f خاصة بالمصدر (البطارية) و p.d خاصة بالمكوّن (المصباح)","لا يوجد أي فرق في الموقع","p.d خاصة بالبطارية فقط"],"answer":1,"why":"كلاهما بالفولت لكن e.m.f طاقة معطاة من المصدر و p.d طاقة محولة بالمكون."},{"type":"tfr","q":"يُوصل الفولتميتر دائمًا على التوازي بين طرفي المكوّن المراد قياس فرق جهده.","answer":true,"reasons":["يُوصل بدل المفتاح","يُوصل على التوالي","لقياس فرق الطاقة لكل كولوم بين نقطتي الدخول والخروج للمكوّن"],"reason":2},{"type":"tfr","q":"تُعد القوة الدافعة الكهربائية (e.m.f) قوةً ميكانيكيةً تُقاس بوحدة النيوتن.","answer":false,"reasons":["رغم اسمها التاريخي، هي طاقة لكل وحدة شحنة وتُقاس بالفولت (J/C) لا بالنيوتن","نعم تقاس بالنيوتن","تقاس بالكيلوجرام"],"reason":0},{"type":"essay","q":"قارن بين الأميتر والفولتميتر من حيث الكمية المقاسة والوحدة وطريقة التوصيل في الدائرة.","model":"الأميتر: يقيس التيار (أمبير A)، يُوصل على التوالي. الفولتميتر: يقيس فرق الجهد (فولت V)، يُوصل على التوازي."},{"type":"essay","q":"نقلت بطارية 9 V طاقةً مقدارها 180 J. احسب الشحنة الكهربائية Q المارة في الدائرة.","model":"Q = E ÷ V = 180 ÷ 9 = 20 C."}],"hard":[{"type":"mcq","q":"نُقلت طاقة 45 J عند مرور شحنة 5 C عبر مقاومة. كم فرق الجهد عبرها؟","options":["40 V","225 V","9 V","0.11 V"],"answer":2,"why":"V = E ÷ Q = 45 ÷ 5 = 9 V."},{"type":"mcq","q":"ماذا يعني أن بطارية هاتف قوتها الدافعة 3.7 V؟","options":["تعمل 3.7 ساعة","تنتج 3.7 أمبير كل ثانية","وزنها 3.7 نيوتن","تزوّد كل 1 كولوم من الشحنة بطاقة 3.7 جول"],"answer":3,"why":"1 V = 1 J/C."},{"type":"mcq","q":"تكون مقاومة الفولتميتر المثالي:","options":["كبيرة جدًّا (حتى لا يسحب تيارًا من الدائرة)","صفرًا","تساوي 1 أوم","سالبة"],"answer":0,"why":"المقاومة العالية تمنع تسرّب التيار عبر الفولتميتر."},{"type":"mcq","q":"بطاريتان 1.5 V وُصلتا متعاكستين (+ مع +) في لعبة أطفال. الجهد الكلي الناتج هو:","options":["3 V","0 V (لا تعمل اللعبة)","1.5 V","4.5 V"],"answer":1,"why":"البطاريتان المتعاكستان تلغي كل منهما الأخرى (1.5 − 1.5 = 0)."},{"type":"tfr","q":"في دائرة التوالي، مجموع فروق الجهد عبر المكوّنات يساوي القوة الدافعة للبطارية.","answer":true,"reasons":["فرق الجهد متساوٍ للبطارية في كل مكون","تحقيقًا لمبدأ حفظ الطاقة في الدائرة","مجموعها صفر"],"reason":1},{"type":"tfr","q":"توصيل بطاريات على التوالي في نفس الاتجاه يزيد القوة الدافعة الكهربائية الكلية.","answer":true,"reasons":["تبقى ثابتة","تقل الفولتية","فتُجمع قيم فولتية البطاريات معًا"],"reason":2},{"type":"tfr","q":"إذا وُضع فولتميتر بطريق الخطأ على التوالي في دائرة، فسيزداد التيار بشدة.","answer":false,"reasons":["مقاومة الفولتميتر عالية جدًّا فتمنع مرور التيار تقريبًا ويتوقف المصباح","نعم يزداد التيار","لا يتأثر التيار"],"reason":0},{"type":"essay","q":"عرّف القوة الدافعة الكهربائية (e.m.f) وفرق الجهد (p.d) موضحًا الفرق بينهما.","model":"e.m.f هي الطاقة التي يمنحها المصدر لكل 1 C لدفعه حول الدائرة كاملة؛ و p.d هي الطاقة المحوّلة من كهربائية لصور أخرى لكل 1 C يمر عبر مكوّن."},{"type":"essay","q":"لديك ٣ خلايا جافة (1.5 V لكل منها) ومصباحان متماثلان على التوالي. احسب الجهد الكلي وفرق الجهد على كل مصباح.","model":"الجهد الكلي = 3 × 1.5 = 4.5 V. وبما أن المصباحين متماثلان، يأخذ كل منهما 4.5 ÷ 2 = 2.25 V."},{"type":"essay","q":"علّل: لماذا لا يعمل جهاز تحكّم التلفاز إذا ركّبت إحدى البطاريتين بالمقلوب؟","model":"لأن البطاريتين تصبحان متعاكستين فيُلغي جهدهما بعضه البعض (1.5 − 1.5 = 0 V) فلا يمر تيار."}]}},
  {"id":"g9-phy-2-u15-3","grade":"g9","subject":"physics","term":2,"unit":15,"no":3,"title":"الكهرباء والطاقة","summary":"شرح متحرك بـ SVG لدرس الكهرباء والطاقة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-electricity-and-energy.html","video":"","pdf":"","notes":["القدرة الكهربائية: P = I × V (واط)، والطاقة: E = I × V × t (جول).","فاتورة الكهرباء تُقاس بالكيلوواط ساعة (kWh) = القدرة (kW) × الزمن (h)، و 1 kWh = 3.6 MJ.","نختار المنصهر (الفيوز) بقيمة أعلى قليلًا من تيار تشغيل الجهاز I = P / V.","الأجهزة الحرارية والتكييف هي الأعلى استهلاكًا للطاقة في المنزل."],"exercises":["مكواة كهربائية تعمل على 230 V وتيار 5 A لمدة 10 دقائق. احسب قدرتها والطاقة المستهلكة بالجول.","تلفاز قدرته 200 W يعمل 5 ساعات يوميًا. احسب استهلاكه الشهري (30 يومًا) بـ kWh وتكلفته بسعر 15 بيسة للوحدة.","فسّر كيف نختار قيمة المنصهر (الفيوز) المناسبة لجهاز كهربائي مع مثال."],"levels":{"easy":[{"type":"mcq","q":"قانون حساب القدرة الكهربائية من التيار والجهد هو:","options":["P = I × V","P = V ÷ I","P = I ÷ V","P = I + V"],"answer":0,"why":"القدرة الكهربائية تساوي حاصل ضرب التيار في فرق الجهد."},{"type":"mcq","q":"مصباح يعمل على جهد 12 V ويمر فيه تيار 0.5 A؛ ما قدرته؟","options":["24 W","6 W","12.5 W","0.04 W"],"answer":1,"why":"P = 0.5 × 12 = 6 W."},{"type":"mcq","q":"الوحدة المستخدمة في عدّاد وفاتورة الكهرباء المنزلية هي:","options":["الأوم","الأمبير","الكيلوواط ساعة (kWh)","النيوتن"],"answer":2,"why":"تُقاس الطاقة الكهربائية المستهلكة في المنازل بـ kWh."},{"type":"mcq","q":"سخّان قدرته 2 kW يعمل لمدة 3 ساعات؛ كم وحدة (kWh) يستهلك؟","options":["6000 kWh","5 kWh","0.67 kWh","6 kWh"],"answer":3,"why":"E = 2 kW × 3 h = 6 kWh."}],"medium":[{"type":"mcq","q":"غلاية قدرتها 2000 W تعمل على جهد 250 V. ما شدة التيار المار فيها؟","options":["8 A","500,000 A","0.125 A","2250 A"],"answer":0,"why":"I = P ÷ V = 2000 ÷ 250 = 8 A."},{"type":"mcq","q":"ما المنصهر (الفيوز) الأنسب للجهاز السابق الذي تياره 8 A من بين (3A, 5A, 10A, 30A)؟","options":["5 A","10 A (أعلى قليلًا من تيار التشغيل)","3 A","30 A"],"answer":1,"why":"نختار منصهرًا أعلى بقليل من تيار التشغيل ليحمي الجهاز دون انصهار فوري."},{"type":"mcq","q":"جهاز جهده 10 V وتياره 2 A يعمل لمدة 30 s. ما الطاقة المنقولة بالجول؟","options":["60 J","20 J","600 J","150 J"],"answer":2,"why":"E = I × V × t = 2 × 10 × 30 = 600 J."},{"type":"tfr","q":"الكيلوواط ساعة (kWh) هي وحدة قياس «للطاقة» الكهربائية وليست للقدرة.","answer":true,"reasons":["لأنها حاصل ضرب القدرة (kW) في الزمن (h) وتساوي 3.6 MJ","هي وحدة قدرة","هي وحدة تيار"],"reason":0},{"type":"tfr","q":"يُحسب التيار المار في جهاز كهربائي بالقانون I = P ÷ V.","answer":true,"reasons":["يحسب بـ P × V","بإعادة ترتيب قانون القدرة P = I × V","يحسب بـ V ÷ P"],"reason":1},{"type":"essay","q":"مكواة كهربائية تعمل على 230 V وتيار 5 A لمدة 10 دقائق. احسب قدرتها والطاقة المستهلكة بالجول.","model":"P = 5 × 230 = 1150 W. t = 600 s ← E = 1150 × 600 = 690,000 J (690 kJ)."},{"type":"essay","q":"تلفاز قدرته 200 W يعمل 5 ساعات يوميًا. احسب استهلاكه الشهري (30 يومًا) بـ kWh وتكلفته بسعر 15 بيسة للوحدة.","model":"0.2 kW × 5 h = 1 kWh يوميًا ← 30 kWh شهريًا × 15 = 450 بيسة."}],"hard":[{"type":"mcq","q":"كم جولًا يوجد في 1 كيلوواط ساعة (1 kWh)؟","options":["60 J","1000 J","3600 J","3,600,000 J (3.6 MJ)"],"answer":3,"why":"1000 W × 3600 s = 3,600,000 J."},{"type":"mcq","q":"مصباح قدرته 100 W يعمل 10 ساعات. كم يستهلك بـ kWh؟","options":["1 kWh","1000 kWh","10 kWh","0.1 kWh"],"answer":0,"why":"100 W = 0.1 kW، إذن 0.1 × 10 = 1 kWh."},{"type":"mcq","q":"ما وظيفة المنصهر (الفيوز) في القابس الكهربائي؟","options":["يزيد الجهد","ينصهر سلكه الرفيع ويقطع الدائرة عند مرور تيار زائد لمنع الحريق وتلف الجهاز","يقلل الفاتورة","يشحن البطارية"],"answer":1,"why":"المنصهر أداة أمان تقطع التيار الزائد فورًا."},{"type":"mcq","q":"إذا كان سعر 1 kWh هو 15 بيسة، فما تكلفة استهلاك 20 kWh؟","options":["1.3 بيسة","35 بيسة","300 بيسة","3000 بيسة"],"answer":2,"why":"20 × 15 = 300 بيسة."},{"type":"tfr","q":"كلما زادت قدرة الجهاز بالواط زاد استهلاكه للطاقة خلال نفس الزمن.","answer":true,"reasons":["لا علاقة بينهما","القدرة الأعلى توفر طاقة","لأن E = P × t تتناسب طرديًا مع القدرة"],"reason":2},{"type":"tfr","q":"يُفضّل وضع منصهر 30 A لجهاز يعمل بتيار 2 A لحمايته.","answer":false,"reasons":["منصهر 30 A كبير جدًّا فلن ينصهر عند حدوث عطل 15 A مما يسبّب حريقًا؛ الصحيح منصهر 3 A","نعم كلما كبر الفيوز كان آمن","المنصهر لا يحمي الجهاز"],"reason":0},{"type":"tfr","q":"الأجهزة الحرارية كالمكيّف والغلاية تستهلك طاقة أكبر بكثير من أجهزة الإضاءة LED.","answer":true,"reasons":["LED يستهلك أكثر","لأن قدرتها بالكيلوواط بينما مصباح LED بضع واطات فقط","كلاهما متساوٍ"],"reason":1},{"type":"essay","q":"فسّر كيف نختار قيمة المنصهر (الفيوز) المناسبة لجهاز كهربائي مع مثال.","model":"نحسب تيار التشغيل I = P/V ثم نختار منصهرًا أكبر قليلًا من I (مثلًا لجهاز تياره 4 A نختار منصهر 5 A)."},{"type":"essay","q":"أثبت أن 1 kWh = 3.6 MJ.","model":"1 kWh = 1000 W × 3600 s = 3,600,000 J = 3.6 MJ."},{"type":"essay","q":"اذكر ثلاث نصائح عملية لتقليل فاتورة الكهرباء في منزلك بعُمان.","model":"١) ضبط المكيّف على 24°C وصيانة فلاتره. ٢) استبدال المصابيح القديمة بـ LED. ٣) إطفاء السخانات والأجهزة غير المستخدمة."}]}},
  {"id":"g9-phy-2-u16-1","grade":"g9","subject":"physics","term":2,"unit":16,"no":1,"title":"المقاوَمة الكهربائيّة","summary":"شرح متحرك بـ SVG لدرس المقاوَمة الكهربائيّة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-electrical-resistance.html","video":"","pdf":"","notes":["المقاومة R = V / I وتقاس بالأوم (Ω).","قانون أوم: I يتناسب طرديًا مع V عند ثبات الحرارة (خط مستقيم يمر بالأصل).","مصباح الفتيلة غير أومي لأن مقاومته تزداد بسخونة الفتيلة.","المقاومة المتغيرة تتحكم بشدة التيار في الإضاءة والصوت."],"exercises":["اكتب نصّ قانون أوم وصيغته الرياضية ووحدات القياس.","مقاومة 8 Ω وُصلت ببطارية 12 V. احسب التيار المار والقدرة المستهلكة فيها.","قارن بين منحنى (I–V) للمقاومة الثابتة ومنحنى (I–V) لمصباح الفتيلة مع التفسير."],"levels":{"easy":[{"type":"mcq","q":"ما وحدة قياس المقاومة الكهربائية؟","options":["الفولت (V)","الأوم (Ω)","الأمبير (A)","الواط (W)"],"answer":1,"why":"تقاس المقاومة بالأوم (Ω) = فولت/أمبير."},{"type":"mcq","q":"مقاومة فرق جهدها 20 V وتيارها 4 A؛ قيمتها تساوي:","options":["0.2 Ω","80 Ω","5 Ω","16 Ω"],"answer":2,"why":"R = 20 ÷ 4 = 5 Ω."},{"type":"mcq","q":"ما الشرط الضروري ليتحقق قانون أوم في موصل فلزي؟","options":["استخدام بطارية واحدة","ارتفاع الحرارة بشدة","انقطاع التيار","ثبات درجة الحرارة"],"answer":3,"why":"ارتفاع الحرارة يزيد مقاومة الفلز فيكسر التناسب الطردي."},{"type":"mcq","q":"ما شكل التمثيل البياني (I–V) لمقاومة ثابتة (موصل أومي) عند ثبات الحرارة؟","options":["خط مستقيم يمر بنقطة الأصل","منحنى يتناقص","دائرة مغلقة","خط أفقي"],"answer":0,"why":"التناسب الطردي يمثَّل بخط مستقيم يمر بـ (0,0)."}],"medium":[{"type":"mcq","q":"مقاومة 6 Ω يمر فيها تيار 2 A. ما فرق الجهد بين طرفيها؟","options":["3 V","12 V","8 V","4 V"],"answer":1,"why":"V = I × R = 2 × 6 = 12 V."},{"type":"mcq","q":"مقاومة 10 Ω وُصلت ببطارية 5 V. ما شدة التيار المار فيها؟","options":["2 A","50 A","0.5 A","15 A"],"answer":2,"why":"I = V ÷ R = 5 ÷ 10 = 0.5 A."},{"type":"mcq","q":"لماذا تزداد مقاومة فتيلة المصباح عند زيادة التيار فيها؟","options":["لأن الجهد ينعدم","لأن طولها ينقص","لأنها تبرد","لأن الفتيلة تسخن بشدة فتزداد اهتزازات الذرات وتعيق حركة الإلكترونات"],"answer":3,"why":"السخونة تزيد تصادمات الإلكترونات بالذرات فتزداد المقاومة."},{"type":"tfr","q":"الموصل الأومي يكون منحناه (I–V) خطًا مستقيمًا يمر بنقطة الأصل عند ثبات درجة الحرارة.","answer":true,"reasons":["يكون منحنيًا","لأن النسبة V/I تبقى ثابتةً تمامًا","لا يمر بالأصل"],"reason":1},{"type":"tfr","q":"تقلّ مقاومة فتيلة المصباح كلما زادت درجة حرارتها.","answer":false,"reasons":["تبقى ثابتة","نعم تقل","بل «تزداد» مقاومتها مع ارتفاع درجة الحرارة بسبب زيادة اهتزاز الذرات"],"reason":2},{"type":"essay","q":"اكتب نصّ قانون أوم وصيغته الرياضية ووحدات القياس.","model":"يتناسب التيار المار في موصل فلزي طرديًا مع فرق الجهد بين طرفيه عند ثبات درجة الحرارة: R = V ÷ I (الأوم = فولت ÷ أمبير)."},{"type":"essay","q":"مقاومة 8 Ω وُصلت ببطارية 12 V. احسب التيار المار والقدرة المستهلكة فيها.","model":"I = 12 ÷ 8 = 1.5 A. القدرة P = I × V = 1.5 × 12 = 18 W."}],"hard":[{"type":"mcq","q":"الأداة المستخدمة لتغيير شدة التيار تدريجيًا في تجربة قانون أوم هي:","options":["المقاومة المتغيرة (الريوستات)","الميزان","المنقلة","العدسة"],"answer":0,"why":"المقاومة المتغيرة تغير المقاومة والتيار بسلاسة."},{"type":"mcq","q":"عند زيادة المقاومة في الدائرة مع ثبات جهد البطارية، فإن شدة التيار:","options":["تزداد","تقلّ","تبقى ثابتة","تتضاعف"],"answer":1,"why":"العلاقة بين I و R عكسية عند ثبات V."},{"type":"mcq","q":"أي مما يلي يُعد تطبيقًا يوميًا للمقاومة المتغيرة؟","options":["البيروسكوب","المرآة المستوية","مفتاح التحكم في سطوع الإضاءة ومستوى الصوت","الترمس"],"answer":2,"why":"المقاومة المتغيرة تتحكم بالتيار وبالتالي بالسطوع والصوت."},{"type":"mcq","q":"لقياس مقاومة سلك عمليًا نحتاج إلى:","options":["ساعة إيقاف فقط","أميترين فقط","فولتميترين فقط","أميتر (توالٍ) وفولتميتر (توازٍ)"],"answer":3,"why":"لإيجاد R = V ÷ I نحتاج قياس V و I معًا."},{"type":"tfr","q":"إذا تضاعف فرق الجهد على مقاومة ثابتة (أومية) يتضاعف التيار المار فيها.","answer":true,"reasons":["لأن العلاقة بين V و I طردية عند ثبات R","يقل التيار للنصف","يبقى ثابتًا"],"reason":0},{"type":"tfr","q":"الأوم الواحد يكافئ 1 فولت لكل أمبير (1 V/A).","answer":true,"reasons":["يكافئ 1 V × A","من قانون أوم R = V / I","يكافئ 1 A / V"],"reason":1},{"type":"tfr","q":"زيادة المقاومة المتغيرة في دائرة مصباح تجعل المصباح يضيء بسطوع أكبر.","answer":false,"reasons":["لا يتغير السطوع","نعم يزداد السطوع","زيادة المقاومة تقلّل التيار فتخفت إضاءة المصباح"],"reason":2},{"type":"essay","q":"قارن بين منحنى (I–V) للمقاومة الثابتة ومنحنى (I–V) لمصباح الفتيلة مع التفسير.","model":"المقاومة الثابتة: خط مستقيم يمر بالأصل (مقاومتها ثابتة). المصباح: ينحني المنحنى لأن الفتيلة تسخن بزيادة التيار فتزداد مقاومتها."},{"type":"essay","q":"ارسم أو صف الدائرة العملية لقياس مقاومة سلك مجهول.","model":"نوصّل البطارية ومفتاحًا ومقاومة متغيرة وأميترًا والسلك المجهول على التوالي، ونوصّل فولتميترًا على التوازي بين طرفي السلك، ثم نأخذ قراءات V و I ونحسب R = V/I."},{"type":"essay","q":"لماذا تزداد مقاومة السلك الفلزي عند تسخينه على المستوى الجزيئي؟","model":"لأن التسخين يزيد طاقة وسعة اهتزاز ذرات الفلز، فتزداد تصادمات الإلكترونات الحرة معها وتُعاق حركتها أكثر."}]}},
  {"id":"g9-phy-2-u16-2","grade":"g9","subject":"physics","term":2,"unit":16,"no":2,"title":"المزيد عن المقاوَمة الكهربائيّة","summary":"شرح متحرك بـ SVG لدرس المزيد عن المقاوَمة الكهربائيّة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-more-about-resistance.html","video":"","pdf":"","notes":["مقاومة السلك تتناسب طرديًا مع طوله (L) وعكسيًا مع مساحة مقطعه (A) وتعتمد على نوع المادة والحرارة.","مضاعفة القطر (×2) تزيد المساحة 4 مرات وتقلل المقاومة للربع.","التوالي: R = R₁ + R₂؛ والتوازي: 1/R = 1/R₁ + 1/R₂ (أصغر من أصغر مقاومة).","النحاس للتوصيل (مقاومة صغيرة)، والنيكروم للتسخين (مقاومة عالية)."],"exercises":["اذكر العوامل الأربعة التي تعتمد عليها مقاومة سلك فلزي.","قارن بين توصيل المقاومات على التوالي وعلى التوازي من حيث القانون وقيمة المقاومة الكلية.","احسب المقاومة الكلية والتيار الكلي لمقاومتين 4 Ω و 12 Ω متصلتين على التوازي مع بطارية 6 V."],"levels":{"easy":[{"type":"mcq","q":"كيف تتغيّر مقاومة سلك عند مضاعفة «طوله» مرتين مع ثبات مساحته ومادته؟","options":["تبقى ثابتة","تقل للنصف","تتضاعف مرتين (×2)","تزداد ٤ مرات"],"answer":2,"why":"المقاومة تتناسب طرديًا مع الطول."},{"type":"mcq","q":"كيف تتغيّر مقاومة سلك عند مضاعفة «مساحة مقطعه» مرتين مع ثبات طوله؟","options":["تبقى ثابتة","تتضاعف مرتين","تقل للربع","تقل إلى النصف (÷2)"],"answer":3,"why":"المقاومة تتناسب عكسيًا مع مساحة المقطع."},{"type":"mcq","q":"مقاومتان 5 Ω و 7 Ω وُصلتا على «التوالي». المقاومة الكلية تساوي:","options":["12 Ω","2 Ω","35 Ω","2.9 Ω"],"answer":0,"why":"في التوالي: 5 + 7 = 12 Ω."},{"type":"mcq","q":"مقاومتان متماثلتان 10 Ω و 10 Ω وُصلتا على «التوازي». المقاومة الكلية تساوي:","options":["20 Ω","5 Ω","10 Ω","100 Ω"],"answer":1,"why":"1/R = 1/10 + 1/10 = 2/10 ← R = 5 Ω."}],"medium":[{"type":"mcq","q":"لماذا تُصنع أسلاك توصيل المكيّف من نحاس «سميك»؟","options":["لتقليل التيار إلى صفر","لزيادة المقاومة","لتقليل المقاومة ومنع ارتفاع حرارة السلك وضياع الطاقة","لأنه أرخص من البلاستيك"],"answer":2,"why":"السلك السميك مقاومته أقل فيتحمل تيار المكيّف العالي بأمان."},{"type":"mcq","q":"أي مادة تناسب صنع عنصر التسخين داخل الغلاية والمكواة؟","options":["الخشب","النحاس النقي السميك","البلاستيك","سبيكة النيكروم (مقاومتها عالية وتتحمل الحرارة)"],"answer":3,"why":"المقاومة العالية تحول الطاقة الكهربائية إلى حرارة بكفاءة."},{"type":"mcq","q":"سلك مقاومته 12 Ω. إذا أخذنا سلكًا آخر من نفس المادة ونفس الطول لكن «ضعف القطر» (×2)، فمقاومته تصبح:","options":["3 Ω (تقل للربع لأن المساحة تزداد ٤ مرات)","6 Ω","24 Ω","48 Ω"],"answer":0,"why":"المساحة تتناسب مع مربع القطر (2²=4) فتقل R إلى 12÷4 = 3 Ω."},{"type":"tfr","q":"تتناسب مقاومة السلك طرديًا مع طوله وعكسيًا مع مساحة مقطعه.","answer":true,"reasons":["عكسيًا مع الطول","طرديًا مع المساحة","فالسلك الأطول والأرفع له مقاومة أكبر، والأقصر والأسمك له مقاومة أقل"],"reason":2},{"type":"tfr","q":"عند توصيل عدة أجهزة منزلية على التوازي في مقبس واحد، تقل المقاومة الكلية ويزداد التيار الكلي مما قد يسبب خطر حريق.","answer":true,"reasons":["لذا يُمنع تحميل مقبس واحد بأجهزة عالية القدرة معًا","تزداد المقاومة ويقل التيار","لا يتغير التيار"],"reason":0},{"type":"essay","q":"اذكر العوامل الأربعة التي تعتمد عليها مقاومة سلك فلزي.","model":"١) طول السلك (طردي). ٢) مساحة المقطع العرضي (عكسي). ٣) نوع المادة. ٤) درجة الحرارة."},{"type":"essay","q":"قارن بين توصيل المقاومات على التوالي وعلى التوازي من حيث القانون وقيمة المقاومة الكلية.","model":"التوالي: R = R₁ + R₂ (أكبر من أكبر مقاومة). التوازي: 1/R = 1/R₁ + 1/R₂ (أصغر من أصغر مقاومة)."}],"hard":[{"type":"mcq","q":"مقاومتان 3 Ω و 6 Ω وُصلتا على التوازي. المقاومة الكلية تساوي:","options":["9 Ω","2 Ω","4.5 Ω","18 Ω"],"answer":1,"why":"1/R = 1/3 + 1/6 = 3/6 = 1/2 ← R = 2 Ω."},{"type":"mcq","q":"عند إضافة مقاومة جديدة على «التوازي» في دائرة، فإن المقاومة الكلية للدائرة:","options":["تبقى ثابتة","تزداد","تقلّ (فيزداد التيار الكلي من البطارية)","تصبح صفرًا"],"answer":2,"why":"التوازي يفتح مسارًا إضافيًا للتيار فتقل المقاومة الكلية."},{"type":"mcq","q":"سلك طوله 2 m مقاومته 6 Ω. ما مقاومة 5 m من نفس السلك؟","options":["30 Ω","12 Ω","2.4 Ω","15 Ω"],"answer":3,"why":"كل 1 m مقاومته 3 Ω ← 5 × 3 = 15 Ω."},{"type":"mcq","q":"أي عبارة صحيحة دائمًا حول توصيل مقاومتين على التوازي؟","options":["المقاومة الكلية أصغر من أصغر مقاومة منهما","أكبر من أكبر مقاومة","تساوي مجموعهما","تساوي حاصل ضربهما"],"answer":0,"why":"في التوازي تكون المكافئة دائمًا أقل من أصغر فرع."},{"type":"tfr","q":"المقاومة المكافئة لمقاومتين 4 Ω و 12 Ω على التوالي أصغر من 4 Ω.","answer":false,"reasons":["نعم أصغر","على التوالي تُجمع فتساوي 16 Ω (أكبر من 12 Ω)؛ أما على التوازي فتساوي 3 Ω","تساوي 3 Ω"],"reason":1},{"type":"tfr","q":"تُصنع أسلاك نقل الكهرباء من النحاس أو الألمنيوم لأن مقاومتهما منخفضة.","answer":true,"reasons":["لأنهما عازلان","لأن مقاومتهما عالية جدًّا","مما يقلّل الطاقة الحرارية المهدرة في الأسلاك"],"reason":2},{"type":"tfr","q":"إذا قطعنا سلكًا مقاومته 20 Ω إلى نصفين متساويين ووصلناهما معًا على التوازي، تصبح المقاومة الجديدة 5 Ω.","answer":true,"reasons":["كل نصف 10 Ω، وعلى التوازي 10 ÷ 2 = 5 Ω","تبقى 20 Ω","تصبح 10 Ω"],"reason":0},{"type":"essay","q":"احسب المقاومة الكلية والتيار الكلي لمقاومتين 4 Ω و 12 Ω متصلتين على التوازي مع بطارية 6 V.","model":"1/R = 1/4 + 1/12 = 4/12 = 1/3 ← R = 3 Ω. التيار الكلي I = 6 ÷ 3 = 2 A."},{"type":"essay","q":"سلك مقاومته 10 Ω. احسب مقاومة سلك آخر من نفس المادة طوله 3 أضعاف الأول ومساحة مقطعه نصف الأول.","model":"R = 10 × 3 ÷ 0.5 = 60 Ω."},{"type":"essay","q":"علّل: لماذا يكون سلك فتيلة المصباح الكهربائي رفيعًا جدًّا وطويلًا وملفوفًا؟","model":"لأن صغر مساحة المقطع وزيادة الطول يرفعان مقاومته بشدة، فيسخن ويتوهج بشدة عند مرور التيار فيه."}]}}
);
UNITS.push(
  {"id":"g9-phy-1-u1","grade":"g9","subject":"physics","term":1,"title":"الوحدة الأولى: الطول والزمن","levels":{"easy":[{"type":"mcq","q":"ما وحدة الكتلة الأساسية في النظام الدولي (SI)؟","options":["الكيلوجرام (kg)","الجرام (g)","اللتر (L)","المتر (m)"],"answer":0,"why":"الكيلوجرام هو الوحدة الأساسية الدولية للكتلة."},{"type":"mcq","q":"ما الأداة الأنسب لقياس قطر سلك نحاسي رفيع جدًّا بدقة؟","options":["المخبار المدرّج","الميكرومتر اللولبي","الميزان","الشريط المتري"],"answer":1,"why":"الميكرومتر يقيس بدقة ٠٫٠١ مم."},{"type":"mcq","q":"ما وحدة قياس الزمن الدوري؟","options":["المتر/ث","المتر (m)","الثانية (s)","الكيلوجرام (kg)"],"answer":2,"why":"الزمن الدوري زمن ذبذبة واحدة فيُقاس بالثانية."},{"type":"mcq","q":"كم ملليمترًا في ١ متر؟","options":["١٠٠ مم","١٠٠٠ مم","١٠ مم","١٠٠٠٠٠ مم"],"answer":1,"why":"١ م = ١٠٠٠ مم."}],"medium":[{"type":"mcq","q":"حوّل ٢٥٠ سم إلى متر:","options":["٢٫٥ م","٢٥ م","٠٫٢٥ م","٢٥٠٠٠ م"],"answer":0,"why":"نقسم ٢٥٠ ÷ ١٠٠ = ٢٫٥ م."},{"type":"mcq","q":"سمك ٢٠٠ ورقة في كتاب هو ١٫٨ سم؛ ما سمك الورقة الواحدة بالملليمتر؟","options":["٠٫٩ مم","٠٫٠٩ مم","٠٫٠٠٩ مم","٩ مم"],"answer":1,"why":"١٨ مم ÷ ٢٠٠ = ٠٫٠٩ مم."},{"type":"mcq","q":"إذا استبدلنا ثقل بندول كتلته ٥٠ جم بآخر كتلته ١٠٠ جم مع إبقاء طول الخيط ثابتًا، فإن الزمن الدوري:","options":["يقل للنصف","يصبح صفرًا","يبقى ثابتًا","يتضاعف"],"answer":2,"why":"الزمن الدوري للبندول لا يعتمد على كتلة الثقل."},{"type":"tfr","q":"يمكن الاعتماد على حاسة اللمس وحدها لتحديد درجة حرارة الماء بدقة علمية.","answer":false,"reasons":["الحواس غير دقيقة وتتأثر بالحالة السابقة، لذا نحتاج أداة قياس كميزان الحرارة","الماء لا يُقاس","الحواس أدق من الأجهزة"],"reason":0},{"type":"tfr","q":"نقرأ حجم الماء في المخبار المدرّج عند أعلى حافة التقعّر.","answer":false,"reasons":["نقرأ دائمًا عند قاع التقعّر والعين بمستوى أفقي","نقرأ من الأعلى دائمًا","لا يتكون تقعر للماء"],"reason":0}],"hard":[{"type":"mcq","q":"إذا كانت بداية مسطرة مكسورة فبدأ الطالب القياس من ٢٫٠ سم وانتهى عند ١٥٫٤ سم، فما الطول الحقيقي؟","options":["١٥٫٤ سم","١٧٫٤ سم","١٣٫٤ سم","٢٫٠ سم"],"answer":2,"why":"نطرح قراءة البداية: ١٥٫٤ − ٢٫٠ = ١٣٫٤ سم."},{"type":"mcq","q":"في إناء إزاحة مملوء تمامًا بالماء حتى الفوهة، غمرنا حجرًا فتجمّع ٤٢ سم³ في مخبار فارغ؛ ما حجم الحجر؟","options":["لا يمكن معرفته","٢١ سم³","٨٤ سم³","٤٢ سم³"],"answer":3,"why":"حجم الماء المزاح يساوي تمامًا حجم الجسم المغمور."},{"type":"mcq","q":"في ٣ محاولات لقياس ٢٠ ذبذبة لبندول كانت الأزمنة: ٢٤٫٢ و ٢٤٫٠ و ٢٣٫٨ ث. ما متوسط الزمن الدوري؟","options":["١٫٢ ث","٢٫٤ ث","٢٤٫٠ ث","٠٫٨٣ ث"],"answer":0,"why":"المتوسط الكلي = ٢٤٫٠ ث ← الزمن الدوري = ٢٤٫٠ ÷ ٢٠ = ١٫٢ ث."},{"type":"essay","q":"فسّر لماذا قد تختلف قراءة طالبين لمستوى الماء في مخبار مدرّج نفسه إذا لم يضعا عينيهما بمستوى السطح.","model":"بسبب خطأ اختلاف النظر (Parallax)؛ فالنظر من أعلى يعطي قراءة أصغر والنظر من أسفل يعطي قراءة أكبر، والصواب النظر أفقيًا بمستوى قاع التقعّر."},{"type":"essay","q":"لُفّ سلك ٢٥ لفةً متراصّةً فشغل طولًا قدره ٣٫٠ سم. احسب قطر السلك بالملليمتر.","model":"٣٫٠ سم = ٣٠ مم ← القطر = ٣٠ ÷ ٢٥ = ١٫٢ مم."}]},"test":[{"type":"mcq","q":"ما وحدة الكتلة الأساسية في النظام الدولي (SI)؟","options":["الكيلوجرام (kg)","الجرام (g)","اللتر (L)","المتر (m)"],"answer":0,"why":"الكيلوجرام هو الوحدة الأساسية الدولية للكتلة."},{"type":"mcq","q":"ما الأداة الأنسب لقياس قطر سلك نحاسي رفيع جدًّا بدقة؟","options":["المخبار المدرّج","الميكرومتر اللولبي","الميزان","الشريط المتري"],"answer":1,"why":"الميكرومتر يقيس بدقة ٠٫٠١ مم."},{"type":"mcq","q":"ما وحدة قياس الزمن الدوري؟","options":["المتر/ث","المتر (m)","الثانية (s)","الكيلوجرام (kg)"],"answer":2,"why":"الزمن الدوري زمن ذبذبة واحدة فيُقاس بالثانية."},{"type":"mcq","q":"كم ملليمترًا في ١ متر؟","options":["١٠٠ مم","١٠٠٠ مم","١٠ مم","١٠٠٠٠٠ مم"],"answer":1,"why":"١ م = ١٠٠٠ مم."},{"type":"mcq","q":"مكعب طول ضلعه ٤ سم، ما حجمه؟","options":["٤ سم³","١٢ سم³","٦٤ سم³","١٦ سم³"],"answer":2,"why":"٤ × ٤ × ٤ = ٦٤ سم³."},{"type":"mcq","q":"كم ثانيةً في نصف ساعة؟","options":["٣٠٠ ث","٦٠٠ ث","٣٦٠٠ ث","١٨٠٠ ث"],"answer":3,"why":"٣٠ دقيقة × ٦٠ = ١٨٠٠ ثانية."},{"type":"mcq","q":"ما الجزءان اللذان يتكوّن منهما أي قياس فيزيائي صحيح؟","options":["وحدة فقط","عدد فقط","قيمة عددية ووحدة قياس","رسم فقط"],"answer":2,"why":"القيمة العددية بلا وحدة غير مفهومة فيزيائيًا."},{"type":"mcq","q":"كم ملليلترًا يعادل ٢٥ سم³؟","options":["٢٫٥ مل","٢٥٠٠ مل","٢٥٠ مل","٢٥ مل"],"answer":3,"why":"١ سم³ = ١ مل تمامًا."},{"type":"mcq","q":"أيُّ أداةٍ تُلغي خطأ ردّ الفعل البشري تمامًا عند قياس زمن سقوط كرة؟","options":["البوابات الضوئية","الساعة الرملية","المسطرة","ساعة الإيقاف اليدوية"],"answer":0,"why":"البوابات الضوئية تعمل إلكترونيًا بقطع الشعاع الضوئي."},{"type":"mcq","q":"ما وحدة الزمن في النظام الدولي (SI)؟","options":["الدقيقة","الساعة (h)","اليوم","الثانية (s)"],"answer":3,"why":"الثانية هي الوحدة الدولية الأساسية للزمن."},{"type":"mcq","q":"في مخبار مدرّج به ٥٠ سم³ ماء، غمرنا مسمارًا فارتفع السطح إلى ٥٦ سم³؛ حجم المسمار:","options":["٦ سم³","٥٠ سم³","٥٦ سم³","١٠٦ سم³"],"answer":0,"why":"٥٦ − ٥٠ = ٦ سم³."},{"type":"mcq","q":"إذا استغرق بندول ٢٠ ثانية لإتمام ١٠ ذبذبات، فما زمنه الدوري؟","options":["١٠ ث","٢ ث","٠٫٥ ث","٢٠٠ ث"],"answer":1,"why":"٢٠ ÷ ١٠ = ٢ ثانية."},{"type":"tf","q":"يمكن الاعتماد على حاسة اللمس وحدها لتحديد درجة حرارة الماء بدقة علمية.","answer":false,"why":"الحواس غير دقيقة وتتأثر بالحالة السابقة، لذا نحتاج أداة قياس كميزان الحرارة"},{"type":"tf","q":"نقرأ حجم الماء في المخبار المدرّج عند أعلى حافة التقعّر.","answer":false,"why":"نقرأ دائمًا عند قاع التقعّر والعين بمستوى أفقي"},{"type":"tf","q":"نبدأ العدّ بالرقم «١» في اللحظة نفسها التي نضغط فيها زر بدء ساعة الإيقاف.","answer":false,"why":"نقول «صفر» عند بدء الساعة ثم «١» بعد إتمام أول ذبذبة كاملة حتى لا نخطئ في العدد"},{"type":"tf","q":"النظام الدولي للوحدات (SI) يسهّل تواصل العلماء وتبادل البيانات عالميًا.","answer":true,"why":"لأنه يوحّد الوحدات القياسية في كل دول العالم فيمنع أخطاء التحويل"},{"type":"tfr","q":"تُستخدم طريقة قياس عدة لفات متراصّة من سلك لتقليل نسبة الخطأ في حساب قطره.","answer":true,"reasons":["لأن السلك لا يُقاس","بقسمة العرض الكلي على عدد اللفات يتوزع أي خطأ صغير على العدد كله فيقل جدًّا","لأنها تزيد الخطأ"],"reason":1},{"type":"tfr","q":"كلما زاد طول خيط البندول، زاد زمنه الدوري (أصبح يتأرجح أبطأ).","answer":true,"reasons":["كلما طال الخيط أسرع","هناك علاقة طردية بين طول الخيط والزمن الدوري للبندول","الطول لا يؤثر"],"reason":1},{"type":"tfr","q":"عند التحويل من وحدة صغيرة (ملليمتر) إلى وحدة كبيرة (متر) نضرب في ١٠٠٠.","answer":false,"reasons":["دائمًا نضرب في ١٠٠٠","نجمع ١٠٠٠","من صغير إلى كبير نقسم على ١٠٠٠، أما من كبير لصغير فنضرب"],"reason":2},{"type":"tfr","q":"يمكن استخدام إزاحة الماء مباشرةً لقياس حجم مكعب من السكر.","answer":false,"reasons":["الماء يزيد حجم السكر","السكر لا يذوب في الماء","السكر يذوب في الماء فيقل حجمه، لذا يجب استخدام سائل لا يذيبه أو قياس أبعاده بالمسطرة"],"reason":2},{"type":"essay","q":"اذكر طريقتين عمليتين لتقليل الأخطاء عند القياس في المختبر.","model":"١) وضع العين عموديةً على التدريج لتجنب خطأ اختلاف النظر. ٢) فحص الصفر وتكرار القياس وحساب المتوسط."},{"type":"essay","q":"اشرح خطوات قياس حجم حجر صغير غير منتظم باستخدام مخبار مدرّج وماء.","model":"١) نضع ماءً في المخبار ونسجّل ح₁. ٢) نغمر الحجر بلطف كاملًا دون تناثر الماء ونسجّل ح₂. ٣) حجم الحجر = ح₂ − ح₁."},{"type":"essay","q":"اشرح خطوات قياس الزمن الدوري لبندول بسيط بدقة عالية في المختبر.","model":"نضع علامة عند منتصف المسار، نترك البندول يتأرجح، نبدأ الساعة عند مروره بالعلامة ونقول صفر، نعدّ ٢٠ ذبذبة كاملة ونوقف الساعة، نقسم الزمن على ٢٠، ونكرّر ٣ مرات لحساب المتوسط."},{"type":"essay","q":"حوّل كلًّا مما يأتي إلى المتر: (١) ٠٫٦ كم، (٢) ٤٥ سم، (٣) ١٢٠٠ مم.","model":"(١) ٦٠٠ م. (٢) ٠٫٤٥ م. (٣) ١٫٢ م."},{"type":"essay","q":"متوازي مستطيلات طوله ١٠ سم وعرضه ٤ سم وارتفاعه ٣ سم. احسب حجمه.","model":"الحجم = ١٠ × ٤ × ٣ = ١٢٠ سم³."}]},
  {"id":"g9-phy-1-u2","grade":"g9","subject":"physics","term":1,"title":"الوحدة الثانية: الحركة","levels":{"easy":[{"type":"mcq","q":"ما وحدة السرعة في النظام الدولي (SI)؟","options":["كم/س","م·ث","ث/م","م/ث (m/s)"],"answer":3,"why":"المتر لكل ثانية هي الوحدة الدولية للسرعة."},{"type":"mcq","q":"على منحنى (المسافة–الزمن)، أيّ محورٍ يمثّل الزمن عادةً؟","options":["المحور الأفقي","القطر","المحور الرأسي","كلاهما"],"answer":0,"why":"الزمن متغير مستقل يوضع دائمًا على المحور الأفقي."},{"type":"mcq","q":"التسارع هو معدل تغيّر:","options":["المسافة بالنسبة للكتلة","السرعة بالنسبة للزمن","الكتلة بالنسبة للزمن","الحجم بالنسبة للطول"],"answer":1,"why":"التسارع يقيس تغيّر السرعة كل ثانية."},{"type":"mcq","q":"ما قانون حساب التسارع؟","options":["a = v × t","a = (v + u) × t","a = (v − u) ÷ t","a = d ÷ t"],"answer":2,"why":"التغيّر في السرعة مقسومًا على الزمن."}],"medium":[{"type":"mcq","q":"حوّل سرعة ٣٦ كم/س إلى م/ث:","options":["٣٫٦ م/ث","١٢٩٫٦ م/ث","٣٦٠ م/ث","١٠ م/ث"],"answer":3,"why":"٣٦ ÷ ٣٫٦ = ١٠ م/ث."},{"type":"mcq","q":"إذا كان ميل الخط (أ) أكبر من ميل الخط (ب) على منحنى (المسافة–الزمن)، فإن:","options":["الجسم (أ) أسرع من (ب)","الجسم (ب) أسرع من (أ)","كلاهما ساكن","سرعتهما متساوية"],"answer":0,"why":"الميل يساوي السرعة، فالأكبر ميلًا هو الأسرع."},{"type":"mcq","q":"على منحنى (السرعة–الزمن)، أين يظهر الجسم الساكن؟","options":["خط هابط","خط منطبق على محور الزمن (السرعة = ٠)","خط صاعد","خط أفقي عند ١٠ م/ث"],"answer":1,"why":"الجسم الساكن سرعته صفر طوال الوقت."},{"type":"tfr","q":"عند حساب السرعة المتوسطة لرحلة تتخلّلها استراحة، نُهمل زمن الاستراحة من الزمن الكلي.","answer":false,"reasons":["الزمن الكلي يشمل زمن الحركة وزمن التوقف معًا","نعم نهمل الاستراحة دائمًا","السرعة لا تعتمد على الزمن"],"reason":0},{"type":"tfr","q":"الخط الأفقي على منحنى (المسافة–الزمن) يعني أن الجسم يتحرك بسرعة ثابتة غير صفرية.","answer":false,"reasons":["بل يعني أن الجسم ساكن وسرعته صفر؛ السرعة الثابتة يمثلها خط أفقي في منحنى (السرعة–الزمن) فقط","يعني أنه يتسارع","نعم يتحرك بسرعة ثابتة"],"reason":0}],"hard":[{"type":"mcq","q":"يصل صوت الرعد بعد ٥ ثوانٍ من البرق؛ إذا كانت سرعة الصوت ٣٤٠ م/ث، كم بُعد العاصفة؟","options":["٣٤٥ م","١٧٠٠ م (١٫٧ كم)","٦٨ م","٣٣٥ م"],"answer":1,"why":"d = ٣٤٠ × ٥ = ١٧٠٠ م."},{"type":"mcq","q":"في رحلة مدتها ٢٠ ثانية: قطع جسم ٦٠ م في أول ١٠ ث، ثم توقف ٥ ث، ثم قطع ٤٠ م في آخر ٥ ث. ما السرعة المتوسطة للرحلة كلها؟","options":["٦ م/ث","٨ م/ث","٥ م/ث","١٠ م/ث"],"answer":2,"why":"المسافة الكلية ١٠٠ م ÷ الزمن الكلي ٢٠ ث = ٥ م/ث."},{"type":"mcq","q":"إذا سقطت كرة من السكون سقوطًا حرًّا بتسارع ١٠ م/ث²، فكم تصبح سرعتها بعد ٣ ثوانٍ؟","options":["٤٠ م/ث","١٠ م/ث","٣٫٣ م/ث","٣٠ م/ث"],"answer":3,"why":"تزداد ١٠ م/ث كل ثانية ← ١٠ × ٣ = ٣٠ م/ث."},{"type":"essay","q":"قطعت سيارة ٩٠ كم بسرعة ٩٠ كم/س، ثم توقفت ٣٠ دقيقة، ثم قطعت ٦٠ كم في ساعة. احسب سرعتها المتوسطة للرحلة كلها.","model":"المسافة الكلية = ١٥٠ كم. الزمن الكلي = ١ + ٠٫٥ + ١ = ٢٫٥ ساعة. السرعة المتوسطة = ١٥٠ ÷ ٢٫٥ = ٦٠ كم/س."},{"type":"essay","q":"لماذا يُنصح باختيار مثلث كبير (نقطتين متباعدتين) عند حساب الميل من الرسم البياني؟","model":"لأن اختيار نقطتين متباعدتين يقلّل نسبة الخطأ الناتجة عن قراءة الإحداثيات من شبكة الرسم البياني."}]},"test":[{"type":"mcq","q":"ما وحدة السرعة في النظام الدولي (SI)؟","options":["كم/س","م·ث","ث/م","م/ث (m/s)"],"answer":3,"why":"المتر لكل ثانية هي الوحدة الدولية للسرعة."},{"type":"mcq","q":"على منحنى (المسافة–الزمن)، أيّ محورٍ يمثّل الزمن عادةً؟","options":["المحور الأفقي","القطر","المحور الرأسي","كلاهما"],"answer":0,"why":"الزمن متغير مستقل يوضع دائمًا على المحور الأفقي."},{"type":"mcq","q":"التسارع هو معدل تغيّر:","options":["المسافة بالنسبة للكتلة","السرعة بالنسبة للزمن","الكتلة بالنسبة للزمن","الحجم بالنسبة للطول"],"answer":1,"why":"التسارع يقيس تغيّر السرعة كل ثانية."},{"type":"mcq","q":"ما قانون حساب التسارع؟","options":["a = v × t","a = (v + u) × t","a = (v − u) ÷ t","a = d ÷ t"],"answer":2,"why":"التغيّر في السرعة مقسومًا على الزمن."},{"type":"mcq","q":"قطعت دراجة ٦٠ مترًا في ٤ ثوانٍ؛ ما سرعتها؟","options":["١٥ م/ث","١٢ م/ث","٢٤٠ م/ث","٦٤ م/ث"],"answer":0,"why":"٦٠ ÷ ٤ = ١٥ م/ث."},{"type":"mcq","q":"الخط المستقيم المائل للأعلى على منحنى (المسافة–الزمن) يدلّ على:","options":["تسارع غير منتظم","سرعة ثابتة","سكون","توقّف مفاجئ"],"answer":1,"why":"الميل الثابت يعني سرعة ثابتة."},{"type":"mcq","q":"عندما يضغط السائق المكابح فتقل سرعة السيارة، نسمّي ذلك:","options":["سكونًا فوريًا","سرعة ثابتة","تباطؤًا (تسارعًا سالبًا)","تسارعًا موجبًا"],"answer":2,"why":"تناقص السرعة هو تباطؤ."},{"type":"mcq","q":"تغيّرت سرعة جسم من ٠ إلى ١٨ م/ث في ٣ ثوانٍ؛ ما تسارعه؟","options":["١٥ م/ث²","٣ م/ث²","٥٤ م/ث²","٦ م/ث²"],"answer":3,"why":"(١٨ − ٠) ÷ ٣ = ٦ م/ث²."},{"type":"mcq","q":"جسم يسير بسرعة ٨ م/ث لمدة ٥ ثوانٍ، ما المسافة التي يقطعها؟","options":["١٫٦ م","٤٠ م","٣ م","١٣ م"],"answer":1,"why":"٨ × ٥ = ٤٠ م."},{"type":"mcq","q":"يمر خط مستقيم من (٠، ٠) إلى (٤ ث، ٢٤ م)؛ ما سرعة الجسم؟","options":["٩٦ م/ث","٢٠ م/ث","٦ م/ث","٤ م/ث"],"answer":2,"why":"٢٤ ÷ ٤ = ٦ م/ث."},{"type":"mcq","q":"على منحنى (السرعة–الزمن)، الخط المستقيم الصاعد يدلّ على:","options":["تباطؤ","سرعة ثابتة","سكون","تسارع منتظم"],"answer":3,"why":"زيادة السرعة بانتظام مع الزمن."},{"type":"mcq","q":"جسم سار بسرعة ثابتة ١٢ م/ث لمدة ٥ ثوانٍ؛ مساحة المستطيل تحت المنحنى (المسافة) =","options":["٦٠ م","٣٠ م","٢٫٤ م","١٧ م"],"answer":0,"why":"١٢ × ٥ = ٦٠ م."},{"type":"tf","q":"عند حساب السرعة المتوسطة لرحلة تتخلّلها استراحة، نُهمل زمن الاستراحة من الزمن الكلي.","answer":false,"why":"الزمن الكلي يشمل زمن الحركة وزمن التوقف معًا"},{"type":"tf","q":"الخط الأفقي على منحنى (المسافة–الزمن) يعني أن الجسم يتحرك بسرعة ثابتة غير صفرية.","answer":false,"why":"بل يعني أن الجسم ساكن وسرعته صفر؛ السرعة الثابتة يمثلها خط أفقي في منحنى (السرعة–الزمن) فقط"},{"type":"tf","q":"الخط المستقيم المائل للأعلى على منحنى (السرعة–الزمن) يدلّ على سرعة ثابتة.","answer":false,"why":"بل يدلّ على تسارع منتظم لأن السرعة تزداد باستمرار؛ السرعة الثابتة يمثلها خط أفقي"},{"type":"tf","q":"المساحة تحت منحنى (المسافة–الزمن) تساوي التسارع.","answer":false,"why":"المساحة تحت منحنى (السرعة–الزمن) هي التي تساوي المسافة، أما منحنى المسافة–الزمن فلا نستخدم مساحته"},{"type":"tfr","q":"السرعة المتوسطة تساوي المسافة الكلية مقسومةً على الزمن الكلي.","answer":true,"reasons":["تساوي المسافة × الزمن","هذا هو التعريف القياسي للسرعة المتوسطة","تساوي الزمن ÷ المسافة"],"reason":1},{"type":"tfr","q":"إذا تسطّح المنحنى تدريجيًا على رسم (المسافة–الزمن) فهذا يدلّ على تباطؤ الجسم.","answer":true,"reasons":["لأن المسافة تختفي","لأن تسطّح المنحنى يعني تناقص الميل، وبما أن الميل هو السرعة فالسرعة تتناقص","لأن السرعة تزداد"],"reason":1},{"type":"tfr","q":"كلما كان الخط الصاعد على منحنى (السرعة–الزمن) أشد انحدارًا كان تسارع الجسم أكبر.","answer":true,"reasons":["لأن التسارع أقل","لأن ميل منحنى (السرعة–الزمن) يساوي التسارع","لأن السرعة ثابتة"],"reason":1},{"type":"tfr","q":"يمكن إيجاد المسافة المقطوعة أثناء التسارع المنتظم من السكون بحساب مساحة المثلث تحت منحنى (السرعة–الزمن).","answer":true,"reasons":["لأن الميل هو المسافة","لأن الخط المائل الصاعد من الصفر يشكّل مثلثًا مع محور الزمن مساحته ½ × t × v","لأنها مساحة مربع"],"reason":1},{"type":"essay","q":"سارت سيارة ١٨٠ كم في ساعتين، ثم ٦٠ كم في ساعة واحدة. احسب سرعتها المتوسطة للرحلة كاملةً.","model":"المسافة الكلية = ٢٤٠ كم، الزمن الكلي = ٣ ساعات ← السرعة المتوسطة = ٢٤٠ ÷ ٣ = ٨٠ كم/س."},{"type":"essay","q":"كيف تحسب سرعة جسم من خط مستقيم على منحنى (المسافة–الزمن)؟","model":"نختار نقطتين متباعدتين على الخط (t₁, d₁) و (t₂, d₂) ثم نحسب الميل: v = (d₂ − d₁) ÷ (t₂ − t₁)."},{"type":"essay","q":"فسّر معنى قولنا: «تسارع جسم يساوي ٤ م/ث²».","model":"يعني أن سرعة الجسم تزداد بمقدار ٤ م/ث في كل ثانية تمرّ عليه."},{"type":"essay","q":"تباطأت دراجة من ١٦ م/ث إلى ٤ م/ث خلال ٣ ثوانٍ. احسب تسارعها.","model":"a = (٤ − ١٦) ÷ ٣ = −١٢ ÷ ٣ = −٤ م/ث² (تباطؤ ٤ م/ث²)."},{"type":"essay","q":"ما الفرق بين السرعة اللحظية والسرعة المتوسطة؟","model":"السرعة اللحظية هي سرعة الجسم في لحظة زمنية محددة (مثل قراءة عدّاد السيارة)، أما المتوسطة فهي المسافة الكلية ÷ الزمن الكلي."}]},
  {"id":"g9-phy-1-u3","grade":"g9","subject":"physics","term":1,"title":"الوحدة الثالثة: الكتلة والوزن","levels":{"easy":[{"type":"mcq","q":"ما وحدة قياس الوزن؟","options":["الجرام (g)","الكيلوجرام (kg)","الجول (J)","النيوتن (N)"],"answer":3,"why":"الوزن قوة يُقاس بالنيوتن."},{"type":"mcq","q":"إذا كانت كتلة كتاب ١٫٥ كجم، فكم وزنه على الأرض (g = ١٠ N/kg)؟","options":["٠٫١٥ N","١١٫٥ N","١٥ N","١٥٠ N"],"answer":2,"why":"١٫٥ × ١٠ = ١٥ نيوتن."},{"type":"mcq","q":"جسم كتلته ٦ كجم على سطح الأرض (g = ١٠ N/kg)؛ كم وزنه؟","options":["٦٠ N","٠٫٦ N","١٦ N","٦ N"],"answer":0,"why":"٦ × ١٠ = ٦٠ نيوتن."},{"type":"mcq","q":"ما كتلة جسم وزنه ٨٠ نيوتن على القمر (g = ١٫٦ N/kg)؟","options":["٨٠ كجم","٨ كجم","١٢٨ كجم","٥٠ كجم"],"answer":3,"why":"٨٠ ÷ ١٫٦ = ٥٠ كجم."}],"medium":[{"type":"mcq","q":"كرة كتلتها ٥٠٠ جم؛ كم وزنها على الأرض (g = ١٠ N/kg)؟","options":["٥٠ N","٠٫٥ N","٥٠٠٠ N","٥ N"],"answer":3,"why":"٥٠٠ جم = ٠٫٥ كجم ← ٠٫٥ × ١٠ = ٥ نيوتن."},{"type":"mcq","q":"إذا كانت كتلة كتاب ١٫٥ كجم، فكم وزنه على الأرض (g = ١٠ N/kg)؟","options":["٠٫١٥ N","١١٫٥ N","١٥ N","١٥٠ N"],"answer":2,"why":"١٫٥ × ١٠ = ١٥ نيوتن."},{"type":"mcq","q":"جسم وزنه ٤٥٠ نيوتن على الأرض (g = ١٠ N/kg)؛ ما كتلته؟","options":["٤٥ كجم","٤٥٠٠ كجم","٤٫٥ كجم","٤٤٠ كجم"],"answer":0,"why":"m = ٤٥٠ ÷ ١٠ = ٤٥ كجم."},{"type":"tfr","q":"تُقاس الكتلة بوحدة النيوتن والوزن بوحدة الكيلوجرام.","answer":false,"reasons":["العكس صحيح: الكتلة بالكيلوجرام والوزن بالنيوتن","كلاهما بالنيوتن","كلاهما بالكيلوجرام"],"reason":0},{"type":"tfr","q":"الوزن على سطح الأرض يتناسب طرديًا مع كتلة الجسم.","answer":true,"reasons":["لا علاقة بينهما","يتناسب عكسيًا","لأن W = m × g وعند ثبات g كلما تضاعفت الكتلة تضاعف الوزن"],"reason":2}],"hard":[{"type":"mcq","q":"صخرة وزنها ٣٢ نيوتن على سطح القمر (g = ١٫٦ N/kg)؛ ما وزنها على سطح الأرض (g = ١٠ N/kg)؟","options":["٣٢٠ N","٢٠٠ N","٢٠ N","٥١٫٢ N"],"answer":1,"why":"كتلتها m = ٣٢ ÷ ١٫٦ = ٢٠ كجم ← وزنها على الأرض = ٢٠ × ١٠ = ٢٠٠ نيوتن."},{"type":"mcq","q":"إذا كانت كتلة كتاب ١٫٥ كجم، فكم وزنه على الأرض (g = ١٠ N/kg)؟","options":["٠٫١٥ N","١١٫٥ N","١٥ N","١٥٠ N"],"answer":2,"why":"١٫٥ × ١٠ = ١٥ نيوتن."},{"type":"mcq","q":"على كوكب المشتري (g = ٢٥ N/kg)، ما وزن مسبار كتلته ٤٠ كجم؟","options":["٦٥ N","١٫٦ N","١٠٠٠ N","٤٠٠ N"],"answer":2,"why":"٤٠ × ٢٥ = ١٠٠٠ نيوتن."},{"type":"essay","q":"فسّر لماذا ينعدم وزن رائد الفضاء في محطة الفضاء لكنه ما زال يحتاج لقوة كبيرة لدفع صندوق كتلته ١٠٠ كجم.","model":"لأن الكتلة لا تتغيّر بانعدام الوزن، والكتلة مقياس للقصور الذاتي (مقاومة تغيير الحركة)، فدفع ١٠٠ كجم يحتاج قوة كبيرة لتسريعها."},{"type":"essay","q":"لماذا يعطي الميزان الزنبركي المصمّم للأرض قراءةً غير صحيحة للكتلة إذا أخذناه إلى القمر؟","model":"لأن الميزان الزنبركي يقيس قوة الوزن التي تعتمد على الجاذبية، فجاذبية القمر أقل بـ ٦ مرات فيستطيل الزنبرك أقل ويعطي قراءة أقل بـ ٦ مرات."}]},"test":[{"type":"mcq","q":"ما وحدة قياس الوزن؟","options":["الجرام (g)","الكيلوجرام (kg)","الجول (J)","النيوتن (N)"],"answer":3,"why":"الوزن قوة يُقاس بالنيوتن."},{"type":"mcq","q":"إذا كانت كتلة كتاب ١٫٥ كجم، فكم وزنه على الأرض (g = ١٠ N/kg)؟","options":["٠٫١٥ N","١١٫٥ N","١٥ N","١٥٠ N"],"answer":2,"why":"١٫٥ × ١٠ = ١٥ نيوتن."},{"type":"mcq","q":"جسم كتلته ٦ كجم على سطح الأرض (g = ١٠ N/kg)؛ كم وزنه؟","options":["٦٠ N","٠٫٦ N","١٦ N","٦ N"],"answer":0,"why":"٦ × ١٠ = ٦٠ نيوتن."},{"type":"mcq","q":"ما كتلة جسم وزنه ٨٠ نيوتن على القمر (g = ١٫٦ N/kg)؟","options":["٨٠ كجم","٨ كجم","١٢٨ كجم","٥٠ كجم"],"answer":3,"why":"٨٠ ÷ ١٫٦ = ٥٠ كجم."},{"type":"mcq","q":"أيُّ كميةٍ تبقى ثابتةً إذا سافرتَ إلى كوكب المريخ؟","options":["الوزن","الكتلة","قوة الجذب","شدة الجاذبية"],"answer":1,"why":"الكتلة مقدار المادة فلا تتغير بتغيّر الكوكب."},{"type":"mcq","q":"أيُّ كوكبٍ سيكون وزنك عليه أكبر إذا كان: الأرض (g=10)، المريخ (g=3.7)، القمر (g=1.6)، زحل (g=10.4)؟","options":["زحل","الأرض","المريخ","القمر"],"answer":0,"why":"زحل له أكبر شدة مجال جاذبية g = ١٠٫٤ N/kg."},{"type":"mcq","q":"ما أداة قياس الوزن مباشرةً؟","options":["الميكرومتر","المخبار المدرّج","الميزان الزنبركي","ساعة الإيقاف"],"answer":2,"why":"الميزان الزنبركي يقيس القوة بالنيوتن."},{"type":"mcq","q":"كرة كتلتها ٥٠٠ جم؛ كم وزنها على الأرض (g = ١٠ N/kg)؟","options":["٥٠ N","٠٫٥ N","٥٠٠٠ N","٥ N"],"answer":3,"why":"٥٠٠ جم = ٠٫٥ كجم ← ٠٫٥ × ١٠ = ٥ نيوتن."},{"type":"mcq","q":"جسم وزنه ٤٥٠ نيوتن على الأرض (g = ١٠ N/kg)؛ ما كتلته؟","options":["٤٥ كجم","٤٥٠٠ كجم","٤٫٥ كجم","٤٤٠ كجم"],"answer":0,"why":"m = ٤٥٠ ÷ ١٠ = ٤٥ كجم."},{"type":"mcq","q":"صخرة وزنها ٣٢ نيوتن على سطح القمر (g = ١٫٦ N/kg)؛ ما وزنها على سطح الأرض (g = ١٠ N/kg)؟","options":["٣٢٠ N","٢٠٠ N","٢٠ N","٥١٫٢ N"],"answer":1,"why":"كتلتها m = ٣٢ ÷ ١٫٦ = ٢٠ كجم ← وزنها على الأرض = ٢٠ × ١٠ = ٢٠٠ نيوتن."},{"type":"mcq","q":"على كوكب المشتري (g = ٢٥ N/kg)، ما وزن مسبار كتلته ٤٠ كجم؟","options":["٦٥ N","١٫٦ N","١٠٠٠ N","٤٠٠ N"],"answer":2,"why":"٤٠ × ٢٥ = ١٠٠٠ نيوتن."},{"type":"mcq","q":"جسم كتلته ١٥٠ جم ووزنه على كوكب مجهول ٠٫٦ نيوتن؛ ما شدة مجال الجاذبية (g) على ذلك الكوكب؟","options":["٢٫٥ N/kg","٠٫٠٠٤ N/kg","٩٠ N/kg","٤ N/kg"],"answer":3,"why":"m = ٠٫١٥ كجم ← g = ٠٫٦ ÷ ٠٫١٥ = ٤ N/kg."},{"type":"tf","q":"تُقاس الكتلة بوحدة النيوتن والوزن بوحدة الكيلوجرام.","answer":false,"why":"العكس صحيح: الكتلة بالكيلوجرام والوزن بالنيوتن"},{"type":"tf","q":"الوزن على سطح الأرض يتناسب طرديًا مع كتلة الجسم.","answer":true,"why":"لأن W = m × g وعند ثبات g كلما تضاعفت الكتلة تضاعف الوزن"},{"type":"tf","q":"يعمل الميزان ذو الكفتين بدقة على سطح القمر لقياس الكتلة.","answer":true,"why":"لأن جاذبية القمر تؤثر بالنسبة نفسها على الكفتين فتتساويان عند تساوي الكتلتين"},{"type":"tf","q":"يمكن أن تنعدم كتلة جسم مادي تمامًا في الفضاء الخارجي.","answer":false,"why":"ينعدم الوزن فقط في غياب الجاذبية، أما الكتلة فمقدار المادة ولا تنعدم"},{"type":"tfr","q":"كلما زادت كتلة الجسم، زادت مقاومته لتغيّر حالته الحركية (قصوره الذاتي).","answer":true,"reasons":["لا علاقة بين الكتلة والحركة","الكتلة الأكبر أسهل في الإيقاف","الكتلة مقياس للقصور الذاتي فالشاحنة أصعب في الإيقاف من الدراجة"],"reason":2},{"type":"tfr","q":"وحدة شدة مجال الجاذبية (N/kg) تكافئ رياضيًا وحدة التسارع (m/s²).","answer":true,"reasons":["لأن القوة = الكتلة × التسارع، فقسمة القوة على الكتلة تعطي تسارع الجاذبية g","هما وحدتان مختلفتان تمامًا","g بلا وحدة"],"reason":0},{"type":"tfr","q":"شدة مجال الجاذبية على قمة جبل شاهق أقلّ قليلًا جدًّا منها عند سطح البحر.","answer":true,"reasons":["تنعدم فوق الجبل","لأن الجاذبية تضعف قليلًا كلما ابتعدنا عن مركز الأرض","تزداد كلما ارتفعنا"],"reason":1},{"type":"tfr","q":"قوة الوزن كمية متجهة اتجاهها دائمًا نحو مركز الأرض.","answer":true,"reasons":["اتجاهه للأعلى","الوزن كمية قياسية بلا اتجاه","الوزن قوة جذب لها مقدار واتجاه نحو مركز الكوكب"],"reason":2},{"type":"essay","q":"عرّف كلًّا من الكتلة والوزن، واذكر وحدة قياس كل منهما.","model":"الكتلة: مقدار المادة في الجسم ووحدتها الكيلوجرام (kg). الوزن: قوة جذب الجاذبية للجسم ووحدته النيوتن (N)."},{"type":"essay","q":"احسب وزن رائد فضاء كتلته ٧٥ كجم على سطح القمر (g = ١٫٦ N/kg).","model":"W = ٧٥ × ١٫٦ = ١٢٠ نيوتن."},{"type":"essay","q":"فسّر لماذا ينعدم وزن رائد الفضاء في محطة الفضاء لكنه ما زال يحتاج لقوة كبيرة لدفع صندوق كتلته ١٠٠ كجم.","model":"لأن الكتلة لا تتغيّر بانعدام الوزن، والكتلة مقياس للقصور الذاتي (مقاومة تغيير الحركة)، فدفع ١٠٠ كجم يحتاج قوة كبيرة لتسريعها."},{"type":"essay","q":"لماذا يعطي الميزان الزنبركي المصمّم للأرض قراءةً غير صحيحة للكتلة إذا أخذناه إلى القمر؟","model":"لأن الميزان الزنبركي يقيس قوة الوزن التي تعتمد على الجاذبية، فجاذبية القمر أقل بـ ٦ مرات فيستطيل الزنبرك أقل ويعطي قراءة أقل بـ ٦ مرات."},{"type":"essay","q":"قارن بين الميزان ذي الكفتين والميزان الزنبركي من حيث ما يقيسه كل منهما وهل يتأثر بتغيّر الكوكب.","model":"ذو الكفتين يقيس الكتلة بالمقارنة ولا يتأثر بتغيّر الكوكب؛ الزنبركي يقيس قوة الوزن بالاستطالة ويتأثر بتغيّر الجاذبية."}]},
  {"id":"g9-phy-1-u4","grade":"g9","subject":"physics","term":1,"title":"الوحدة الرابعة: الكثافة","levels":{"easy":[{"type":"mcq","q":"ما قانون حساب الكثافة؟","options":["الكثافة = الكتلة ÷ الحجم","الكثافة = الكتلة × الحجم","الكثافة = الحجم ÷ الكتلة","الكثافة = الوزن × الطول"],"answer":0,"why":"ρ = m ÷ V."},{"type":"mcq","q":"إذا كانت كثافة الجليد ٠٫٩٢ جم/سم³ وكتلة قطعة منه ٩٢ جم، فما حجمها؟","options":["٨٤٫٦ سم³","١٠٠ سم³","١٠ سم³","١٠٠٠ سم³"],"answer":1,"why":"V = ٩٢ ÷ ٠٫٩٢ = ١٠٠ سم³."},{"type":"mcq","q":"مكعب حجمه ٢٥ سم³ وكتلته ٢٠٠ جم؛ ما كثافته؟","options":["٢٢٥ جم/سم³","٨ جم/سم³","٠٫١٢٥ جم/سم³","٥٠٠٠ جم/سم³"],"answer":1,"why":"٢٠٠ ÷ ٢٥ = ٨ جم/سم³."},{"type":"mcq","q":"أيّ مادةٍ مما يأتي تغوص في الماء (كثافة الماء = ١ جم/سم³)؟","options":["الفلين (٠٫٢٥ جم/سم³)","الخشب (٠٫٦ جم/سم³)","الزجاج (٢٫٥ جم/سم³)","زيت الزيتون (٠٫٩ جم/سم³)"],"answer":2,"why":"كثافة الزجاج أكبر من ١ جم/سم³ فيغوص."}],"medium":[{"type":"mcq","q":"قطعة حديد كثافتها ٧٫٨ جم/سم³ وحجمها ١٠ سم³؛ ما كتلتها؟","options":["٧٨ جم","٧٨٠ جم","١٧٫٨ جم","٠٫٧٨ جم"],"answer":0,"why":"m = ٧٫٨ × ١٠ = ٧٨ جم."},{"type":"mcq","q":"إذا كانت كثافة الجليد ٠٫٩٢ جم/سم³ وكتلة قطعة منه ٩٢ جم، فما حجمها؟","options":["٨٤٫٦ سم³","١٠٠ سم³","١٠ سم³","١٠٠٠ سم³"],"answer":1,"why":"V = ٩٢ ÷ ٠٫٩٢ = ١٠٠ سم³."},{"type":"mcq","q":"مخبار فارغ كتلته ٦٠ جم، وعند وضع ٥٠ سم³ من سائل أصبحت كتلته ١٠٠ جم؛ ما كثافة السائل؟","options":["٢ جم/سم³","٠٫٨ جم/سم³","٣٫٢ جم/سم³","١٫٢ جم/سم³"],"answer":1,"why":"كتلة السائل = ٤٠ جم ← ٤٠ ÷ ٥٠ = ٠٫٨ جم/سم³."},{"type":"tfr","q":"إذا تضاعف حجم قطعة من الألمنيوم النقي فإن كثافتها تتضاعف أيضًا.","answer":false,"reasons":["الكثافة تبقى ثابتة للمادة النقية الواحدة لأن الكتلة والحجم يتضاعفان معًا","نعم تتضاعف","تقل للنصف"],"reason":0},{"type":"tfr","q":"لقياس حجم حجر كبير لا يدخل المخبار المدرّج نستخدم إناء الإزاحة (يوريكا).","answer":true,"reasons":["نكسر الحجر ونرميه","يُجمع الماء المنسكب من فوهة إناء الإزاحة في مخبار مدرّج فيساوي حجم الحجر","لا يمكن قياس حجمه"],"reason":1}],"hard":[{"type":"mcq","q":"متوازي مستطيلات أبعاده ٥ × ٤ × ٢ سم وكتلته ١٠٨ جم؛ ما كثافته؟","options":["١٫٣٥ جم/سم³","٥٫٤ جم/سم³","٢٫٧ جم/سم³","١٠٫٨ جم/سم³"],"answer":2,"why":"الحجم = ٤٠ سم³ ← الكثافة = ١٠٨ ÷ ٤٠ = ٢٫٧ جم/سم³."},{"type":"mcq","q":"إذا كانت كثافة الجليد ٠٫٩٢ جم/سم³ وكتلة قطعة منه ٩٢ جم، فما حجمها؟","options":["٨٤٫٦ سم³","١٠٠ سم³","١٠ سم³","١٠٠٠ سم³"],"answer":1,"why":"V = ٩٢ ÷ ٠٫٩٢ = ١٠٠ سم³."},{"type":"mcq","q":"حوّل كثافة ٢٥٠٠ كجم/م³ إلى وحدة جم/سم³:","options":["٢٥ جم/سم³","٠٫٢٥ جم/سم³","٢٥٠ جم/سم³","٢٫٥ جم/سم³"],"answer":3,"why":"نقسم على ١٠٠٠ ← ٢٫٥ جم/سم³."},{"type":"essay","q":"لماذا يسهل الطفو على الإنسان في ماء البحر المالح أكثر منه في ماء المسبح العذب؟","model":"لأن الأملاح الذائبة ترفع كثافة ماء البحر (نحو ١٫٠٣ جم/سم³) فتصبح أكبر من الماء العذب، مما يزيد قوة الطفو."},{"type":"essay","q":"صُبّ في أنبوب زجاجي ثلاثة سوائل لا تمتزج: زئبق (١٣٫٦)، ماء (١٫٠)، زيت (٠٫٨) جم/سم³. رتّبها من الأسفل إلى الأعلى.","model":"من الأسفل للأعلى (من الأكبر كثافة للأقل): الزئبق في القاع، ثم الماء في الوسط، ثم الزيت في الأعلى."}]},"test":[{"type":"mcq","q":"ما قانون حساب الكثافة؟","options":["الكثافة = الكتلة ÷ الحجم","الكثافة = الكتلة × الحجم","الكثافة = الحجم ÷ الكتلة","الكثافة = الوزن × الطول"],"answer":0,"why":"ρ = m ÷ V."},{"type":"mcq","q":"إذا كانت كثافة الجليد ٠٫٩٢ جم/سم³ وكتلة قطعة منه ٩٢ جم، فما حجمها؟","options":["٨٤٫٦ سم³","١٠٠ سم³","١٠ سم³","١٠٠٠ سم³"],"answer":1,"why":"V = ٩٢ ÷ ٠٫٩٢ = ١٠٠ سم³."},{"type":"mcq","q":"مكعب حجمه ٢٥ سم³ وكتلته ٢٠٠ جم؛ ما كثافته؟","options":["٢٢٥ جم/سم³","٨ جم/سم³","٠٫١٢٥ جم/سم³","٥٠٠٠ جم/سم³"],"answer":1,"why":"٢٠٠ ÷ ٢٥ = ٨ جم/سم³."},{"type":"mcq","q":"أيّ مادةٍ مما يأتي تغوص في الماء (كثافة الماء = ١ جم/سم³)؟","options":["الفلين (٠٫٢٥ جم/سم³)","الخشب (٠٫٦ جم/سم³)","الزجاج (٢٫٥ جم/سم³)","زيت الزيتون (٠٫٩ جم/سم³)"],"answer":2,"why":"كثافة الزجاج أكبر من ١ جم/سم³ فيغوص."},{"type":"mcq","q":"كم تساوي كثافة الماء النقي بوحدة جم/سم³؟","options":["١٠٠٠ جم/سم³","١٠ جم/سم³","١ جم/سم³","٠٫١ جم/سم³"],"answer":2,"why":"كثافة الماء ١ جم/سم³ (أي ١٠٠٠ كجم/م³)."},{"type":"mcq","q":"جسم كتلته ٤٥ جم وحجمه ١٥ سم³؛ ما كثافته بوحدة كجم/م³؟","options":["٣٠٠ كجم/م³","٦٧٥ كجم/م³","٣ كجم/م³","٣٠٠٠ كجم/م³"],"answer":3,"why":"٤٥ ÷ ١٥ = ٣ جم/سم³ = ٣٠٠٠ كجم/م³."},{"type":"mcq","q":"يطفو الزيت فوق الماء لأن كثافة الزيت:","options":["مساوية للماء","صفر","أكبر من كثافة الماء","أقل من كثافة الماء"],"answer":3,"why":"المادة الأقل كثافةً تطفو فوق الأكثر كثافةً."},{"type":"mcq","q":"قطعة حديد كثافتها ٧٫٨ جم/سم³ وحجمها ١٠ سم³؛ ما كتلتها؟","options":["٧٨ جم","٧٨٠ جم","١٧٫٨ جم","٠٫٧٨ جم"],"answer":0,"why":"m = ٧٫٨ × ١٠ = ٧٨ جم."},{"type":"mcq","q":"مخبار فارغ كتلته ٦٠ جم، وعند وضع ٥٠ سم³ من سائل أصبحت كتلته ١٠٠ جم؛ ما كثافة السائل؟","options":["٢ جم/سم³","٠٫٨ جم/سم³","٣٫٢ جم/سم³","١٫٢ جم/سم³"],"answer":1,"why":"كتلة السائل = ٤٠ جم ← ٤٠ ÷ ٥٠ = ٠٫٨ جم/سم³."},{"type":"mcq","q":"متوازي مستطيلات أبعاده ٥ × ٤ × ٢ سم وكتلته ١٠٨ جم؛ ما كثافته؟","options":["١٫٣٥ جم/سم³","٥٫٤ جم/سم³","٢٫٧ جم/سم³","١٠٫٨ جم/سم³"],"answer":2,"why":"الحجم = ٤٠ سم³ ← الكثافة = ١٠٨ ÷ ٤٠ = ٢٫٧ جم/سم³."},{"type":"mcq","q":"حوّل كثافة ٢٥٠٠ كجم/م³ إلى وحدة جم/سم³:","options":["٢٥ جم/سم³","٠٫٢٥ جم/سم³","٢٥٠ جم/سم³","٢٫٥ جم/سم³"],"answer":3,"why":"نقسم على ١٠٠٠ ← ٢٫٥ جم/سم³."},{"type":"mcq","q":"غرفة أبعادها ٥ م × ٤ م × ٣ م مملوءة بهواء كثافته ١٫٢ كجم/م³؛ ما كتلة الهواء داخل الغرفة؟","options":["٧٢ كجم","٥٠ كجم","٦٠ كجم","١٢ كجم"],"answer":0,"why":"الحجم = ٦٠ م³ ← الكتلة = ٦٠ × ١٫٢ = ٧٢ كجم."},{"type":"tf","q":"إذا تضاعف حجم قطعة من الألمنيوم النقي فإن كثافتها تتضاعف أيضًا.","answer":false,"why":"الكثافة تبقى ثابتة للمادة النقية الواحدة لأن الكتلة والحجم يتضاعفان معًا"},{"type":"tf","q":"لقياس حجم حجر كبير لا يدخل المخبار المدرّج نستخدم إناء الإزاحة (يوريكا).","answer":true,"why":"يُجمع الماء المنسكب من فوهة إناء الإزاحة في مخبار مدرّج فيساوي حجم الحجر"},{"type":"tf","q":"في تجربة قياس كثافة حجر يجب قياس كتلته وهو جاف قبل غمره في الماء.","answer":true,"why":"حتى لا يلتصق الماء بسطحه فيزيد قراءة الكتلة ويعطي كثافة غير دقيقة"},{"type":"tf","q":"إذا كان لمادتين مختلفتين الحجم نفسه، فالمادة ذات الكتلة الأكبر تكون كثافتها أكبر.","answer":true,"why":"عند ثبات V، تتناسب الكثافة ρ طرديًا مع الكتلة m"},{"type":"tfr","q":"يطفو الثلج فوق الماء السائل لأن كثافة الثلج (٠٫٩٢ جم/سم³) أقل من كثافة الماء (١٫٠ جم/سم³).","answer":true,"reasons":["كثافتهما متساوية","الثلج أثقل كثافة من الماء","الماء يتمدد عند التجمد فتقل كثافته ويطفو الثلج"],"reason":2},{"type":"tfr","q":"تاج ذهبي كتلته ٣٨٦ جم وحجمه ٢٥ سم³ يكون مصنوعًا من ذهب خالص (كثافة الذهب ١٩٫٣ جم/سم³).","answer":false,"reasons":["كثافة التاج = ٣٨٦ ÷ ٢٥ = ١٥٫٤٤ جم/سم³ ≠ ١٩٫٣، إذن التاج مخلوط بمعدن آخر أرخص!","الحجم لا يهم","نعم ذهب خالص"],"reason":0},{"type":"tfr","q":"تطفو السفينة الحديدية لأن تجويفها المملوء بالهواء يجعل متوسط كثافتها الكلي أقل من كثافة الماء.","answer":true,"reasons":["لأن الحديد أقل كثافة من الماء","متوسط الكثافة = الكتلة الكلية ÷ الحجم الكلي شاملاً الفراغ الهوائي، فيكون أقل من ١ جم/سم³","لأن السفينة بلا كتلة"],"reason":1},{"type":"tfr","q":"إذا ارتفعت درجة حرارة معظم المواد وتمددت، فإن كثافتها تقلّ قليلًا.","answer":true,"reasons":["تزداد كثافتها","تزداد كتلتها","تبقى الكتلة ثابتة ويزداد الحجم بالتمدد ← الكتلة ÷ الحجم تقلّ"],"reason":2},{"type":"essay","q":"اشرح خطوات قياس كثافة سائل (مثل زيت الطعام) في المختبر.","model":"١) نقيس كتلة مخبار فارغ (ك₁). ٢) نضع حجمًا معلومًا V من الزيت ونقيس كتلتهما معًا (ك₂). ٣) كتلة الزيت = ك₂ − ك₁. ٤) الكثافة = (ك₂ − ك₁) ÷ V."},{"type":"essay","q":"احسب حجم قطعة رصاص كتلتها ٢٢٦ جم وكثافتها ١١٫٣ جم/سم³.","model":"V = m ÷ ρ = ٢٢٦ ÷ ١١٫٣ = ٢٠ سم³."},{"type":"essay","q":"لماذا يسهل الطفو على الإنسان في ماء البحر المالح أكثر منه في ماء المسبح العذب؟","model":"لأن الأملاح الذائبة ترفع كثافة ماء البحر (نحو ١٫٠٣ جم/سم³) فتصبح أكبر من الماء العذب، مما يزيد قوة الطفو."},{"type":"essay","q":"صُبّ في أنبوب زجاجي ثلاثة سوائل لا تمتزج: زئبق (١٣٫٦)، ماء (١٫٠)، زيت (٠٫٨) جم/سم³. رتّبها من الأسفل إلى الأعلى.","model":"من الأسفل للأعلى (من الأكبر كثافة للأقل): الزئبق في القاع، ثم الماء في الوسط، ثم الزيت في الأعلى."},{"type":"essay","q":"احسب كثافة حجر كتلته ٩٠ جم غُمر في مخبار به ٣٠ سم³ ماء فارتفع إلى ٦٠ سم³، ثم حوّل الناتج إلى كجم/م³.","model":"الحجم = ٦٠ − ٣٠ = ٣٠ سم³. الكثافة = ٩٠ ÷ ٣٠ = ٣ جم/سم³ = ٣٠٠٠ كجم/م³."}]},
  {"id":"g9-phy-1-u5","grade":"g9","subject":"physics","term":1,"title":"الوحدة الخامسة: نموذج الحركة الجزيئية البسيطة للمادة","levels":{"easy":[{"type":"mcq","q":"أيُّ حالةٍ للمادة يكون شكلها وحجمها ثابتين؟","options":["البلازما","الصلبة","السائلة","الغازية"],"answer":1,"why":"المواد الصلبة تحافظ على شكلها وحجمها."},{"type":"mcq","q":"كيف تتحرّك الجسيمات في المادة الصلبة؟","options":["تطير عشوائيًا","تنزلق بحرية","تهتزّ حول مواضع ثابتة","تتوقّف تمامًا"],"answer":2,"why":"تهتز الجسيمات في أماكنها الثابتة."},{"type":"mcq","q":"في أي حالة تكون قوى التجاذب بين الجسيمات أقوى ما يمكن؟","options":["السائلة","الغازية","البخار","الصلبة"],"answer":3,"why":"قوى التجاذب القوية تحفظ شكل الصلب الثابت."},{"type":"mcq","q":"ما مصدر ضغط الغاز المحبوس في أسطوانة؟","options":["تصادم جزيئات الغاز بجدران الأسطوانة","وزن الأسطوانة","برودة الغاز","قوة التجاذب بين الجزيئات"],"answer":0,"why":"تصادم الجزيئات المستمر يولد قوة ضغط على الجدران."}],"medium":[{"type":"mcq","q":"ما الفرق بين التبخّر والغليان؟","options":["الغليان يحدث من السطح فقط","التبخّر يحدث من السطح عند أي حرارة، والغليان في كل السائل عند درجة محددة","التبخّر يحدث عند ١٠٠°م فقط","لا يوجد فرق"],"answer":1,"why":"التبخّر سطحي وتدريجي، والغليان شامل عند درجة الغليان."},{"type":"mcq","q":"لماذا تستطيع جزيئات الهواء الصغيرة جدًّا تحريك حبيبة دخان أكبر منها بكثير؟","options":["لأن الدخان غاز","بسبب الضوء","لأن جزيئات الهواء تتحرك بسرعة هائلة جدًّا وتصطدم بها بكثرة","لأن جزيئات الهواء أثقل من الدخان"],"answer":2,"why":"السرعة العالية جدًّا لجزيئات الهواء تعطيها زخمًا كافيًا لدفع حبيبة الدخان."},{"type":"mcq","q":"كيف تساعد الرياح (تيار الهواء) في تسريع التبخّر؟","options":["تضغط السائل","تزيد قوى التجاذب","تخفض حرارة السائل أولًا","تزيح جزيئات البخار بعيدًا عن السطح فتمنع عودتها للسائل"],"answer":3,"why":"إبعاد البخار يمنع التكثف العكسي ويسرّع التبخّر."},{"type":"tfr","q":"تنضغط السوائل بسهولة مثل الغازات عند وضعها في محقنة مغلقة.","answer":false,"reasons":["السوائل غير قابلة للانضغاط تقريبًا لأن جسيماتها متقاربة جدًّا","الصلب فقط ينضغط","نعم تنضغط بسهولة"],"reason":0},{"type":"tfr","q":"يمكن رؤية جزيئات الهواء نفسها بوضوح باستخدام المجهر الضوئي المدرسي.","answer":false,"reasons":["جزيئات الهواء أصغر بكثير من قدرة المجهر الضوئي؛ نحن نرى حبيبات الدخان فقط ونستدل منها على جزيئات الهواء","المجهر لا يرى الدخان","نعم نرى جزيئات الأكسجين بوضوح"],"reason":0}],"hard":[{"type":"mcq","q":"في منحنى تسخين مادة صلبة نقية، ظهرت فترتان أفقيّتان عند ٢٥°م وعند ١١٠°م؛ ماذا تعنيان؟","options":["درجة الغليان ٢٥°م","توقف التسخين","المادة غير نقية","درجة الانصهار ٢٥°م ودرجة الغليان ١١٠°م"],"answer":3,"why":"الثبات الأول للانصهار والثاني للغليان."},{"type":"mcq","q":"لو سخّنّا الهواء داخل خلية الدخان في تجربة الحركة البراونية، ماذا نلاحظ على حركة حبيبات الدخان؟","options":["تصبح حركتها أسرع وأكثر عنفًا","تتباطأ بشدة","تتوقف عن الحركة","تتحرك في خط مستقيم"],"answer":0,"why":"تزداد سرعة جزيئات الهواء فتصبح تصادماتها بحبيبات الدخان أقوى وأسرع."},{"type":"mcq","q":"لماذا تستهلك عملية الغليان طاقةً حراريةً أكبر بكثير من عملية الانصهار للكتلة نفسها من الماء؟","options":["لأن البخار أثقل من الماء","لأن الغليان يفصل الجزيئات تمامًا ويكسر كل قوى التجاذب، بينما الانصهار يضعفها فقط","لأن الغليان يبرد الماء","لأن الثلج بلا قوى"],"answer":1,"why":"التغلب الكامل على قوى التجاذب يتطلب طاقة أكبر بكثير."},{"type":"essay","q":"اشرح سبب ثبات درجة الحرارة أثناء الانصهار رغم استمرار تزويد المادة بالحرارة.","model":"تُستهلك الطاقة الحرارية المضافة في التغلب على قوى التجاذب بين الجسيمات وفصلها جزئيًا بدل زيادة طاقتها الحركية، فتبقى الحرارة ثابتة."},{"type":"essay","q":"اشرح لماذا يفسّر نموذج الحركة الجزيئية احتفاظ المكعب الصلب بشكله الثابت بينما يأخذ الماء شكل الكوب.","model":"في الصلب الجسيمات مرتّبة في مواضع ثابتة ولا تغادرها (تهتز فقط)، أما في السائل فتنزلق الجسيمات فوق بعضها بحرية فتأخذ شكل الإناء."}]},"test":[{"type":"mcq","q":"أيُّ حالةٍ للمادة يكون شكلها وحجمها ثابتين؟","options":["البلازما","الصلبة","السائلة","الغازية"],"answer":1,"why":"المواد الصلبة تحافظ على شكلها وحجمها."},{"type":"mcq","q":"كيف تتحرّك الجسيمات في المادة الصلبة؟","options":["تطير عشوائيًا","تنزلق بحرية","تهتزّ حول مواضع ثابتة","تتوقّف تمامًا"],"answer":2,"why":"تهتز الجسيمات في أماكنها الثابتة."},{"type":"mcq","q":"في أي حالة تكون قوى التجاذب بين الجسيمات أقوى ما يمكن؟","options":["السائلة","الغازية","البخار","الصلبة"],"answer":3,"why":"قوى التجاذب القوية تحفظ شكل الصلب الثابت."},{"type":"mcq","q":"ما مصدر ضغط الغاز المحبوس في أسطوانة؟","options":["تصادم جزيئات الغاز بجدران الأسطوانة","وزن الأسطوانة","برودة الغاز","قوة التجاذب بين الجزيئات"],"answer":0,"why":"تصادم الجزيئات المستمر يولد قوة ضغط على الجدران."},{"type":"mcq","q":"تحوّل المادة من الحالة الصلبة إلى السائلة يُسمّى:","options":["تجمّدًا","تكثّفًا","انصهارًا","غليانًا"],"answer":2,"why":"الانصهار هو تحول الصلب إلى سائل بالتسخين."},{"type":"mcq","q":"ما الذي نراه تحت المجهر في تجربة الحركة البراونية للدخان؟","options":["سكون تام","خطوط مستقيمة فقط","جزيئات الهواء مباشرةً","حبيبات الدخان تتحرك حركة عشوائية متعرّجة"],"answer":3,"why":"نرى حبيبات الدخان المضيئة ولا نرى جزيئات الهواء."},{"type":"mcq","q":"أيّ جزيئات السائل تستطيع الإفلات من السطح أثناء التبخّر؟","options":["الأسرع والأعلى طاقةً حركية","الأبطأ","الأثقل فقط","التي في قاع الكوب"],"answer":0,"why":"تحتاج طاقة كافية للتغلب على قوى التجاذب."},{"type":"mcq","q":"ما الصيغة الرياضية لقانون بويل؟","options":["P = d ÷ t","P₁ × V₁ = P₂ × V₂","P = m ÷ V","P₁ ÷ V₁ = P₂ ÷ V₂"],"answer":1,"why":"حاصل ضرب الضغط في الحجم ثابت عند ثبات الحرارة."},{"type":"mcq","q":"ما درجة غليان الماء النقي عند الضغط الجوي المعتاد؟","options":["٥٠°م","٣٧°م","٠°م","١٠٠°م"],"answer":3,"why":"يغلي الماء النقي عند ١٠٠°م."},{"type":"mcq","q":"كيف تتغيّر سرعة جسيمات السائل عند تسخينه؟","options":["تزداد سرعتها","تقل سرعتها","تتوقف","لا تتغير"],"answer":0,"why":"التسخين يزيد الطاقة الحركية للجسيمات."},{"type":"mcq","q":"أيُّ ظرفٍ يجعل الملابس المبلّلة تجفّ أسرع؟","options":["يوم بارد ورطب وطي الملابس","يوم حار وعاصف مع فرد الملابس","غرفة مغلقة باردة","إناء ضيق"],"answer":1,"why":"الحرارة + الرياح + مساحة السطح الكبيرة."},{"type":"mcq","q":"إذا سخّنا غازًا في وعاء معدني مغلق ثابت الحجم، فإن ضغطه:","options":["لا يتغيّر","يصبح صفرًا","يرتفع","ينخفض"],"answer":2,"why":"تزداد سرعة الجزيئات فتزداد قوة وتكرار التصادمات."},{"type":"tf","q":"تنضغط السوائل بسهولة مثل الغازات عند وضعها في محقنة مغلقة.","answer":false,"why":"السوائل غير قابلة للانضغاط تقريبًا لأن جسيماتها متقاربة جدًّا"},{"type":"tf","q":"يمكن رؤية جزيئات الهواء نفسها بوضوح باستخدام المجهر الضوئي المدرسي.","answer":false,"why":"جزيئات الهواء أصغر بكثير من قدرة المجهر الضوئي؛ نحن نرى حبيبات الدخان فقط ونستدل منها على جزيئات الهواء"},{"type":"tf","q":"تتحرك جميع جزيئات السائل عند درجة ٢٥°م بالسرعة نفسها تمامًا.","answer":false,"why":"تتوزع سرعات الجزيئات بين بطيئة ومتوسطة وسريعة جدًّا، والحرارة تمثّل المتوسط فقط"},{"type":"tf","q":"عند تقليل حجم الغاز بثبات درجة الحرارة، تزداد سرعة جزيئات الغاز.","answer":false,"why":"السرعة تعتمد على درجة الحرارة فتبقى ثابتة؛ الذي يزداد هو عدد التصادمات في الثانية لصغر المساحة"},{"type":"tfr","q":"درجة انصهار المادة النقية تساوي درجة تجمّدها.","answer":true,"reasons":["تختلف بـ ١٠٠ درجة","الماء النقي ينصهر ويتجمد عند ٠°م","التجمد أعلى من الانصهار"],"reason":1},{"type":"tfr","q":"درجة حرارة الجسم مرتبطة بمتوسط الطاقة الحركية لجسيماته.","answer":true,"reasons":["لا علاقة للحرارة بالحركة","كلما زاد متوسط الطاقة الحركية ارتفعت درجة الحرارة","الحرارة تقيس عدد الجسيمات فقط"],"reason":1},{"type":"tfr","q":"ارتفاع الرطوبة الشديد في الجو يقلّل من سرعة تبخّر العرق ويجعلنا نشعر بحرّ أكبر.","answer":true,"reasons":["الرطوبة تسرّع التبخّر","الهواء المشبع بالبخار يعيد الجزيئات للسطح فيبطئ التبخّر والتبريد","لا علاقة للرطوبة بالتبخّر"],"reason":1},{"type":"tfr","q":"العلاقة بين ضغط الغاز وحجمه عند ثبات درجة الحرارة علاقة طردية.","answer":false,"reasons":["نعم طردية","بل علاقة عكسية: كلما قلّ الحجم زاد الضغط (P₁V₁ = P₂V₂)","لا علاقة بينهما"],"reason":1},{"type":"essay","q":"اذكر أربعة تحوّلات لحالة المادة مع تحديد ما إذا كان كل منها يحتاج تسخينًا أم تبريدًا.","model":"بالتسخين: الانصهار (صلب←سائل) والغليان (سائل←غاز). بالتبريد: التكثّف (غاز←سائل) والتجمّد (سائل←صلب)."},{"type":"essay","q":"فسّر الحركة البراونية لحبوب اللقاح المعلّقة في قطرة ماء تحت المجهر.","model":"تصطدم جزيئات الماء الصغيرة جدًّا والسريعة بحبوب اللقاح الكبيرة عشوائيًا وبقوة غير متساوية من الجهات المختلفة فتجعلها تتحرك حركة متعرجة."},{"type":"essay","q":"اذكر العوامل الثلاثة الرئيسة التي تزيد معدل تبخّر سائل.","model":"١) رفع درجة الحرارة. ٢) زيادة مساحة سطح السائل. ٣) زيادة حركة الهواء (الرياح) فوق السطح."},{"type":"essay","q":"فسّر بالنظرية الحركية لماذا ينصح بعدم إلقاء عبوات العطور والمبيدات المضغوطة في النار.","model":"عند تسخين الغاز المحبوس تزداد سرعة جزيئاته بشدة فتصطدم بجدار العبوة بقوة وتكرار هائلين، فيرتفع الضغط جدًّا وقد تنفجر العبوة."},{"type":"essay","q":"لماذا لا تنضغط المواد الصلبة والسائلة بسهولة بينما تنضغط الغازات بسهولة؟","model":"لأن جسيمات الصلب والسائل متلاصقة تقريبًا دون فراغات كبيرة، بينما تفصل بين جسيمات الغاز مسافات شاسعة."}]},
  {"id":"g9-phy-1-u6","grade":"g9","subject":"physics","term":1,"title":"الوحدة السادسة: المادة والخصائص الحرارية","levels":{"easy":[{"type":"mcq","q":"أيُّ حالةٍ للمادة هي الأقل تمدّدًا عند التسخين؟","options":["البخار","المواد الصلبة","الغازات","السوائل"],"answer":1,"why":"قوى التجاذب القوية في الصلب تحدّ من تمدّده."},{"type":"mcq","q":"عند تبريد قضيب ألمنيوم ساخن، ماذا يحدث لطوله وللمسافات بين ذراته؟","options":["ينكمش وتقلّ المسافات بين ذراته","يتمدّد وتزيد المسافات","يبقى ثابتًا","ينكمش ويصغر حجم الذرات"],"answer":0,"why":"التبريد يخفض اهتزاز الذرات فتتقارب وينكمش القضيب."},{"type":"mcq","q":"ما الذي يزداد فعليًا عند تمدّد قضيب معدني بالتسخين؟","options":["حجم الذرات نفسها","كتلة القضيب","المسافات بين الجسيمات","عدد الذرات"],"answer":2,"why":"الكتلة وحجم الذرة ثابتان، والمسافات فقط تزداد."},{"type":"mcq","q":"أيُّ سلوكٍ يميّز الماء عن معظم السوائل الأخرى عند تبريده من ٤°م إلى ٠°م؟","options":["ينكمش بشدة","يتمدّد حجمه وتقلّ كثافته","تزداد كثافته جدًّا","يتبخر كله"],"answer":1,"why":"شذوذ الماء يجعله يتمدّد عند التجمد فيطفو الجليد."}],"medium":[{"type":"mcq","q":"رتّب حالات المادة تنازليًا من الأكثر تمدّدًا إلى الأقل تمدّدًا بالتسخين:","options":["صلب ← سوائل ← غازات","غازات ← سوائل ← صلب","سوائل ← صلب ← غازات","كلها متساوية"],"answer":1,"why":"الغازات أكثرها تمددًا ثم السوائل ثم الصلب."},{"type":"mcq","q":"عند تبريد قضيب ألمنيوم ساخن، ماذا يحدث لطوله وللمسافات بين ذراته؟","options":["ينكمش وتقلّ المسافات بين ذراته","يتمدّد وتزيد المسافات","يبقى ثابتًا","ينكمش ويصغر حجم الذرات"],"answer":0,"why":"التبريد يخفض اهتزاز الذرات فتتقارب وينكمش القضيب."},{"type":"mcq","q":"ماذا يحدث لكثافة قضيب نحاسي عند تسخينه وتمدّده؟","options":["تزداد","تصبح صفرًا","تقلّ قليلًا (ثبات الكتلة وزيادة الحجم)","تتضاعف"],"answer":2,"why":"ρ = m ÷ V؛ زيادة V مع ثبات m تقلّل الكثافة."},{"type":"tfr","q":"عند تسخين قطعة حديد تزداد كتلتها لأنها تتمدّد.","answer":false,"reasons":["الكتلة تبقى ثابتة تمامًا لأن عدد الذرات لم يتغير، والذي يزداد هو الحجم فقط","تقل كتلتها","نعم تزداد كتلتها"],"reason":0},{"type":"tfr","q":"تتمدّد جميع الفلزات المختلفة بنفس المقدار تمامًا عند تسخينها بالدرجة نفسها.","answer":false,"reasons":["تختلف الفلزات في مقدار تمددها (فالنحاس يتمدد أكثر من الفولاذ)، وهذه هي فكرة الشريط ثنائي الفلز","نعم تتمدد بنفس المقدار","الفولاذ لا يتمدد أبدًا"],"reason":0}],"hard":[{"type":"mcq","q":"لماذا يُفضّل استخدام زجاج «البيركس» (Pyrex) في أواني المختبر والفرن؟","options":["لأنه يتمدد أكثر من النحاس","لأنه لا يسخن أبدًا","لأنه معدن","لأن تمدّده الحراري ضئيل جدًّا فلا يتشقق بالتسخين المفاجئ"],"answer":3,"why":"معامل تمدد البيركس منخفض جدًّا فيتحمل تغير الحرارة."},{"type":"mcq","q":"عند تبريد قضيب ألمنيوم ساخن، ماذا يحدث لطوله وللمسافات بين ذراته؟","options":["ينكمش وتقلّ المسافات بين ذراته","يتمدّد وتزيد المسافات","يبقى ثابتًا","ينكمش ويصغر حجم الذرات"],"answer":0,"why":"التبريد يخفض اهتزاز الذرات فتتقارب وينكمش القضيب."},{"type":"mcq","q":"إذا سخّنا لوحًا معدنيًا فيه ثقب دائري في منتصفه، ماذا يحدث لقطر الثقب؟","options":["يزداد قطر الثقب (يتمدد كالمادة المحيطة به)","يبقى ثابتًا تمامًا","يضيق الثقب","يختفي الثقب"],"answer":0,"why":"التمدد الحراري يشبه تكبير صورة فوتوغرافية؛ كل الأبعاد بما فيها الثقب تكبر."},{"type":"essay","q":"صف كيف يعمل منبّه الحريق المعتمد على الشريط ثنائي الفلز.","model":"عند نشوب حريق يسخن الشريط ثنائي الفلز فينحني باتجاه نقطة تلامس كهربائية، فيغلق الدائرة الكهربائية ويرنّ جرس الإنذار."},{"type":"essay","q":"لماذا تنفجر أنابيب المياه أحيانًا في الدول شديدة البرودة عندما يتجمد الماء بداخلها؟","model":"لأن الماء شاذّ في سلوكه؛ يتمدد حجمه بنحو ٩٪ عند تجمده إلى جليد، فيولّد ضغطًا هائلًا يشقّ الأنبوب."}]},"test":[{"type":"mcq","q":"أيُّ حالةٍ للمادة هي الأقل تمدّدًا عند التسخين؟","options":["البخار","المواد الصلبة","الغازات","السوائل"],"answer":1,"why":"قوى التجاذب القوية في الصلب تحدّ من تمدّده."},{"type":"mcq","q":"عند تبريد قضيب ألمنيوم ساخن، ماذا يحدث لطوله وللمسافات بين ذراته؟","options":["ينكمش وتقلّ المسافات بين ذراته","يتمدّد وتزيد المسافات","يبقى ثابتًا","ينكمش ويصغر حجم الذرات"],"answer":0,"why":"التبريد يخفض اهتزاز الذرات فتتقارب وينكمش القضيب."},{"type":"mcq","q":"ما الذي يزداد فعليًا عند تمدّد قضيب معدني بالتسخين؟","options":["حجم الذرات نفسها","كتلة القضيب","المسافات بين الجسيمات","عدد الذرات"],"answer":2,"why":"الكتلة وحجم الذرة ثابتان، والمسافات فقط تزداد."},{"type":"mcq","q":"أيُّ سلوكٍ يميّز الماء عن معظم السوائل الأخرى عند تبريده من ٤°م إلى ٠°م؟","options":["ينكمش بشدة","يتمدّد حجمه وتقلّ كثافته","تزداد كثافته جدًّا","يتبخر كله"],"answer":1,"why":"شذوذ الماء يجعله يتمدّد عند التجمد فيطفو الجليد."},{"type":"mcq","q":"في أي جهاز يُستخدم الشريط ثنائي الفلز لتنظيم درجة الحرارة تلقائيًا؟","options":["المخبار المدرج","المسطرة","العدسة","المكواة الكهربائية (الثرموستات)"],"answer":3,"why":"ينحني الشريط فيفصل الدائرة الكهربائية عند الحرارة المطلوبة."},{"type":"mcq","q":"ما سبب وضع حلقات انحناء (U-shaped loops) في أنابيب نقل النفط الطويلة؟","options":["لتقليل الضغط فقط","لإبطاء النفط","للسماح بتمدّد الأنابيب وانكماشها دون التواء أو انفجار","لتجميل الصحراء"],"answer":2,"why":"حلقات التمدد تمتص تغير طول الأنابيب بين الصيف والشتاء."},{"type":"mcq","q":"لماذا نمرّر ماءً ساخنًا على غطاء معدني عالق لمرطبان زجاجي؟","options":["لأن المعدن يتمدّد أكثر من الزجاج فيتسع ويُفتح بسهولة","لأن الزجاج ينصهر","لأن المعدن ينكمش","لتجميد الغطاء"],"answer":0,"why":"الفلزات تتمدّد بمقدار أكبر من الزجاج."},{"type":"mcq","q":"رتّب حالات المادة تنازليًا من الأكثر تمدّدًا إلى الأقل تمدّدًا بالتسخين:","options":["صلب ← سوائل ← غازات","غازات ← سوائل ← صلب","سوائل ← صلب ← غازات","كلها متساوية"],"answer":1,"why":"الغازات أكثرها تمددًا ثم السوائل ثم الصلب."},{"type":"mcq","q":"ماذا يحدث لكثافة قضيب نحاسي عند تسخينه وتمدّده؟","options":["تزداد","تصبح صفرًا","تقلّ قليلًا (ثبات الكتلة وزيادة الحجم)","تتضاعف"],"answer":2,"why":"ρ = m ÷ V؛ زيادة V مع ثبات m تقلّل الكثافة."},{"type":"mcq","q":"لماذا يُفضّل استخدام زجاج «البيركس» (Pyrex) في أواني المختبر والفرن؟","options":["لأنه يتمدد أكثر من النحاس","لأنه لا يسخن أبدًا","لأنه معدن","لأن تمدّده الحراري ضئيل جدًّا فلا يتشقق بالتسخين المفاجئ"],"answer":3,"why":"معامل تمدد البيركس منخفض جدًّا فيتحمل تغير الحرارة."},{"type":"mcq","q":"إذا سخّنا لوحًا معدنيًا فيه ثقب دائري في منتصفه، ماذا يحدث لقطر الثقب؟","options":["يزداد قطر الثقب (يتمدد كالمادة المحيطة به)","يبقى ثابتًا تمامًا","يضيق الثقب","يختفي الثقب"],"answer":0,"why":"التمدد الحراري يشبه تكبير صورة فوتوغرافية؛ كل الأبعاد بما فيها الثقب تكبر."},{"type":"mcq","q":"عند تثبيت إطار فولاذي على عجلة خشبية (أو برشام ساخن)، لماذا يُسخّن الفولاذ أولًا قبل التركيب؟","options":["لينصهر تمامًا","ليتمدد فيسهل تركيبه، ثم عند تبريده ينكمش ويشدّ بإحكام شديد","لتقليل كتلته","لمنع الصدأ"],"answer":1,"why":"الانكماش بالتبريد يولّد قوة تثبيت هائلة."},{"type":"tf","q":"عند تسخين قطعة حديد تزداد كتلتها لأنها تتمدّد.","answer":false,"why":"الكتلة تبقى ثابتة تمامًا لأن عدد الذرات لم يتغير، والذي يزداد هو الحجم فقط"},{"type":"tf","q":"تتمدّد جميع الفلزات المختلفة بنفس المقدار تمامًا عند تسخينها بالدرجة نفسها.","answer":false,"why":"تختلف الفلزات في مقدار تمددها (فالنحاس يتمدد أكثر من الفولاذ)، وهذه هي فكرة الشريط ثنائي الفلز"},{"type":"tf","q":"عند تسخين شريط ثنائي الفلز يتكوّن من نحاس وحديد، ينحني الشريط نحو جهة الحديد لأن النحاس يتمدّد أكثر.","answer":true,"why":"الفلز الأكثر تمددًا يصبح على القوس الخارجي الأطول، فينحني الشريط نحو الأقل تمددًا"},{"type":"tf","q":"استخدام الماء الساخن لفتح غطاء معدني عالق لمرطبان زجاجي تطبيق عملي على اختلاف التمدد الحراري.","answer":true,"why":"المعدن يتمدد أكثر من الزجاج فيتسع الغطاء ويُفتح بسهولة"},{"type":"tfr","q":"في تجربة الكرة والحلقة المعدنية، لا تمرّ الكرة الساخنة عبر الحلقة لأن قطرها ازداد بالتمدّد.","answer":true,"reasons":["لأن الكرة انكمشت","لأن الحلقة انكمشت فقط","التسخين يمدد الكرة في جميع الأبعاد فيزداد قطرها"],"reason":2},{"type":"tfr","q":"يجب أن يكون لمادة حشوة الأسنان معدل تمدّد حراري مقارب جدًّا لمعدل تمدد مينا الأسنان.","answer":true,"reasons":["حتى لا تتمدد الحشوة أكثر من السن عند شرب الساخن فتكسره، أو تنكمش أكثر عند البارد فتسقط","يجب أن تتمدد أكثر بكثير","لا علاقة لحشوة الأسنان بالتمدد"],"reason":0},{"type":"tfr","q":"يتمدد الهواء داخل بالون بمقدار أكبر بكثير من تمدد حجم مماثل من الماء عند رفع حرارتهما بمقدار ١٠°م.","answer":true,"reasons":["يتمددان بنفس المقدار","الغازات تتمدد أكثر بكثير من السوائل لضعف قوى التجاذب بين جزيئاتها","الماء يتمدد أكثر من الهواء"],"reason":1},{"type":"tfr","q":"في تجربة الكرة والحلقة، إذا سخّنا «الحلقة» فقط وبقيت الكرة باردة، فإن الكرة تمرّ بسهولة أكبر.","answer":true,"reasons":["لأن الفتحة تضيق بالتسخين","لأن الكرة تسخن وحدها","لأن تسخين الحلقة يوسّع قطر فتحتها الداخلية"],"reason":2},{"type":"essay","q":"اشرح لماذا ينكسر كوب زجاجي سميك أحيانًا عند صبّ ماء مغلي فيه فجأة.","model":"يتمدد السطح الداخلي للزجاج سريعًا بالحرارة بينما يبقى السطح الخارجي باردًا ولم يتمدد بعد، فيتولد إجهاد غير متساوٍ يؤدي لكسر الزجاج."},{"type":"essay","q":"اذكر مشكلتين يسبّبهما التمدّد الحراري في الحياة العملية وكيف يعالجهما المهندسون.","model":"١) التواء قضبان السكك الحديدية والجسور ← تُترك فواصل تمدد. ٢) انقطاع أسلاك الكهرباء شتاءً ← تُترك مرتخية قليلًا عند تركيبها صيفًا."},{"type":"essay","q":"صف كيف يعمل منبّه الحريق المعتمد على الشريط ثنائي الفلز.","model":"عند نشوب حريق يسخن الشريط ثنائي الفلز فينحني باتجاه نقطة تلامس كهربائية، فيغلق الدائرة الكهربائية ويرنّ جرس الإنذار."},{"type":"essay","q":"لماذا تنفجر أنابيب المياه أحيانًا في الدول شديدة البرودة عندما يتجمد الماء بداخلها؟","model":"لأن الماء شاذّ في سلوكه؛ يتمدد حجمه بنحو ٩٪ عند تجمده إلى جليد، فيولّد ضغطًا هائلًا يشقّ الأنبوب."},{"type":"essay","q":"اشرح لماذا ينصح بالابتعاد عن صبّ الماء البارد جدًّا على صينية زجاجية ساخنة خرجت للتو من الفرن.","model":"ينكمش السطح الخارجي فجأةً بينما يبقى الداخل ساخنًا متمددًا، فيحدث فرق إجهاد يسبّب تحطّم الزجاج."}]},
  {"id":"g9-phy-1-u7","grade":"g9","subject":"physics","term":1,"title":"الوحدة السابعة: قياس درجة الحرارة","levels":{"easy":[{"type":"mcq","q":"ما النقطة الثابتة السفلى في مقياس السيليزيوس؟","options":["١٠٠°م","٣٧°م","٠°م (درجة انصهار الجليد النقي)","−١٠٠°م"],"answer":2,"why":"تُحدد بوضع المستودع في جليد نقي منصهر."},{"type":"mcq","q":"ما المقصود بـ «مدى» ميزان الحرارة؟","options":["طول المستودع","لون السائل","سمك الزجاج","أدنى إلى أعلى درجة حرارة يستطيع قياسها"],"answer":3,"why":"المدى يحدد نطاق القياس المتاح."},{"type":"mcq","q":"أيّ سائلٍ يتجمّد عند −١١٥°م فيُستخدم لقياس درجات الحرارة المنخفضة جدًّا؟","options":["الزئبق","الزيت","الماء","الكحول"],"answer":3,"why":"الكحول لا يتجمد إلا عند −١١٥°م."},{"type":"mcq","q":"لجعل ميزان حرارة أكثر حساسيةً نستخدم أنبوبًا شعريًا:","options":["أضيق قطرًا","أوسع قطرًا","أقصر","أسمك جدارًا"],"answer":0,"why":"نفس حجم التمدد يرتفع مسافة أطول في الأنبوب الأضيق."}],"medium":[{"type":"mcq","q":"لماذا لا يُستخدم ميزان الكحول لقياس درجة غليان الماء (١٠٠°م)؟","options":["لأن الكحول يتجمد","لأن الكحول سام","لأن الكحول يغلي عند ٧٨°م قبل الوصول إلى ١٠٠°م","لأنه شفاف"],"answer":2,"why":"درجة غليان الكحول ٧٨°م أقل من ١٠٠°م."},{"type":"mcq","q":"كيف نزيد «مدى» ميزان حرارة دون أن نخسر من «حساسيته»؟","options":["بتوسيع الأنبوب","بتصغير المستودع","بترقيق الزجاج","بإطالة الأنبوب الشعري"],"answer":3,"why":"إطالة الأنبوب تتيح ارتفاع السائل لدرجات أعلى مع بقاء الحساسية نفسها."},{"type":"mcq","q":"ميزان سائل طول عموده عند ٠°م هو ٤ سم وعند ١٠٠°م هو ٢٤ سم؛ كم درجة الحرارة عند طول ١٤ سم؟","options":["٦٠°م","٢٥°م","٤٠°م","٥٠°م"],"answer":3,"why":"[(١٤−٤) ÷ (٢٤−٤)] × ١٠٠ = (١٠ ÷ ٢٠) × ١٠٠ = ٥٠°م."},{"type":"tfr","q":"درجة الحرارة والطاقة الحرارية هما نفس الكمية الفيزيائية تمامًا.","answer":false,"reasons":["درجة الحرارة تقيس متوسط الطاقة الحركية للجسيم الواحد (°C)، أما الطاقة الحرارية فمجموع طاقات الجسيمات كلها (J)","نعم هما متطابقتان","الطاقة الحرارية تُقاس بـ °C"],"reason":0},{"type":"tfr","q":"زيادة حجم المستودع تجعل الميزان أسرع استجابةً لتغيّر درجة الحرارة.","answer":false,"reasons":["المستودع الأكبر يحتوي على سائل أكثر فيستغرق وقتًا أطول ليسخن كله (أبطأ استجابة)، لكنه يزيد الحساسية","لا يؤثر على الاستجابة","نعم يصبح أسرع استجابة"],"reason":0}],"hard":[{"type":"mcq","q":"طول عمود الزئبق في ميزان عند ٠°م هو ١٫٥ سم وعند ١٠٠°م هو ٢١٫٥ سم؛ ما طول العمود عند درجة ٣٥°م؟","options":["٨٫٥ سم","١٠٫٥ سم","٩٫٥ سم","٧٫٠ سم"],"answer":0,"why":"٢٠ سم لكل ١٠٠ درجة = ٠٫٢ سم/درجة ← ٣٥×٠٫٢ = ٧ سم ← ١٫٥ + ٧ = ٨٫٥ سم."},{"type":"mcq","q":"صمّم طالب ميزانًا بحساسية عالية جدًّا لكنه لاحظ أن السائل يفيض ويصل لأعلى الأنبوب عند ٦٠°م فقط؛ ما السبب؟","options":["الزجاج رقيق","المدى أصبح ضيقًا بسبب الأنبوب الضيق جدًّا أو القصير","الاستجابة سريعة","السائل خطّي"],"answer":1,"why":"المقايضة بين الحساسية والمدى عند قصر الأنبوب."},{"type":"mcq","q":"أيُّ جسمين له طاقة حرارية أكبر: إناء به ١٠٠ جم ماء عند ٨٠°م أم حوض به ١٠ كجم ماء عند ٥٠°م؟","options":["لا توجد طاقة في الحوض","الحوض (لأن كتلته أكبر بـ ١٠٠ مرة)","متساويان","الإناء"],"answer":1,"why":"الطاقة الحرارية تعتمد على الكتلة ودرجة الحرارة معًا."},{"type":"essay","q":"لماذا لا يُستخدم الماء كسائل داخل موازين الحرارة الزجاجية؟ (اذكر سببين).","model":"١) يتجمد عند ٠°م ويتمدد عند التجمّد فيكسر الزجاج. ٢) تمدّده غير منتظم بين ٠°م و ٤°م، كما أنه يلتصق بالزجاج وشفاف."},{"type":"essay","q":"قارن بين أثر «تضييق الأنبوب الشعري» و«تكبير المستودع» على كل من: الحساسية، والمدى، وسرعة الاستجابة.","model":"كلاهما يزيد الحساسية ويقلّل المدى (بثبات الطول). لكن تضييق الأنبوب لا يبطئ الاستجابة، بينما تكبير المستودع يبطئ الاستجابة لزيادة كمية السائل."}]},"test":[{"type":"mcq","q":"ما النقطة الثابتة السفلى في مقياس السيليزيوس؟","options":["١٠٠°م","٣٧°م","٠°م (درجة انصهار الجليد النقي)","−١٠٠°م"],"answer":2,"why":"تُحدد بوضع المستودع في جليد نقي منصهر."},{"type":"mcq","q":"ما المقصود بـ «مدى» ميزان الحرارة؟","options":["طول المستودع","لون السائل","سمك الزجاج","أدنى إلى أعلى درجة حرارة يستطيع قياسها"],"answer":3,"why":"المدى يحدد نطاق القياس المتاح."},{"type":"mcq","q":"أيّ سائلٍ يتجمّد عند −١١٥°م فيُستخدم لقياس درجات الحرارة المنخفضة جدًّا؟","options":["الزئبق","الزيت","الماء","الكحول"],"answer":3,"why":"الكحول لا يتجمد إلا عند −١١٥°م."},{"type":"mcq","q":"لجعل ميزان حرارة أكثر حساسيةً نستخدم أنبوبًا شعريًا:","options":["أضيق قطرًا","أوسع قطرًا","أقصر","أسمك جدارًا"],"answer":0,"why":"نفس حجم التمدد يرتفع مسافة أطول في الأنبوب الأضيق."},{"type":"mcq","q":"كم كلفن تساوي درجة حرارة ٢٧°م؟","options":["٣٠٠ كلفن","٣٧٣ كلفن","٢٤٦ كلفن","٢٧ كلفن"],"answer":0,"why":"٢٧ + ٢٧٣ = ٣٠٠ K."},{"type":"mcq","q":"لجعل ميزان الحرارة أسرع استجابةً، يجب أن يكون زجاج المستودع:","options":["معتمًا","رقيقًا جدًّا","بلاستيكيًا سميكًا","سميكًا جدًّا"],"answer":1,"why":"الجدار الرقيق ينقل الحرارة للسائل أسرع."},{"type":"mcq","q":"ما الخاصية الفيزيائية التي تعتمد عليها المزدوجة الحرارية؟","options":["تغيّر اللون","تغيّر الجهد الكهربائي بين وصلتَي فلزين مختلفين","انصهار الجليد","تمدّد الكحول"],"answer":1,"why":"فرق الحرارة بين الوصلتين يولّد جهدًا كهربائيًا."},{"type":"mcq","q":"ما الخاصية التي تعني تساوي المسافات بين التدريجات على طول الميزان؟","options":["الكثافة","الاختناق","الخطّية","المدى"],"answer":2,"why":"التمدد الخطي المنتظم يعطي تدريجات متساوية."},{"type":"mcq","q":"لماذا لا يُستخدم ميزان الكحول لقياس درجة غليان الماء (١٠٠°م)؟","options":["لأن الكحول يتجمد","لأن الكحول سام","لأن الكحول يغلي عند ٧٨°م قبل الوصول إلى ١٠٠°م","لأنه شفاف"],"answer":2,"why":"درجة غليان الكحول ٧٨°م أقل من ١٠٠°م."},{"type":"mcq","q":"كيف نزيد «مدى» ميزان حرارة دون أن نخسر من «حساسيته»؟","options":["بتوسيع الأنبوب","بتصغير المستودع","بترقيق الزجاج","بإطالة الأنبوب الشعري"],"answer":3,"why":"إطالة الأنبوب تتيح ارتفاع السائل لدرجات أعلى مع بقاء الحساسية نفسها."},{"type":"mcq","q":"ميزان سائل طول عموده عند ٠°م هو ٤ سم وعند ١٠٠°م هو ٢٤ سم؛ كم درجة الحرارة عند طول ١٤ سم؟","options":["٦٠°م","٢٥°م","٤٠°م","٥٠°م"],"answer":3,"why":"[(١٤−٤) ÷ (٢٤−٤)] × ١٠٠ = (١٠ ÷ ٢٠) × ١٠٠ = ٥٠°م."},{"type":"mcq","q":"أيّ ميزانين أكثر حساسية: ميزان يتمدد سائله ٣ مم لكل ١°م، أم ميزان يتمدد ١ مم لكل ١°م؟","options":["الأول (٣ مم/°م)","لا يمكن المعرفة","متساويان","الثاني (١ مم/°م)"],"answer":0,"why":"كلما زادت المسافة لكل درجة زادت الحساسية وسهلت قراءة أجزاء الدرجة."},{"type":"tf","q":"درجة الحرارة والطاقة الحرارية هما نفس الكمية الفيزيائية تمامًا.","answer":false,"why":"درجة الحرارة تقيس متوسط الطاقة الحركية للجسيم الواحد (°C)، أما الطاقة الحرارية فمجموع طاقات الجسيمات كلها (J)"},{"type":"tf","q":"زيادة حجم المستودع تجعل الميزان أسرع استجابةً لتغيّر درجة الحرارة.","answer":false,"why":"المستودع الأكبر يحتوي على سائل أكثر فيستغرق وقتًا أطول ليسخن كله (أبطأ استجابة)، لكنه يزيد الحساسية"},{"type":"tf","q":"تستجيب المزدوجة الحرارية للتغيّرات السريعة جدًّا في درجة الحرارة لأن كتلتها الحرارية عند الوصلة صغيرة جدًّا.","answer":true,"why":"تسخن الوصلة المعدنية الصغيرة وتبرد في أجزاء من الثانية فتقيس التغيرات السريعة بدقة"},{"type":"tf","q":"الكحول يعطي حساسية أعلى من الزئبق في ميزانين متماثلين لأن الكحول يتمدّد أكثر من الزئبق.","answer":true,"why":"معامل تمدد الكحول أكبر من الزئبق فيتحرك مسافة أطول لكل درجة"},{"type":"tfr","q":"في معايرة النقطة العليا (١٠٠°م) نضع مستودع الميزان في «بخار الماء المغلي» وليس في الماء نفسه.","answer":true,"reasons":["لأن الماء لا يغلي","لأن البخار أبرد من الماء","لأن الشوائب ترفع درجة غليان الماء نفسه فوق ١٠٠°م، بينما يبقى البخار المتصاعد نقيًا عند ١٠٠°م"],"reason":2},{"type":"tfr","q":"استخدام أنبوب شعري أوسع يزيد مدى الميزان لكنه يقلّل حساسيته.","answer":true,"reasons":["يقلل المدى","يزيد الحساسية والمدى معًا","في الأنبوب الأوسع يرتفع السائل مسافة أقل لكل درجة فتقل الحساسية ويزداد المدى"],"reason":2},{"type":"tfr","q":"يمكن لميزان حراري رقمي متصل بمزدوجة حرارية تسجيل درجة حرارة لهب أو محرك نفاث عن بُعد بأمان.","answer":true,"reasons":["لأن الإشارة الكهربائية تنتقل عبر أسلاك طويلة إلى شاشة القراءة أو الحاسوب","الزئبق أفضل للمحرك","لا يمكن قياس حرارة المحرك"],"reason":0},{"type":"tfr","q":"إذا كان الميزان غير خطّي، فلا يمكن قراءة درجة الحرارة بدقة بتقسيم المسافة بين ٠°م و ١٠٠°م إلى ١٠٠ قسم متساوٍ.","answer":true,"reasons":["لأن التمدد غير المنتظم يعني أن كل سم لا يمثّل عدد الدرجات نفسه في كل جزء من التدريج","يمكن تقسيمه بالتساوي دائمًا","الخطية غير مهمة"],"reason":0},{"type":"essay","q":"اشرح كيف تضع علامتَي ٠°م و ١٠٠°م على ميزان حرارة زجاجي غير مدرّج.","model":"نضع المستودع في جليد نقي منصهر ونعلّم مستوى السائل بـ ٠°م، ثم نضعه في بخار ماء نقي يغلي عند الضغط الجوي المعتاد ونعلّم ١٠٠°م، ثم نقسم المسافة إلى ١٠٠ قسم متساوٍ."},{"type":"essay","q":"عرّف كلًّا من «الحساسية» و«الخطّية» في تصميم موازين الحرارة.","model":"الحساسية: مقدار حركة السائل لكل ١°م. الخطّية: تمدّد السائل بمقادير متساوية لكل زيادة متساوية في درجة الحرارة."},{"type":"essay","q":"اذكر ميزتين للمزدوجة الحرارية مقارنةً بميزان الحرارة الزئبقي.","model":"١) مدى قياس واسع جدًّا (حتى ١٥٠٠°م). ٢) استجابة سريعة جدًّا للتغيرات، ويمكن ربطها بحاسوب لقراءة البيانات عن بُعد."},{"type":"essay","q":"لماذا يُصنع زجاج مستودع الميزان رقيقًا، بينما يُصنع زجاج ساق الميزان سميكًا؟","model":"المستودع رقيق لسرعة انتقال الحرارة واستجابة الميزان، أما الساق فسميكة لحماية الأنبوب الشعري من الكسر ولعملها كعدسة مكبّرة تسهل رؤية خيط السائل."},{"type":"essay","q":"لماذا لا يُستخدم الماء كسائل داخل موازين الحرارة الزجاجية؟ (اذكر سببين).","model":"١) يتجمد عند ٠°م ويتمدد عند التجمّد فيكسر الزجاج. ٢) تمدّده غير منتظم بين ٠°م و ٤°م، كما أنه يلتصق بالزجاج وشفاف."}]},
  {"id":"g9-phy-1-u8","grade":"g9","subject":"physics","term":1,"title":"الوحدة الثامنة: الطاقة","levels":{"easy":[{"type":"mcq","q":"وحدة قياس الطاقة في النظام الدولي (SI) هي:","options":["الجول (J)","الواط (W)","النيوتن (N)","الباسكال (Pa)"],"answer":0,"why":"تُقاس الطاقة بجميع صورها بوحدة الجول (J)."},{"type":"mcq","q":"الجهاز الذي يحوّل الطاقة الحركية الدورانية في محطة التوليد إلى طاقة كهربائية هو:","options":["المصباح","السخّان الشمسي","البطارية الكيميائية","المولّد الكهربائي"],"answer":3,"why":"المولّد الكهربائي يحوّل حركة التوربين إلى كهرباء."},{"type":"mcq","q":"ينصّ مبدأ حفظ الطاقة على أن الطاقة:","options":["تزداد تلقائيًا مع الزمن","تُستحدث داخل المحركات الكهربائية","لا تفنى ولا تُستحدث ولكن تتحوّل من صورة لأخرى","تختفي تمامًا عند توقف الجسم"],"answer":2,"why":"الطاقة الكلية محفوظة دائمًا وتتغير صورها فقط."},{"type":"mcq","q":"قانون حساب طاقة الوضع الجاذبية هو:","options":["ΔEp = m ÷ h","ΔEp = m g Δh","ΔEp = ½ m v²","ΔEp = F ÷ t"],"answer":1,"why":"طاقة الوضع الجاذبية تساوي حاصل ضرب الكتلة في شدة الجاذبية في الارتفاع."}],"medium":[{"type":"mcq","q":"عند تشغيل مصباح يدوي يعمل ببطارية، فإن تسلسل تحوّل الطاقة هو:","options":["كيميائية ← كهربائية ← ضوئية وحرارية","نووية ← ضوئية ← كيميائية","حركية ← كهربائية ← ضوئية","مرونية ← حرارية ← ضوئية"],"answer":0,"why":"تتحول الطاقة الكيميائية في البطارية إلى كهربائية ثم ضوئية مفيدة وحرارية مهدرة."},{"type":"mcq","q":"في محطة توليد كهرباء تعمل بالفحم، ما الترتيب الصحيح لتحوّلات الطاقة؟","options":["نووية ← حركية ← حرارية ← كهربائية","وضع ← حركية ← كيميائية ← كهربائية","حرارية ← كيميائية ← ضوئية ← كهربائية","كيميائية ← حرارية ← حركية ← كهربائية"],"answer":3,"why":"حرق الفحم يحرر حرارة تغلي الماء فينتج بخار يحرّك التوربين والمولد."},{"type":"mcq","q":"محرّك كهربائي تدخله 600 J، وتبلغ الطاقة المهدرة فيه 180 J. كم تبلغ الطاقة المفيدة وكفاءته؟","options":["780 J وكفاءته 130%","180 J وكفاءته 30%","420 J وكفاءته 70%","420 J وكفاءته 30%"],"answer":2,"why":"المفيدة = 600 − 180 = 420 J، والكفاءة = (420 ÷ 600) × 100% = 70%."},{"type":"tfr","q":"يزداد مقدار طاقة الوضع الجاذبية للجسم كلما ارتفع عن سطح الأرض.","answer":true,"reasons":["لأننا نبذل شغلًا ضد الجاذبية لرفعه فيختزن طاقة وضع أكبر","لأن الجاذبية تنعدم فوق سطح الأرض","لأن كتلته تزداد مع الارتفاع"],"reason":0},{"type":"tfr","q":"لا تُنتج محطات الطاقة النووية غاز ثاني أكسيد الكربون أثناء التشغيل، لكنها تُعد غير متجددة.","answer":true,"reasons":["لأن اليورانيوم يتجدد يوميًا","لأنها تحرق الفحم الحجري","لأنها تعتمد على خام اليورانيوم المحدود في الأرض دون احتراق كربوني"],"reason":2}],"hard":[{"type":"mcq","q":"في البندول البسيط المتأرجح، يكون للجسم أكبر طاقة حركة عند:","options":["نقطة التوقف اللحظي","أعلى نقطة على اليسار","أعلى نقطة على اليمين","أدنى نقطة في مساره (المنتصف)"],"answer":3,"why":"في أدنى نقطة تكون طاقة الوضع أقل ما يمكن وسرعة الكرة أكبر ما يمكن."},{"type":"mcq","q":"لماذا تُعد الطاقة الحرارية الأرضية أكثر موثوقيةً من الطاقة الشمسية؟","options":["لأنها تتوفر بكثرة في كل مكان على سطح الأرض","لأنها غير متجددة","لأن حرارة باطن الأرض متوفرة باستمرار ليلًا ونهارًا بغض النظر عن الطقس","لأنها لا تحتاج إلى توربينات"],"answer":2,"why":"حرارة باطن الأرض لا تتوقف في الليل أو في الأيام الغائمة."},{"type":"mcq","q":"جهاز كفاءته 40% أنتج طاقةً مفيدةً مقدارها 120 J. ما مقدار الطاقة الكلية الداخلة؟","options":["200 J","300 J","160 J","48 J"],"answer":1,"why":"الداخلة = المفيدة ÷ الكفاءة = 120 ÷ 0.40 = 300 J."},{"type":"essay","q":"قارن بين «مخازن الطاقة» و«طرق انتقال الطاقة» مع ذكر مثالين لكل منهما.","model":"مخازن الطاقة هي الأشكال التي تُحفظ بها الطاقة داخل الجسم أو النظام (مثل الكيميائية والوضع والحركية). أما طرق الانتقال فهي المسارات التي تنتقل بها الطاقة من مخزن لآخر (مثل الانتقال الميكانيكي والكهربائي والتسخين والإشعاع)."},{"type":"essay","q":"اقترح خطةً متكاملةً لتوليد الكهرباء في سلطنة عُمان تجمع بين مصدرين متجددين مع تبرير اختيارك.","model":"الجمع بين محطات الطاقة الشمسية (لاستغلال السطوع الشمسي القوي نهارًا في معظم المحافظات) ومحطات طاقة الرياح (مثل ظفار للاستفادة من الرياح الموسمية ليلًا ونهارًا) مع بطاريات تخزين لضمان استقرار الشبكة."}]},"test":[{"type":"mcq","q":"وحدة قياس الطاقة في النظام الدولي (SI) هي:","options":["الجول (J)","الواط (W)","النيوتن (N)","الباسكال (Pa)"],"answer":0,"why":"تُقاس الطاقة بجميع صورها بوحدة الجول (J)."},{"type":"mcq","q":"الجهاز الذي يحوّل الطاقة الحركية الدورانية في محطة التوليد إلى طاقة كهربائية هو:","options":["المصباح","السخّان الشمسي","البطارية الكيميائية","المولّد الكهربائي"],"answer":3,"why":"المولّد الكهربائي يحوّل حركة التوربين إلى كهرباء."},{"type":"mcq","q":"ينصّ مبدأ حفظ الطاقة على أن الطاقة:","options":["تزداد تلقائيًا مع الزمن","تُستحدث داخل المحركات الكهربائية","لا تفنى ولا تُستحدث ولكن تتحوّل من صورة لأخرى","تختفي تمامًا عند توقف الجسم"],"answer":2,"why":"الطاقة الكلية محفوظة دائمًا وتتغير صورها فقط."},{"type":"mcq","q":"قانون حساب طاقة الوضع الجاذبية هو:","options":["ΔEp = m ÷ h","ΔEp = m g Δh","ΔEp = ½ m v²","ΔEp = F ÷ t"],"answer":1,"why":"طاقة الوضع الجاذبية تساوي حاصل ضرب الكتلة في شدة الجاذبية في الارتفاع."},{"type":"mcq","q":"تُعرَّف القدرة بأنها:","options":["معدل نقل الطاقة أو بذل الشغل في الثانية","مقدار القوة المؤثرة في الجسم","المسافة المقطوعة في الثانية","كتلة الجسم المتحرك"],"answer":0,"why":"القدرة هي الطاقة المنقولة مقسومةً على الزمن."},{"type":"mcq","q":"جهاز ينقل 800 J في 4 s؛ قدرته تساوي:","options":["804 W","3200 W","400 W","200 W"],"answer":3,"why":"P = 800 ÷ 4 = 200 W."},{"type":"mcq","q":"الطاقة التي يمتلكها الجسم بسبب ارتفاعه عن سطح الأرض تُسمّى:","options":["الطاقة المرونية","طاقة الوضع الجاذبية","طاقة الحركة","الطاقة النووية"],"answer":1,"why":"الارتفاع عن الأرض يكسب الجسم طاقة وضع جاذبية."},{"type":"mcq","q":"أي من المصادر الآتية يُصنّف مصدرًا متجددًا للطاقة؟","options":["طاقة الرياح","النفط","الفحم الحجري","اليورانيوم"],"answer":0,"why":"الرياح تتجدد طبيعيًا باستمرار ولا تنفد."},{"type":"mcq","q":"في مخطط سانكي، السهم المتجه للأسفل يمثّل عادةً:","options":["الكتلة","الطاقة الداخلة","الطاقة المفيدة","الطاقة المهدرة"],"answer":3,"why":"تُظهر مخططات سانكي الطاقة المهدرة بسهم ينحني للأسفل."},{"type":"mcq","q":"قانون حساب طاقة الحركة هو:","options":["Ek = ½ m v","Ek = m v","Ek = ½ m v²","Ek = m g h"],"answer":2,"why":"طاقة الحركة تساوي نصف الكتلة في مربّع السرعة."},{"type":"mcq","q":"تُكافئ وحدة الواط (W):","options":["نيوتن / ثانية (N/s)","جول / ثانية (J/s)","كيلوجرام / ثانية","جول × ثانية (J·s)"],"answer":1,"why":"P = E/t لذا 1 W = 1 J/s."},{"type":"mcq","q":"مروحة قدرتها 60 W تعمل لمدة 10 s؛ الطاقة المستهلكة تساوي:","options":["600 J","6000 J","70 J","6 J"],"answer":0,"why":"ΔE = P × t = 60 × 10 = 600 J."},{"type":"tf","q":"يزداد مقدار طاقة الوضع الجاذبية للجسم كلما ارتفع عن سطح الأرض.","answer":true,"why":"لأننا نبذل شغلًا ضد الجاذبية لرفعه فيختزن طاقة وضع أكبر"},{"type":"tf","q":"لا تُنتج محطات الطاقة النووية غاز ثاني أكسيد الكربون أثناء التشغيل، لكنها تُعد غير متجددة.","answer":true,"why":"لأنها تعتمد على خام اليورانيوم المحدود في الأرض دون احتراق كربوني"},{"type":"tf","q":"عندما يتوقف بندول متأرجح بعد عدة دقائق، فإن طاقته تكون قد فنيت.","answer":false,"why":"لأن طاقته لم تفنَ بل تشتّتت كحرارة في الهواء ونقطة التعليق بسبب المقاومة والاحتكاك"},{"type":"tf","q":"لا تعتمد سرعة جسم يسقط سقوطًا حرًّا من ارتفاع معين (بإهمال مقاومة الهواء) على كتلته.","answer":true,"why":"لأن الكتلة m تُختصر من طرفي المعادلة mgh = ½mv² فتبقى v = √(2gh)"},{"type":"tfr","q":"الجهاز ذو القدرة الأعلى يحوّل كمية أكبر من الطاقة في الثانية الواحدة.","answer":true,"reasons":["لأن الجهاز ذو القدرة الأعلى يعمل زمنًا أطول دائمًا","لأن القدرة لا ترتبط بالطاقة","لأن القدرة تقيس عدد الجولات المحوّلة في كل ثانية"],"reason":2},{"type":"tfr","q":"إذا زاد زمن رفع نفس الجسم لنفس الارتفاع إلى الضعف، فإن القدرة تقلّ إلى النصف.","answer":true,"reasons":["لأن الكتلة تقل للنصف","لأن P = W/t فتتناسب القدرة عكسيًا مع الزمن عند ثبات الشغل","لأن الشغل يقل للنصف"],"reason":1},{"type":"tfr","q":"تُعد الطاقة الحرارية الناتجة في محرك السيارة طاقةً مفيدةً.","answer":false,"reasons":["لأن الحرارة تتحول كلها إلى بنزين","لأن الغرض من المحرك هو تحريك السيارة، فتُعد الحرارة طاقةً مهدرةً","لأن المحرك لا ينتج حرارة أبدًا"],"reason":1},{"type":"tfr","q":"تحتاج الخلايا الشمسية إلى بخار ماء وتوربين لإنتاج الكهرباء.","answer":false,"reasons":["لأنها تحوّل ضوء الشمس مباشرة إلى كهرباء عبر أشباه الموصلات دون توربين","لأنها تحرق الوقود الحيوي","لأنها تعمل بالرياح"],"reason":0},{"type":"essay","q":"اذكر أربعًا من طرق انتقال الطاقة مع مثال واحد لكل طريقة.","model":"١) ميكانيكيًا: دفع عربة. ٢) كهربائيًا: تيار يسري في مصباح. ٣) بالتسخين: غلي الماء على موقد. ٤) بالإشعاع: ضوء الشمس أو موجات الصوت."},{"type":"essay","q":"قارن بين محطة الوقود الأحفوري ومحطة طاقة الرياح من حيث التجدّد والأثر البيئي والاستمرارية.","model":"الوقود الأحفوري غير متجدد ويلوّث الهواء بغاز CO₂ لكنه يعطي إنتاجًا مستمرًا وموثوقًا. أما الرياح فمتجددة ونظيفة بلا انبعاثات، لكنها متقطّعة تعتمد على سرعة الهواء."},{"type":"essay","q":"سخّان كهربائي تدخله 2500 J، فينقل 2000 J إلى الماء. احسب: (أ) الطاقة المهدرة، (ب) كفاءة السخان.","model":"أ) الطاقة المهدرة = 2500 − 2000 = 500 J. ب) الكفاءة = (2000 ÷ 2500) × 100% = 80%."},{"type":"essay","q":"احسب ارتفاع رفٍّ وُضع عليه كتاب كتلته 1.5 kg فأصبحت طاقة وضعه الجاذبية 30 J (حيث g = 10 N/kg).","model":"Δh = ΔEp ÷ (m × g) = 30 ÷ (1.5 × 10) = 30 ÷ 15 = 2 m."},{"type":"essay","q":"ما الفرق بين «الطاقة» و«القدرة»؟ وضّح بمثال من حياتك اليومية.","model":"الطاقة هي الكمية الكلية للشغل وتُقاس بالجول (مثل كمية الطاقة اللازمة لغلي لتر ماء)، أما القدرة فهي سرعة نقل هذه الطاقة وتُقاس بالواط (غلاية 2000 W تغلي الماء أسرع من غلاية 1000 W رغم استهلاك نفس الطاقة تقريبًا)."}]},
  {"id":"g9-phy-1-u9","grade":"g9","subject":"physics","term":1,"title":"الوحدة التاسعة: انتقال الطاقة: التوصيل والحمل الحراري والإشعاع","levels":{"easy":[{"type":"mcq","q":"أفضل المواد الآتية توصيلًا للحرارة هو:","options":["الخشب","الهواء","النحاس","البلاستيك"],"answer":2,"why":"النحاس فلز غني بالإلكترونات الحرة وهو من أفضل الموصلات."},{"type":"mcq","q":"يحدث انتقال الحرارة بالحمل الحراري في:","options":["الفلزات الصلبة فقط","السوائل والغازات فقط","الفراغ فقط","المواد الصلبة فقط"],"answer":1,"why":"تحتاج تيارات الحمل لمائع يستطيع التدفق والحركة."},{"type":"mcq","q":"نوع الموجات المسؤولة عن الإشعاع الحراري هو:","options":["الأشعة تحت الحمراء","موجات الصوت","الإلكترونات الحرة","تيارات الحمل"],"answer":0,"why":"الإشعاع الحراري ينتقل على هيئة موجات كهرومغناطيسية تحت حمراء."},{"type":"mcq","q":"المادة التي تُستخدم لصنع مقابض أواني الطبخ هي:","options":["الألمنيوم","النحاس","الحديد","البلاستيك أو الخشب (عازل)"],"answer":3,"why":"نستخدم العوازل للمقابض لمنع انتقال الحرارة لليد."}],"medium":[{"type":"mcq","q":"لماذا توصل الفلزات الحرارة أسرع بكثير من اللافلزات؟","options":["لأن الفلزات خفيفة الوزن","لأن ذرات الفلزات لا تهتز","لوجود إلكترونات حرة تنقل الطاقة بسرعة عبر الفلز","لأن المسافات بين ذرات الفلزات ضخمة"],"answer":2,"why":"حركة الإلكترونات الحرة السريعة وتصادمها بالذرات يسرّع التوصيل جدًّا."},{"type":"mcq","q":"لماذا تُستخدم بلورة برمنجنات البوتاسيوم البنفسجية في تجربة الحمل الحراري بالماء؟","options":["لمنع الماء من التمدد","لتلوين الماء وجعل حركة تيار الحمل مرئيةً بالعين","لتجميد الماء في القاع","لتسخين الماء دون لهب"],"answer":1,"why":"الماء شفاف، واللون البنفسجي يوضح مسار صعود وهبوط تيارات الحمل."},{"type":"mcq","q":"أي العبارات الآتية صحيحة عن السطح الأسود المعتم؟","options":["هو أفضل ماصّ وأفضل باعث للإشعاع الحراري","لا يشعّ أي حرارة أبدًا","هو أفضل عاكس للإشعاع","هو أفضل ماصّ لكنه أضعف باعث"],"answer":0,"why":"الماصّ الجيد للإشعاع هو دائمًا باعث جيد أيضًا."},{"type":"tfr","q":"الماء موصل جيّد للحرارة بالتوصيل.","answer":false,"reasons":["لأن تجربة تسخين أعلى أنبوب الماء وبه ثلج في القاع تثبت أنه موصل رديء بالتوصيل","لأن الماء مادة صلبة","لأن الماء يحتوي إلكترونات حرة"],"reason":0},{"type":"tfr","q":"يزداد حجم جزيء الهواء نفسه عند تسخينه فيقل وزنه ويصعد للأعلى.","answer":false,"reasons":["لأن الهواء البارد يصعد للأعلى","لأن الهواء ينكمش بالتسخين","لأن الجزيء نفسه لا يكبر، بل تتباعد الجزيئات عن بعضها فيزداد حجم المائع وتقل كثافته"],"reason":2}],"hard":[{"type":"mcq","q":"في النوافذ ذات الزجاج المزدوج، يتم حبس طبقة رقيقة من الهواء (أو الأرجون) بين لوحي الزجاج بهدف:","options":["زيادة توصيل الحرارة للداخل","تقليل انتقال الحرارة بالتوصيل لكون الهواء عازلًا","منع دخول الضوء","زيادة وزن النافذة"],"answer":1,"why":"الهواء المحبوس عازل ممتاز يقلل التوصيل الحراري عبر النافذة."},{"type":"mcq","q":"تُبنى مداخن المصانع عاليةً جدًّا لأن:","options":["الغازات الساخنة الأقل كثافةً تصعد بقوة للأعلى فتسحب هواءً نقيًا للاحتراق وتُبعد الدخان","المداخن تمنع التمدد","الهواء البارد يصعد لأعلى المدخنة","الحمل الحراري يحدث في الطوب الصلب"],"answer":0,"why":"تيار الحمل الصاعد في المدخنة يطرد الدخان عاليًا ويجلب الأكسجين للموقد."},{"type":"mcq","q":"يرتدي رجال الإطفاء بدلات ذات سطح فضي لامع عند الاقتراب من الحرائق الشديدة لأنها:","options":["تمتص الحرارة بسرعة","تسمح بدخول تيارات الحمل","تزيد التوصيل الحراري لأجسامهم","تعكس معظم الأشعة تحت الحمراء القادمة من اللهب"],"answer":3,"why":"السطح الفضي اللامع يعكس الإشعاع الحراري الشديد فيحمي رجل الإطفاء."},{"type":"essay","q":"قارن بين آلية التوصيل الحراري في قضيب من الألمنيوم وقضيب من الزجاج.","model":"في الزجاج (لافلز): ينتقل التوصيل ببطء عبر اهتزاز الذرات وتصادمها مع جيرانها فقط. في الألمنيوم (فلز): بالإضافة لاهتزاز الذرات، تكتسب الإلكترونات الحرة طاقة وتتحرك بسرعة كبيرة عبر الفلز لتصطدم بالذرات البعيدة فتنقل الحرارة بسرعة فائقة."},{"type":"essay","q":"قارن بين التوصيل الحراري والحمل الحراري من حيث: (١) الوسط الذي يحدثان فيه، (٢) حركة المادة نفسها.","model":"التوصيل يحدث أساسًا في المواد الصلبة ولا تتحرك الجزيئات من مواقعها بل تهتز وتنقل الطاقة (مع الإلكترونات الحرة في الفلزات). أما الحمل فيحدث في الموائع (السوائل والغازات) وتتحرك فيه كتل المائع نفسها صعودًا وهبوطًا لاختلاف الكثافة."}]},"test":[{"type":"mcq","q":"أفضل المواد الآتية توصيلًا للحرارة هو:","options":["الخشب","الهواء","النحاس","البلاستيك"],"answer":2,"why":"النحاس فلز غني بالإلكترونات الحرة وهو من أفضل الموصلات."},{"type":"mcq","q":"يحدث انتقال الحرارة بالحمل الحراري في:","options":["الفلزات الصلبة فقط","السوائل والغازات فقط","الفراغ فقط","المواد الصلبة فقط"],"answer":1,"why":"تحتاج تيارات الحمل لمائع يستطيع التدفق والحركة."},{"type":"mcq","q":"نوع الموجات المسؤولة عن الإشعاع الحراري هو:","options":["الأشعة تحت الحمراء","موجات الصوت","الإلكترونات الحرة","تيارات الحمل"],"answer":0,"why":"الإشعاع الحراري ينتقل على هيئة موجات كهرومغناطيسية تحت حمراء."},{"type":"mcq","q":"المادة التي تُستخدم لصنع مقابض أواني الطبخ هي:","options":["الألمنيوم","النحاس","الحديد","البلاستيك أو الخشب (عازل)"],"answer":3,"why":"نستخدم العوازل للمقابض لمنع انتقال الحرارة لليد."},{"type":"mcq","q":"عند تسخين الهواء في أسفل الغرفة فإنه:","options":["تزداد كتلته ويبقى في الأسفل","يتحوّل إلى مادة صلبة","يتمدد وتقل كثافته فيصعد للأعلى","ينكمش وتزداد كثافته ويهبط"],"answer":2,"why":"التمدد الحراري يقلل الكثافة فيصعد الهواء الدافئ."},{"type":"mcq","q":"الطريقة التي تنقل الحرارة عبر الفراغ هي:","options":["التوصيل فقط","الإشعاع فقط","الحمل فقط","التوصيل والحمل"],"answer":1,"why":"التوصيل والحمل يحتاجان لوسط مادي، أما الإشعاع فيعبر الفراغ."},{"type":"mcq","q":"تنتقل الحرارة بالتوصيل في اللافلزات الصلبة عن طريق:","options":["اهتزاز الذرات وتصادمها مع المجاورة","الإلكترونات الحرة فقط","الموجات الكهرومغناطيسية","تيارات الحمل"],"answer":0,"why":"اللافلزات لا تحتوي إلكترونات حرة فتعتمد على اهتزاز الذرات فقط."},{"type":"mcq","q":"تُوضع المدفأة الكهربائية عادةً على أرضية الغرفة (في الأسفل) لكي:","options":["يبقى الهواء الساخن عند الأرض فقط","تمنع التوصيل","تقل كثافة الأرضية","يصعد الهواء الساخن ويهبط البارد فتدفأ الغرفة كلها"],"answer":3,"why":"تيار الحمل الصاعد يوزع الدفء في أنحاء الغرفة."},{"type":"mcq","q":"أفضل سطح لـ«عكس» الإشعاع الحراري هو:","options":["السطح الأسود المعتم","السطح البني الخشن","السطح الفضي أو الأبيض اللامع","السطح الرمادي المعتم"],"answer":2,"why":"الأسطح اللامعة الفاتحة تعكس معظم الإشعاع الساقط عليها."},{"type":"mcq","q":"يُعد الهواء الساكن المحبوس بين ألياف الصوف:","options":["فلزًا سائلًا","عازلًا حراريًا ممتازًا","موصلًا حراريًا قويًا","مصدرًا للحرارة"],"answer":1,"why":"تباعد جزيئات الهواء يجعله عازلًا ممتازًا عند منعه من الحركة."},{"type":"mcq","q":"في ظاهرة نسيم البحر نهارًا، يتحرّك الهواء البارد من:","options":["البحر نحو اليابسة","الأعلى نحو الفضاء","اليابسة نحو البحر","الفضاء نحو البحر"],"answer":0,"why":"يسخن هواء اليابسة ويصعد فيحل محله هواء البحر البارد."},{"type":"mcq","q":"تُطلى خزانات المياه والوقود في المناطق الحارة باللون الأبيض أو الفضي اللامع لكي:","options":["تزيد التوصيل الحراري","تزيد كثافة الماء","تمتص أكبر قدر من الحرارة","تعكس إشعاع الشمس فلا تسخن كثيرًا"],"answer":3,"why":"الأبيض والفضي اللامع يقللان امتصاص حرارة الشمس."},{"type":"tf","q":"الماء موصل جيّد للحرارة بالتوصيل.","answer":false,"why":"لأن تجربة تسخين أعلى أنبوب الماء وبه ثلج في القاع تثبت أنه موصل رديء بالتوصيل"},{"type":"tf","q":"يزداد حجم جزيء الهواء نفسه عند تسخينه فيقل وزنه ويصعد للأعلى.","answer":false,"why":"لأن الجزيء نفسه لا يكبر، بل تتباعد الجزيئات عن بعضها فيزداد حجم المائع وتقل كثافته"},{"type":"tf","q":"لا يُصدر جسم الإنسان أي إشعاع حراري لأن درجة حرارته 37°C فقط.","answer":false,"why":"لأن جميع الأجسام فوق الصفر المطلق تشعّ أشعةً تحت حمراء، وتلتقطها الكاميرات الحرارية"},{"type":"tf","q":"لا يمكن أن تنتقل الحرارة من الشمس إلى الأرض بالتوصيل.","answer":true,"why":"لأن الفضاء فراغ لا يحتوي على جسيمات تنقل الاهتزاز أو تتصادم"},{"type":"tfr","q":"يُوضع مجمّد الثلاجة (الفريزر) في الجزء العلوي منها لتبريد الثلاجة بكفاءة عبر تيارات الحمل.","answer":true,"reasons":["لأن الهواء الملامس للفريزر يبرد وتزداد كثافته فيهبط لتبريد الرفوف السفلية ويصعد الدافئ مكانه","لأن الهواء البارد يصعد للأعلى","لأن الفريزر يعمل بالتوصيل فقط"],"reason":0},{"type":"tfr","q":"يبرد إبريق الشاي الفضي اللامع أبطأ من إبريق أسود معتم متماثل له.","answer":true,"reasons":["لأن الأسود عازل حراري","لأن الفضي يمتص حرارة من الغرفة","لأن السطح الفضي اللامع باعث رديء للإشعاع الحراري فيفقد حرارته ببطء أكبر"],"reason":2},{"type":"tfr","q":"في الصيف الحار بعُمان، يبدو مقبض السيارة المعدني أسخن بكثير من مقعد القماش رغم تساوي حرارتهما.","answer":true,"reasons":["لأن القماش أبرد دائمًا بـ 20 درجة","لأن المعدن عازل","لأن المعدن موصل جيد فينقل الحرارة من المقبض الساخن إلى يدك بسرعة كبيرة"],"reason":2},{"type":"tfr","q":"لا يمكن حدوث تيارات حمل حراري في محطة فضائية يسودها انعدام الوزن الظاهري.","answer":true,"reasons":["لأن المحطة لا تحتوي هواءً","لأن صعود الأقل كثافة وهبوط الأكثر كثافة يعتمد على وجود الجاذبية (الطفو)","لأن الهواء لا يتمدد في الفضاء"],"reason":1},{"type":"essay","q":"صف باختصار تجربةً عمليةً لإثبات أن الماء موصل رديء للحرارة.","model":"نضع قطعة ثلج مربوطة بثقل (شبك معدني) في قاع أنبوب اختبار مملوء بالماء، ثم نسخّن الجزء العلوي من الأنبوب بلهب بنزن. نلاحظ غليان الماء في الأعلى بينما يبقى الثلج في القاع دون أن ينصهر."},{"type":"essay","q":"اشرح ماذا يحدث في تجربة صندوق الدخان ذي المدخنتين عند إشعال شمعة أسفل إحدى المدخنتين.","model":"يسخن الهواء فوق الشمعة فيتمدد وتقل كثافته ويصعد خارجًا من المدخنة الأولى، فينسحب الهواء البارد ومعه الدخان للأسفل عبر المدخنة الثانية ليحل محله، مشكلًا تيار حمل حراري واضح."},{"type":"essay","q":"علّل: تُطلى أنابيب التبريد الموجودة خلف الثلاجة باللون الأسود المعتم.","model":"لأن الأسود المعتم أفضل باعث للإشعاع الحراري، فيساعد على التخلّص السريع من الحرارة المسحوبة من داخل الثلاجة إلى هواء الغرفة."},{"type":"essay","q":"لماذا تُصنع قواعد أواني الطبخ الفاخرة أحيانًا من النحاس أو الألمنيوم وتُصنع مقابضها من البلاستيك؟","model":"القاعدة من فلز موصل جيد لتنقل الحرارة بسرعة وانتظام من الموقد إلى الطعام، والمقبض من بلاستيك عازل لحماية اليد من الحرارة."},{"type":"essay","q":"لماذا لا تنتقل الحرارة من الشمس إلى الأرض بالحمل الحراري؟","model":"لأن الفضاء بين الشمس والأرض فراغ لا يحتوي على أي سائل أو غاز لتتشكّل فيه تيارات حمل."}]},
  {"id":"g9-phy-1-u10","grade":"g9","subject":"physics","term":1,"title":"الوحدة العاشرة: التطبيقات والآثار المترتّبة على نقل الطاقة الحرارية","levels":{"easy":[{"type":"mcq","q":"الجزء الذي يمنع انتقال الحرارة بالتوصيل والحمل معًا في الترمس هو:","options":["اللون الأسود","الطلاء الفضي اللامع","المقبض الخارجي","طبقة الفراغ بين الجدارين"],"answer":3,"why":"الفراغ لا يحتوي جسيمات فيمنع التوصيل والحمل تمامًا."},{"type":"mcq","q":"يُعد «الفراغ» عازلًا مثاليًا ضد كل من:","options":["الإشعاع فقط","الجاذبية","الضوء فقط","التوصيل والحمل الحراري"],"answer":3,"why":"لعدم وجود أي جسيمات في الفراغ، ينعدم التوصيل والحمل الحراري تمامًا."},{"type":"mcq","q":"الجزء الذي يقلل فقدان الحرارة بـ«الإشعاع» في الترمس هو:","options":["السطح الفضي اللامع","الماء بداخل الترمس","الفراغ","السدادة الفلينية"],"answer":0,"why":"السطح الفضي اللامع يعكس الأشعة تحت الحمراء للداخل."},{"type":"mcq","q":"السبب الرئيس في وضع أكياس الثلج «أعلى» صندوق حفظ الأطعمة المبرّدة هو:","options":["ليهبط الهواء البارد الأكثر كثافةً ويبرد الطعام في الأسفل بالحمل","لمنع الإشعاع","لزيادة التوصيل عبر الغطاء","ليصعد الهواء البارد للأعلى"],"answer":0,"why":"تيار الحمل الهابط للهواء البارد يبرد محتويات الصندوق بفاعلية."}],"medium":[{"type":"mcq","q":"يمكن للترمس أن يحفظ مشروبًا مثلّجًا باردًا لساعات طويلة لأنه:","options":["يُنتج برودة داخلية بالكهرباء","يزيد امتصاص الأشعة تحت الحمراء","يسمح بمرور الهواء البارد","يمنع دخول الحرارة من الخارج بالتوصيل والحمل والإشعاع"],"answer":3,"why":"منع انتقال الحرارة يعمل في الاتجاهين: يمنع خروجها من الساخن ودخولها للبارد."},{"type":"mcq","q":"يُعد «الفراغ» عازلًا مثاليًا ضد كل من:","options":["الإشعاع فقط","الجاذبية","الضوء فقط","التوصيل والحمل الحراري"],"answer":3,"why":"لعدم وجود أي جسيمات في الفراغ، ينعدم التوصيل والحمل الحراري تمامًا."},{"type":"mcq","q":"أي تصميمٍ لمشتّت حراري (Heat Sink) داخل الحاسوب يبرّد المعالج بأفضل كفاءة؟","options":["مصنوع من الألمنيوم وبه زعانف كثيرة ومطلي بالأسود المعتم","مصنوع من الخشب ومغلف بالصوف","مصنوع من البلاستيك وأملس وأبيض","مصنوع من الزجاج ومفرّغ من الهواء"],"answer":0,"why":"الألمنيوم موصل ممتاز، والزعانف تزيد مساحة السطح، والأسود المعتم يسرّع الإشعاع."},{"type":"tfr","q":"رغم وجود الفراغ في الترمس، يفقد الشاي الساخن حرارته ببطء شديد عبر ساعات طويلة.","answer":true,"reasons":["لأن بعض الحرارة يتسرّب تدريجيًا بالتوصيل عبر السدادة وعنق الزجاج وبقدر ضئيل بالإشعاع","لأن الفراغ يختفي بعد ساعة","لأن الحرارة تفنى تلقائيًا"],"reason":0},{"type":"tfr","q":"تقلّل النوافذ ذات الزجاج المزدوج من فقدان أو اكتساب الحرارة بالتوصيل والحمل معًا.","answer":true,"reasons":["لأن الهواء يوصل الحرارة بسرعة","لأن الزجاج فلز","لأن الطبقة الرقيقة من الهواء المحبوس بين اللوحين عازل رديء التوصيل ولا تتحرك بحرية للحمل"],"reason":2}],"hard":[{"type":"mcq","q":"عند وضع ورقة فضية لامعة خلف مدفأة الجدار في منزل ببلد بارد، فإن الهدف هو:","options":["منع الحمل الحراري في الغرفة","زيادة التوصيل عبر الجدار للخارج","عكس الإشعاع الحراري المتجه نحو الجدار وإعادته إلى داخل الغرفة","امتصاص الحرارة داخل الجدار"],"answer":2,"why":"الرقاقة اللامعة تقلل ضياع الحرارة بالإشعاع نحو الجدار الخارجي."},{"type":"mcq","q":"يُعد «الفراغ» عازلًا مثاليًا ضد كل من:","options":["الإشعاع فقط","الجاذبية","الضوء فقط","التوصيل والحمل الحراري"],"answer":3,"why":"لعدم وجود أي جسيمات في الفراغ، ينعدم التوصيل والحمل الحراري تمامًا."},{"type":"mcq","q":"في الصحراء، لماذا تنام بعض الحيوانات داخل جحور عميقة تحت الرمال خلال النهار الحار؟","options":["لأن الإشعاع يخترق الأرض","لأن الرمل موصل ممتاز للبرودة","لأن تيارات الحمل تهبط تحت الرمل","لأن الرمل عازل حراري رديء التوصيل فيبقى الجحر في الأسفل باردًا ومعتدلًا"],"answer":3,"why":"الرمل المحبوس بينه هواء موصل رديء، فلا تصل حرارة السطح الشديدة إلى عمق الجحر."},{"type":"essay","q":"قارن بين تصميم «الترمس» وتصميم «مشعاع السيارة» من حيث الهدف وطريقة التعامل مع التوصيل والحمل والإشعاع.","model":"هدف الترمس «منع» انتقال الحرارة: يستخدم الفراغ (لا توصيل ولا حمل) والفضي اللامع (لا إشعاع) وسدادة عازلة. أما مشعاع السيارة فهدفه «تسريع» فقدان الحرارة: يستخدم فلزًا موصلًا (توصيل) ومروحة وهواء متحركًا (حمل) ولونًا أسود معتمًا وزعانف واسعة (إشعاع وحمل)."},{"type":"essay","q":"اشرح كيف تتحقّق ظاهرة «الاحتباس الحراري» الطبيعية ولماذا يؤدي تزايدها عن الحد الطبيعي إلى تغيّر المناخ.","model":"يمر إشعاع الشمس للغلاف الجوي ويدفئ الأرض، فتُشع الأرض أشعة تحت حمراء يمتص جزءًا منها غازات الدفيئة (مثل CO₂ وبخار الماء) فتحفظ دفء الأرض. لكن حرق الوقود الأحفوري يزيد هذه الغازات بشدة، فيحتبس مزيد من الحرارة مما يرفع حرارة الكوكب ويذيب الجليد ويغير أنماط الطقس."}]},"test":[{"type":"mcq","q":"الجزء الذي يمنع انتقال الحرارة بالتوصيل والحمل معًا في الترمس هو:","options":["اللون الأسود","الطلاء الفضي اللامع","المقبض الخارجي","طبقة الفراغ بين الجدارين"],"answer":3,"why":"الفراغ لا يحتوي جسيمات فيمنع التوصيل والحمل تمامًا."},{"type":"mcq","q":"يُعد «الفراغ» عازلًا مثاليًا ضد كل من:","options":["الإشعاع فقط","الجاذبية","الضوء فقط","التوصيل والحمل الحراري"],"answer":3,"why":"لعدم وجود أي جسيمات في الفراغ، ينعدم التوصيل والحمل الحراري تمامًا."},{"type":"mcq","q":"الجزء الذي يقلل فقدان الحرارة بـ«الإشعاع» في الترمس هو:","options":["السطح الفضي اللامع","الماء بداخل الترمس","الفراغ","السدادة الفلينية"],"answer":0,"why":"السطح الفضي اللامع يعكس الأشعة تحت الحمراء للداخل."},{"type":"mcq","q":"السبب الرئيس في وضع أكياس الثلج «أعلى» صندوق حفظ الأطعمة المبرّدة هو:","options":["ليهبط الهواء البارد الأكثر كثافةً ويبرد الطعام في الأسفل بالحمل","لمنع الإشعاع","لزيادة التوصيل عبر الغطاء","ليصعد الهواء البارد للأعلى"],"answer":0,"why":"تيار الحمل الهابط للهواء البارد يبرد محتويات الصندوق بفاعلية."},{"type":"mcq","q":"لماذا تُصنع السدادة العلوية للترمس من البلاستيك أو الفلين؟","options":["لأنها موصل ممتاز","لأنها عازلة تقلل التوصيل وتمنع تيارات الحمل والتبخر","لأنها ثقيلة جدًّا","لأنها تسمح بخروج البخار"],"answer":1,"why":"السدادة تغلق الفوهة فتوقف الحمل والتبخر، وتقلل التوصيل لكونها عازلة."},{"type":"mcq","q":"أي مادة مما يلي تناسب حشو التجويف بين جدارين مزدوجين في مبنى سكني لعزله حراريًا؟","options":["ألواح الألمنيوم المصمتة","الصوف الصخري أو الفوم المسامي","شرائح الحديد","قضبان النحاس"],"answer":1,"why":"الصوف الصخري والفوم يحبسان الهواء الساكن فيقللان التوصيل والحمل."},{"type":"mcq","q":"في البيوت المحمية الزراعية، يمنع السقف والجدران الزجاجية فقدان الحرارة أساسًا عن طريق:","options":["تحويل الزجاج إلى فراغ","منع دخول ضوء الشمس","منع هروب الهواء الدافئ بتيارات الحمل","زيادة التوصيل"],"answer":2,"why":"إغلاق البيت المحمي يمنع اختلاط الهواء الدافئ بالخارج فيحفظ الدفء."},{"type":"mcq","q":"يمكن للترمس أن يحفظ مشروبًا مثلّجًا باردًا لساعات طويلة لأنه:","options":["يُنتج برودة داخلية بالكهرباء","يزيد امتصاص الأشعة تحت الحمراء","يسمح بمرور الهواء البارد","يمنع دخول الحرارة من الخارج بالتوصيل والحمل والإشعاع"],"answer":3,"why":"منع انتقال الحرارة يعمل في الاتجاهين: يمنع خروجها من الساخن ودخولها للبارد."},{"type":"mcq","q":"أي تصميمٍ لمشتّت حراري (Heat Sink) داخل الحاسوب يبرّد المعالج بأفضل كفاءة؟","options":["مصنوع من الألمنيوم وبه زعانف كثيرة ومطلي بالأسود المعتم","مصنوع من الخشب ومغلف بالصوف","مصنوع من البلاستيك وأملس وأبيض","مصنوع من الزجاج ومفرّغ من الهواء"],"answer":0,"why":"الألمنيوم موصل ممتاز، والزعانف تزيد مساحة السطح، والأسود المعتم يسرّع الإشعاع."},{"type":"mcq","q":"لماذا يُنصح بإغلاق الستائر الفاتحة على النوافذ في ظهيرة الصيف الحار؟","options":["لزيادة امتصاص الحرارة","لعكس إشعاع الشمس وتقليل الحمل الحراري قرب الزجاج الساخن","لزيادة التوصيل","لتوليد طاقة كهربائية"],"answer":1,"why":"الستائر الفاتحة تعكس الإشعاع وتحبس طبقة هواء عازلة قرب النافذة."},{"type":"mcq","q":"عند وضع ورقة فضية لامعة خلف مدفأة الجدار في منزل ببلد بارد، فإن الهدف هو:","options":["منع الحمل الحراري في الغرفة","زيادة التوصيل عبر الجدار للخارج","عكس الإشعاع الحراري المتجه نحو الجدار وإعادته إلى داخل الغرفة","امتصاص الحرارة داخل الجدار"],"answer":2,"why":"الرقاقة اللامعة تقلل ضياع الحرارة بالإشعاع نحو الجدار الخارجي."},{"type":"mcq","q":"في الصحراء، لماذا تنام بعض الحيوانات داخل جحور عميقة تحت الرمال خلال النهار الحار؟","options":["لأن الإشعاع يخترق الأرض","لأن الرمل موصل ممتاز للبرودة","لأن تيارات الحمل تهبط تحت الرمل","لأن الرمل عازل حراري رديء التوصيل فيبقى الجحر في الأسفل باردًا ومعتدلًا"],"answer":3,"why":"الرمل المحبوس بينه هواء موصل رديء، فلا تصل حرارة السطح الشديدة إلى عمق الجحر."},{"type":"tf","q":"رغم وجود الفراغ في الترمس، يفقد الشاي الساخن حرارته ببطء شديد عبر ساعات طويلة.","answer":true,"why":"لأن بعض الحرارة يتسرّب تدريجيًا بالتوصيل عبر السدادة وعنق الزجاج وبقدر ضئيل بالإشعاع"},{"type":"tf","q":"تقلّل النوافذ ذات الزجاج المزدوج من فقدان أو اكتساب الحرارة بالتوصيل والحمل معًا.","answer":true,"why":"لأن الطبقة الرقيقة من الهواء المحبوس بين اللوحين عازل رديء التوصيل ولا تتحرك بحرية للحمل"},{"type":"tf","q":"طلاء سقف المنزل باللون الأسود الداكن يقلّل من استهلاك المكيّف في الصيف.","answer":false,"why":"بل يزيد امتصاص حرارة الشمس فيرفع حرارة المنزل ويزيد استهلاك المكيّف؛ الأفضل اللون الأبيض"},{"type":"tf","q":"تُساعد المروحة الموجودة خلف مشعاع السيارة على زيادة سرعة التبريد بـ«الحمل الحراري القسري».","answer":true,"why":"لأن المروحة تدفع هواءً باردًا باستمرار فوق الزعانف الساخنة فتُبعد الهواء الساخن بسرعة"},{"type":"tfr","q":"تسهم تيارات الحمل الحراري في المحيطات (التيارات البحرية) في توزيع الحرارة حول الكوكب.","answer":true,"reasons":["لأن المحيطات لا تتأثر بالشمس","لأن الماء موصل ممتاز بالتوصيل","لأن المياه الدافئة الاستوائية تتحرك نحو المناطق الأبرد والمياه الباردة تتحرك نحو الاستواء"],"reason":2},{"type":"tfr","q":"تُصنع مقابض أواني الطبخ من الفلزات لكي تنقل الحرارة إلى يد الطاهي بسرعة.","answer":false,"reasons":["لأن الفلزات عازلة للحرارة","بل تُصنع من البلاستيك أو الخشب العازل لحماية اليد من انتقال الحرارة بالتوصيل","لأن المقابض لا تلمس القدر"],"reason":1},{"type":"tfr","q":"دعامات الفلين أو البلاستيك التي تثبّت القارورة الزجاجية داخل الغلاف الخارجي للترمس هدفها زيادة التوصيل.","answer":false,"reasons":["هدفها تثبيت القارورة مع تقليل التوصيل الحراري للغلاف الخارجي إلى أدنى حد","هدفها منع الإشعاع","هدفها السماح بدخول الهواء"],"reason":0},{"type":"tfr","q":"تعتمد البيوت التراثية العمانية ذات الجدران الطينية السميكة على ضعف توصيل الطين لإبقاء الداخل باردًا نهارًا.","answer":true,"reasons":["لأن الطين يولد تيارات تبريد كهربائية","لأن الجدران السميكة العازلة تبطئ جدًّا انتقال حرارة النهار الشديدة إلى داخل الغرفة","لأن الطين فلز موصل"],"reason":1},{"type":"essay","q":"اربط كل ميزة في عزل المنازل الحديثة بطريقة انتقال الحرارة التي تقلّلها: (١) حشو الجدران بالفوم، (٢) طلاء السطح بالأبيض، (٣) إغلاق شقوق الأبواب.","model":"١) الفوم يقلّل التوصيل والحمل (يحبس الهواء الساكن). ٢) الطلاء الأبيض يقلّل الإشعاع (يعكس أشعة الشمس). ٣) إغلاق الشقوق يمنع الحمل الحراري (تيارات الهواء الساخن الداخلة)."},{"type":"essay","q":"فسّر لماذا يسخن مشروب ساخن أو يبرد بسرعة أكبر بكثير إذا تركت غطاء الترمس مفتوحًا.","model":"لأن فتح الغطاء يسمح بصعود الهواء الساخن والبخار (تيارات الحمل الحراري والتبخر) فتفقد القهوة حرارتها بسرعة كبيرة."},{"type":"essay","q":"قارن بين تصميم «الترمس» وتصميم «مشعاع السيارة» من حيث الهدف وطريقة التعامل مع التوصيل والحمل والإشعاع.","model":"هدف الترمس «منع» انتقال الحرارة: يستخدم الفراغ (لا توصيل ولا حمل) والفضي اللامع (لا إشعاع) وسدادة عازلة. أما مشعاع السيارة فهدفه «تسريع» فقدان الحرارة: يستخدم فلزًا موصلًا (توصيل) ومروحة وهواء متحركًا (حمل) ولونًا أسود معتمًا وزعانف واسعة (إشعاع وحمل)."},{"type":"essay","q":"اشرح كيف تتحقّق ظاهرة «الاحتباس الحراري» الطبيعية ولماذا يؤدي تزايدها عن الحد الطبيعي إلى تغيّر المناخ.","model":"يمر إشعاع الشمس للغلاف الجوي ويدفئ الأرض، فتُشع الأرض أشعة تحت حمراء يمتص جزءًا منها غازات الدفيئة (مثل CO₂ وبخار الماء) فتحفظ دفء الأرض. لكن حرق الوقود الأحفوري يزيد هذه الغازات بشدة، فيحتبس مزيد من الحرارة مما يرفع حرارة الكوكب ويذيب الجليد ويغير أنماط الطقس."},{"type":"essay","q":"صمّم صندوقًا محمولًا لحفظ الأدوية باردةً أثناء نقلها في يوم حار بعُمان، موضحًا المواد المختارة والسبب الفيزيائي لكل مادة.","model":"جدران سميكة من الفوم العازل (تحبس الهواء الساكن لتقليل التوصيل والحمل)، وغلاف خارجي أبيض أو فضي لامع (يعكس إشعاع الشمس)، وغطاء محكم الإغلاق مع بطانة مطاطية (يمنع دخول الهواء الساخن بالحمل الحراري)، مع أكياس ثلج في الأعلى (ليهبط الهواء البارد ويبرد الأدوية بالحمل)."}]},
  {"id":"g9-phy-2-u11","grade":"g9","subject":"physics","term":2,"title":"الوحدة الحادية عشرة: مصادر الطاقة","levels":{"easy":[{"type":"mcq","q":"أي المصادر الآتية يُعد مصدرًا «غير متجدد» للطاقة؟","options":["الطاقة الحرارية الأرضية","طاقة الرياح","الطاقة الشمسية","الغاز الطبيعي واليورانيوم"],"answer":3,"why":"الغاز الطبيعي وقود أحفوري واليورانيوم خام محدود كلاهما غير متجدد."},{"type":"mcq","q":"ما المصدر الذي يحوّل الضوء مباشرةً إلى كهرباء دون توربين؟","options":["الخلايا الشمسية الكهروضوئية","محطة الفحم","محطة الرياح","المحطة النووية"],"answer":0,"why":"الخلايا الشمسية تنتج تيارًا كهربائيًا مباشرةً من الضوء."},{"type":"mcq","q":"ما الميزة الكبرى لطاقة المدّ والجزر مقارنةً بطاقة الرياح؟","options":["لا تحتاج ماءً","مواعيدها متوقّعة بدقة يوميًا","غير متجددة","تنتج CO₂"],"answer":1,"why":"حركة المد والجزر مرتبطة بحركة القمر المنتظمة فيسهل التنبؤ بها."},{"type":"mcq","q":"ما العيب البيئي الأبرز لمحطات الطاقة النووية؟","options":["اعتمادها على الرياح","انبعاث كميات ضخمة من CO₂","النفايات المشعة الخطيرة التي تحتاج تخزينًا آمنًا لآلاف السنين","عدم قدرتها على العمل ليلًا"],"answer":2,"why":"النووي لا يطلق CO₂ لكنه يخلّف نفايات مشعة خطيرة."}],"medium":[{"type":"mcq","q":"ما وظيفة المولّد الكهربائي في محطة الطاقة؟","options":["امتصاص CO₂","حرق الوقود","تخزين الماء","تحويل الطاقة الحركية الدورانية إلى طاقة كهربائية"],"answer":3,"why":"التوربين يدير المولد فينتج الكهرباء."},{"type":"mcq","q":"أي مصدر متجدد يعمل باستمرار ليلًا ونهارًا دون التأثر بالطقس؟","options":["الطاقة الحرارية الأرضية","الخلايا الشمسية","طاقة الرياح","الأمواج"],"answer":0,"why":"حرارة باطن الأرض مستمرة دائمًا في المناطق الجيولوجية المناسبة."},{"type":"mcq","q":"لماذا تُعد الطاقة الشمسية والرياح مكمّلتين لبعضهما؟","options":["لأنهما غير متجددتين","لأن الشمس متوفرة نهارًا بينما قد تهب الرياح ليلًا ونهارًا","لأنهما تنتجان دخانًا","لأنهما لا تحتاجان مساحة"],"answer":1,"why":"الجمع بينهما يقلل أثر التقطع."},{"type":"tfr","q":"بناء السدود الكهرومائية الكبيرة قد يغمر مساحات زراعية ويغيّر مواطن الكائنات الحية.","answer":true,"reasons":["لا أثر لها مطلقًا","تنتج نفايات مشعة","فرغم أنها متجددة ونظيفة إلا أن لها أثرًا بيئيًا محليًا عند البناء"],"reason":2},{"type":"tfr","q":"تُعد الطاقة النووية والحرارية الأرضية والمدّ والجزر المصادر الثلاثة التي لا ترجع للشمس.","answer":true,"reasons":["فالنووية من اليورانيوم والأرضية من باطن الأرض والمد والجزر من جاذبية القمر","كل الطاقات ترجع للشمس بلا استثناء","الرياح ليست من الشمس"],"reason":0}],"hard":[{"type":"mcq","q":"في المحطة الكهرومائية (السدود)، ما تحوّل الطاقة الأساسي؟","options":["كيميائية ← حرارية","نووية ← ضوئية","وضع جاذبية ← حركية ← كهربائية","مرونية ← صوتية"],"answer":2,"why":"الماء المرتفع يختزن طاقة وضع تتحول لحركة تدير التوربين."},{"type":"mcq","q":"من عيوب التوسّع الكبير في زراعة محاصيل الوقود الحيوي:","options":["توقف المطر","انعدام الأكسجين","إنتاج نفايات نووية","منافسة الأراضي الزراعية المخصّصة للغذاء"],"answer":3,"why":"تخصيص أراضٍ للوقود قد يقلل المساحة المتاحة للغذاء."},{"type":"mcq","q":"لماذا يُعد الغاز الطبيعي أنظف نسبيًا من الفحم الحجري؟","options":["لأنه يطلق كمية أقل من CO₂ والملوثات لكل وحدة طاقة","لأنه متجدد","لأنه لا يحترق","لأنه لا يحتوي كربون"],"answer":0,"why":"الغاز أقل انبعاثًا للكربون والكبريت من الفحم لكنه يظل غير متجدد."},{"type":"essay","q":"قارن بين المصادر المتجددة وغير المتجددة مع مثالين لكل منهما.","model":"المتجددة تتجدد طبيعيًا ولا تنفد وأقل تلوثًا (الشمس، الرياح). غير المتجددة محدودة وتنفد (النفط، الغاز، اليورانيوم)."},{"type":"essay","q":"اشرح سلسلة تحوّل الطاقة في محطة كهرباء تعمل بالغاز الطبيعي.","model":"طاقة كيميائية في الغاز ← حرارية تغلي الماء ← حركية في البخار والتوربين ← كهربائية في المولّد."}]},"test":[{"type":"mcq","q":"أي المصادر الآتية يُعد مصدرًا «غير متجدد» للطاقة؟","options":["الطاقة الحرارية الأرضية","طاقة الرياح","الطاقة الشمسية","الغاز الطبيعي واليورانيوم"],"answer":3,"why":"الغاز الطبيعي وقود أحفوري واليورانيوم خام محدود كلاهما غير متجدد."},{"type":"mcq","q":"ما المصدر الذي يحوّل الضوء مباشرةً إلى كهرباء دون توربين؟","options":["الخلايا الشمسية الكهروضوئية","محطة الفحم","محطة الرياح","المحطة النووية"],"answer":0,"why":"الخلايا الشمسية تنتج تيارًا كهربائيًا مباشرةً من الضوء."},{"type":"mcq","q":"ما الميزة الكبرى لطاقة المدّ والجزر مقارنةً بطاقة الرياح؟","options":["لا تحتاج ماءً","مواعيدها متوقّعة بدقة يوميًا","غير متجددة","تنتج CO₂"],"answer":1,"why":"حركة المد والجزر مرتبطة بحركة القمر المنتظمة فيسهل التنبؤ بها."},{"type":"mcq","q":"ما العيب البيئي الأبرز لمحطات الطاقة النووية؟","options":["اعتمادها على الرياح","انبعاث كميات ضخمة من CO₂","النفايات المشعة الخطيرة التي تحتاج تخزينًا آمنًا لآلاف السنين","عدم قدرتها على العمل ليلًا"],"answer":2,"why":"النووي لا يطلق CO₂ لكنه يخلّف نفايات مشعة خطيرة."},{"type":"mcq","q":"ما وظيفة المولّد الكهربائي في محطة الطاقة؟","options":["امتصاص CO₂","حرق الوقود","تخزين الماء","تحويل الطاقة الحركية الدورانية إلى طاقة كهربائية"],"answer":3,"why":"التوربين يدير المولد فينتج الكهرباء."},{"type":"mcq","q":"أي مصدر متجدد يعمل باستمرار ليلًا ونهارًا دون التأثر بالطقس؟","options":["الطاقة الحرارية الأرضية","الخلايا الشمسية","طاقة الرياح","الأمواج"],"answer":0,"why":"حرارة باطن الأرض مستمرة دائمًا في المناطق الجيولوجية المناسبة."},{"type":"mcq","q":"لماذا تُعد الطاقة الشمسية والرياح مكمّلتين لبعضهما؟","options":["لأنهما غير متجددتين","لأن الشمس متوفرة نهارًا بينما قد تهب الرياح ليلًا ونهارًا","لأنهما تنتجان دخانًا","لأنهما لا تحتاجان مساحة"],"answer":1,"why":"الجمع بينهما يقلل أثر التقطع."},{"type":"mcq","q":"في المحطة الكهرومائية (السدود)، ما تحوّل الطاقة الأساسي؟","options":["كيميائية ← حرارية","نووية ← ضوئية","وضع جاذبية ← حركية ← كهربائية","مرونية ← صوتية"],"answer":2,"why":"الماء المرتفع يختزن طاقة وضع تتحول لحركة تدير التوربين."},{"type":"mcq","q":"من عيوب التوسّع الكبير في زراعة محاصيل الوقود الحيوي:","options":["توقف المطر","انعدام الأكسجين","إنتاج نفايات نووية","منافسة الأراضي الزراعية المخصّصة للغذاء"],"answer":3,"why":"تخصيص أراضٍ للوقود قد يقلل المساحة المتاحة للغذاء."},{"type":"mcq","q":"لماذا يُعد الغاز الطبيعي أنظف نسبيًا من الفحم الحجري؟","options":["لأنه يطلق كمية أقل من CO₂ والملوثات لكل وحدة طاقة","لأنه متجدد","لأنه لا يحترق","لأنه لا يحتوي كربون"],"answer":0,"why":"الغاز أقل انبعاثًا للكربون والكبريت من الفحم لكنه يظل غير متجدد."},{"type":"mcq","q":"يُسمّى الاعتماد على عدة مصادر طاقة مختلفة لضمان استمرار الكهرباء:","options":["الاحتكار","مزيج الطاقة المستدام","التوصيل الحراري","التسارع"],"answer":1,"why":"التنويع يضمن أمن الطاقة وتقليل التلوث."},{"type":"mcq","q":"ما التفاعل الذي يُنتج الطاقة الهائلة في قلب الشمس؟","options":["الانشطار النووي لليورانيوم","احتراق الفحم","الاندماج النووي (دمج أنوية الهيدروجين لتكوين الهيليوم)","الاحتكاك"],"answer":2,"why":"تندمج أنوية الهيدروجين في الشمس لتكوين الهيليوم مطلقةً طاقة هائلة."},{"type":"tf","q":"تُعد الطاقة النووية مصدرًا متجددًا لأنها لا تُطلق غاز CO₂.","answer":false,"why":"هي غير متجددة لأن خام اليورانيوم محدود في الأرض وينفد"},{"type":"tf","q":"تحتاج معظم محطات توليد الكهرباء إلى توربين ومولّد كهربائي.","answer":true,"why":"لتتحول حركة التوربين الدورانية إلى طاقة كهربائية، باستثناء الخلايا الشمسية"},{"type":"tf","q":"محطة ظفار لطاقة الرياح ومحطة عبري للطاقة الشمسية مثالان على الطاقة المتجددة في عُمان.","answer":true,"why":"فهما تستغلان الرياح والشمس لتوليد كهرباء نظيفة ومستدامة"},{"type":"tf","q":"تعمل الخلايا الشمسية بكامل طاقتها في منتصف الليل دون بطاريات.","answer":false,"why":"الخلايا الشمسية تحتاج لضوء الشمس، وتلزم بطاريات تخزين لتشغيل الأجهزة ليلًا"},{"type":"tfr","q":"بناء السدود الكهرومائية الكبيرة قد يغمر مساحات زراعية ويغيّر مواطن الكائنات الحية.","answer":true,"reasons":["لا أثر لها مطلقًا","تنتج نفايات مشعة","فرغم أنها متجددة ونظيفة إلا أن لها أثرًا بيئيًا محليًا عند البناء"],"reason":2},{"type":"tfr","q":"تُعد الطاقة النووية والحرارية الأرضية والمدّ والجزر المصادر الثلاثة التي لا ترجع للشمس.","answer":true,"reasons":["فالنووية من اليورانيوم والأرضية من باطن الأرض والمد والجزر من جاذبية القمر","كل الطاقات ترجع للشمس بلا استثناء","الرياح ليست من الشمس"],"reason":0},{"type":"tfr","q":"تُنتج الشمس طاقتها عبر احتراق غاز الأكسجين والفحم في باطنها.","answer":false,"reasons":["بالتوصيل الحراري","تُنتج طاقتها بالاندماج النووي للهيدروجين إلى هيليوم، وليس احتراقًا كيميائيًا","نعم بالاحتراق العادي"],"reason":1},{"type":"tfr","q":"تعتمد طاقة الرياح على تسخين الشمس غير المتساوي لسطح الأرض.","answer":true,"reasons":["لا علاقة للشمس بالرياح","تنشأ الرياح من القمر","فيسخن الهواء في مناطق ويصعد ويندفع الهواء البارد مكانه فتنشأ الرياح"],"reason":2},{"type":"essay","q":"قارن بين المصادر المتجددة وغير المتجددة مع مثالين لكل منهما.","model":"المتجددة تتجدد طبيعيًا ولا تنفد وأقل تلوثًا (الشمس، الرياح). غير المتجددة محدودة وتنفد (النفط، الغاز، اليورانيوم)."},{"type":"essay","q":"اشرح سلسلة تحوّل الطاقة في محطة كهرباء تعمل بالغاز الطبيعي.","model":"طاقة كيميائية في الغاز ← حرارية تغلي الماء ← حركية في البخار والتوربين ← كهربائية في المولّد."},{"type":"essay","q":"اذكر ميزتين وعيبين للطاقة الشمسية في سلطنة عُمان.","model":"المزايا: متجددة ونظيفة وسطوع الشمس قوي في عُمان. العيوب: لا تعمل ليلًا وتحتاج مساحة وأنظمة تخزين وتنظيف من الغبار."},{"type":"essay","q":"علّل: لماذا تتجه الدول إلى «مزيج طاقة» بدل الاعتماد على مصدر واحد فقط؟","model":"لأن المصادر النظيفة كالشمس والرياح متقطّعة، فالتنويع مع التخزين يضمن استقرار الشبكة ٢٤ ساعة مع تقليل التلوث."},{"type":"essay","q":"ما الفرق بين المحطة النووية ومحطة الوقود الأحفوري من حيث الأثر البيئي؟","model":"الوقود الأحفوري يطلق CO₂ و SO₂ (احتباس حراري ومطر حمضي)، بينما النووي لا يطلق غازات دفيئة لكنه ينتج نفايات إشعاعية خطيرة طويلة الأمد."}]},
  {"id":"g9-phy-2-u12","grade":"g9","subject":"physics","term":2,"title":"الوحدة الثانية عشرة: انعكاس الضوء","levels":{"easy":[{"type":"mcq","q":"ما الزاوية التي نُقيس منها زاوية السقوط وزاوية الانعكاس؟","options":["العمود المقام على السطح العاكس","سطح المرآة","الأفق","اتجاه الجاذبية"],"answer":0,"why":"تُقاس الزاويتان دائمًا بالنسبة للعمود المقام."},{"type":"mcq","q":"إذا كانت زاوية السقوط 35°، فكم تساوي زاوية الانعكاس؟","options":["90°","35°","70°","55°"],"answer":1,"why":"وفق قانون الانعكاس: i = r = 35°."},{"type":"mcq","q":"وقف شخص على بُعد 1.5 m أمام مرآة مستوية. كم المسافة بينه وبين صورته؟","options":["0.75 m","1.5 m","3 m","4.5 m"],"answer":2,"why":"بُعد الصورة خلف المرآة 1.5 m، إذن المسافة بينهما 1.5 + 1.5 = 3 m."},{"type":"mcq","q":"لماذا تُكتب كلمة «إسعاف» معكوسةً على مقدّمة سيارة الإسعاف؟","options":["للزينة فقط","لتكبير الكلمة","لأن المرآة تقلبها رأسيًا","لأن المرآة المستوية تعكس الصورة جانبيًا فيقرأها السائق أمامها صحيحةً"],"answer":3,"why":"الانعكاس الجانبي يقلب اليمين يسارًا فيعيد الكلمة المعكوسة صحيحةً."}],"medium":[{"type":"mcq","q":"إذا صنع شعاع ساقط زاوية 25° مع سطح المرآة، فكم تساوي زاوية الانعكاس؟","options":["65°","25°","50°","90°"],"answer":0,"why":"i = 90° − 25° = 65°، إذن r = 65°."},{"type":"mcq","q":"إذا سقط شعاع ضوئي عموديًا على مرآة مستوية (i = 0°)، فإنه:","options":["يختفي","يرتدّ على نفسه (r = 0°)","ينفذ عبر المرآة","ينعكس بزاوية 90°"],"answer":1,"why":"عندما i = 0° تكون r = 0° فيرتد الشعاع على نفسه."},{"type":"mcq","q":"الانعكاس على سطح ورقة بيضاء خشنة يُعد:","options":["انكسارًا","انعكاسًا منتظمًا","انعكاسًا غير منتظم (مشتّتًا)","تداخلًا"],"answer":2,"why":"الأسطح الخشنة تشتت الأشعة في اتجاهات متعددة."},{"type":"tfr","q":"إذا نظرت لساعة حائط تشير إلى 3:00 في مرآة مستوية فستبدو كأنها تشير إلى 9:00.","answer":true,"reasons":["بسبب خاصية الانعكاس الجانبي في المرآة المستوية","تبقى 3:00","تصبح 6:00"],"reason":0},{"type":"tfr","q":"يُرى انعكاس الشمس بوضوح كصورة محددة على سطح ماء هادئ ساكن بسبب الانعكاس المنتظم.","answer":true,"reasons":["لأنه انعكاس مشتت","لأن السطح الأملس يعكس الأشعة المتوازية متوازيةً في اتجاه واحد","لأن الماء معتم"],"reason":1}],"hard":[{"type":"mcq","q":"تُسمّى الصورة في المرآة المستوية «تقديرية» لأنها:","options":["أكبر من الجسم","حقيقية أمام المرآة","مقلوبة رأسيًا","تتكوّن من تلاقي امتدادات الأشعة المنعكسة ولا يمكن استقبالها على حائل"],"answer":3,"why":"لا تتلاقى الأشعة الفعلية خلف المرآة بل امتداداتها فقط."},{"type":"mcq","q":"ما زاوية ميل كل مرآة في البيروسكوب البسيط؟","options":["45°","90°","0°","180°"],"answer":0,"why":"زاوية 45° تعكس الضوء بزاوية قائمة 90°."},{"type":"mcq","q":"إذا اقترب جسم مسافة 0.5 m نحو مرآة مستوية، فإن المسافة بين الجسم وصورته تقلّ بمقدار:","options":["2.0 m","1.0 m","0.25 m","0.5 m"],"answer":1,"why":"يقترب الجسم 0.5 m وتقترب الصورة 0.5 m فالمجموع 1.0 m."},{"type":"essay","q":"اذكر الصفات الخمس للصورة المتكوّنة في المرآة المستوية.","model":"١) تقديرية. ٢) معتدلة. ٣) مساوية للجسم. ٤) معكوسة جانبيًا. ٥) بُعدها خلف المرآة يساوي بُعد الجسم أمامها."},{"type":"essay","q":"سقط شعاع ضوئي بزاوية 35° مع سطح المرآة. احسب: (أ) زاوية السقوط، (ب) زاوية الانعكاس، (ج) الزاوية بين الشعاع الساقط والمنعكس.","model":"أ) i = 90 − 35 = 55°. ب) r = 55°. ج) 55 + 55 = 110°."}]},"test":[{"type":"mcq","q":"ما الزاوية التي نُقيس منها زاوية السقوط وزاوية الانعكاس؟","options":["العمود المقام على السطح العاكس","سطح المرآة","الأفق","اتجاه الجاذبية"],"answer":0,"why":"تُقاس الزاويتان دائمًا بالنسبة للعمود المقام."},{"type":"mcq","q":"إذا كانت زاوية السقوط 35°، فكم تساوي زاوية الانعكاس؟","options":["90°","35°","70°","55°"],"answer":1,"why":"وفق قانون الانعكاس: i = r = 35°."},{"type":"mcq","q":"وقف شخص على بُعد 1.5 m أمام مرآة مستوية. كم المسافة بينه وبين صورته؟","options":["0.75 m","1.5 m","3 m","4.5 m"],"answer":2,"why":"بُعد الصورة خلف المرآة 1.5 m، إذن المسافة بينهما 1.5 + 1.5 = 3 m."},{"type":"mcq","q":"لماذا تُكتب كلمة «إسعاف» معكوسةً على مقدّمة سيارة الإسعاف؟","options":["للزينة فقط","لتكبير الكلمة","لأن المرآة تقلبها رأسيًا","لأن المرآة المستوية تعكس الصورة جانبيًا فيقرأها السائق أمامها صحيحةً"],"answer":3,"why":"الانعكاس الجانبي يقلب اليمين يسارًا فيعيد الكلمة المعكوسة صحيحةً."},{"type":"mcq","q":"إذا صنع شعاع ساقط زاوية 25° مع سطح المرآة، فكم تساوي زاوية الانعكاس؟","options":["65°","25°","50°","90°"],"answer":0,"why":"i = 90° − 25° = 65°، إذن r = 65°."},{"type":"mcq","q":"إذا سقط شعاع ضوئي عموديًا على مرآة مستوية (i = 0°)، فإنه:","options":["يختفي","يرتدّ على نفسه (r = 0°)","ينفذ عبر المرآة","ينعكس بزاوية 90°"],"answer":1,"why":"عندما i = 0° تكون r = 0° فيرتد الشعاع على نفسه."},{"type":"mcq","q":"الانعكاس على سطح ورقة بيضاء خشنة يُعد:","options":["انكسارًا","انعكاسًا منتظمًا","انعكاسًا غير منتظم (مشتّتًا)","تداخلًا"],"answer":2,"why":"الأسطح الخشنة تشتت الأشعة في اتجاهات متعددة."},{"type":"mcq","q":"تُسمّى الصورة في المرآة المستوية «تقديرية» لأنها:","options":["أكبر من الجسم","حقيقية أمام المرآة","مقلوبة رأسيًا","تتكوّن من تلاقي امتدادات الأشعة المنعكسة ولا يمكن استقبالها على حائل"],"answer":3,"why":"لا تتلاقى الأشعة الفعلية خلف المرآة بل امتداداتها فقط."},{"type":"mcq","q":"ما زاوية ميل كل مرآة في البيروسكوب البسيط؟","options":["45°","90°","0°","180°"],"answer":0,"why":"زاوية 45° تعكس الضوء بزاوية قائمة 90°."},{"type":"mcq","q":"إذا اقترب جسم مسافة 0.5 m نحو مرآة مستوية، فإن المسافة بين الجسم وصورته تقلّ بمقدار:","options":["2.0 m","1.0 m","0.25 m","0.5 m"],"answer":1,"why":"يقترب الجسم 0.5 m وتقترب الصورة 0.5 m فالمجموع 1.0 m."},{"type":"mcq","q":"الزاوية الكلية بين الشعاع الساقط والشعاع المنعكس إذا كانت i = 40° هي:","options":["50°","40°","80°","90°"],"answer":2,"why":"i + r = 40° + 40° = 80°."},{"type":"mcq","q":"إذا سقط شعاع ضوئي بزاوية ٣٥° مع السطح العاكس للمرآة المستوية، فما قيمة زاوية السقوط؟","options":["٩٠°","٣٥°","٧٠°","٥٥°"],"answer":3,"why":"العمود المقام يصنع ٩٠° مع السطح ← ٩٠° − ٣٥° = ٥٥°."},{"type":"tf","q":"الصورة المتكوّنة في المرآة المستوية تكون دائمًا مساويةً للجسم في الحجم ومعتدلةً.","answer":true,"why":"وهي أيضًا تقديرية ومعكوسة جانبيًا وبُعدها يساوي بُعد الجسم"},{"type":"tf","q":"تُقاس زاوية السقوط بين الشعاع الساقط وسطح المرآة.","answer":false,"why":"بل تُقاس بين الشعاع الساقط والعمود المقام على السطح"},{"type":"tf","q":"ينطبق قانون الانعكاس (i = r) على الانعكاس غير المنتظم أيضًا عند كل نقطة دقيقة على السطح.","answer":true,"why":"لكن اختلاف ميل السطح الخشن من نقطة لأخرى يشتت الأشعة المنعكسة"},{"type":"tf","q":"يمكن استقبال الصورة المتكوّنة في المرآة المستوية على شاشة ورقية خلف المرآة.","answer":false,"why":"لأنها صورة تقديرية لا تصل الأشعة الحقيقية خلف المرآة"},{"type":"tfr","q":"إذا نظرت لساعة حائط تشير إلى 3:00 في مرآة مستوية فستبدو كأنها تشير إلى 9:00.","answer":true,"reasons":["بسبب خاصية الانعكاس الجانبي في المرآة المستوية","تبقى 3:00","تصبح 6:00"],"reason":0},{"type":"tfr","q":"يُرى انعكاس الشمس بوضوح كصورة محددة على سطح ماء هادئ ساكن بسبب الانعكاس المنتظم.","answer":true,"reasons":["لأنه انعكاس مشتت","لأن السطح الأملس يعكس الأشعة المتوازية متوازيةً في اتجاه واحد","لأن الماء معتم"],"reason":1},{"type":"tfr","q":"تُستخدم المرآتان المستويتان المتوازيتان بزاوية ٤٥° في البيريسكوب للرؤية فوق العوائق.","answer":true,"reasons":["بل عدسات مقعرة فقط","بل بزاوية ٩٠° مع السطح","حيث ينعكس الشعاع بزاوية ٩٠° مرتين ليصل إلى عين المشاهد"],"reason":2},{"type":"tfr","q":"تظهر كلمة «إسعاف» معكوسةً أفقيًا على مقدمة سيارة الإسعاف بسبب المعكوس الجانبي في المرآة المستوية.","answer":true,"reasons":["لتُقرأ بشكل صحيح ومعتدل في مرآة السائق الأمامية","للزينة فقط","بسبب انكسار الضوء"],"reason":0},{"type":"essay","q":"اذكر الصفات الخمس للصورة المتكوّنة في المرآة المستوية.","model":"١) تقديرية. ٢) معتدلة. ٣) مساوية للجسم. ٤) معكوسة جانبيًا. ٥) بُعدها خلف المرآة يساوي بُعد الجسم أمامها."},{"type":"essay","q":"سقط شعاع ضوئي بزاوية 35° مع سطح المرآة. احسب: (أ) زاوية السقوط، (ب) زاوية الانعكاس، (ج) الزاوية بين الشعاع الساقط والمنعكس.","model":"أ) i = 90 − 35 = 55°. ب) r = 55°. ج) 55 + 55 = 110°."},{"type":"essay","q":"قارن بين الانعكاس المنتظم والانعكاس غير المنتظم من حيث نوع السطح وتكوين الصورة.","model":"المنتظم: سطح أملس مصقول (مرآة)، تنعكس الأشعة متوازية وتتكون صورة واضحة. غير المنتظم: سطح خشن (ورق/جدار)، تتشتت الأشعة ولا تتكون صورة."},{"type":"essay","q":"اشرح فكرة عمل البيروسكوب مع تحديد زاوية المرآتين.","model":"يحتوي أنبوبًا به مرآتان مستويتان متوازيتان مائلتان بزاوية 45°؛ تعكس العليا الضوء بزاوية 90° للأسفل نحو السفلى فتعكسه 90° نحو عين الراصد."},{"type":"essay","q":"كيف تثبت عمليًا قانون الانعكاس باستخدام مرآة مستوية وصندوق ضوئي ومنقلة؟","model":"نرسم خط المرآة والعمود المقام على ورقة، نوجّه شعاعًا بزاوية سقوط i معلومة، نحدد مسار الشعاع المنعكس ونقيس r بالمنقلة فنكرّر لعدة زوايا فنجد دائمًا i = r."}]},
  {"id":"g9-phy-2-u13","grade":"g9","subject":"physics","term":2,"title":"الوحدة الثالثة عشرة: انكسار الضوء","levels":{"easy":[{"type":"mcq","q":"ما السبب الفيزيائي المباشر لحدوث انكسار الضوء بين وسطين شفافين؟","options":["توقف الضوء","تغيّر سرعة الضوء عند انتقاله بين الوسطين","امتصاص الضوء","تغيّر لون الضوء"],"answer":1,"why":"اختلاف سرعة الضوء بين الأوساط هو سبب انحرافه."},{"type":"mcq","q":"عند انتقال شعاع ضوئي مائل من الهواء إلى الزجاج فإنه:","options":["يرتد للخلف","تزداد سرعته ويبتعد عن العمود","تقل سرعته وينكسر مقتربًا من العمود المقام","لا تتغير سرعته"],"answer":2,"why":"الزجاج أكبر كثافة ضوئية فيبطئ الضوء ويقترب من العمود."},{"type":"mcq","q":"قانون سنل لحساب معامل الانكسار (n) عند السقوط من الهواء هو:","options":["n = i + r","n = i × r","n = sin r ÷ sin i","n = sin i ÷ sin r"],"answer":3,"why":"نسبة جيب زاوية السقوط إلى جيب زاوية الانكسار."},{"type":"mcq","q":"لماذا تبدو بركة الماء الصافي أقل عمقًا من عمقها الحقيقي؟","options":["بسبب انكسار الأشعة الخارجة من الماء للهواء مبتعدةً عن العمود","لأن الماء يكبر الأجسام فقط","بسبب الانعكاس فقط","بسبب التبخر"],"answer":0,"why":"تتلاقى امتدادات الأشعة المنكسرة عند عمق ظاهري أقرب للسطح."}],"medium":[{"type":"mcq","q":"سقط شعاع عموديًا على سطح ماء (i = 0°). ماذا يحدث له؟","options":["يتوقف","تقل سرعته لكنه ينفذ مستقيمًا دون انحراف (r = 0°)","ينعكس تمامًا","ينكسر بزاوية 45°"],"answer":1,"why":"السقوط العمودي يغير السرعة دون تغيير الاتجاه."},{"type":"mcq","q":"وحدة قياس معامل الانكسار (n) هي:","options":["m/s","الدرجة (°)","ليس له وحدة","المتر"],"answer":2,"why":"نسبة بين كميتين متماثلتين لذا هو بلا وحدة."},{"type":"mcq","q":"إذا كانت سرعة الضوء في الفراغ 3×10⁸ m/s وفي الزجاج 2×10⁸ m/s، فمعامل انكسار الزجاج هو:","options":["0.67","1.0","6.0","1.5"],"answer":3,"why":"n = 3×10⁸ ÷ 2×10⁸ = 1.5."},{"type":"tfr","q":"يبقى تردّد الضوء ثابتًا عند انتقاله بين وسطين بينما تتغير سرعته وطوله الموجي.","answer":true,"reasons":["لا يتغير شيء","التردد يعتمد على المصدر فقط، وتغير السرعة يغير الطول الموجي","يتغير التردد فقط"],"reason":1},{"type":"tfr","q":"يحدث الانعكاس الداخلي الكلي عندما تكون زاوية السقوط أكبر من الزاوية الحرجة في الوسط الأكبر كثافة.","answer":true,"reasons":["في الهواء فقط","عندما تكون أصغر من c","فتنعكس 100% من الأشعة داخل الوسط دون خروج"],"reason":2}],"hard":[{"type":"mcq","q":"عند خروج شعاع ضوئي من الماء إلى الهواء مائلًا، فإنه ينكسر:","options":["مبتعدًا عن العمود المقام (r > i)","مقتربًا من العمود","لا ينكسر","بزاوية 0°"],"answer":0,"why":"تزداد سرعته في الهواء فيبتعد عن العمود."},{"type":"mcq","q":"أي ألوان الطيف يكون «الأكثر انكسارًا» عند مرور الضوء الأبيض عبر منشور زجاجي؟","options":["الأصفر","البنفسجي","البرتقالي","الأحمر"],"answer":1,"why":"البنفسجي أبطأ قليلًا في الزجاج فينحرف بزاوية أكبر من الأحمر."},{"type":"mcq","q":"عند مرور شعاع عبر لوح زجاجي متوازي الوجهين، يكون الشعاع الخارج:","options":["منطبقًا دون إزاحة","عموديًا على الساقط","موازيًا للشعاع الساقط الأصلي ومزاحًا جانبيًا","مختفيًا"],"answer":2,"why":"الانكسار الثاني يعادل الانكسار الأول فيخرج موازيًا."},{"type":"essay","q":"فسّر لماذا يبدو القلم المغمور جزئيًا في كوب ماء كأنه مكسور.","model":"لأن الأشعة الضوئية القادمة من الجزء المغمور تنكسر مبتعدةً عن العمود المقام عند خروجها من الماء للهواء، فتراها العين على امتداداتها في موضع أقرب للسطح."},{"type":"essay","q":"سقط شعاع من الهواء على سائل بزاوية 45° فانكسر بزاوية 30°. احسب معامل انكسار السائل (sin45=0.707, sin30=0.5).","model":"n = sin 45° ÷ sin 30° = 0.707 ÷ 0.5 ≈ 1.41."}]},"test":[{"type":"mcq","q":"ما السبب الفيزيائي المباشر لحدوث انكسار الضوء بين وسطين شفافين؟","options":["توقف الضوء","تغيّر سرعة الضوء عند انتقاله بين الوسطين","امتصاص الضوء","تغيّر لون الضوء"],"answer":1,"why":"اختلاف سرعة الضوء بين الأوساط هو سبب انحرافه."},{"type":"mcq","q":"عند انتقال شعاع ضوئي مائل من الهواء إلى الزجاج فإنه:","options":["يرتد للخلف","تزداد سرعته ويبتعد عن العمود","تقل سرعته وينكسر مقتربًا من العمود المقام","لا تتغير سرعته"],"answer":2,"why":"الزجاج أكبر كثافة ضوئية فيبطئ الضوء ويقترب من العمود."},{"type":"mcq","q":"قانون سنل لحساب معامل الانكسار (n) عند السقوط من الهواء هو:","options":["n = i + r","n = i × r","n = sin r ÷ sin i","n = sin i ÷ sin r"],"answer":3,"why":"نسبة جيب زاوية السقوط إلى جيب زاوية الانكسار."},{"type":"mcq","q":"لماذا تبدو بركة الماء الصافي أقل عمقًا من عمقها الحقيقي؟","options":["بسبب انكسار الأشعة الخارجة من الماء للهواء مبتعدةً عن العمود","لأن الماء يكبر الأجسام فقط","بسبب الانعكاس فقط","بسبب التبخر"],"answer":0,"why":"تتلاقى امتدادات الأشعة المنكسرة عند عمق ظاهري أقرب للسطح."},{"type":"mcq","q":"سقط شعاع عموديًا على سطح ماء (i = 0°). ماذا يحدث له؟","options":["يتوقف","تقل سرعته لكنه ينفذ مستقيمًا دون انحراف (r = 0°)","ينعكس تمامًا","ينكسر بزاوية 45°"],"answer":1,"why":"السقوط العمودي يغير السرعة دون تغيير الاتجاه."},{"type":"mcq","q":"وحدة قياس معامل الانكسار (n) هي:","options":["m/s","الدرجة (°)","ليس له وحدة","المتر"],"answer":2,"why":"نسبة بين كميتين متماثلتين لذا هو بلا وحدة."},{"type":"mcq","q":"إذا كانت سرعة الضوء في الفراغ 3×10⁸ m/s وفي الزجاج 2×10⁸ m/s، فمعامل انكسار الزجاج هو:","options":["0.67","1.0","6.0","1.5"],"answer":3,"why":"n = 3×10⁸ ÷ 2×10⁸ = 1.5."},{"type":"mcq","q":"عند خروج شعاع ضوئي من الماء إلى الهواء مائلًا، فإنه ينكسر:","options":["مبتعدًا عن العمود المقام (r > i)","مقتربًا من العمود","لا ينكسر","بزاوية 0°"],"answer":0,"why":"تزداد سرعته في الهواء فيبتعد عن العمود."},{"type":"mcq","q":"أي ألوان الطيف يكون «الأكثر انكسارًا» عند مرور الضوء الأبيض عبر منشور زجاجي؟","options":["الأصفر","البنفسجي","البرتقالي","الأحمر"],"answer":1,"why":"البنفسجي أبطأ قليلًا في الزجاج فينحرف بزاوية أكبر من الأحمر."},{"type":"mcq","q":"عند مرور شعاع عبر لوح زجاجي متوازي الوجهين، يكون الشعاع الخارج:","options":["منطبقًا دون إزاحة","عموديًا على الساقط","موازيًا للشعاع الساقط الأصلي ومزاحًا جانبيًا","مختفيًا"],"answer":2,"why":"الانكسار الثاني يعادل الانكسار الأول فيخرج موازيًا."},{"type":"mcq","q":"إذا كان معامل انكسار الماس 2.4 وللماء 1.33، فأيهما يكون فيه الضوء أبطأ؟","options":["الماء","لا يمر الضوء في الماس","متساويان","الماس (لأن معامل انكساره أكبر)"],"answer":3,"why":"كلما زاد n قلت سرعة الضوء في الوسط (v = c/n)."},{"type":"mcq","q":"ما الزاوية الحرجة (c)؟","options":["زاوية السقوط في الوسط الأكبر كثافةً التي تقابلها زاوية انكسار 90°","زاوية انعكاس تساوي 0°","زاوية السقوط في الهواء دائمًا","زاوية تساوي 180°"],"answer":0,"why":"عند i = c يخرج الشعاع مماسًا للسطح (r = 90°)."},{"type":"tf","q":"تقلّ سرعة الضوء عند انتقاله من الهواء إلى الماء أو الزجاج.","answer":true,"why":"لأن الماء والزجاج أكبر كثافةً ضوئيةً من الهواء"},{"type":"tf","q":"ينكسر الشعاع الساقط عموديًا (i = 0°) بزاوية انكسار 90°.","answer":false,"why":"ينفذ على استقامته دون انحراف (r = 0°) مع تغير سرعته فقط"},{"type":"tf","q":"معامل الانكسار لأي مادة شفافة يكون دائمًا أكبر من أو يساوي 1.","answer":true,"why":"لأن سرعة الضوء في الفراغ c هي القصوى، وبما أن v ≤ c فإن n = c/v ≥ 1"},{"type":"tf","q":"العمق الحقيقي للسمكة في الماء أكبر من العمق الظاهري الذي يراه الصياد من الهواء.","answer":true,"why":"لذا على الصياد التصويب أعمق قليلًا من الموضع الظاهري للسمكة"},{"type":"tfr","q":"يبقى تردّد الضوء ثابتًا عند انتقاله بين وسطين بينما تتغير سرعته وطوله الموجي.","answer":true,"reasons":["لا يتغير شيء","التردد يعتمد على المصدر فقط، وتغير السرعة يغير الطول الموجي","يتغير التردد فقط"],"reason":1},{"type":"tfr","q":"يحدث الانعكاس الداخلي الكلي عندما تكون زاوية السقوط أكبر من الزاوية الحرجة في الوسط الأكبر كثافة.","answer":true,"reasons":["في الهواء فقط","عندما تكون أصغر من c","فتنعكس 100% من الأشعة داخل الوسط دون خروج"],"reason":2},{"type":"tfr","q":"كلما زاد معامل انكسار المادة (n)، زادت زاويتها الحرجة (c).","answer":false,"reasons":["بل «تقل» الزاوية الحرجة لأن sin c = 1/n (علاقة عكسية)","نعم تزداد","لا علاقة بينهما"],"reason":0},{"type":"tfr","q":"يعمل المنظار الطبي (Endoscope) باستخدام حزم من الألياف البصرية لنقل الضوء والصورة من داخل الجسم.","answer":true,"reasons":["يستخدم أسلاك نحاس فقط","حزمة تضيء الداخل وحزمة تنقل الصورة بالانعكاس الداخلي الكلي","يستخدم أشعة إكس"],"reason":1},{"type":"essay","q":"فسّر لماذا يبدو القلم المغمور جزئيًا في كوب ماء كأنه مكسور.","model":"لأن الأشعة الضوئية القادمة من الجزء المغمور تنكسر مبتعدةً عن العمود المقام عند خروجها من الماء للهواء، فتراها العين على امتداداتها في موضع أقرب للسطح."},{"type":"essay","q":"سقط شعاع من الهواء على سائل بزاوية 45° فانكسر بزاوية 30°. احسب معامل انكسار السائل (sin45=0.707, sin30=0.5).","model":"n = sin 45° ÷ sin 30° = 0.707 ÷ 0.5 ≈ 1.41."},{"type":"essay","q":"قارن بين مسار الشعاع عند الانتقال من الهواء للزجاج ومن الزجاج للهواء.","model":"من الهواء للزجاج: تقل السرعة ويقترب من العمود (r < i). من الزجاج للهواء: تزداد السرعة ويبتعد عن العمود (r > i)."},{"type":"essay","q":"احسب سرعة الضوء في الماء إذا كان معامل انكساره 1.33 وسرعة الضوء في الفراغ 3×10⁸ m/s.","model":"v = c ÷ n = (3×10⁸) ÷ 1.33 ≈ 2.26 × 10⁸ m/s."},{"type":"essay","q":"اشرح سبب تفريق المنشور الزجاجي للضوء الأبيض إلى ألوان الطيف السبعة.","model":"الضوء الأبيض مزيج من سبعة ألوان تختلف قليلًا في سرعتها ومعامل انكسارها داخل الزجاج، فينكسر البنفسجي أكثر من الأحمر وتتفرق الألوان."}]},
  {"id":"g9-phy-2-u14","grade":"g9","subject":"physics","term":2,"title":"الوحدة الرابعة عشرة: العدسات المحدّبة الرقيقة","levels":{"easy":[{"type":"mcq","q":"ما النقطة التي تتجمّع فيها الأشعة المتوازية بعد مرورها بالعدسة المحدّبة؟","options":["المركز البصري","حافة العدسة","البؤرة الرئيسة (F)","الشاشة البعيدة"],"answer":2,"why":"تجمع العدسة المحدّبة الأشعة المتوازية في البؤرة F."},{"type":"mcq","q":"الشعاع الذي يمر بالمركز البصري للعدسة الرقيقة:","options":["ينكسر بزاوية 90°","ينعكس للخلف","يختفي","ينفذ على استقامته دون انحراف"],"answer":3,"why":"الشعاع المار بالمركز البصري لا ينحرف."},{"type":"mcq","q":"أين نضع الجسم أمام عدسة محدّبة لتعمل كـ«عدسة مكبّرة» (تقديرية، معتدلة، مكبّرة)؟","options":["أقرب من البؤرة (على بُعد أقل من f)","أبعد من 2F","عند 2F تمامًا","في اللانهاية"],"answer":0,"why":"الوضع الوحيد الذي يعطي صورة تقديرية معتدلة مكبّرة هو أقل من f."},{"type":"mcq","q":"ما نوع العدسة المستخدمة لتصحيح «طول النظر»؟","options":["عدسة مقعّرة (مفرّقة)","عدسة محدّبة (لامّة)","مرآة مستوية","زجاج معتم"],"answer":1,"why":"تجمع العدسة المحدّبة الأشعة لتقع على الشبكية بدل خلفها."}],"medium":[{"type":"mcq","q":"وُضع جسم على بُعد 2F أمام عدسة محدّبة. صفات الصورة هي:","options":["تقديرية ومكبرة","حقيقية ومصغرة","حقيقية، مقلوبة، ومساوية للجسم","لا تتكون صورة"],"answer":2,"why":"عند 2F تكون الصورة عند 2F مساوية ومقلوبة وحقيقية."},{"type":"mcq","q":"أي جهاز يستخدم عدسة محدّبة وجسمًا أبعد من 2F لتكوين صورة حقيقية مصغّرة؟","options":["جهاز العرض","العدسة المكبّرة","المرآة المستوية","الكاميرا (والعين البشرية)"],"answer":3,"why":"الكاميرا تكوّن صورة حقيقية مصغرة على المستشعر."},{"type":"mcq","q":"أي جهاز يضع الشريحة بين F و 2F لتكوين صورة حقيقية مقلوبة مكبّرة على الحائط؟","options":["جهاز العرض (البروجكتر)","العدسة المكبّرة","مرآة السيارة","النظارة الشمسية"],"answer":0,"why":"العارض يكبّر الصورة على شاشة حقيقية."},{"type":"tfr","q":"تغطية النصف السفلي لعدسة محدّبة بقطعة ورق سوداء يُخفي نصف الصورة على الشاشة.","answer":false,"reasons":["يختفي نصف الصورة","تختفي الصورة تمامًا","تبقى الصورة كاملةً لكن تقلّ شدة إضاءتها (سطوعها) لأن باقي العدسة يمرر أشعة من كل الجسم"],"reason":2},{"type":"tfr","q":"الصورة الحقيقية التي تكوّنها العدسة المحدّبة تكون دائمًا مقلوبةً ويمكن استقبالها على حائل.","answer":true,"reasons":["لأن الأشعة المنكسرة تتقاطع فعليًا عند موضع الصورة","بل تكون معتدلة دائمًا","لا يمكن استقبالها على حائل"],"reason":0}],"hard":[{"type":"mcq","q":"عدسة محدّبة بعدها البؤري 8 cm. إذا وُضع جسم على بُعد 5 cm منها فالصورة تكون:","options":["حقيقية، مقلوبة، مصغرة","تقديرية، معتدلة، مكبّرة","حقيقية ومساوية","حقيقية ومكبرة"],"answer":1,"why":"لأن 5 cm < 8 cm (أقرب من البؤرة)."},{"type":"mcq","q":"الفرق الأساسي بين الصورة الحقيقية والتقديرية هو أن الحقيقية:","options":["معتدلة دائمًا","لا تُستقبل على شاشة","تُستقبل على شاشة وتتكوّن من تلاقي الأشعة الفعلية","تتكون من امتدادات الأشعة"],"answer":2,"why":"الصورة الحقيقية ناتجة عن تلاقي الأشعة نفسها."},{"type":"mcq","q":"ما نوع العدسة المستخدمة لتصحيح «قصر النظر»؟","options":["منشور زجاجي","عدسة محدّبة (لامّة)","لوح خشبي","عدسة مقعّرة (مفرّقة)"],"answer":3,"why":"العدسة المقعرة تفرّق الأشعة قليلًا لتتجمع على الشبكية بدل أمامها."},{"type":"essay","q":"اذكر الأشعة القياسية الثلاثة المستخدمة في رسم مسار الأشعة خلال العدسة المحدّبة الرقيقة.","model":"١) الموازي للمحور ينكسر بالبؤرة F. ٢) المار بالمركز البصري ينفذ مستقيمًا. ٣) المار بالبؤرة ينكسر موازيًا للمحور."},{"type":"essay","q":"قارن بين الصورة المتكوّنة عندما يكون الجسم أبعد من 2F وعندما يكون أقرب من F.","model":"أبعد من 2F: حقيقية، مقلوبة، مصغّرة (تُستقبل على شاشة). أقرب من F: تقديرية، معتدلة، مكبّرة (لا تُستقبل على شاشة — عدسة مكبّرة)."}]},"test":[{"type":"mcq","q":"ما النقطة التي تتجمّع فيها الأشعة المتوازية بعد مرورها بالعدسة المحدّبة؟","options":["المركز البصري","حافة العدسة","البؤرة الرئيسة (F)","الشاشة البعيدة"],"answer":2,"why":"تجمع العدسة المحدّبة الأشعة المتوازية في البؤرة F."},{"type":"mcq","q":"الشعاع الذي يمر بالمركز البصري للعدسة الرقيقة:","options":["ينكسر بزاوية 90°","ينعكس للخلف","يختفي","ينفذ على استقامته دون انحراف"],"answer":3,"why":"الشعاع المار بالمركز البصري لا ينحرف."},{"type":"mcq","q":"أين نضع الجسم أمام عدسة محدّبة لتعمل كـ«عدسة مكبّرة» (تقديرية، معتدلة، مكبّرة)؟","options":["أقرب من البؤرة (على بُعد أقل من f)","أبعد من 2F","عند 2F تمامًا","في اللانهاية"],"answer":0,"why":"الوضع الوحيد الذي يعطي صورة تقديرية معتدلة مكبّرة هو أقل من f."},{"type":"mcq","q":"ما نوع العدسة المستخدمة لتصحيح «طول النظر»؟","options":["عدسة مقعّرة (مفرّقة)","عدسة محدّبة (لامّة)","مرآة مستوية","زجاج معتم"],"answer":1,"why":"تجمع العدسة المحدّبة الأشعة لتقع على الشبكية بدل خلفها."},{"type":"mcq","q":"وُضع جسم على بُعد 2F أمام عدسة محدّبة. صفات الصورة هي:","options":["تقديرية ومكبرة","حقيقية ومصغرة","حقيقية، مقلوبة، ومساوية للجسم","لا تتكون صورة"],"answer":2,"why":"عند 2F تكون الصورة عند 2F مساوية ومقلوبة وحقيقية."},{"type":"mcq","q":"أي جهاز يستخدم عدسة محدّبة وجسمًا أبعد من 2F لتكوين صورة حقيقية مصغّرة؟","options":["جهاز العرض","العدسة المكبّرة","المرآة المستوية","الكاميرا (والعين البشرية)"],"answer":3,"why":"الكاميرا تكوّن صورة حقيقية مصغرة على المستشعر."},{"type":"mcq","q":"أي جهاز يضع الشريحة بين F و 2F لتكوين صورة حقيقية مقلوبة مكبّرة على الحائط؟","options":["جهاز العرض (البروجكتر)","العدسة المكبّرة","مرآة السيارة","النظارة الشمسية"],"answer":0,"why":"العارض يكبّر الصورة على شاشة حقيقية."},{"type":"mcq","q":"عدسة محدّبة بعدها البؤري 8 cm. إذا وُضع جسم على بُعد 5 cm منها فالصورة تكون:","options":["حقيقية، مقلوبة، مصغرة","تقديرية، معتدلة، مكبّرة","حقيقية ومساوية","حقيقية ومكبرة"],"answer":1,"why":"لأن 5 cm < 8 cm (أقرب من البؤرة)."},{"type":"mcq","q":"الفرق الأساسي بين الصورة الحقيقية والتقديرية هو أن الحقيقية:","options":["معتدلة دائمًا","لا تُستقبل على شاشة","تُستقبل على شاشة وتتكوّن من تلاقي الأشعة الفعلية","تتكون من امتدادات الأشعة"],"answer":2,"why":"الصورة الحقيقية ناتجة عن تلاقي الأشعة نفسها."},{"type":"mcq","q":"ما نوع العدسة المستخدمة لتصحيح «قصر النظر»؟","options":["منشور زجاجي","عدسة محدّبة (لامّة)","لوح خشبي","عدسة مقعّرة (مفرّقة)"],"answer":3,"why":"العدسة المقعرة تفرّق الأشعة قليلًا لتتجمع على الشبكية بدل أمامها."},{"type":"mcq","q":"عدسة محدّبة أكثر سمكًا وتحدّبًا يكون بُعدها البؤري:","options":["أقصر (أقوى تجميعًا للضوء)","أطول بكثير","لانهائيًا","صفرًا"],"answer":0,"why":"زيادة التحدّب تقرّب البؤرة وتزيد قدرة العدسة."},{"type":"mcq","q":"أي شعاع يمر عبر المركز البصري لعدسة محدّبة رقيقة فإنه:","options":["ينكسر مارًا بالبؤرة","ينفذ على استقامته دون أن ينحرف","ينعكس للخلف","يتوقف داخل العدسة"],"answer":1,"why":"الشعاع المار بالمركز البصري يستمر في خط مستقيم."},{"type":"tf","q":"تكون جميع الصور الحقيقية المتكوّنة بالعدسة المحدّبة مقلوبةً.","answer":true,"why":"بينما تكون الصورة التقديرية معتدلةً دائمًا"},{"type":"tf","q":"الشعاع الساقط موازيًا للمحور الرئيس ينكسر مارًّا بالبؤرة F.","answer":true,"why":"وهذه القاعدة الأولى في رسم مخطط الأشعة للعدسة اللامّة"},{"type":"tf","q":"تُستخدم العدسة المحدّبة لتصحيح قصر النظر.","answer":false,"why":"العدسة المحدّبة تصحّح طول النظر، أما قصر النظر فتصحّحه العدسة المقعّرة"},{"type":"tf","q":"عند وضع جسم عند البؤرة F تمامًا لا تتكوّن صورة واضحة لأن الأشعة تخرج متوازيةً.","answer":true,"why":"وتُستغل هذه الحالة في كشافات الإضاءة لإنتاج حزمة ضوء متوازية"},{"type":"tfr","q":"تغطية النصف السفلي لعدسة محدّبة بقطعة ورق سوداء يُخفي نصف الصورة على الشاشة.","answer":false,"reasons":["يختفي نصف الصورة","تختفي الصورة تمامًا","تبقى الصورة كاملةً لكن تقلّ شدة إضاءتها (سطوعها) لأن باقي العدسة يمرر أشعة من كل الجسم"],"reason":2},{"type":"tfr","q":"الصورة الحقيقية التي تكوّنها العدسة المحدّبة تكون دائمًا مقلوبةً ويمكن استقبالها على حائل.","answer":true,"reasons":["لأن الأشعة المنكسرة تتقاطع فعليًا عند موضع الصورة","بل تكون معتدلة دائمًا","لا يمكن استقبالها على حائل"],"reason":0},{"type":"tfr","q":"العدسة المحدّبة الأكثر سُمكًا (تحدّبًا) لها بُعد بؤري أطول من العدسة الرقيقة قليلة التحدّب.","answer":false,"reasons":["نعم بُعدها البؤري أطول","بل لها بُعد بؤري «أقصر» لأنها تكسر الضوء بقوة أكبر وتجمعه أقرب إليها","التحدّب لا يؤثر على البُعد البؤري"],"reason":1},{"type":"tfr","q":"تُستخدم العدسة المحدّبة لتصحيح «طول النظر» لأنها تساعد العين على تجميع الأشعة على الشبكية.","answer":true,"reasons":["لأنها تفرّق الأشعة","لتصحيح قصر النظر فقط","حيث تجمع الأشعة قليلًا قبل دخولها عدسة العين فتسقط على الشبكية بدلًا من خلفها"],"reason":2},{"type":"essay","q":"اذكر الأشعة القياسية الثلاثة المستخدمة في رسم مسار الأشعة خلال العدسة المحدّبة الرقيقة.","model":"١) الموازي للمحور ينكسر بالبؤرة F. ٢) المار بالمركز البصري ينفذ مستقيمًا. ٣) المار بالبؤرة ينكسر موازيًا للمحور."},{"type":"essay","q":"قارن بين الصورة المتكوّنة عندما يكون الجسم أبعد من 2F وعندما يكون أقرب من F.","model":"أبعد من 2F: حقيقية، مقلوبة، مصغّرة (تُستقبل على شاشة). أقرب من F: تقديرية، معتدلة، مكبّرة (لا تُستقبل على شاشة — عدسة مكبّرة)."},{"type":"essay","q":"قارن بين طول النظر وقصر النظر من حيث موضع تكوّن الصورة والعدسة المصحّحة.","model":"طول النظر: تتكوّن خلف الشبكية ويُصحّح بعدسة محدّبة. قصر النظر: تتكوّن أمام الشبكية ويُصحّح بعدسة مقعّرة."},{"type":"essay","q":"عدسة محدّبة بعدها البؤري 12 cm. حدّد صفات الصورة لجسم يبعد: (أ) 30 cm، (ب) 24 cm، (ج) 8 cm.","model":"أ) >2F: حقيقية مقلوبة مصغّرة. ب) =2F: حقيقية مقلوبة مساوية. ج) <F: تقديرية معتدلة مكبّرة."},{"type":"essay","q":"كيف تقيس البعد البؤري (f) لعدسة محدّبة في مختبر المدرسة باستخدام نافذة بعيدة وشاشة ورقية؟","model":"نحرّك الشاشة خلف العدسة حتى تتكوّن أوضح صورة مصغّرة ومقلوبة للنافذة البعيدة، ثم نقيس المسافة بين العدسة والشاشة بالمسطرة فتكون هي البعد البؤري f."}]},
  {"id":"g9-phy-2-u15","grade":"g9","subject":"physics","term":2,"title":"الوحدة الخامسة عشرة: التيّار وفرق الجهد والقوّة الدافعة الكهربائيّة","levels":{"easy":[{"type":"mcq","q":"ما وحدة قياس شدة التيار الكهربائي في النظام الدولي؟","options":["الأوم (Ω)","الفولت (V)","الكولوم (C)","الأمبير (A)"],"answer":3,"why":"يُقاس التيار الكهربائي بوحدة الأمبير (A)."},{"type":"mcq","q":"كيف يُوصَّل جهاز الأميتر في الدائرة الكهربائية لقياس التيار؟","options":["على التوالي","على التوازي","خارج الدائرة","بين الأرضي والسقف"],"answer":0,"why":"الأميتر يُوصل على التوالي ليمر عبره كامل التيار."},{"type":"mcq","q":"مرّت شحنة كهربائية 60 C عبر سلك خلال 15 s. شدة التيار تساوي:","options":["900 A","4 A","45 A","0.25 A"],"answer":1,"why":"I = Q ÷ t = 60 ÷ 15 = 4 A."},{"type":"mcq","q":"ما اتجاه «تدفق الإلكترونات» الفعلي خارج البطارية؟","options":["من الموجب إلى السالب","في كلا الاتجاهين معًا","من القطب السالب (−) إلى القطب الموجب (+)","لا تتحرك الإلكترونات"],"answer":2,"why":"الإلكترونات سالبة فتتنافر مع السالب وتنجذب للموجب."}],"medium":[{"type":"mcq","q":"تيار شدته 3 A يسري لمدة دقيقة واحدة (60 s). ما الشحنة المارة؟","options":["20 C","3 C","63 C","180 C"],"answer":3,"why":"Q = 3 × 60 = 180 C."},{"type":"mcq","q":"ما وحدة قياس الشحنة الكهربائية (Q)؟","options":["الكولوم (C)","الأمبير (A)","الجول (J)","الواط (W)"],"answer":0,"why":"تقاس الشحنة بالكولوم (C)."},{"type":"mcq","q":"ما نوع التيار الذي تنتجه البطاريات الجافة؟","options":["تيار متردد (AC)","تيار مستمر (DC) يسري في اتجاه واحد","تيار حراري","لا تنتج تيارًا"],"answer":1,"why":"البطاريات مصدر للتيار المستمر DC."},{"type":"tfr","q":"في الفلزات الصلبة، تتحرك الإلكترونات الحرة لتنقل التيار الكهربائي.","answer":true,"reasons":["أما الذرات الموجبة فتهتز في مواقعها الثابتة فقط","تتحرك البروتونات","لا توجد إلكترونات حرة"],"reason":0},{"type":"tfr","q":"يُوصل الفولتميتر دائمًا على التوازي بين طرفي المكوّن المراد قياس فرق جهده.","answer":true,"reasons":["يُوصل بدل المفتاح","لقياس فرق الطاقة لكل كولوم بين نقطتي الدخول والخروج للمكوّن","يُوصل على التوالي"],"reason":1}],"hard":[{"type":"mcq","q":"لماذا تُغلّف أسلاك النحاس الكهربائية بطبقة من البلاستيك؟","options":["لزيادة التيار","لتسخين السلك","لأن البلاستيك عازل كهربائي يحمي الإنسان من الصعق ويمنع التماس الأسلاك","لجعل السلك أثقل"],"answer":2,"why":"العزل البلاستيكي ضروري للسلامة الكهربائية."},{"type":"mcq","q":"في دائرة توالي بها مصباحان وأميتر قبل الأول يقرأ 0.5 A؛ كم يقرأ أميتر آخر بعد المصباح الثاني؟","options":["1.0 A","0.25 A","0 A","0.5 A (نفس القراءة)"],"answer":3,"why":"التيار لا يُستهلك ويبقى ثابتًا في كل نقاط دائرة التوالي."},{"type":"mcq","q":"كم ثانيةً تلزم لمرور شحنة 120 C في سلك تياره 4 A؟","options":["30 s","480 s","124 s","0.03 s"],"answer":0,"why":"t = Q ÷ I = 120 ÷ 4 = 30 s."},{"type":"essay","q":"عرّف التيار الكهربائي واكتب قانونه ووحدات قياس كمياته الثلاث.","model":"معدل تدفق الشحنة الكهربائية في الثانية: I = Q ÷ t، حيث I بالأمبير (A)، و Q بالكولوم (C)، و t بالثانية (s)."},{"type":"essay","q":"يمر تيار شدته 0.5 A في مصباح لمدة 4 دقائق. احسب الشحنة الكهربائية المارة.","model":"t = 4 × 60 = 240 s. Q = 0.5 × 240 = 120 C."}]},"test":[{"type":"mcq","q":"ما وحدة قياس شدة التيار الكهربائي في النظام الدولي؟","options":["الأوم (Ω)","الفولت (V)","الكولوم (C)","الأمبير (A)"],"answer":3,"why":"يُقاس التيار الكهربائي بوحدة الأمبير (A)."},{"type":"mcq","q":"كيف يُوصَّل جهاز الأميتر في الدائرة الكهربائية لقياس التيار؟","options":["على التوالي","على التوازي","خارج الدائرة","بين الأرضي والسقف"],"answer":0,"why":"الأميتر يُوصل على التوالي ليمر عبره كامل التيار."},{"type":"mcq","q":"مرّت شحنة كهربائية 60 C عبر سلك خلال 15 s. شدة التيار تساوي:","options":["900 A","4 A","45 A","0.25 A"],"answer":1,"why":"I = Q ÷ t = 60 ÷ 15 = 4 A."},{"type":"mcq","q":"ما اتجاه «تدفق الإلكترونات» الفعلي خارج البطارية؟","options":["من الموجب إلى السالب","في كلا الاتجاهين معًا","من القطب السالب (−) إلى القطب الموجب (+)","لا تتحرك الإلكترونات"],"answer":2,"why":"الإلكترونات سالبة فتتنافر مع السالب وتنجذب للموجب."},{"type":"mcq","q":"تيار شدته 3 A يسري لمدة دقيقة واحدة (60 s). ما الشحنة المارة؟","options":["20 C","3 C","63 C","180 C"],"answer":3,"why":"Q = 3 × 60 = 180 C."},{"type":"mcq","q":"ما وحدة قياس الشحنة الكهربائية (Q)؟","options":["الكولوم (C)","الأمبير (A)","الجول (J)","الواط (W)"],"answer":0,"why":"تقاس الشحنة بالكولوم (C)."},{"type":"mcq","q":"ما نوع التيار الذي تنتجه البطاريات الجافة؟","options":["تيار متردد (AC)","تيار مستمر (DC) يسري في اتجاه واحد","تيار حراري","لا تنتج تيارًا"],"answer":1,"why":"البطاريات مصدر للتيار المستمر DC."},{"type":"mcq","q":"لماذا تُغلّف أسلاك النحاس الكهربائية بطبقة من البلاستيك؟","options":["لزيادة التيار","لتسخين السلك","لأن البلاستيك عازل كهربائي يحمي الإنسان من الصعق ويمنع التماس الأسلاك","لجعل السلك أثقل"],"answer":2,"why":"العزل البلاستيكي ضروري للسلامة الكهربائية."},{"type":"mcq","q":"في دائرة توالي بها مصباحان وأميتر قبل الأول يقرأ 0.5 A؛ كم يقرأ أميتر آخر بعد المصباح الثاني؟","options":["1.0 A","0.25 A","0 A","0.5 A (نفس القراءة)"],"answer":3,"why":"التيار لا يُستهلك ويبقى ثابتًا في كل نقاط دائرة التوالي."},{"type":"mcq","q":"كم ثانيةً تلزم لمرور شحنة 120 C في سلك تياره 4 A؟","options":["30 s","480 s","124 s","0.03 s"],"answer":0,"why":"t = Q ÷ I = 120 ÷ 4 = 30 s."},{"type":"mcq","q":"ما نوع التيار الموجود في مقابس الكهرباء المنزلية؟","options":["تيار مستمر (DC)","تيار متردد (AC)","تيار ساكن","تيار مغناطيسي"],"answer":1,"why":"كهرباء الشبكة المنزلية تيار متردد AC."},{"type":"mcq","q":"ما وحدة قياس فرق الجهد والقوة الدافعة الكهربائية؟","options":["الكولوم (C)","الأمبير (A)","الفولت (V)","الأوم (Ω)"],"answer":2,"why":"تُقاس كل من e.m.f و p.d بوحدة الفولت (V)."},{"type":"tf","q":"التيار الاصطلاحي يسري من القطب الموجب إلى السالب، وهو عكس اتجاه حركة الإلكترونات.","answer":true,"why":"اصطلح العلماء على اتجاهه قبل اكتشاف الإلكترون السالب"},{"type":"tf","q":"يُستهلك التيار الكهربائي تدريجيًا أثناء مروره في المصباح فيقل بعد المصباح.","answer":false,"why":"التيار (الشحنات) محفوظ ولا يُستهلك؛ الذي يتحول ويُستهلك هو الطاقة الكهربائية"},{"type":"tf","q":"الأمبير الواحد (1 A) يكافئ مرور شحنة 1 كولوم كل ثانية (1 C/s).","answer":true,"why":"من القانون I = Q / t"},{"type":"tf","q":"يجب توصيل الأميتر على التوازي مع المصباح.","answer":false,"why":"يُوصل الأميتر دائمًا على التوالي، أما الفولتميتر فعلى التوازي"},{"type":"tfr","q":"في الفلزات الصلبة، تتحرك الإلكترونات الحرة لتنقل التيار الكهربائي.","answer":true,"reasons":["أما الذرات الموجبة فتهتز في مواقعها الثابتة فقط","تتحرك البروتونات","لا توجد إلكترونات حرة"],"reason":0},{"type":"tfr","q":"يُوصل الفولتميتر دائمًا على التوازي بين طرفي المكوّن المراد قياس فرق جهده.","answer":true,"reasons":["يُوصل بدل المفتاح","لقياس فرق الطاقة لكل كولوم بين نقطتي الدخول والخروج للمكوّن","يُوصل على التوالي"],"reason":1},{"type":"tfr","q":"تُعد القوة الدافعة الكهربائية (e.m.f) قوةً ميكانيكيةً تُقاس بوحدة النيوتن.","answer":false,"reasons":["تقاس بالكيلوجرام","نعم تقاس بالنيوتن","رغم اسمها التاريخي، هي طاقة لكل وحدة شحنة وتُقاس بالفولت (J/C) لا بالنيوتن"],"reason":2},{"type":"tfr","q":"في دائرة التوالي، مجموع فروق الجهد عبر المكوّنات يساوي القوة الدافعة للبطارية.","answer":true,"reasons":["تحقيقًا لمبدأ حفظ الطاقة في الدائرة","فرق الجهد متساوٍ للبطارية في كل مكون","مجموعها صفر"],"reason":0},{"type":"essay","q":"عرّف التيار الكهربائي واكتب قانونه ووحدات قياس كمياته الثلاث.","model":"معدل تدفق الشحنة الكهربائية في الثانية: I = Q ÷ t، حيث I بالأمبير (A)، و Q بالكولوم (C)، و t بالثانية (s)."},{"type":"essay","q":"يمر تيار شدته 0.5 A في مصباح لمدة 4 دقائق. احسب الشحنة الكهربائية المارة.","model":"t = 4 × 60 = 240 s. Q = 0.5 × 240 = 120 C."},{"type":"essay","q":"قارن بين التيار المستمر (DC) والتيار المتردد (AC) مع مثال لمصدر كل منهما.","model":"DC يسري في اتجاه واحد ثابت (البطارية). AC يعكس اتجاهه دوريًا (مقبس الكهرباء المنزلي)."},{"type":"essay","q":"ما الفرق بين «التيار الاصطلاحي» و«تدفق الإلكترونات»؟","model":"التيار الاصطلاحي يُرسم من (+) إلى (−) خارج البطارية، أما الإلكترونات السالبة فتتحرك فعليًا من (−) إلى (+)."},{"type":"essay","q":"لماذا تكون قراءة الأميتر متساوية قبل وبعد المصباح في دائرة التوالي؟","model":"لأن الشحنات الكهربائية محفوظة لا تفنى في المصباح، وإنما تنقل طاقتها إلى المصباح لتتحول إلى ضوء وحرارة."}]},
  {"id":"g9-phy-2-u16","grade":"g9","subject":"physics","term":2,"title":"الوحدة السادسة عشرة: المقاوَمة","levels":{"easy":[{"type":"mcq","q":"ما وحدة قياس المقاومة الكهربائية؟","options":["الأوم (Ω)","الفولت (V)","الأمبير (A)","الواط (W)"],"answer":0,"why":"تقاس المقاومة بالأوم (Ω) = فولت/أمبير."},{"type":"mcq","q":"مقاومة فرق جهدها 20 V وتيارها 4 A؛ قيمتها تساوي:","options":["0.2 Ω","5 Ω","80 Ω","16 Ω"],"answer":1,"why":"R = 20 ÷ 4 = 5 Ω."},{"type":"mcq","q":"ما الشرط الضروري ليتحقق قانون أوم في موصل فلزي؟","options":["استخدام بطارية واحدة","ارتفاع الحرارة بشدة","ثبات درجة الحرارة","انقطاع التيار"],"answer":2,"why":"ارتفاع الحرارة يزيد مقاومة الفلز فيكسر التناسب الطردي."},{"type":"mcq","q":"ما شكل التمثيل البياني (I–V) لمقاومة ثابتة (موصل أومي) عند ثبات الحرارة؟","options":["خط أفقي","منحنى يتناقص","دائرة مغلقة","خط مستقيم يمر بنقطة الأصل"],"answer":3,"why":"التناسب الطردي يمثَّل بخط مستقيم يمر بـ (0,0)."}],"medium":[{"type":"mcq","q":"مقاومة 6 Ω يمر فيها تيار 2 A. ما فرق الجهد بين طرفيها؟","options":["12 V","3 V","8 V","4 V"],"answer":0,"why":"V = I × R = 2 × 6 = 12 V."},{"type":"mcq","q":"مقاومة 10 Ω وُصلت ببطارية 5 V. ما شدة التيار المار فيها؟","options":["2 A","0.5 A","50 A","15 A"],"answer":1,"why":"I = V ÷ R = 5 ÷ 10 = 0.5 A."},{"type":"mcq","q":"لماذا تزداد مقاومة فتيلة المصباح عند زيادة التيار فيها؟","options":["لأن الجهد ينعدم","لأن طولها ينقص","لأن الفتيلة تسخن بشدة فتزداد اهتزازات الذرات وتعيق حركة الإلكترونات","لأنها تبرد"],"answer":2,"why":"السخونة تزيد تصادمات الإلكترونات بالذرات فتزداد المقاومة."},{"type":"tfr","q":"زيادة المقاومة المتغيرة في دائرة مصباح تجعل المصباح يضيء بسطوع أكبر.","answer":false,"reasons":["لا يتغير السطوع","زيادة المقاومة تقلّل التيار فتخفت إضاءة المصباح","نعم يزداد السطوع"],"reason":1},{"type":"tfr","q":"تتناسب مقاومة السلك طرديًا مع طوله وعكسيًا مع مساحة مقطعه.","answer":true,"reasons":["عكسيًا مع الطول","طرديًا مع المساحة","فالسلك الأطول والأرفع له مقاومة أكبر، والأقصر والأسمك له مقاومة أقل"],"reason":2}],"hard":[{"type":"mcq","q":"الأداة المستخدمة لتغيير شدة التيار تدريجيًا في تجربة قانون أوم هي:","options":["العدسة","الميزان","المنقلة","المقاومة المتغيرة (الريوستات)"],"answer":3,"why":"المقاومة المتغيرة تغير المقاومة والتيار بسلاسة."},{"type":"mcq","q":"عند زيادة المقاومة في الدائرة مع ثبات جهد البطارية، فإن شدة التيار:","options":["تقلّ","تزداد","تبقى ثابتة","تتضاعف"],"answer":0,"why":"العلاقة بين I و R عكسية عند ثبات V."},{"type":"mcq","q":"أي مما يلي يُعد تطبيقًا يوميًا للمقاومة المتغيرة؟","options":["البيروسكوب","مفتاح التحكم في سطوع الإضاءة ومستوى الصوت","المرآة المستوية","الترمس"],"answer":1,"why":"المقاومة المتغيرة تتحكم بالتيار وبالتالي بالسطوع والصوت."},{"type":"essay","q":"اكتب نصّ قانون أوم وصيغته الرياضية ووحدات القياس.","model":"يتناسب التيار المار في موصل فلزي طرديًا مع فرق الجهد بين طرفيه عند ثبات درجة الحرارة: R = V ÷ I (الأوم = فولت ÷ أمبير)."},{"type":"essay","q":"مقاومة 8 Ω وُصلت ببطارية 12 V. احسب التيار المار والقدرة المستهلكة فيها.","model":"I = 12 ÷ 8 = 1.5 A. القدرة P = I × V = 1.5 × 12 = 18 W."}]},"test":[{"type":"mcq","q":"ما وحدة قياس المقاومة الكهربائية؟","options":["الأوم (Ω)","الفولت (V)","الأمبير (A)","الواط (W)"],"answer":0,"why":"تقاس المقاومة بالأوم (Ω) = فولت/أمبير."},{"type":"mcq","q":"مقاومة فرق جهدها 20 V وتيارها 4 A؛ قيمتها تساوي:","options":["0.2 Ω","5 Ω","80 Ω","16 Ω"],"answer":1,"why":"R = 20 ÷ 4 = 5 Ω."},{"type":"mcq","q":"ما الشرط الضروري ليتحقق قانون أوم في موصل فلزي؟","options":["استخدام بطارية واحدة","ارتفاع الحرارة بشدة","ثبات درجة الحرارة","انقطاع التيار"],"answer":2,"why":"ارتفاع الحرارة يزيد مقاومة الفلز فيكسر التناسب الطردي."},{"type":"mcq","q":"ما شكل التمثيل البياني (I–V) لمقاومة ثابتة (موصل أومي) عند ثبات الحرارة؟","options":["خط أفقي","منحنى يتناقص","دائرة مغلقة","خط مستقيم يمر بنقطة الأصل"],"answer":3,"why":"التناسب الطردي يمثَّل بخط مستقيم يمر بـ (0,0)."},{"type":"mcq","q":"مقاومة 6 Ω يمر فيها تيار 2 A. ما فرق الجهد بين طرفيها؟","options":["12 V","3 V","8 V","4 V"],"answer":0,"why":"V = I × R = 2 × 6 = 12 V."},{"type":"mcq","q":"مقاومة 10 Ω وُصلت ببطارية 5 V. ما شدة التيار المار فيها؟","options":["2 A","0.5 A","50 A","15 A"],"answer":1,"why":"I = V ÷ R = 5 ÷ 10 = 0.5 A."},{"type":"mcq","q":"لماذا تزداد مقاومة فتيلة المصباح عند زيادة التيار فيها؟","options":["لأن الجهد ينعدم","لأن طولها ينقص","لأن الفتيلة تسخن بشدة فتزداد اهتزازات الذرات وتعيق حركة الإلكترونات","لأنها تبرد"],"answer":2,"why":"السخونة تزيد تصادمات الإلكترونات بالذرات فتزداد المقاومة."},{"type":"mcq","q":"الأداة المستخدمة لتغيير شدة التيار تدريجيًا في تجربة قانون أوم هي:","options":["العدسة","الميزان","المنقلة","المقاومة المتغيرة (الريوستات)"],"answer":3,"why":"المقاومة المتغيرة تغير المقاومة والتيار بسلاسة."},{"type":"mcq","q":"عند زيادة المقاومة في الدائرة مع ثبات جهد البطارية، فإن شدة التيار:","options":["تقلّ","تزداد","تبقى ثابتة","تتضاعف"],"answer":0,"why":"العلاقة بين I و R عكسية عند ثبات V."},{"type":"mcq","q":"أي مما يلي يُعد تطبيقًا يوميًا للمقاومة المتغيرة؟","options":["البيروسكوب","مفتاح التحكم في سطوع الإضاءة ومستوى الصوت","المرآة المستوية","الترمس"],"answer":1,"why":"المقاومة المتغيرة تتحكم بالتيار وبالتالي بالسطوع والصوت."},{"type":"mcq","q":"لقياس مقاومة سلك عمليًا نحتاج إلى:","options":["ساعة إيقاف فقط","أميترين فقط","أميتر (توالٍ) وفولتميتر (توازٍ)","فولتميترين فقط"],"answer":2,"why":"لإيجاد R = V ÷ I نحتاج قياس V و I معًا."},{"type":"mcq","q":"كيف تتغيّر مقاومة سلك عند مضاعفة «طوله» مرتين مع ثبات مساحته ومادته؟","options":["تبقى ثابتة","تقل للنصف","تزداد ٤ مرات","تتضاعف مرتين (×2)"],"answer":3,"why":"المقاومة تتناسب طرديًا مع الطول."},{"type":"tf","q":"الموصل الأومي يكون منحناه (I–V) خطًا مستقيمًا يمر بنقطة الأصل عند ثبات درجة الحرارة.","answer":true,"why":"لأن النسبة V/I تبقى ثابتةً تمامًا"},{"type":"tf","q":"تقلّ مقاومة فتيلة المصباح كلما زادت درجة حرارتها.","answer":false,"why":"بل «تزداد» مقاومتها مع ارتفاع درجة الحرارة بسبب زيادة اهتزاز الذرات"},{"type":"tf","q":"إذا تضاعف فرق الجهد على مقاومة ثابتة (أومية) يتضاعف التيار المار فيها.","answer":true,"why":"لأن العلاقة بين V و I طردية عند ثبات R"},{"type":"tf","q":"الأوم الواحد يكافئ 1 فولت لكل أمبير (1 V/A).","answer":true,"why":"من قانون أوم R = V / I"},{"type":"tfr","q":"زيادة المقاومة المتغيرة في دائرة مصباح تجعل المصباح يضيء بسطوع أكبر.","answer":false,"reasons":["لا يتغير السطوع","زيادة المقاومة تقلّل التيار فتخفت إضاءة المصباح","نعم يزداد السطوع"],"reason":1},{"type":"tfr","q":"تتناسب مقاومة السلك طرديًا مع طوله وعكسيًا مع مساحة مقطعه.","answer":true,"reasons":["عكسيًا مع الطول","طرديًا مع المساحة","فالسلك الأطول والأرفع له مقاومة أكبر، والأقصر والأسمك له مقاومة أقل"],"reason":2},{"type":"tfr","q":"عند توصيل عدة أجهزة منزلية على التوازي في مقبس واحد، تقل المقاومة الكلية ويزداد التيار الكلي مما قد يسبب خطر حريق.","answer":true,"reasons":["لذا يُمنع تحميل مقبس واحد بأجهزة عالية القدرة معًا","تزداد المقاومة ويقل التيار","لا يتغير التيار"],"reason":0},{"type":"tfr","q":"المقاومة المكافئة لمقاومتين 4 Ω و 12 Ω على التوالي أصغر من 4 Ω.","answer":false,"reasons":["نعم أصغر","على التوالي تُجمع فتساوي 16 Ω (أكبر من 12 Ω)؛ أما على التوازي فتساوي 3 Ω","تساوي 3 Ω"],"reason":1},{"type":"essay","q":"اكتب نصّ قانون أوم وصيغته الرياضية ووحدات القياس.","model":"يتناسب التيار المار في موصل فلزي طرديًا مع فرق الجهد بين طرفيه عند ثبات درجة الحرارة: R = V ÷ I (الأوم = فولت ÷ أمبير)."},{"type":"essay","q":"مقاومة 8 Ω وُصلت ببطارية 12 V. احسب التيار المار والقدرة المستهلكة فيها.","model":"I = 12 ÷ 8 = 1.5 A. القدرة P = I × V = 1.5 × 12 = 18 W."},{"type":"essay","q":"قارن بين منحنى (I–V) للمقاومة الثابتة ومنحنى (I–V) لمصباح الفتيلة مع التفسير.","model":"المقاومة الثابتة: خط مستقيم يمر بالأصل (مقاومتها ثابتة). المصباح: ينحني المنحنى لأن الفتيلة تسخن بزيادة التيار فتزداد مقاومتها."},{"type":"essay","q":"ارسم أو صف الدائرة العملية لقياس مقاومة سلك مجهول.","model":"نوصّل البطارية ومفتاحًا ومقاومة متغيرة وأميترًا والسلك المجهول على التوالي، ونوصّل فولتميترًا على التوازي بين طرفي السلك، ثم نأخذ قراءات V و I ونحسب R = V/I."},{"type":"essay","q":"لماذا تزداد مقاومة السلك الفلزي عند تسخينه على المستوى الجزيئي؟","model":"لأن التسخين يزيد طاقة وسعة اهتزاز ذرات الفلز، فتزداد تصادمات الإلكترونات الحرة معها وتُعاق حركتها أكثر."}]}
);
